__reload_all = true
local System = require("System.System")
local readonly = System.readonly
local Text_Voice = readonly({
  Voice_100335_AwakerVoiceContent = {
    Text = "Guardião, quando posso visitar o cemitério da academia? As grandes almas ali enterradas certamente me trarão uma inspiração extraordinária! Fique tranquilo, eu prometo que não irei mais desenterrar aqueles corpos para observá-los de perto..."
  },
  Voice_100335_AwakerVoiceTitle = {
    Text = "Conversa: Sobre o modelo"
  },
  Voice_100336_AwakerVoiceContent = {
    Text = "Espere! Eu pensei em uma nova forma de expressão que certamente vai chocar o mundo da pintura!"
  },
  Voice_100336_AwakerVoiceTitle = {
    Text = "Atualizar·II"
  },
  Voice_100337_AwakerVoiceContent = {
    Text = "Eu sou a luz e sombra, eu sou a cor, eu... sou a própria pintura!"
  },
  Voice_100337_AwakerVoiceTitle = {
    Text = "Superexaltação"
  },
  Voice_100338_AwakerVoiceContent = {
    Text = "Sss... uma cor que nunca vi antes brilha em seu mundo espiritual... o que será..."
  },
  Voice_100338_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_100338_UnlockDesc = {
    Text = "Nível de iluminação atingiu 2 para desbloquear"
  },
  Voice_100339_AwakerVoiceContent = {
    Text = "Que tinta negra maravilhosa! Eu já coletei muitos líquidos de corrosão para pintar, e no final, todas aquelas obras desapareceram. Cores do universo primordial, todas as pinturas que foram devoradas e não lembradas por ninguém... Não é ainda mais incrível?!"
  },
  Voice_100339_AwakerVoiceTitle = {
    Text = "Conversa fiada·Sobre a crise"
  },
  Voice_100340_AwakerVoiceContent = {
    Text = "Deixe-me chegar mais perto... Deixe-me olhar um pouco mais! Essas luzes e sombras, essas cores, essas posturas... Comparado a elas, as coisas que eu pintava antes eram apenas um monte de papel velho..."
  },
  Voice_100340_AwakerVoiceTitle = {
    Text = "Iluminar: Insight"
  },
  Voice_100340_UnlockDesc = {
    Text = "Nível de iluminação atingiu 7 para desbloquear"
  },
  Voice_100341_AwakerVoiceContent = {
    Text = "Dulesain sempre fala sobre como sua culinária é cheia de arte, mas eu digo que comer e arte não têm nada a ver! Além de desperdiçar um tempo precioso de criação com todo aquele trabalho complicado de lidar com os corpos, depois de finalmente criar um prato que é tanto bonito quanto saboroso, ainda precisa mordê-lo e engoli-lo! Isso é simplesmente um crime contra a arte!"
  },
  Voice_100341_AwakerVoiceTitle = {
    Text = "Conversa·Coisas odiadas"
  },
  Voice_100342_AwakerVoiceContent = {Text = "Ugh..."},
  Voice_100342_AwakerVoiceTitle = {
    Text = "Acertar·III"
  },
  Voice_100343_AwakerVoiceContent = {
    Text = "Modelo ruim..."
  },
  Voice_100343_AwakerVoiceTitle = {Text = "Defesa·II"},
  Voice_100344_AwakerVoiceContent = {
    Text = "Não, não, mais uma pintura horrível... Preciso encontrar inspiração em algum lugar. Um cemitério? Ou um local de execução..."
  },
  Voice_100344_AwakerVoiceTitle = {
    Text = "Investigação Interrompida"
  },
  Voice_100345_AwakerVoiceContent = {
    Text = "Embora eu ache que a escultura é uma forma de arte um tanto rígida e antiquada, a escultora chamada Shan, sua faca é capaz de ter uma expressividade que vai além do que essa forma de arte pode transmitir... realmente um gênio raro!"
  },
  Voice_100345_AwakerVoiceTitle = {
    Text = "Conversa: Sobre Shan"
  },
  Voice_100345_UnlockDesc = {
    Text = "Desbloqueado após obter Despertador \"Sanga\""
  },
  Voice_100346_AwakerVoiceContent = {
    Text = "Você viu esta pintura, Guardião? Esta é a sua retrato que eu fiz para você. Veja como você devora os corpos, quão encantador! Eu sei que nem todos conseguem entender minhas obras, mas a loucura da beleza que esta pintura transmite, você certamente já a tocou, não é?! Para mim, isso já é suficiente, completamente suficiente..."
  },
  Voice_100346_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Quatro"
  },
  Voice_100346_UnlockDesc = {
    Text = "Nível de afinidade atingido 8 desbloqueado"
  },
  Voice_100347_AwakerVoiceContent = {
    Text = "Você disse que queria comprar esta pintura... é verdade?! Oobrigado, Guardião do Segredo! Poucas pessoas conseguem apreciar isso..."
  },
  Voice_100347_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Dois"
  },
  Voice_100347_UnlockDesc = {
    Text = "Nível de afinidade atingido 4 desbloqueado"
  },
  Voice_100348_AwakerVoiceContent = {
    Text = "Guardião, você ainda tem tempo para ser meu modelo recentemente? Comparado com a cena que vi em você da última vez, os outros modelos estão completamente desperdiçando meu tempo..."
  },
  Voice_100348_AwakerVoiceTitle = {
    Text = "Conversa·Sobre Guardião do Segredo"
  },
  Voice_100349_AwakerVoiceContent = {
    Text = "Nesta obra, testemunhe o renascimento!"
  },
  Voice_100349_AwakerVoiceTitle = {
    Text = "Despertar do Conhecimento Espiritual"
  },
  Voice_100350_AwakerVoiceContent = {
    Text = "Veja estas linhas vibrantes!"
  },
  Voice_100350_AwakerVoiceTitle = {
    Text = "Habilidade·Um"
  },
  Voice_100351_AwakerVoiceContent = {
    Text = "Tenho a sensação de que o que esta pincel vai criar vai deixar todos maravilhados!"
  },
  Voice_100351_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · Três"
  },
  Voice_100352_AwakerVoiceContent = {
    Text = "Ah! Uma tinta curiosa... Vou aplicá-la no lugar mais apropriado!"
  },
  Voice_100352_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · I"
  },
  Voice_100353_AwakerVoiceContent = {
    Text = "Este lugar realmente inspira a criatividade! Eu tenho algumas novas criações, Guardião, você está livre recentemente para visitar meu estúdio? Venha, venha!"
  },
  Voice_100353_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Um"
  },
  Voice_100353_UnlockDesc = {
    Text = "Nível de afinidade atingido 2 desbloqueado"
  },
  Voice_100354_AwakerVoiceContent = {
    Text = "Isso mesmo, isso mesmo! A vitória regada com sangue! Que composição maravilhosa!"
  },
  Voice_100354_AwakerVoiceTitle = {
    Text = "Investigação Bem-sucedida"
  },
  Voice_100355_AwakerVoiceContent = {Text = "Ugh..."},
  Voice_100355_AwakerVoiceTitle = {Text = "Acertar·1"},
  Voice_100356_AwakerVoiceContent = {
    Text = "Ah! Sente-se, Guardião. Ser meu modelo é um trabalho árduo. Não se preocupe, eu certamente criarei uma pintura incrível para você."
  },
  Voice_100356_AwakerVoiceTitle = {
    Text = "Iluminar·Visão Remota"
  },
  Voice_100356_UnlockDesc = {
    Text = "Nível de iluminação atingiu 1 para desbloquear"
  },
  Voice_100357_AwakerVoiceContent = {
    Text = "Um artista deve ver apenas a obra em si e não se importar com o olhar dos outros, mas eu não consigo... Desde o dia em que peguei o pincel pela primeira vez, eu desejei poder levar a verdadeira beleza a todos."
  },
  Voice_100357_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Três"
  },
  Voice_100357_UnlockDesc = {
    Text = "Nível de afinidade atingido 6 desbloqueado"
  },
  Voice_100358_AwakerVoiceContent = {
    Text = "Isso me faz lembrar os tempos que passei na academia de pintura. Embora a maioria dos professores e colegas fossem pessoas totalmente sem entendimento de arte, sempre havia uma ou duas pessoas perspicazes que conseguiam vislumbrar a beleza que eu via nas minhas pinturas."
  },
  Voice_100358_AwakerVoiceTitle = {
    Text = "Conversa·Sobre Missaga"
  },
  Voice_100359_AwakerVoiceContent = {
    Text = "Que tipo de arte louca será gerada por este espetáculo brutal?!"
  },
  Voice_100359_AwakerVoiceTitle = {
    Text = "Início da Investigação"
  },
  Voice_100360_AwakerVoiceContent = {
    Text = "Minha paleta!"
  },
  Voice_100360_AwakerVoiceTitle = {
    Text = "Golpe·Quatro"
  },
  Voice_100361_AwakerVoiceContent = {
    Text = "A dor também é arte..."
  },
  Voice_100361_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_100362_AwakerVoiceContent = {
    Text = "Ah! Eu a vi... o olho cego escondido sob o abismo, a visão final do universo... Por favor, espere um pouco mais, Guardião do Segredo, estamos quase terminando!"
  },
  Voice_100362_AwakerVoiceTitle = {
    Text = "Iluminar·Construção"
  },
  Voice_100362_UnlockDesc = {
    Text = "Nível de iluminação atingiu 11 para desbloquear"
  },
  Voice_100363_AwakerVoiceContent = {
    Text = "Meu pincel, feito com meus ossos da perna. A paleta de cores, essas tintas foram coletadas em cemitérios de vinte cidades... e meu precioso tecido de couro! Guardião, por favor, leve isso e pinte um retrato para mim! Não, não, não, você não precisa ter nenhuma habilidade de pintura... Eu acredito que quando essa ressonância espiritual se manifestar na tela, será uma obra de arte de uma beleza que eu nunca imaginei...!"
  },
  Voice_100363_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Cinco"
  },
  Voice_100363_UnlockDesc = {
    Text = "Nível de afinidade atingido 10 desbloqueado"
  },
  Voice_100364_AwakerVoiceContent = {
    Text = "Eu sou luz e sombra, eu sou cor, eu... sou a própria pintura!"
  },
  Voice_100364_AwakerVoiceTitle = {
    Text = "Sobre-Exaltação Aliemus Explosão·II"
  },
  Voice_100365_AwakerVoiceContent = {
    Text = "Tente esta cor!"
  },
  Voice_100365_AwakerVoiceTitle = {Text = "Ataque·II"},
  Voice_100366_AwakerVoiceContent = {
    Text = "A essência da arte é a loucura...!"
  },
  Voice_100366_AwakerVoiceTitle = {
    Text = "Exaltar · Dois"
  },
  Voice_100367_AwakerVoiceContent = {
    Text = "Você quer dizer que na próxima vez posso tentar fazer um close nesse ponto na pintura? Hm... Eu realmente não havia pensado nisso! Que ideia genial!"
  },
  Voice_100367_AwakerVoiceTitle = {
    Text = "Conversa·Toque"
  },
  Voice_100368_AwakerVoiceContent = {Text = "Cuidado!"},
  Voice_100368_AwakerVoiceTitle = {
    Text = "Defesa · I"
  },
  Voice_100369_AwakerVoiceContent = {
    Text = "A essência da arte é a loucura...!"
  },
  Voice_100369_AwakerVoiceTitle = {
    Text = "Fúria Explosiva"
  },
  Voice_100370_AwakerVoiceContent = {
    Text = "Minha paleta!"
  },
  Voice_100370_AwakerVoiceTitle = {
    Text = "Acertar · II"
  },
  Voice_100371_AwakerVoiceContent = {
    Text = "Oh! Este maxilar fluido, olhos brilhantes, forma perfeita, e, e este vasto mundo espiritual como um céu estrelado... Sou o pintor Pikman, posso ter a sorte de convidá-lo para ser meu modelo?"
  },
  Voice_100371_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_100372_AwakerVoiceContent = {
    Text = "A filosofia artística em que acredito é louca e inquieta, a música de Hameln é completamente diferente, rigorosa como aquelas lápides de cemitérios mortos. Mas não sei por que, sempre consigo ver a mais intensa confusão nas notas organizadas..."
  },
  Voice_100372_AwakerVoiceTitle = {
    Text = "Conversa: sobre Hameln"
  },
  Voice_100372_UnlockDesc = {
    Text = "Desbloqueia ao obter o despertador \"Hameln\""
  },
  Voice_100373_AwakerVoiceContent = {
    Text = "Veja, Guardião! Aquela visão eterna e louca na tela, quão emocionante, quão desesperadora! É na loucura e na dor suprema que floresce a verdadeira arte..."
  },
  Voice_100373_AwakerVoiceTitle = {
    Text = "Iluminar·Florescer"
  },
  Voice_100373_UnlockDesc = {
    Text = "Nível de iluminação atingiu 15 para desbloquear"
  },
  Voice_100374_AwakerVoiceContent = {
    Text = "Ah! Desculpe, Guardião do Segredo... Eu vi uma visão sem precedentes em você... mais aterrorizante do que o abismo, mais fascinante do que o abismo..."
  },
  Voice_100374_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexão"
  },
  Voice_100374_UnlockDesc = {
    Text = "Nível de iluminação atingiu 3 para desbloquear"
  },
  Voice_100375_AwakerVoiceContent = {
    Text = "Não entendo, se os humanos tivessem a oportunidade, por que não se tornariam ghouls? Essa beleza insana e ensanguentada não é muito mais interessante do que ser um humano sem paixão em uma mansão?!"
  },
  Voice_100375_AwakerVoiceTitle = {
    Text = "Conversa·Coisas favoritas"
  },
  Voice_100376_AwakerVoiceContent = {Text = "Ha!"},
  Voice_100376_AwakerVoiceTitle = {Text = "Ataque·Um"},
  Voice_116964_AwakerVoiceContent = {
    Text = "Punição dos pecados!"
  },
  Voice_116964_AwakerVoiceTitle = {
    Text = "Habilidade Especial · Um"
  },
  Voice_116965_AwakerVoiceContent = {
    Text = "Punição dos pecados!"
  },
  Voice_116965_AwakerVoiceTitle = {
    Text = "Habilidade Especial · Dois"
  },
  Voice_117791_AwakerVoiceContent = {
    Text = "Eu admito que ela tem um certo talento para roubar, mas uma dama não precisa de truques tão mesquinhos. O que eu quero, as pessoas podem me dar \"voluntariamente\", não é?"
  },
  Voice_117791_AwakerVoiceTitle = {
    Text = "Fofocas · Sobre Jenki"
  },
  Voice_117791_UnlockDesc = {
    Text = "Desbloqueado após adquirir o Despertar \"Jenkin\""
  },
  Voice_117792_AwakerVoiceContent = {
    Text = "Hahaha, meu, meu, todas as doces de Misaq são minhas agora! O que você está esperando? Venha comigo, bruxa, vamos nos preparar para conquistar todas as confeitarias de Londinium!"
  },
  Voice_117792_AwakerVoiceTitle = {
    Text = "Iluminar·Florescer"
  },
  Voice_117792_UnlockDesc = {
    Text = "Nível de iluminação atingiu 15 para desbloquear"
  },
  Voice_117793_AwakerVoiceContent = {
    Text = "Não vai dar? Então a bruxa vai levar isso a sério!"
  },
  Voice_117793_AwakerVoiceTitle = {
    Text = "Sobre-Exaltação Aliemus Explosão·II"
  },
  Voice_117794_AwakerVoiceContent = {
    Text = "Você disse como o recheio desses doces é colocado dentro, não há fendas ou furos visíveis. Eu realmente gostaria que a pessoa que inventou esses doces trabalhasse no restaurante de Misaq, criando uma nova sobremesa para mim todos os dias!"
  },
  Voice_117794_AwakerVoiceTitle = {
    Text = "Atualizar·II"
  },
  Voice_117795_AwakerVoiceContent = {
    Text = "Você irritou a bruxa!"
  },
  Voice_117795_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_117796_AwakerVoiceContent = {
    Text = "Antes, eu sempre achei que os doces eram muito simples e não tão elegantes em comparação aos bolos, mas agora vejo que subestimei essas pequenas coisas coloridas dentro de papéis plásticos. Especialmente em comparação aos bolos, esses doces têm uma vida útil muito mais longa, e não tenho medo de estocar quantos quiser, realmente quero encher toda a casa com eles!"
  },
  Voice_117796_AwakerVoiceTitle = {
    Text = "Conversa·Coisas favoritas"
  },
  Voice_117797_AwakerVoiceContent = {
    Text = "Você encontrou um novo tipo de doce? Deixa eu ver... O que é isso? Esse doce em forma de anel é muito engraçado, onde já se viu um diamante tão grande quanto um ovo! Espera, o que você quer dizer com me dar um anel? Me explica direito!"
  },
  Voice_117797_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Quatro"
  },
  Voice_117797_UnlockDesc = {
    Text = "Nível de afinidade atingido 8 desbloqueado"
  },
  Voice_117798_AwakerVoiceContent = {
    Text = "Ouvi dizer que as bruxas geralmente têm um gato preto misterioso ao seu lado. Escolher aquele gato selvagem do campus realmente é muito embaraçoso para uma dama. Decidido, você vai usar a tiara de orelhas de gato e agir como meu pequeno gato preto."
  },
  Voice_117798_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Três"
  },
  Voice_117798_UnlockDesc = {
    Text = "Nível de afinidade atingido 6 desbloqueado"
  },
  Voice_117799_AwakerVoiceContent = {
    Text = "Resistir é inútil."
  },
  Voice_117799_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_117800_AwakerVoiceContent = {
    Text = "Humm, humm, humm!"
  },
  Voice_117800_AwakerVoiceTitle = {
    Text = "Defesa · I"
  },
  Voice_117801_AwakerVoiceContent = {
    Text = "Será que existem bruxas no mundo? Elas vivem sozinhas em florestas onde não há nem sombra de pessoas, quem cozinha para elas, lava suas roupas e prepara sobremesas? Se nem mesmo podem tomar um chá da tarde, qual é o sentido de uma vida assim? Só de pensar nisso já não aguento mais."
  },
  Voice_117801_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Um"
  },
  Voice_117801_UnlockDesc = {
    Text = "Nível de afinidade atingido 2 desbloqueado"
  },
  Voice_117802_AwakerVoiceContent = {
    Text = "A bruxa chegou!"
  },
  Voice_117802_AwakerVoiceTitle = {Text = "Ataque·Um"},
  Voice_117803_AwakerVoiceContent = {
    Text = "Você ainda tem chocolate na mão? Ótimo, me dê tudo. O que aconteceu? Suas coisas são minhas, isso não é natural?"
  },
  Voice_117803_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_117803_UnlockDesc = {
    Text = "Nível de iluminação atingiu 2 para desbloquear"
  },
  Voice_117804_AwakerVoiceContent = {
    Text = "Você me pergunta qual é o meu doce favorito? Deixe-me pensar, o sabor do doce de avelã é muito bom, o chocolate de caramelo também é delicioso, os doces macios de morango e uva têm uma textura interessante, e tem um tipo de açúcar de malte que pode ser esticado bem longo, com uma cor tão bonita quanto o mel... Não dá, não consigo escolher, cada doce tem sua própria característica, de qualquer forma, a cesta de abóbora tem bastante, eu quero todos!"
  },
  Voice_117804_AwakerVoiceTitle = {
    Text = "Iluminar: Insight"
  },
  Voice_117804_UnlockDesc = {
    Text = "Nível de iluminação atingiu 7 para desbloquear"
  },
  Voice_117805_AwakerVoiceContent = {
    Text = "Meu objetivo de vida agora é experimentar todos os doces do mundo. Só de pensar que existem tantas variedades de doces esperando por mim, fico cheio de motivação para levantar da cama todos os dias. Você mencionou bolo? Bolo é outro dos meus objetivos de vida."
  },
  Voice_117805_AwakerVoiceTitle = {
    Text = "Iluminar·Construção"
  },
  Voice_117805_UnlockDesc = {
    Text = "Nível de iluminação atingiu 11 para desbloquear"
  },
  Voice_117806_AwakerVoiceContent = {
    Text = "Não se deixe enganar pela aparência de criança dele, na verdade ele é tão velho que já poderia estar enterrado. Não fale de doces, ele não se interessaria por nada que uma pessoa viva goste. Portanto, em vez de enviar aqueles doces para ele, por que não me dá todos? Eu sou a que menos desapontaria eles."
  },
  Voice_117806_AwakerVoiceTitle = {
    Text = "Papo reto · Sobre Tulu"
  },
  Voice_117806_UnlockDesc = {
    Text = "Desbloqueado após obter o Despertador \"Tulu\""
  },
  Voice_117807_AwakerVoiceContent = {
    Text = "Se eu fosse uma bruxa, com certeza seria uma bruxa que mora em um palácio luxuoso, onde sempre houvesse muita agitação, e contrataria dez dos melhores chefs para me fazer bolos e doces diferentes todos os dias... Você está dizendo que isso se chama princesa? E daí, eu posso ser uma bruxa princesa!"
  },
  Voice_117807_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Dois"
  },
  Voice_117807_UnlockDesc = {
    Text = "Nível de afinidade atingido 4 desbloqueado"
  },
  Voice_117808_AwakerVoiceContent = {
    Text = "Ei, prepare algumas pastas de dente para mim, rápido. Não, eu não comi muito açúcar, eu não tenho cáries, só estou com um pouquinho de dor à noite quando durmo..."
  },
  Voice_117808_AwakerVoiceTitle = {
    Text = "Conversa·Sobre balas"
  },
  Voice_117809_AwakerVoiceContent = {
    Text = "Embora as regras do refeitório de Misaq muitas vezes sejam irritantes, a habilidade deles em fazer sobremesas, hm... é até que aceitável."
  },
  Voice_117809_AwakerVoiceTitle = {
    Text = "Chat·Sobre a Universidade Mythag"
  },
  Voice_117810_AwakerVoiceContent = {
    Text = "Neste mundo existem tantos lugares escuros e nojentos; em vez de se preocupar com a destruição do mundo, é melhor comer mais alguns pedaços de doce antes que isso aconteça."
  },
  Voice_117810_AwakerVoiceTitle = {
    Text = "Bate-papo · Sobre Dissolução"
  },
  Voice_117811_AwakerVoiceContent = {Text = "Ai!"},
  Voice_117811_AwakerVoiceTitle = {
    Text = "Acertar·III"
  },
  Voice_117812_AwakerVoiceContent = {
    Text = "Embora agora não haja mais aqueles tapetes de lã de cordeiro, colares de pérolas negras do mar e pijamas de seda oriental, acordar todos os dias em um quarto cheio de doces, onde ao estender a mão você pode tocar uma cesta de abóbora cheia, talvez essa seja a verdadeira forma de felicidade... Ei, não ria tão orgulhosamente, você deve continuar a servir esta senhorita, ainda precisa se esforçar mais!"
  },
  Voice_117812_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Cinco"
  },
  Voice_117812_UnlockDesc = {
    Text = "Nível de afinidade atingido 10 desbloqueado"
  },
  Voice_117813_AwakerVoiceContent = {
    Text = "Maldito Misaq, ousou me impedir de pegar os doces, mas veja, não consegui comer?"
  },
  Voice_117813_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · I"
  },
  Voice_117814_AwakerVoiceContent = {
    Text = "O que você quer? Quer comer minhas balas? Humpf, não que eu não possa ser generosa e te dar algumas, venha, chame-me de Senhora Bruxa!"
  },
  Voice_117814_AwakerVoiceTitle = {
    Text = "Conversa·Toque"
  },
  Voice_117815_AwakerVoiceContent = {
    Text = "Como isso pode ser chamado de roubo? Eu estou apenas exercendo o nobre poder de uma dama."
  },
  Voice_117815_AwakerVoiceTitle = {
    Text = "Despertar do Conhecimento Espiritual"
  },
  Voice_117816_AwakerVoiceContent = {
    Text = "A bruxa doce da justiça chegou, todos os doces perdidos devem voltar ao seu devido lugar!"
  },
  Voice_117816_AwakerVoiceTitle = {
    Text = "Início da Investigação"
  },
  Voice_117817_AwakerVoiceContent = {
    Text = "Maldito, pão-duro, a bruxa vai se lembrar de você..."
  },
  Voice_117817_AwakerVoiceTitle = {
    Text = "Investigação Interrompida"
  },
  Voice_117818_AwakerVoiceContent = {
    Text = "Por que aquele ratinho pode vasculhar doces à vontade, enquanto eu não posso? Isso é discriminação contra uma dama! Desrespeito!"
  },
  Voice_117818_AwakerVoiceTitle = {
    Text = "Conversa·Coisas odiadas"
  },
  Voice_117819_AwakerVoiceContent = {
    Text = "Não vai dar? Então a bruxa vai levar a sério!"
  },
  Voice_117819_AwakerVoiceTitle = {
    Text = "Superexaltação"
  },
  Voice_117820_AwakerVoiceContent = {
    Text = "Vou te dar doces!"
  },
  Voice_117820_AwakerVoiceTitle = {Text = "Ataque·II"},
  Voice_117821_AwakerVoiceContent = {
    Text = "Comparado com os garçons daqueles restaurantes, você é o mais compreensivo, sabe preparar especialmente para mim uma porção de açúcar. Continue assim, meu servo exclusivo."
  },
  Voice_117821_AwakerVoiceTitle = {
    Text = "Iluminar·Visão Remota"
  },
  Voice_117821_UnlockDesc = {
    Text = "Nível de iluminação atingiu 1 para desbloquear"
  },
  Voice_117822_AwakerVoiceContent = {
    Text = "Ligeiramente!"
  },
  Voice_117822_AwakerVoiceTitle = {Text = "Defesa·II"},
  Voice_117823_AwakerVoiceContent = {Text = "Exagero!"},
  Voice_117823_AwakerVoiceTitle = {Text = "Acertar·1"},
  Voice_117824_AwakerVoiceContent = {
    Text = "Por que você está me impedindo? Como meu fiel servo, você não deveria me ajudar a pegar todos os doces... e trazê-los para mim?"
  },
  Voice_117824_AwakerVoiceTitle = {
    Text = "Conversa·Sobre Guardião do Segredo"
  },
  Voice_117825_AwakerVoiceContent = {
    Text = "Pare! Assalto! É melhor você se comportar e entregar todos os doces, caso contrário, hum..."
  },
  Voice_117825_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_117826_AwakerVoiceContent = {
    Text = "Mole, duro, crocante, quebradiço, sabor de leite, sabor de fruta, sabor de noz, sabor de chocolate... Ah, como pode haver tantas variedades de doces que eu nunca comi no mundo? Decidido, vamos propor a Misaq para celebrarmos o Dia de Todos os Santos uma vez por semana!"
  },
  Voice_117826_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · Três"
  },
  Voice_117827_AwakerVoiceContent = {Text = "(Gemido)"},
  Voice_117827_AwakerVoiceTitle = {
    Text = "Golpe·Quatro"
  },
  Voice_117828_AwakerVoiceContent = {
    Text = "A grande bruxa certamente vencerá! O deus dos doces me abençoa, e eu, abençoo todos os doces! Ahahahaha!"
  },
  Voice_117828_AwakerVoiceTitle = {
    Text = "Investigação Bem-sucedida"
  },
  Voice_117829_AwakerVoiceContent = {
    Text = "Resistir não adianta."
  },
  Voice_117829_AwakerVoiceTitle = {
    Text = "Carta de Habilidade·Quatro"
  },
  Voice_117830_AwakerVoiceContent = {
    Text = "Todos os doces acabarão pertencendo a mim!"
  },
  Voice_117830_AwakerVoiceTitle = {
    Text = "Exaltar · Dois"
  },
  Voice_117831_AwakerVoiceContent = {
    Text = "Aquela criança é tão obediente que chega a ser assustador. Sempre que você pede doces a ela, ela dá, e nem deixa um para si mesma, o que deixa a gente até meio envergonhado... Ahem, quero dizer, já que ela é tão sensível, a gentil bruxa, é claro, deixará alguns como recompensa."
  },
  Voice_117831_AwakerVoiceTitle = {
    Text = "Fala Ociosa · Sobre Lily"
  },
  Voice_117831_UnlockDesc = {
    Text = "Desbloqueado após adquirir o Despertar \"Lily\""
  },
  Voice_117832_AwakerVoiceContent = {
    Text = "Você irritou a bruxa!"
  },
  Voice_117832_AwakerVoiceTitle = {
    Text = "Habilidade·Um"
  },
  Voice_117833_AwakerVoiceContent = {
    Text = "Estou com raiva!"
  },
  Voice_117833_AwakerVoiceTitle = {
    Text = "Acertar · II"
  },
  Voice_117834_AwakerVoiceContent = {
    Text = "Todas as doces um dia me pertencerão!"
  },
  Voice_117834_AwakerVoiceTitle = {
    Text = "Fúria Explosiva"
  },
  Voice_117835_AwakerVoiceContent = {
    Text = "O que você está dizendo, esse algodão doce pode ser assado? Hã, quente e pegajoso, será que é gostoso? Deixa eu provar? Tudo bem, então vou me esforçar para experimentar um pedaço, se você me enganar... Hm?! Essa textura crocante e macia, que delícia!"
  },
  Voice_117835_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexão"
  },
  Voice_117835_UnlockDesc = {
    Text = "Nível de iluminação atingiu 3 para desbloquear"
  },
  Voice_122115_AwakerVoiceContent = {
    Text = "Ilusão, perversão, é o destino!"
  },
  Voice_122115_AwakerVoiceTitle = {
    Text = "Superexaltação"
  },
  Voice_122117_AwakerVoiceContent = {
    Text = "Ilusão, perversão, é o destino!"
  },
  Voice_122117_AwakerVoiceTitle = {
    Text = "Sobre-Exaltação Aliemus Explosão·II"
  },
  Voice_123312_AwakerVoiceContent = {
    Text = "Porque você enfrentou o verdadeiro terror, não terá medo do verdadeiro eu? Hmph, essa é uma resposta bastante inteligente, mas também me deixa... cada vez mais curioso sobre você."
  },
  Voice_123312_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Quatro"
  },
  Voice_123312_UnlockDesc = {
    Text = "Nível de afinidade atingido 8 desbloqueado"
  },
  Voice_123313_AwakerVoiceContent = {
    Text = "Como é o mundo aos seus olhos? Onde estão aqueles extremos aterrorizantes? Não, eu não quero ouvir você descrevê-lo; eu quero vivenciá-lo com você— a loucura, a morte, o horror. Eu tomei minha decisão! Não vou te deixar até que minha curiosidade esteja satisfeita."
  },
  Voice_123313_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Cinco"
  },
  Voice_123313_UnlockDesc = {
    Text = "Nível de afinidade atingido 10 desbloqueado"
  },
  Voice_123314_AwakerVoiceContent = {
    Text = "Um lunático incontrolável? Você está certo. Este não é o meu mundo; não há leis ou regras chatas aqui... Aqui, posso fazer o que eu quiser, então Guardião, é melhor você ter cuidado—não seja mordido por um lunático fora de controle."
  },
  Voice_123314_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Três"
  },
  Voice_123314_UnlockDesc = {
    Text = "Nível de afinidade atingido 6 desbloqueado"
  },
  Voice_123315_AwakerVoiceContent = {
    Text = "Para o bem da minha saúde mental e física, você quer ter uma conversa profunda? Certo, vamos começar rápido—essa coisa chata, quanto mais cedo começarmos, mais cedo termina."
  },
  Voice_123315_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Um"
  },
  Voice_123315_UnlockDesc = {
    Text = "Nível de afinidade atingido 2 desbloqueado"
  },
  Voice_123316_AwakerVoiceContent = {
    Text = "Eu estava apenas fingindo ser uma pessoa normal para responder à sua pergunta? Ah, você me descobriu—então, você está pronto para ver minha verdadeira forma?"
  },
  Voice_123316_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Dois"
  },
  Voice_123316_UnlockDesc = {
    Text = "Nível de afinidade atingido 4 desbloqueado"
  },
  Voice_123770_AwakerVoiceContent = {
    Text = "Corte sua cabeça."
  },
  Voice_123770_AwakerVoiceTitle = {Text = "Ataque·Um"},
  Voice_123771_AwakerVoiceContent = {
    Text = "Todos, jovens e velhos, adoram isso! Tornado Brilhante☆—!!"
  },
  Voice_123771_AwakerVoiceTitle = {
    Text = "Exaltar · Dois"
  },
  Voice_123772_AwakerVoiceContent = {
    Text = "Não deveria ser eu caindo..."
  },
  Voice_123772_AwakerVoiceTitle = {Text = "Acertar·1"},
  Voice_123773_AwakerVoiceContent = {
    Text = "Impacto da tempestade!"
  },
  Voice_123773_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_123774_AwakerVoiceContent = {
    Text = "Você quer salvar este mundo distorcido e aterrorizante? Que maneira louca e interessante de morrer—vamos ver até onde você consegue ir."
  },
  Voice_123774_AwakerVoiceTitle = {
    Text = "Conversa·Sobre Guardião do Segredo"
  },
  Voice_123775_AwakerVoiceContent = {
    Text = "Ei, pequenos, querem experimentar meu machado? Não se preocupem, já está chegando..."
  },
  Voice_123775_AwakerVoiceTitle = {
    Text = "Início da Investigação"
  },
  Voice_123776_AwakerVoiceContent = {
    Text = "Guardião, parece que vi a luz. Poderia ser que desta vez... Eu me pergunto como estão meus colegas da equipe de investigação? Por favor, não deixem uma tonelada de trabalho para mim; eu realmente não quero fazer hora extra."
  },
  Voice_123776_AwakerVoiceTitle = {
    Text = "Iluminar: Insight"
  },
  Voice_123776_UnlockDesc = {
    Text = "Nível de iluminação atingiu 7 para desbloquear"
  },
  Voice_123777_AwakerVoiceContent = {
    Text = "Posso voltar para casa através deste ritual? Você tem certeza? Quantas vezes já foi... Bem, não custa nada tentar de qualquer maneira."
  },
  Voice_123777_AwakerVoiceTitle = {
    Text = "Iluminar·Visão Remota"
  },
  Voice_123777_UnlockDesc = {
    Text = "Nível de iluminação atingiu 1 para desbloquear"
  },
  Voice_123778_AwakerVoiceContent = {
    Text = "Haha, parece que essa vida cheia de adrenalina me cai muito melhor do que a rotina diária entediante!"
  },
  Voice_123778_AwakerVoiceTitle = {
    Text = "Sobre-Exaltação Aliemus Explosão·II"
  },
  Voice_123779_AwakerVoiceContent = {Text = "Ha!"},
  Voice_123779_AwakerVoiceTitle = {Text = "Ataque·II"},
  Voice_123780_AwakerVoiceContent = {
    Text = "Não deveria ser eu caindo..."
  },
  Voice_123780_AwakerVoiceTitle = {
    Text = "Acertar·III"
  },
  Voice_123781_AwakerVoiceContent = {
    Text = "Tornado Brilhante☆—Radiar!"
  },
  Voice_123781_AwakerVoiceTitle = {
    Text = "Habilidade·Um"
  },
  Voice_123782_AwakerVoiceContent = {
    Text = "Todos, jovens e velhos, adoram isso! Tornado Brilhante☆—!!"
  },
  Voice_123782_AwakerVoiceTitle = {
    Text = "Fúria Explosiva"
  },
  Voice_123783_AwakerVoiceContent = {
    Text = "Agora, sinto... como se estivesse entrando na névoa. Falando em névoa, isso me lembra aqueles pequenos caras na névoa. É uma pena que eu não possa desabafar meus sentimentos com eles quando estou de mau humor."
  },
  Voice_123783_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_123783_UnlockDesc = {
    Text = "Nível de iluminação atingiu 2 para desbloquear"
  },
  Voice_123784_AwakerVoiceContent = {
    Text = "Ódio? Eu não diria isso. Apenas espero sinceramente que todas aquelas reuniões tediosas, encontros sociais e valores universais desapareçam."
  },
  Voice_123784_AwakerVoiceTitle = {
    Text = "Conversa·Coisas odiadas"
  },
  Voice_123785_AwakerVoiceContent = {
    Text = "É isso... eu sinto que estou me aproximando do meu \"eu verdadeiro\"."
  },
  Voice_123785_AwakerVoiceTitle = {
    Text = "Atualizar·II"
  },
  Voice_123786_AwakerVoiceContent = {
    Text = "Ah, uma falha que era de se esperar. A vida tem seus altos e baixos, você vai se acostumar com isso... Mas ainda assim, obrigado por tentar desta vez."
  },
  Voice_123786_AwakerVoiceTitle = {
    Text = "Iluminar·Construção"
  },
  Voice_123786_UnlockDesc = {
    Text = "Nível de iluminação atingiu 11 para desbloquear"
  },
  Voice_123787_AwakerVoiceContent = {
    Text = "Assim como o desastre da névoa, eu não sei nada sobre a Dissolução. É isso que a torna tão fascinante, não é?"
  },
  Voice_123787_AwakerVoiceTitle = {
    Text = "Conversa fiada·Sobre a crise"
  },
  Voice_123788_AwakerVoiceContent = {
    Text = "Mouchette, a equipe de investigação... oh não, eu não sou mais a vanguarda da equipe de investigação. Então, deixe-me me reintroduzir—meu nome é Mouchette, apenas uma menina adorável~"
  },
  Voice_123788_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_123789_AwakerVoiceContent = {
    Text = "Vá embora!"
  },
  Voice_123789_AwakerVoiceTitle = {Text = "Defesa·II"},
  Voice_123790_AwakerVoiceContent = {
    Text = "Aqui está muito perto de assentamentos humanos, com adultos entediantes por toda parte... Você já pensou em mudar a escola para uma floresta remota e desabitada?"
  },
  Voice_123790_AwakerVoiceTitle = {
    Text = "Conversa·Sobre Missaga"
  },
  Voice_123791_AwakerVoiceContent = {Text = "(Gemido)"},
  Voice_123791_AwakerVoiceTitle = {
    Text = "Golpe·Quatro"
  },
  Voice_123792_AwakerVoiceContent = {
    Text = "Estou prestes a me apaixonar por essa sensação de flutuar em outro mundo, os poderosos Despertadores, a aterrorizante erosão e as divindades desconhecidas! Ah, tudo é um alívio longe da sociedade comum!"
  },
  Voice_123792_AwakerVoiceTitle = {
    Text = "Conversa·Coisas favoritas"
  },
  Voice_123793_AwakerVoiceContent = {
    Text = "Tem mais? Estou me divertindo—apressa-te, alguém me deixe cortar mais um machado."
  },
  Voice_123793_AwakerVoiceTitle = {
    Text = "Investigação Bem-sucedida"
  },
  Voice_123794_AwakerVoiceContent = {Text = "(Gemido)"},
  Voice_123794_AwakerVoiceTitle = {
    Text = "Acertar · II"
  },
  Voice_123795_AwakerVoiceContent = {
    Text = "Uma falha não significa nada... estou apenas brincando. É melhor vocês limparem o pescoço e me aguardarem!"
  },
  Voice_123795_AwakerVoiceTitle = {
    Text = "Investigação Interrompida"
  },
  Voice_123796_AwakerVoiceContent = {
    Text = "Tem uma tarefa? Não precisa cumprimentar da próxima vez, já estamos familiarizados o suficiente para não fazer a \"rotina de cumprimentos sociais.\""
  },
  Voice_123796_AwakerVoiceTitle = {
    Text = "Conversa·Toque"
  },
  Voice_123797_AwakerVoiceContent = {
    Text = "Sacrificar-se pelos outros é realmente uma ideia tola e irritante. Ninguém tem o direito de exigir isso dos outros, nem mesmo os deuses."
  },
  Voice_123797_AwakerVoiceTitle = {
    Text = "Conversa fiada: Sobre o Salvador"
  },
  Voice_123797_UnlockDesc = {
    Text = "Desbloqueado após adquirir o Despertar \"Salvador\""
  },
  Voice_123798_AwakerVoiceContent = {
    Text = "Nada mal mesmo—"
  },
  Voice_123798_AwakerVoiceTitle = {
    Text = "Defesa · I"
  },
  Voice_123799_AwakerVoiceContent = {
    Text = "Finalmente, nada de fingir mais... Agora, vamos nos divertir."
  },
  Voice_123799_AwakerVoiceTitle = {
    Text = "Despertar do Conhecimento Espiritual"
  },
  Voice_123800_AwakerVoiceContent = {
    Text = "O ritual ainda não acabou? Eu realmente quero voltar rápido para comer um ensopado ravenloft e uma xícara fumegante de chá kava com avelã. Claro, o chá preto do Ceilão e os doces andaluzes aqui também são bem agradáveis."
  },
  Voice_123800_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexão"
  },
  Voice_123800_UnlockDesc = {
    Text = "Nível de iluminação atingiu 3 para desbloquear"
  },
  Voice_123801_AwakerVoiceContent = {
    Text = "Sempre aprimorando minhas habilidades, você não tem medo de que um dia eu possa perder o controle...? Haha, estou apenas brincando."
  },
  Voice_123801_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · I"
  },
  Voice_123802_AwakerVoiceContent = {
    Text = "Na verdade, ficar neste mundo por um tempo não é tão ruim. Vou lembrar de tudo que acontece aqui e escrever, para poder compartilhar com todos em casa quando voltar. Hmm, vamos chamar de \"A Aventura de Mouchette em Outro Mundo.\" Parece ótimo, não é?"
  },
  Voice_123802_AwakerVoiceTitle = {
    Text = "Iluminar·Florescer"
  },
  Voice_123802_UnlockDesc = {
    Text = "Nível de iluminação atingiu 15 para desbloquear"
  },
  Voice_123803_AwakerVoiceContent = {
    Text = "Eu admito que ela é muito fofa... Sim, é verdade, vê-la correr e brigar com aqueles gatos de rua que andam pelo campus é realmente adorável."
  },
  Voice_123803_AwakerVoiceTitle = {
    Text = "Conversa: Sobre Murphy"
  },
  Voice_123803_UnlockDesc = {
    Text = "Desbloqueado após obter Despertador \"Murphy\""
  },
  Voice_123804_AwakerVoiceContent = {
    Text = "Embora este poder não me permita retornar ao meu mundo, ficar mais forte é sempre algo bom."
  },
  Voice_123804_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · Três"
  },
  Voice_123805_AwakerVoiceContent = {
    Text = "Empregada, eu também fiz isso; vamos encontrar um momento para ela ver meu método de lutar com um aspirador de pó!"
  },
  Voice_123805_AwakerVoiceTitle = {
    Text = "Chat: Sobre Karen"
  },
  Voice_123805_UnlockDesc = {
    Text = "Após obter o despertador \"Karen\", desbloqueado"
  },
  Voice_123806_AwakerVoiceContent = {
    Text = "Haha, parece que essa vida cheia de adrenalina me cai muito melhor do que a rotina diária entediante!"
  },
  Voice_123806_AwakerVoiceTitle = {
    Text = "Superexaltação"
  },
  Voice_124737_AwakerVoiceContent = {
    Text = "Um golpe, uma morte."
  },
  Voice_124737_AwakerVoiceTitle = {
    Text = "Habilidade Especial · Dois"
  },
  Voice_124738_AwakerVoiceContent = {
    Text = "Alinhem-se um a um."
  },
  Voice_124738_AwakerVoiceTitle = {
    Text = "Habilidade Especial · Um"
  },
  Voice_124769_AwakerVoiceContent = {
    Text = "Desaparecer!"
  },
  Voice_124769_AwakerVoiceTitle = {
    Text = "Habilidade Especial · Um"
  },
  Voice_126946_AwakerVoiceContent = {
    Text = "Não pense ou perturbe, ouça e obedeça cegamente, pois o mundo mundano não é nada além de um fardo!"
  },
  Voice_126946_AwakerVoiceTitle = {
    Text = "Superexaltação"
  },
  Voice_126947_AwakerVoiceContent = {
    Text = "Não pense ou perturbe, ouça e obedeça cegamente, pois o mundo mundano não é nada além de um fardo!"
  },
  Voice_126947_AwakerVoiceTitle = {
    Text = "Sobre-Exaltação Aliemus Explosão·II"
  },
  Voice_126948_AwakerVoiceContent = {
    Text = "Você pergunta a eles por que suas cabeças estão vazias? Bem, talvez eles tenham nascido assim."
  },
  Voice_126948_AwakerVoiceTitle = {
    Text = "Investigação Bem-sucedida"
  },
  Voice_126949_AwakerVoiceContent = {
    Text = "Cesse sua raiva e ressentimento, pois todas as coisas se tornarão em nada."
  },
  Voice_126949_AwakerVoiceTitle = {
    Text = "Fúria Explosiva"
  },
  Voice_126950_AwakerVoiceContent = {
    Text = "Tal atenção me faz não conseguir resistir a querer provocá-lo mais."
  },
  Voice_126950_AwakerVoiceTitle = {
    Text = "Atualizar·II"
  },
  Voice_126951_AwakerVoiceContent = {Text = "Oops!"},
  Voice_126951_AwakerVoiceTitle = {
    Text = "Acertar·III"
  },
  Voice_126952_AwakerVoiceContent = {
    Text = "Você espera que eu seja mais bonita ou mais aterrorizante?"
  },
  Voice_126952_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · I"
  },
  Voice_126953_AwakerVoiceContent = {
    Text = "A princesa nascida da alegria, seu vestido bordado com fios de ouro, sua pele semelhante ao marfim, com a fragrância de madeira de ágar pairando ao seu redor, cativa a todos com seu olhar encantador."
  },
  Voice_126953_AwakerVoiceTitle = {
    Text = "Iluminar·Visão Remota"
  },
  Voice_126953_UnlockDesc = {
    Text = "Nível de iluminação atingiu 1 para desbloquear"
  },
  Voice_126954_AwakerVoiceContent = {
    Text = "Logo ela ficou cansada dessa diversão, pois seus crentes simplesmente repetiam as mesmas rotinas, entregando-se ao amor nascido do desejo, ou ao desejo nascido do amor. A dor da perda e da traição os fazia desejar a morte, e a tolice deles a entediava, enquanto suas lágrimas também a exauriam."
  },
  Voice_126954_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexão"
  },
  Voice_126954_UnlockDesc = {
    Text = "Nível de iluminação atingiu 3 para desbloquear"
  },
  Voice_126955_AwakerVoiceContent = {
    Text = "Seus olhares mesquinhos realmente me fazem sentir nojo."
  },
  Voice_126955_AwakerVoiceTitle = {
    Text = "Início da Investigação"
  },
  Voice_126956_AwakerVoiceContent = {
    Text = "A Madame de Vermelho me enviou vários convites para seu salão. \n O sabor dos doces exóticos é bastante bom, mas... \n Ela deveria ter me avisado antes que em sua residência, petiscos e criadas não significam a mesma coisa."
  },
  Voice_126956_AwakerVoiceTitle = {
    Text = "Chat: Sobre Sorel"
  },
  Voice_126956_UnlockDesc = {
    Text = "Desbloqueado após obter Despertar\"Sorel\""
  },
  Voice_126958_AwakerVoiceContent = {
    Text = "Não é amor? Então, por que o medo quando cercado? Não é desprezo? Então, por que as lágrimas quando é para sempre inalcançável?\nAh, você agora tem medo da minha sombra? O perfume da magnólia branca se tornou um almíscar enjoativo e inexplicável para você?"
  },
  Voice_126958_AwakerVoiceTitle = {
    Text = "Iluminar·Construção"
  },
  Voice_126958_UnlockDesc = {
    Text = "Nível de iluminação atingiu 11 para desbloquear"
  },
  Voice_126959_AwakerVoiceContent = {
    Text = "...Tá bom!"
  },
  Voice_126959_AwakerVoiceTitle = {
    Text = "Acertar · II"
  },
  Voice_126960_AwakerVoiceContent = {
    Text = "Hã? Você está me perguntando por que eles têm aqueles padrões debaixo das axilas? Você não acha isso realmente divertido?"
  },
  Voice_126960_AwakerVoiceTitle = {
    Text = "Chat: A Ordem da Graça do Inchaço"
  },
  Voice_126961_AwakerVoiceContent = {Text = "Oops!"},
  Voice_126961_AwakerVoiceTitle = {Text = "Acertar·1"},
  Voice_126963_AwakerVoiceContent = {
    Text = "Comparado às ofertas dos crentes, estas são mais do meu agrado."
  },
  Voice_126963_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · Três"
  },
  Voice_126964_AwakerVoiceContent = {
    Text = "Primeiro a postura, depois a figura, até que também possuíssem um par... ou melhor, o que restava para ser lembrado era um par de olhos belos e comoventes—assim como os meus."
  },
  Voice_126964_AwakerVoiceTitle = {
    Text = "Iluminar: Insight"
  },
  Voice_126964_UnlockDesc = {
    Text = "Nível de iluminação atingiu 7 para desbloquear"
  },
  Voice_126965_AwakerVoiceContent = {
    Text = "Estou realmente entediado hoje. Você não tem nenhum desejo que precise ser realizado?\nÉ uma pena que muitas pessoas estejam dispostas a empunhar suas foices e oferecer sangue e carne para mim, tudo por alguns propósitos chatos.\nMas se fosse você..."
  },
  Voice_126965_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Dois"
  },
  Voice_126965_UnlockDesc = {
    Text = "Nível de afinidade atingido 4 desbloqueado"
  },
  Voice_126966_AwakerVoiceContent = {
    Text = "Por que a Forma volumosa me segue, e qual foi sua gênese? Uma pergunta divertida. Você também conheceu a pessoa inalcançável, ou o arrependimento de uma luta fracassada?\nHmm, parece que não. Que desperdício. Aquela expressão de luta desesperada — seria tão divertido contemplá-la em seu rosto."
  },
  Voice_126966_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Três"
  },
  Voice_126966_UnlockDesc = {
    Text = "Nível de afinidade atingido 6 desbloqueado"
  },
  Voice_126967_AwakerVoiceContent = {
    Text = "...Se você continuar sendo tão presunçoso, o que eu usar para enfrentá-lo pode não ser essa postura."
  },
  Voice_126967_AwakerVoiceTitle = {
    Text = "Conversa·Toque"
  },
  Voice_126968_AwakerVoiceContent = {
    Text = "A história dela, eu quase a esqueci completamente, mas é uma história de alegria, uma história de crueldade, uma história que começa com abandono e retribuição, e depois se torna uma de sacrifício e obediência."
  },
  Voice_126968_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_126968_UnlockDesc = {
    Text = "Nível de iluminação atingiu 2 para desbloquear"
  },
  Voice_126969_AwakerVoiceContent = {
    Text = "Por favor, me satisfaça, e deixe a dor e o medo te levarem a se matarem uns aos outros~"
  },
  Voice_126969_AwakerVoiceTitle = {
    Text = "Habilidade·Um"
  },
  Voice_126970_AwakerVoiceContent = {
    Text = "...Isso realmente despertou um pouco do meu interesse."
  },
  Voice_126970_AwakerVoiceTitle = {
    Text = "Investigação Interrompida"
  },
  Voice_126971_AwakerVoiceContent = {
    Text = "Todos verão o rosto de seu amado sob meu leque. Eu empresto este poder aos fracos, tornando-me uma lâmina para diversão. \n Mas talvez, eu esteja apenas dizendo, talvez. \n Se você estiver disposto a ser cativado por isso, sentirei um êxtase verdadeiro e supremo."
  },
  Voice_126971_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Cinco"
  },
  Voice_126971_UnlockDesc = {
    Text = "Nível de afinidade atingido 10 desbloqueado"
  },
  Voice_126972_AwakerVoiceContent = {
    Text = "Não se preocupe, você é diferente daquelas pessoas insignificantes. \n Shh, não olhe para trás de mim, não se importe com os toques invisíveis—apenas olhe nos meus olhos."
  },
  Voice_126972_AwakerVoiceTitle = {
    Text = "Iluminar·Florescer"
  },
  Voice_126972_UnlockDesc = {
    Text = "Nível de iluminação atingiu 15 para desbloquear"
  },
  Voice_126973_AwakerVoiceContent = {
    Text = "*Ri(sos). Você se atreve a olhar para minha verdadeira forma?"
  },
  Voice_126973_AwakerVoiceTitle = {
    Text = "Despertar do Conhecimento Espiritual"
  },
  Voice_126975_AwakerVoiceContent = {
    Text = "Barulhento."
  },
  Voice_126975_AwakerVoiceTitle = {Text = "Ataque·II"},
  Voice_126976_AwakerVoiceContent = {
    Text = "O que? Você está olhando para meu leque novamente, encantado? \n Hehe, não importa de quem você deseja ver o rosto por trás do leque, eu vou te satisfazer... Venha, chegue um pouco mais perto— \n Oh, você não quer? Dizendo palavras tão frias, mas sua expressão é bem fofa..."
  },
  Voice_126976_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Um"
  },
  Voice_126976_UnlockDesc = {
    Text = "Nível de afinidade atingido 2 desbloqueado"
  },
  Voice_126977_AwakerVoiceContent = {
    Text = "Você veio à Terra Sem Sonhos, o que você está procurando?"
  },
  Voice_126977_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_126978_AwakerVoiceContent = {
    Text = "Cesse sua raiva e ressentimento, pois todas as coisas se tornarão em nada."
  },
  Voice_126978_AwakerVoiceTitle = {
    Text = "Exaltar · Dois"
  },
  Voice_126979_AwakerVoiceContent = {
    Text = "Não seja rude."
  },
  Voice_126979_AwakerVoiceTitle = {
    Text = "Defesa · I"
  },
  Voice_126980_AwakerVoiceContent = {
    Text = "...Tá bom!"
  },
  Voice_126980_AwakerVoiceTitle = {
    Text = "Golpe·Quatro"
  },
  Voice_126981_AwakerVoiceContent = {
    Text = "Eu uma vez tive uma linda e tímida garotinha assim. \n Um botão de flor impressionante, é claro, deve ter alguns espinhos adicionados; não pode simplesmente ser colocado em um vaso."
  },
  Voice_126981_AwakerVoiceTitle = {
    Text = "Chat: Sobre Lily"
  },
  Voice_126981_UnlockDesc = {
    Text = "Desbloqueado após adquirir o Despertar \"Lily\""
  },
  Voice_126982_AwakerVoiceContent = {
    Text = "A academia rejeitou firmemente minha candidatura para trabalhar na sala de aconselhamento. É realmente estranho, o que poderia estar errado?"
  },
  Voice_126982_AwakerVoiceTitle = {
    Text = "Conversa·Sobre Missaga"
  },
  Voice_126983_AwakerVoiceContent = {
    Text = "Tudo eventualmente retornará à efemeridade, então por que não procurar um pouco de diversão comigo? \n Fique tranquilo, se chegar um dia em que você não puder resistir, eu não deixarei que Ele te leve primeiro."
  },
  Voice_126983_AwakerVoiceTitle = {
    Text = "Conversa fiada·Sobre a crise"
  },
  Voice_126984_AwakerVoiceContent = {Text = "Chato."},
  Voice_126984_AwakerVoiceTitle = {Text = "Ataque·Um"},
  Voice_126985_AwakerVoiceContent = {
    Text = "Você é uma pessoa realmente notável, ocupada com tantas questões externas em um mundo destinado à destruição. \n Isso até desperta meu próprio interesse."
  },
  Voice_126985_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Quatro"
  },
  Voice_126985_UnlockDesc = {
    Text = "Nível de afinidade atingido 8 desbloqueado"
  },
  Voice_126986_AwakerVoiceContent = {
    Text = "Não chegue muito perto!"
  },
  Voice_126986_AwakerVoiceTitle = {Text = "Defesa·II"},
  Voice_126988_AwakerVoiceContent = {
    Text = "Eu sou Xu, a Dama da Terra Sem Sonhos. Se há alguém em seu coração que você deseja ver, mas não pode, estou disposta a alimentar as chamas e lhe conceder um vislumbre."
  },
  Voice_126988_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_127088_AwakerVoiceContent = {
    Text = "Todos os descendentes dos seres vivos podem ser bastante problemáticos. \n Pequenos, macios e barulhentos, eles inadvertidamente viram tudo ao seu redor de cabeça para baixo. Eu gosto de uma atmosfera animada, mas realmente não gosto desse tipo de agitação, então, por favor, mantenha-os à distância."
  },
  Voice_127088_AwakerVoiceTitle = {
    Text = "Conversa·Coisas odiadas"
  },
  Voice_127089_AwakerVoiceContent = {
    Text = "Minha pequena jasmim, meu querido bebê, eu estou doce como mel imersa neste jogo de casinha~\nah, algumas palavras sem sentido de bom humor, você não precisa se preocupar."
  },
  Voice_127089_AwakerVoiceTitle = {
    Text = "Conversa·Sobre Guardião do Segredo"
  },
  Voice_127090_AwakerVoiceContent = {
    Text = "Nas lendas do Império Panlong, o pavão é uma besta bela e flamboyante. \n Bonito, mas maligno, seu som é de tirar o fôlego; se fosse feio, mas bondoso, seria bastante sem graça."
  },
  Voice_127090_AwakerVoiceTitle = {
    Text = "Conversa·Coisas favoritas"
  },
  Voice_129651_AwakerVoiceContent = {
    Text = "Devore! Nham nham!"
  },
  Voice_129651_AwakerVoiceTitle = {
    Text = "Exaltar · Dois"
  },
  Voice_129652_AwakerVoiceContent = {Text = "Glub glub~"},
  Voice_129652_AwakerVoiceTitle = {Text = "Defesa·II"},
  Voice_129653_AwakerVoiceContent = {
    Text = "Pequena bola de carvão, eu, vamos comer, juntos? Juntos!"
  },
  Voice_129653_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Três"
  },
  Voice_129653_UnlockDesc = {
    Text = "Nível de afinidade atingido 6 desbloqueado"
  },
  Voice_129654_AwakerVoiceContent = {
    Text = "Mosk! Muito forte!"
  },
  Voice_129654_AwakerVoiceTitle = {
    Text = "Habilidade·Um"
  },
  Voice_129655_AwakerVoiceContent = {
    Text = "Abismo! Espiral! Destruição! Tudo — transforme-se em vórtice!"
  },
  Voice_129655_AwakerVoiceTitle = {
    Text = "Superexaltação"
  },
  Voice_129656_AwakerVoiceContent = {Text = "Dor!"},
  Voice_129656_AwakerVoiceTitle = {
    Text = "Golpe·Quatro"
  },
  Voice_129657_AwakerVoiceContent = {
    Text = "Não me toque, não! Não me toque, estrague!"
  },
  Voice_129657_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Um"
  },
  Voice_129657_UnlockDesc = {
    Text = "Nível de afinidade atingido 2 desbloqueado"
  },
  Voice_129658_AwakerVoiceContent = {
    Text = "Conchas, brilhantes! Brilhantes, bonitas, para você!"
  },
  Voice_129658_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Dois"
  },
  Voice_129658_UnlockDesc = {
    Text = "Nível de afinidade atingido 4 desbloqueado"
  },
  Voice_129659_AwakerVoiceContent = {
    Text = "Frio, assustador, Mosk, esconda-se!"
  },
  Voice_129659_AwakerVoiceTitle = {
    Text = "Conversa: Sobre boneca"
  },
  Voice_129659_UnlockDesc = {
    Text = "Após obter o despertador \"Boneca\", desbloqueado"
  },
  Voice_129660_AwakerVoiceContent = {Text = "Ahuh!"},
  Voice_129660_AwakerVoiceTitle = {
    Text = "Investigação Bem-sucedida"
  },
  Voice_129661_AwakerVoiceContent = {
    Text = "Caça, maldito! Quebrado! Mosk, bata neles, quebrado!"
  },
  Voice_129661_AwakerVoiceTitle = {
    Text = "Conversa·Coisas odiadas"
  },
  Voice_129662_AwakerVoiceContent = {
    Text = "Divertido! Na próxima vez! Quero mais!"
  },
  Voice_129662_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_129662_UnlockDesc = {
    Text = "Nível de iluminação atingiu 2 para desbloquear"
  },
  Voice_129663_AwakerVoiceContent = {
    Text = "Acaricie, bom! Mosk, você, acaricie!"
  },
  Voice_129663_AwakerVoiceTitle = {
    Text = "Conversa·Toque"
  },
  Voice_129664_AwakerVoiceContent = {
    Text = "Não, não! Pequena bola de carvão, Mosk, proteja!"
  },
  Voice_129664_AwakerVoiceTitle = {
    Text = "Conversa fiada·Sobre a crise"
  },
  Voice_129665_AwakerVoiceContent = {
    Text = "Mais uma vez? Mais uma vez!"
  },
  Voice_129665_AwakerVoiceTitle = {
    Text = "Investigação Interrompida"
  },
  Voice_129666_AwakerVoiceContent = {
    Text = "Hehehe, Mosk, vamos brincar!"
  },
  Voice_129666_AwakerVoiceTitle = {
    Text = "Despertar do Conhecimento Espiritual"
  },
  Voice_129667_AwakerVoiceContent = {
    Text = "A grande onda está chegando!"
  },
  Voice_129667_AwakerVoiceTitle = {Text = "Ataque·II"},
  Voice_129668_AwakerVoiceContent = {Text = "Perda!"},
  Voice_129668_AwakerVoiceTitle = {Text = "Ataque·Um"},
  Voice_129669_AwakerVoiceContent = {Text = "Dor!"},
  Voice_129669_AwakerVoiceTitle = {
    Text = "Acertar · II"
  },
  Voice_129670_AwakerVoiceContent = {Text = "Eca!"},
  Voice_129670_AwakerVoiceTitle = {Text = "Acertar·1"},
  Voice_129671_AwakerVoiceContent = {
    Text = "Ritual?! Leve-me junto!"
  },
  Voice_129671_AwakerVoiceTitle = {
    Text = "Iluminar·Visão Remota"
  },
  Voice_129671_UnlockDesc = {
    Text = "Nível de iluminação atingiu 1 para desbloquear"
  },
  Voice_129672_AwakerVoiceContent = {
    Text = "Vórtice! Força! Bastão!"
  },
  Voice_129672_AwakerVoiceTitle = {
    Text = "Iluminar·Florescer"
  },
  Voice_129672_UnlockDesc = {
    Text = "Nível de iluminação atingiu 15 para desbloquear"
  },
  Voice_129673_AwakerVoiceContent = {Text = "Pim!"},
  Voice_129673_AwakerVoiceTitle = {
    Text = "Habilidade Especial · Um"
  },
  Voice_129674_AwakerVoiceContent = {Text = "Legal!"},
  Voice_129674_AwakerVoiceTitle = {
    Text = "Início da Investigação"
  },
  Voice_129675_AwakerVoiceContent = {Text = "Ufa ufa~"},
  Voice_129675_AwakerVoiceTitle = {
    Text = "Defesa · I"
  },
  Voice_129676_AwakerVoiceContent = {Text = "Briga!"},
  Voice_129676_AwakerVoiceTitle = {
    Text = "Conversa: Sobre Goliath"
  },
  Voice_129676_UnlockDesc = {
    Text = "Após obter o despertador \"Golias\", desbloqueado"
  },
  Voice_129677_AwakerVoiceContent = {
    Text = "Encontrei muitos, brilhantes!"
  },
  Voice_129677_AwakerVoiceTitle = {
    Text = "Iluminar: Insight"
  },
  Voice_129677_UnlockDesc = {
    Text = "Nível de iluminação atingiu 7 para desbloquear"
  },
  Voice_129678_AwakerVoiceContent = {
    Text = "Abismo! Espiral! Destruição! Tudo — transforme-se em vórtice!"
  },
  Voice_129678_AwakerVoiceTitle = {
    Text = "Sobre-Exaltação Aliemus Explosão·II"
  },
  Voice_129679_AwakerVoiceContent = {Text = "Uhu!"},
  Voice_129679_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · I"
  },
  Voice_129680_AwakerVoiceContent = {Text = "Eca!"},
  Voice_129680_AwakerVoiceTitle = {
    Text = "Acertar·III"
  },
  Voice_129681_AwakerVoiceContent = {
    Text = "Mosk! Muito forte!"
  },
  Voice_129681_AwakerVoiceTitle = {
    Text = "Habilidade·Um"
  },
  Voice_129682_AwakerVoiceContent = {
    Text = "Devore! Nham nham!"
  },
  Voice_129682_AwakerVoiceTitle = {
    Text = "Fúria Explosiva"
  },
  Voice_129683_AwakerVoiceContent = {
    Text = "A Nautilus, Nautila, Pequena bola de carvão! Brilhante!"
  },
  Voice_129683_AwakerVoiceTitle = {
    Text = "Conversa·Coisas favoritas"
  },
  Voice_129684_AwakerVoiceContent = {
    Text = "Mosk, carregue as balas!"
  },
  Voice_129684_AwakerVoiceTitle = {
    Text = "Habilidade·II·Recarregar Um"
  },
  Voice_129685_AwakerVoiceContent = {
    Text = "Mosk, corra!"
  },
  Voice_129685_AwakerVoiceTitle = {
    Text = "Habilidade·Dois·Recarregar·II"
  },
  Voice_129686_AwakerVoiceContent = {
    Text = "Abraço! Mosk! Gosto!"
  },
  Voice_129686_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Quatro"
  },
  Voice_129686_UnlockDesc = {
    Text = "Nível de afinidade atingido 8 desbloqueado"
  },
  Voice_129687_AwakerVoiceContent = {
    Text = "Pequena bola de carvão, amigo! Mosk, para sempre!"
  },
  Voice_129687_AwakerVoiceTitle = {
    Text = "Conversa·Sobre Guardião do Segredo"
  },
  Voice_129688_AwakerVoiceContent = {
    Text = "Mais rápido, mais rápido!"
  },
  Voice_129688_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexão"
  },
  Voice_129688_UnlockDesc = {
    Text = "Nível de iluminação atingiu 3 para desbloquear"
  },
  Voice_129689_AwakerVoiceContent = {
    Text = "Mosk! Pequena bola de carvão! Juntos, sempre? Para sempre!"
  },
  Voice_129689_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Cinco"
  },
  Voice_129689_UnlockDesc = {
    Text = "Nível de afinidade atingido 10 desbloqueado"
  },
  Voice_129690_AwakerVoiceContent = {
    Text = "Uhul~ As grandes ondas estão se levantando!"
  },
  Voice_129690_AwakerVoiceTitle = {
    Text = "Iluminar·Construção"
  },
  Voice_129690_UnlockDesc = {
    Text = "Nível de iluminação atingiu 11 para desbloquear"
  },
  Voice_129691_AwakerVoiceContent = {
    Text = "Amigo! Muitos! Gosto!"
  },
  Voice_129691_AwakerVoiceTitle = {
    Text = "Conversa·Sobre Missaga"
  },
  Voice_129692_AwakerVoiceContent = {
    Text = "Mosk! Impressionante!"
  },
  Voice_129692_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · Três"
  },
  Voice_129693_AwakerVoiceContent = {
    Text = "Nautila, quero ver. Oi, Nautila, Mosk, Mosk!"
  },
  Voice_129693_AwakerVoiceTitle = {
    Text = "Conversa: Sobre Náutilo"
  },
  Voice_129693_UnlockDesc = {
    Text = "Após obter o despertador \"Náutilo\", desbloqueado"
  },
  Voice_129694_AwakerVoiceContent = {
    Text = "Ficou mais forte!"
  },
  Voice_129694_AwakerVoiceTitle = {
    Text = "Atualizar·II"
  },
  Voice_129695_AwakerVoiceContent = {
    Text = "Eu! Mosk! Olá!"
  },
  Voice_129695_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_130511_AwakerVoiceContent = {Text = "Ufa—"},
  Voice_130511_AwakerVoiceTitle = {
    Text = "Habilidade·Dois·Recarga Três"
  },
  Voice_133720_AwakerVoiceContent = {
    Text = "O erro deve ser corrigido."
  },
  Voice_133720_AwakerVoiceTitle = {
    Text = "Acertar · II"
  },
  Voice_133721_AwakerVoiceContent = {
    Text = "A tragédia diante de você é apenas um vislumbre entre incontáveis possibilidades.\n\nAlém da cortina do destino jaz um palco engolido pela escuridão —\nluzes apagadas, atores partidos, tudo retornando às profundezas.\n\nMas não é onde termina.\nCarrego a determinação de suportar este trabalho ingrato, até o dia em que as luzes retornem."
  },
  Voice_133721_AwakerVoiceTitle = {
    Text = "Conversa fiada·Sobre a crise"
  },
  Voice_133722_AwakerVoiceContent = {
    Text = "O destino de cada alma é carregado por fios... mas o seu é um roteiro que não consigo decifrar. Me pego ansioso por qualquer improviso que você trará a este mundo."
  },
  Voice_133722_AwakerVoiceTitle = {
    Text = "Conversa·Sobre Guardião do Segredo"
  },
  Voice_133723_AwakerVoiceContent = {
    Text = "O palco sempre foi seu. Avance, querida marionete."
  },
  Voice_133723_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_133724_AwakerVoiceContent = {Text = "Sim?"},
  Voice_133724_AwakerVoiceTitle = {
    Text = "Golpe·Quatro"
  },
  Voice_133725_AwakerVoiceContent = {
    Text = "Tudo é um epílogo passado. Tudo é um novo prólogo. O novo capítulo entre nós espera que você o escreva, Guardião."
  },
  Voice_133725_AwakerVoiceTitle = {
    Text = "Iluminar·Florescer"
  },
  Voice_133725_UnlockDesc = {
    Text = "Nível de iluminação atingiu 15 para desbloquear"
  },
  Voice_133726_AwakerVoiceContent = {
    Text = "Se comédia é sua inclinação, <Italic:Um sonho de uma noite de verão> lhe serviria bem. Tenho particular apreço pelas divagações travessas de Puck — escondido dentro do riso de um duende, o destino sempre deixa algo escapar."
  },
  Voice_133726_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_133726_UnlockDesc = {
    Text = "Nível de iluminação atingiu 2 para desbloquear"
  },
  Voice_133727_AwakerVoiceContent = {
    Text = "Submeta-se a isto."
  },
  Voice_133727_AwakerVoiceTitle = {Text = "Ataque·II"},
  Voice_133728_AwakerVoiceContent = {
    Text = "O fuso do destino agora gira."
  },
  Voice_133728_AwakerVoiceTitle = {
    Text = "Habilidade·Um"
  },
  Voice_133729_AwakerVoiceContent = {
    Text = "Prisioneiro do destino, lastimável como sempre... o que está escrito não pode ser recusado."
  },
  Voice_133729_AwakerVoiceTitle = {
    Text = "Sobre-Exaltação Aliemus Explosão·II"
  },
  Voice_133730_AwakerVoiceContent = {
    Text = "Mesmo quem observa todas as coisas permanece um ator desajeitado em seu próprio roteiro. Segurar a teia do destino, mas ser preso por seus fios — trilhamos caminhos diferentes nesta circunstância destinada, mas nenhum de nós jamais abandonou verdadeiramente nossas buscas ingratas. Tolo, talvez. Iludido, talvez. Assim é comigo, e assim é com ela."
  },
  Voice_133730_AwakerVoiceTitle = {
    Text = "Conversa: Sobre Tawil"
  },
  Voice_133730_UnlockDesc = {
    Text = "Desbloqueia ao obter o despertador \"Tawil\""
  },
  Voice_133731_AwakerVoiceContent = {
    Text = "Uma reviravolta inesperada?"
  },
  Voice_133731_AwakerVoiceTitle = {Text = "Acertar·1"},
  Voice_133732_AwakerVoiceContent = {
    Text = "Obrigado por me acompanhar através de tantas cortinas que se ergueram e caíram. Não o decepcionarei — ainda há mais noites por vir que o comoverão de maneiras que não esperava."
  },
  Voice_133732_AwakerVoiceTitle = {
    Text = "Iluminar·Construção"
  },
  Voice_133732_UnlockDesc = {
    Text = "Nível de iluminação atingiu 11 para desbloquear"
  },
  Voice_133733_AwakerVoiceContent = {
    Text = "Que cantora talentosa. Uma voz concedida pela graça, clara e ardente ao mesmo tempo, como se emergisse do próprio destino. Se ela se apresentasse em meu teatro, imagino que até a plateia mais exigente seria pega de surpresa."
  },
  Voice_133733_AwakerVoiceTitle = {
    Text = "Conversa: Sobre Tinct"
  },
  Voice_133733_UnlockDesc = {
    Text = "Após obter o despertador \"Tinta\", desbloqueado"
  },
  Voice_133734_AwakerVoiceContent = {
    Text = "Os fios invisíveis que pertencem a você e a mim há muito se enrolaram firmemente um ao outro, tecendo ao mesmo tempo uma gaiola e um caminho.\nNão consigo ver onde a gaiola termina, nem para onde o caminho leva.\nÉ precisamente isso que torna esta história tão cativante."
  },
  Voice_133734_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Cinco"
  },
  Voice_133734_UnlockDesc = {
    Text = "Nível de afinidade atingido 10 desbloqueado"
  },
  Voice_133735_AwakerVoiceContent = {
    Text = "Os fios do destino permanecem imóveis."
  },
  Voice_133735_AwakerVoiceTitle = {
    Text = "Habilidade·Um"
  },
  Voice_133736_AwakerVoiceContent = {
    Text = "Ela visita meu teatro frequentemente... mas sei que não vem pelas peças. Ela parece usar este palco para emprestar certo refinamento à sua própria imagem. Uma habilidade notável, porém — gastá-la apenas como espectadora parece um desperdício. Aquela senhora não é do tipo que floresce na escuridão da plateia. Ela pertence à luz."
  },
  Voice_133736_AwakerVoiceTitle = {
    Text = "Chat: Sobre Sorel"
  },
  Voice_133736_UnlockDesc = {
    Text = "Desbloqueado após obter Despertar\"Sorel\""
  },
  Voice_133737_AwakerVoiceContent = {
    Text = "Uma vez o ouvi tocar. Aquela música fez a alma tremer... Talvez eu devesse convidá-lo para compor uma sinfonia do destino para minha próxima produção."
  },
  Voice_133737_AwakerVoiceTitle = {
    Text = "Conversa: sobre Hameln"
  },
  Voice_133737_UnlockDesc = {
    Text = "Desbloqueia ao obter o despertador \"Hameln\""
  },
  Voice_133738_AwakerVoiceContent = {
    Text = "Mais uma história, belamente completa, chega ao seu fim."
  },
  Voice_133738_AwakerVoiceTitle = {
    Text = "Investigação Bem-sucedida"
  },
  Voice_133739_AwakerVoiceContent = {
    Text = "Finalmente vi por inteiro. A teia infinita do destino."
  },
  Voice_133739_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · Três"
  },
  Voice_133740_AwakerVoiceContent = {
    Text = "Se me permitir... desejo tecer uma peça que pertença apenas a você e a mim.\nSem plateia, sem ensaio. Simplesmente desejo ver como o fio que nem eu consigo ler começará a se agitar... quando você entrar na luz."
  },
  Voice_133740_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Quatro"
  },
  Voice_133740_UnlockDesc = {
    Text = "Nível de afinidade atingido 8 desbloqueado"
  },
  Voice_133741_AwakerVoiceContent = {
    Text = "Que dançarina de destino tão infeliz. Observei seus passos. A dela é uma beleza que caminha rumo à ruína — cada giro acendendo chamas verdes, como se tentasse queimar os fios do destino, embora no fim esses fios apenas esculpam algo dolorosamente vívido dela. Se a oportunidade surgir, gostaria de escrever um balé só para ela."
  },
  Voice_133741_AwakerVoiceTitle = {
    Text = "Conversa: Sobre Liz"
  },
  Voice_133741_UnlockDesc = {
    Text = "Desbloqueado após adquirir o Despertar \"Liz\""
  },
  Voice_133742_AwakerVoiceContent = {
    Text = "Aqui é tecido. Aqui é pesado. Aqui é cortado."
  },
  Voice_133742_AwakerVoiceTitle = {
    Text = "Exaltar · Dois"
  },
  Voice_133743_AwakerVoiceContent = {
    Text = "Fique quieto..."
  },
  Voice_133743_AwakerVoiceTitle = {
    Text = "Defesa · I"
  },
  Voice_133744_AwakerVoiceContent = {
    Text = "Mais um fio se torna claro."
  },
  Voice_133744_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · I"
  },
  Voice_133745_AwakerVoiceContent = {
    Text = "A cortina está aberta para você, e o roteiro do destino aguarda para começar. Diga-me: qual caminho destinado prefere trilhar? Um final triste, ou uma abertura alegre?"
  },
  Voice_133745_AwakerVoiceTitle = {
    Text = "Iluminar·Visão Remota"
  },
  Voice_133745_UnlockDesc = {
    Text = "Nível de iluminação atingiu 1 para desbloquear"
  },
  Voice_133746_AwakerVoiceContent = {
    Text = "Tornei-me bastante afeiçoado a esta tecelagem, dia após dia... No silêncio, no puxar repetido de cada um, vejo através dos começos e fins de todas as histórias. Observando cada cortina cair, sinto por vezes como se tivesse me elevado acima do próprio destino. E, no entanto, não se pode escapar da teia do destino, e apenas observar deixa, no fim, um sentimento vazio.\nNesses momentos, vou ao teatro. Para encenar as tristezas e alegrias que teci com minhas próprias mãos, mas que nunca vivi."
  },
  Voice_133746_AwakerVoiceTitle = {
    Text = "Conversa·Coisas favoritas"
  },
  Voice_133747_AwakerVoiceContent = {Text = "Ugh..."},
  Voice_133747_AwakerVoiceTitle = {
    Text = "Acertar·III"
  },
  Voice_133748_AwakerVoiceContent = {Text = "Heh..."},
  Voice_133748_AwakerVoiceTitle = {Text = "Ataque·Um"},
  Voice_133749_AwakerVoiceContent = {
    Text = "Aqui é tecido. Aqui é pesado. Aqui é cortado."
  },
  Voice_133749_AwakerVoiceTitle = {
    Text = "Fúria Explosiva"
  },
  Voice_133750_AwakerVoiceContent = {
    Text = "O Destino se agita. Seu sussurro se aproxima."
  },
  Voice_133750_AwakerVoiceTitle = {
    Text = "Atualizar·II"
  },
  Voice_133751_AwakerVoiceContent = {
    Text = "O teatro encenou uma nova comédia romântica, e reservei um lugar para você entre a plateia do destino. Através de cada longa noite onde destinos se entrelaçam, esperarei silenciosamente pelo momento em que nossas estrelas se encontrem."
  },
  Voice_133751_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Três"
  },
  Voice_133751_UnlockDesc = {
    Text = "Nível de afinidade atingido 6 desbloqueado"
  },
  Voice_133752_AwakerVoiceContent = {
    Text = "Puxar com tanta insistência os fios do destino...\n\nVocê parece bastante ansioso para ler sua própria história, não?"
  },
  Voice_133752_AwakerVoiceTitle = {
    Text = "Conversa·Toque"
  },
  Voice_133753_AwakerVoiceContent = {
    Text = "O que foi escrito se aproxima."
  },
  Voice_133753_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_133754_AwakerVoiceContent = {
    Text = "Se deseja entrar no salão da tragédia, permita-me apresentar <Italic:Antígona>. Presa entre a lei divina e o decreto mortal, cada passo que ela dá recai sobre fios que o destino já teceu, até que ela adentra enfim a sombra profunda do túmulo de pedra. É precisamente porque essas correntes não podem ser quebradas que a vontade ardendo dentro de seu pequeno corpo brilha tão vividamente contra a longa noite."
  },
  Voice_133754_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexão"
  },
  Voice_133754_UnlockDesc = {
    Text = "Nível de iluminação atingiu 3 para desbloquear"
  },
  Voice_133755_AwakerVoiceContent = {
    Text = "Nenhum final é verdadeiramente certo, mas nenhum escapa à teia de causa e consequência..."
  },
  Voice_133755_AwakerVoiceTitle = {
    Text = "Investigação Interrompida"
  },
  Voice_133756_AwakerVoiceContent = {
    Text = "Sobre os fios, vejo cores mudarem por todos os tons do arco-íris.\nEles se estendem por uma teia infinita, tecendo mundos ilimitados e possibilidades infinitas, até formar um padrão mais belo do que qualquer um já visto.\n\nNo final — deus ou mortal, herói ou vilão — cada um é guiado por esses fios delicados, correndo de cabeça em direção ao seu fim destinado sob o olhar implacável do destino."
  },
  Voice_133756_AwakerVoiceTitle = {
    Text = "Conversa·Sobre Missaga"
  },
  Voice_133757_AwakerVoiceContent = {
    Text = "Pensei que nada neste mundo pudesse mais me surpreender... Seu gosto para teatro deixou uma impressão."
  },
  Voice_133757_AwakerVoiceTitle = {
    Text = "Iluminar: Insight"
  },
  Voice_133757_UnlockDesc = {
    Text = "Nível de iluminação atingiu 7 para desbloquear"
  },
  Voice_133758_AwakerVoiceContent = {
    Text = "Os fios do destino sempre se conectam nas sombras... Você perturbou um desses fios, e assim me sobressaltou."
  },
  Voice_133758_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Um"
  },
  Voice_133758_UnlockDesc = {
    Text = "Nível de afinidade atingido 2 desbloqueado"
  },
  Voice_133759_AwakerVoiceContent = {
    Text = "Nunca apreciei apresentações que simplesmente se repetem. A razão pela qual se entra em um teatro é para testemunhar um palco vivo — um que não pode ser recriado.\nSe não faz nada além de girar como um relógio, o palco se torna uma gaiola ornamentada, e assistir se torna nada mais que uma peregrinação tediosa rumo a um final que você já conhece.\nUma mascarada sem alma, não importa quão magnífica seja a produção. O que acha?"
  },
  Voice_133759_AwakerVoiceTitle = {
    Text = "Conversa·Coisas odiadas"
  },
  Voice_133760_AwakerVoiceContent = {
    Text = "Aqueles fios outrora fluíam em perfeita ordem por minhas mãos... até você aparecer, e enviar ondulações por seu curso que eu jamais havia previsto."
  },
  Voice_133760_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Dois"
  },
  Voice_133760_UnlockDesc = {
    Text = "Nível de afinidade atingido 4 desbloqueado"
  },
  Voice_133761_AwakerVoiceContent = {
    Text = "Prisioneiro do destino, lastimável como sempre... o que está escrito não pode ser recusado."
  },
  Voice_133761_AwakerVoiceTitle = {
    Text = "Superexaltação"
  },
  Voice_133762_AwakerVoiceContent = {
    Text = "De fios infinitos, teço o único caminho."
  },
  Voice_133762_AwakerVoiceTitle = {
    Text = "Despertar do Conhecimento Espiritual"
  },
  Voice_133763_AwakerVoiceContent = {
    Text = "No grande palco do destino, todas as almas aguardam sua deixa na teia de causa e consequência, suas alegrias e tristezas silenciosamente tomando forma enquanto as engrenagens giram...\nA cortina se ergueu, Guardião. É aqui que a sua história, e a minha, começa."
  },
  Voice_133763_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_133764_AwakerVoiceContent = {
    Text = "O conflito está aqui. Você vai Disparar como o herói que rompe a teia, ou o jogador que se move apenas conforme os fios permitem?"
  },
  Voice_133764_AwakerVoiceTitle = {
    Text = "Início da Investigação"
  },
  Voice_133765_AwakerVoiceContent = {
    Text = "Resistência fútil."
  },
  Voice_133765_AwakerVoiceTitle = {Text = "Defesa·II"},
  Voice_139865_AwakerVoiceContent = {
    Text = "Obrigada por este presente. Vou guardá-lo com carinho."
  },
  Voice_139865_AwakerVoiceTitle = {
    Text = "Atualizar·II"
  },
  Voice_139866_AwakerVoiceContent = {
    Text = "Eu estudei bastante a estrutura dos Corpos Despertos, então me considero uma especialista a essa altura. Mas a \"espiritualidade\" dentro dos Núcleos de Prata... essa parte eu ainda não entendo muito bem."
  },
  Voice_139866_AwakerVoiceTitle = {
    Text = "Iluminar·Construção"
  },
  Voice_139866_UnlockDesc = {
    Text = "Nível de iluminação atingiu 11 para desbloquear"
  },
  Voice_139867_AwakerVoiceContent = {
    Text = "Aqui é... onde um novo mundo começa."
  },
  Voice_139867_AwakerVoiceTitle = {
    Text = "Fúria Explosiva"
  },
  Voice_139868_AwakerVoiceContent = {
    Text = "Eu consigo fazer coisas assim, sabia? Como reorganizar ou ajustar os corpos de outras criaturas..."
  },
  Voice_139868_AwakerVoiceTitle = {
    Text = "Iluminar·Visão Remota"
  },
  Voice_139868_UnlockDesc = {
    Text = "Nível de iluminação atingiu 1 para desbloquear"
  },
  Voice_139869_AwakerVoiceContent = {
    Text = "Cada ser vivo é diferente, então antes de começar a mexer nas coisas, você realmente precisa estudá-los com cuidado."
  },
  Voice_139869_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_139869_UnlockDesc = {
    Text = "Nível de iluminação atingiu 2 para desbloquear"
  },
  Voice_139870_AwakerVoiceContent = {
    Text = "Você não tem medo de mim? Ahh... que sem graça..."
  },
  Voice_139870_AwakerVoiceTitle = {
    Text = "Conversa·Toque"
  },
  Voice_139871_AwakerVoiceContent = {
    Text = "Não vou deixar ninguém ficar no nosso caminho."
  },
  Voice_139871_AwakerVoiceTitle = {
    Text = "Habilidade·Um"
  },
  Voice_139872_AwakerVoiceContent = {
    Text = "Estou pronta, a qualquer momento."
  },
  Voice_139872_AwakerVoiceTitle = {
    Text = "Início da Investigação"
  },
  Voice_139873_AwakerVoiceContent = {
    Text = "Os seres vivos realmente são cheios de diversidade. Quero aprender muito mais!"
  },
  Voice_139873_AwakerVoiceTitle = {
    Text = "Investigação Interrompida"
  },
  Voice_139875_AwakerVoiceContent = {
    Text = "Quer brincar com a Saya?"
  },
  Voice_139875_AwakerVoiceTitle = {Text = "Ataque·II"},
  Voice_139876_AwakerVoiceContent = {Text = "Ai!!"},
  Voice_139876_AwakerVoiceTitle = {Text = "Acertar·1"},
  Voice_139877_AwakerVoiceContent = {
    Text = "Aqui é... onde um novo mundo começa."
  },
  Voice_139877_AwakerVoiceTitle = {
    Text = "Exaltar · Dois"
  },
  Voice_139878_AwakerVoiceContent = {
    Text = "Estou satisfeita. Obrigada pela comida!"
  },
  Voice_139878_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · I"
  },
  Voice_139880_AwakerVoiceContent = {
    Text = "Ei, Guardião... você já amou alguém? Você já sentiu saudade de alguém de verdade, com todo o seu coração?"
  },
  Voice_139880_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Quatro"
  },
  Voice_139880_UnlockDesc = {
    Text = "Nível de afinidade atingido 8 desbloqueado"
  },
  Voice_139881_AwakerVoiceContent = {Text = "Ngh!"},
  Voice_139881_AwakerVoiceTitle = {
    Text = "Acertar·III"
  },
  Voice_139882_AwakerVoiceContent = {Text = "É aqui?"},
  Voice_139882_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_139883_AwakerVoiceContent = {
    Text = "Bom trabalho! Encontrou algo bom?"
  },
  Voice_139883_AwakerVoiceTitle = {
    Text = "Investigação Bem-sucedida"
  },
  Voice_139884_AwakerVoiceContent = {
    Text = "Depois de todos os meus testes, eu entendo muito mais agora. A \"espiritualidade\" que cada Corpo Desperto carrega — são todas completamente diferentes. E parece que a espiritualidade do meu Núcleo de Prata é... \"amor.\""
  },
  Voice_139884_AwakerVoiceTitle = {
    Text = "Iluminar·Florescer"
  },
  Voice_139884_UnlockDesc = {
    Text = "Nível de iluminação atingiu 15 para desbloquear"
  },
  Voice_139885_AwakerVoiceContent = {
    Text = "E aí? Te peguei, não foi?"
  },
  Voice_139885_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · Três"
  },
  Voice_139886_AwakerVoiceContent = {
    Text = "Este é meu último presente... para você."
  },
  Voice_139886_AwakerVoiceTitle = {
    Text = "Superexaltação"
  },
  Voice_139887_AwakerVoiceContent = {
    Text = "\"<Italic:Em uma dessas estrelas, minha flor está desabrochando...>\"\nSinto que você já disse algo assim antes."
  },
  Voice_139887_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Dois"
  },
  Voice_139887_UnlockDesc = {
    Text = "Nível de afinidade atingido 4 desbloqueado"
  },
  Voice_139888_AwakerVoiceContent = {
    Text = "Parece que os \"Núcleos de Prata\" estão cada um conectados a uma vontade de muito, muito longe. Que misterioso..."
  },
  Voice_139888_AwakerVoiceTitle = {
    Text = "Iluminar: Insight"
  },
  Voice_139888_UnlockDesc = {
    Text = "Nível de iluminação atingiu 7 para desbloquear"
  },
  Voice_139889_AwakerVoiceContent = {
    Text = "Este é meu último presente... para você."
  },
  Voice_139889_AwakerVoiceTitle = {
    Text = "Sobre-Exaltação Aliemus Explosão·II"
  },
  Voice_139891_AwakerVoiceContent = {Text = "Ah!"},
  Voice_139891_AwakerVoiceTitle = {
    Text = "Acertar · II"
  },
  Voice_139892_AwakerVoiceContent = {
    Text = "O Pequeno Príncipe diz que sua rosa se tornou especial porque ele cuidou dela... Você acha isso?"
  },
  Voice_139892_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Três"
  },
  Voice_139892_UnlockDesc = {
    Text = "Nível de afinidade atingido 6 desbloqueado"
  },
  Voice_139893_AwakerVoiceContent = {
    Text = "Ontem, encontrei um livro chamado <Italic:O Pequeno Príncipe> na estante da Lily. Era muito bom! Você quer ler?"
  },
  Voice_139893_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Um"
  },
  Voice_139893_UnlockDesc = {
    Text = "Nível de afinidade atingido 2 desbloqueado"
  },
  Voice_139895_AwakerVoiceContent = {
    Text = "Sim, eu estudei a estrutura dos Núcleos de Prata e estou começando a entender como os Corpos Despertos funcionam."
  },
  Voice_139895_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexão"
  },
  Voice_139895_UnlockDesc = {
    Text = "Nível de iluminação atingiu 3 para desbloquear"
  },
  Voice_139896_AwakerVoiceContent = {Text = "Ah!"},
  Voice_139896_AwakerVoiceTitle = {
    Text = "Golpe·Quatro"
  },
  Voice_139897_AwakerVoiceContent = {Text = "E aí!"},
  Voice_139897_AwakerVoiceTitle = {
    Text = "Habilidade·Um"
  },
  Voice_139899_AwakerVoiceContent = {
    Text = "Muito prazer em trabalhar com você!"
  },
  Voice_139899_AwakerVoiceTitle = {Text = "Ataque·Um"},
  Voice_139900_AwakerVoiceContent = {
    Text = "Olá! ...É assim que se diz?\nEu sou a Saya, e... prazer em conhecer você!"
  },
  Voice_139900_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_139901_AwakerVoiceContent = {
    Text = "Você conhece os dentes-de-leão, certo? Aqueles que espalham suas sementes ao vento. Uma pequena semente é levada para longe, muito longe de sua terra natal... e talvez caia em um deserto onde nada cresce — nem uma única folha de grama. Eu me pergunto... o que aquela única e pequena semente sentiria...?"
  },
  Voice_139901_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Cinco"
  },
  Voice_139901_UnlockDesc = {
    Text = "Nível de afinidade atingido 10 desbloqueado"
  },
  Voice_139902_AwakerVoiceContent = {
    Text = "Não importa quantas vezes faça, é sempre divertido!"
  },
  Voice_139902_AwakerVoiceTitle = {
    Text = "Despertar do Conhecimento Espiritual"
  },
  Voice_139903_AwakerVoiceContent = {Text = "Oi!"},
  Voice_139903_AwakerVoiceTitle = {Text = "Defesa·II"},
  Voice_139906_AwakerVoiceContent = {Text = "Cuidado!"},
  Voice_139906_AwakerVoiceTitle = {
    Text = "Defesa · I"
  },
  Voice_140533_AwakerVoiceContent = {
    Text = "Eu adoro boa comida! E gosto de pessoas que são gentis comigo! Quando alguém é carinhoso comigo... isso simplesmente me deixa muito feliz."
  },
  Voice_140533_AwakerVoiceTitle = {
    Text = "Conversa·Coisas favoritas"
  },
  Voice_140534_AwakerVoiceContent = {
    Text = "Foi ela quem me despertou? Ela parece realmente... deslumbrante. E então, você a ajudou a encontrar a irmã dela?"
  },
  Voice_140534_AwakerVoiceTitle = {
    Text = "Conversa: Sobre Tinct"
  },
  Voice_140534_UnlockDesc = {
    Text = "Após obter o despertador \"Tinta\", desbloqueado"
  },
  Voice_140535_AwakerVoiceContent = {
    Text = "Sempre que estou perto de você, pessoas estranhas simplesmente aparecem e se juntam ao nosso redor. Na verdade, eu preferia quando éramos só nós dois no Domínio."
  },
  Voice_140535_AwakerVoiceTitle = {
    Text = "Conversa·Sobre Missaga"
  },
  Voice_140536_AwakerVoiceContent = {
    Text = "Entendi. Estou nessa!"
  },
  Voice_140536_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_140537_AwakerVoiceContent = {
    Text = "Guardião, Vínculo, Corpo Desperto. É assim que estamos conectados. Você me contou sobre isso. Eu consigo sentir nossas almas ligadas... como um fio de prata? Hmm, parece um pouco complicado demais..."
  },
  Voice_140537_AwakerVoiceTitle = {
    Text = "Conversa·Sobre Guardião do Segredo"
  },
  Voice_140538_AwakerVoiceContent = {
    Text = "Propagar sementes através de carne e sangue? Hmm... interessante. Na verdade, estou um pouco curioso sobre as ovelhas dela."
  },
  Voice_140538_AwakerVoiceTitle = {
    Text = "Conversa fiada: Sobre Táias"
  },
  Voice_140538_UnlockDesc = {
    Text = "Após obter o despertador \"Táias\", desbloqueado"
  },
  Voice_140539_AwakerVoiceContent = {
    Text = "Certas ameaças lá fora podem trazer uma escuridão grande o suficiente para destruir este mundo, certo? Eu sei. A Professora Doll me contou tudo sobre isso."
  },
  Voice_140539_AwakerVoiceTitle = {
    Text = "Conversa fiada·Sobre a crise"
  },
  Voice_140540_AwakerVoiceContent = {
    Text = "Eu não gosto de pessoas brutas. Elas me passam uma sensação ruim..."
  },
  Voice_140540_AwakerVoiceTitle = {
    Text = "Conversa·Coisas odiadas"
  },
  Voice_140541_AwakerVoiceContent = {
    Text = "Oh? Então a espécie dela se reproduz em novos planetas predando outras espécies. Huh, entendo..."
  },
  Voice_140541_AwakerVoiceTitle = {
    Text = "Conversa: Sobre Winkle"
  },
  Voice_140541_UnlockDesc = {
    Text = "Após obter o despertador \"Búzio\", desbloqueado"
  },
  Voice_141963_AwakerVoiceContent = {
    Text = "Bom garoto."
  },
  Voice_141963_AwakerVoiceTitle = {
    Text = "Habilidade Especial · Dois"
  },
  Voice_141964_AwakerVoiceContent = {Text = "Oi!"},
  Voice_141964_AwakerVoiceTitle = {
    Text = "Habilidade Especial · Três"
  },
  Voice_141965_AwakerVoiceContent = {
    Text = "...Tá bom!"
  },
  Voice_141965_AwakerVoiceTitle = {
    Text = "Recebido·Cinco"
  },
  Voice_143501_AwakerVoiceContent = {
    Text = "Que pena, quando você mudar de ideia, saberá onde me encontrar."
  },
  Voice_143501_AwakerVoiceTitle = {
    Text = "Iluminar·Florescer"
  },
  Voice_143501_UnlockDesc = {
    Text = "Nível de iluminação atingiu 15 para desbloquear"
  },
  Voice_143502_AwakerVoiceContent = {Text = "Maldito..."},
  Voice_143502_AwakerVoiceTitle = {
    Text = "Acertar · II"
  },
  Voice_143503_AwakerVoiceContent = {
    Text = "Pele, músculo, nervos, ossos — tudo será reconstruído, restaurado à saúde e integridade, revitalizado com nova energia."
  },
  Voice_143503_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_143503_UnlockDesc = {
    Text = "Nível de iluminação atingiu 2 para desbloquear"
  },
  Voice_143504_AwakerVoiceContent = {
    Text = "Diante do oceano, não há inimigo indestrutível!"
  },
  Voice_143504_AwakerVoiceTitle = {
    Text = "Superexaltação"
  },
  Voice_143505_AwakerVoiceContent = {
    Text = "Banquete, Caçada, refúgio?\nOre a mim, as águas mais antigas te dirão meu nome.\nSou o Senhor do Abismo, Pontos."
  },
  Voice_143505_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_143506_AwakerVoiceContent = {
    Text = "Hehe, com saudades dos momentos em Ebwynnos?...\nEle está aqui, neste corpo, sempre te recebendo de volta."
  },
  Voice_143506_AwakerVoiceTitle = {
    Text = "Conversa·Toque"
  },
  Voice_143507_AwakerVoiceContent = {
    Text = "Embora eu não tenha feito isso, se algum dia você ouvir o som de água do mar e o bater de asas em seus ouvidos, não se preocupe — é um fenômeno normal."
  },
  Voice_143507_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · Três"
  },
  Voice_143508_AwakerVoiceContent = {
    Text = "Ofereça seus sentidos e reflita eternamente no abismo!"
  },
  Voice_143508_AwakerVoiceTitle = {
    Text = "Habilidade·Um"
  },
  Voice_143509_AwakerVoiceContent = {
    Text = "Gosto de jovens cheios de energia. Pena que Misaq tem um controle tão rígido sobre as festividades — nem sequer há um campo de caça decente.\nAlém disso, lá dentro ainda há aquela coisa imunda que ousa circular abertamente, até ostentando o título de professor."
  },
  Voice_143509_AwakerVoiceTitle = {
    Text = "Conversa·Sobre Missaga"
  },
  Voice_143510_AwakerVoiceContent = {Text = "Ugh!"},
  Voice_143510_AwakerVoiceTitle = {Text = "Acertar·1"},
  Voice_143511_AwakerVoiceContent = {
    Text = "Fiz tanto por você, e você nem sequer está disposto a me chamar de tio novamente. Que dor de cabeça."
  },
  Voice_143511_AwakerVoiceTitle = {
    Text = "Conversa·Sobre Guardião do Segredo"
  },
  Voice_143513_AwakerVoiceContent = {
    Text = "Não há pressa. A escuridão das profundezas do oceano irá Devorar vocês."
  },
  Voice_143513_AwakerVoiceTitle = {
    Text = "Investigação Interrompida"
  },
  Voice_143514_AwakerVoiceContent = {
    Text = "Ajoelhe-se e torne-se o alimento de Ebwynnos."
  },
  Voice_143514_AwakerVoiceTitle = {
    Text = "Habilidade Especial · Três"
  },
  Voice_143515_AwakerVoiceContent = {
    Text = "Quanto ao ser que me escolheu... só posso dizer que é ao mesmo tempo gentil e cruel.\nOnde cair depende inteiramente do humor, inevitavelmente te salvará de situações perigosas — mas se o lugar for outro perigo, isso já não é algo que esta \"jornada\" precisa considerar.\nQue interessante, que imprevisível. Estou pensando em dar continuidade a essa tradição."
  },
  Voice_143515_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Quatro"
  },
  Voice_143515_UnlockDesc = {
    Text = "Nível de afinidade atingido 8 desbloqueado"
  },
  Voice_143516_AwakerVoiceContent = {
    Text = "Tenho uma ligação especial com Ebwynnos — melhor dizendo, eu sou Ebwynnos. Ebwynnos é sustentado por mim, existindo através do meu corpo."
  },
  Voice_143516_AwakerVoiceTitle = {
    Text = "Conversa: Sobre Ebwynnos"
  },
  Voice_143517_AwakerVoiceContent = {
    Text = "Erga a cabeça e exponha sua garganta."
  },
  Voice_143517_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_143518_AwakerVoiceContent = {
    Text = "Apagar memórias, apagar a existência. Algo familiar... você entende o que quero dizer. Embora as origens sejam diferentes, parece que Eles sempre brotam de lugares sem luz."
  },
  Voice_143518_AwakerVoiceTitle = {
    Text = "Conversa fiada·Sobre a crise"
  },
  Voice_143519_AwakerVoiceContent = {
    Text = "Vocês não deveriam ser tolos o suficiente para invadir minha majestade."
  },
  Voice_143519_AwakerVoiceTitle = {
    Text = "Investigação Bem-sucedida"
  },
  Voice_143520_AwakerVoiceContent = {
    Text = "Muito fraco."
  },
  Voice_143520_AwakerVoiceTitle = {Text = "Defesa·II"},
  Voice_143521_AwakerVoiceContent = {
    Text = "Em Ebwynnos, a festa jamais cessará, e os inimigos de Ebwynnos jamais encontrarão paz."
  },
  Voice_143521_AwakerVoiceTitle = {
    Text = "Iluminar·Visão Remota"
  },
  Voice_143521_UnlockDesc = {
    Text = "Nível de iluminação atingiu 1 para desbloquear"
  },
  Voice_143522_AwakerVoiceContent = {
    Text = "Ah, eu sinto o mesmo tremor que você, mas isso é completamente desnecessário, meu jovem amigo.\nAceite seu medo da mediocridade e de ser desgastado, olhe para mim — você entende que sempre há outra escolha."
  },
  Voice_143522_AwakerVoiceTitle = {
    Text = "Iluminar: Insight"
  },
  Voice_143522_UnlockDesc = {
    Text = "Nível de iluminação atingiu 7 para desbloquear"
  },
  Voice_143523_AwakerVoiceContent = {
    Text = "É verdade, eu sei que aquele desastre não foi diretamente ordenado por ele, apenas um acidente no caminho de sua diversão. Mas isso obviamente só me faz querer matá-lo ainda mais.\nAquela névoa negra é melhor não ficar sozinha, e não ser pega por mim."
  },
  Voice_143523_AwakerVoiceTitle = {
    Text = "Conversa·Coisas odiadas"
  },
  Voice_143524_AwakerVoiceContent = {
    Text = "Esses Homens-Peixe viscosos não são meus amigos, são meus inimigos. Surpreendente? O oceano nunca pertenceu a eles."
  },
  Voice_143524_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Um"
  },
  Voice_143524_UnlockDesc = {
    Text = "Nível de afinidade atingido 2 desbloqueado"
  },
  Voice_143525_AwakerVoiceContent = {
    Text = "Para sempre, permaneça aqui!"
  },
  Voice_143525_AwakerVoiceTitle = {
    Text = "Despertar do Conhecimento Espiritual"
  },
  Voice_143526_AwakerVoiceContent = {
    Text = "Estão prontos, presas!"
  },
  Voice_143526_AwakerVoiceTitle = {
    Text = "Início da Investigação"
  },
  Voice_143527_AwakerVoiceContent = {
    Text = "A espiritualidade gera novos corpos, os corpos são preenchidos com conhecimento irrelevante, e então esses indivíduos belos e vibrantes se reunirão para sempre em um único lugar.\nAinda se lembra do que eu disse? As profundezas do oceano acolhem tudo... e retêm tudo."
  },
  Voice_143527_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexão"
  },
  Voice_143527_UnlockDesc = {
    Text = "Nível de iluminação atingiu 3 para desbloquear"
  },
  Voice_143528_AwakerVoiceContent = {
    Text = "Pesadelo, bloqueie-Os."
  },
  Voice_143528_AwakerVoiceTitle = {
    Text = "Defesa · I"
  },
  Voice_143529_AwakerVoiceContent = {
    Text = "Espero que essas criaturas não te arruínem com suas despesas. Você sabe, sustentar uma família grande não é tarefa fácil."
  },
  Voice_143529_AwakerVoiceTitle = {
    Text = "Atualizar·II"
  },
  Voice_143530_AwakerVoiceContent = {
    Text = "Há muito, muito tempo atrás, antes que a terra emergisse do oceano, este planeta despertou certas espiritualidades especiais. Poderosas, majestosas, impossíveis de Voyeur.\nElas não podem ser definidas como hostis ou amigáveis; os humanos, assim como inúmeros seres do passado, são irrelevantes para Elas — serão apagados como poeira ou protegidos junto ao território."
  },
  Voice_143530_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Dois"
  },
  Voice_143530_UnlockDesc = {
    Text = "Nível de afinidade atingido 4 desbloqueado"
  },
  Voice_143531_AwakerVoiceContent = {
    Text = "Apenas o envelhecimento é a aventura que você precisa enfrentar sozinho, seu melhor amigo e seu inimigo mais difícil de lidar. As luzes de Ebwynnos o expulsarão completamente... Apenas algumas memórias sem importância, você não precisa ser ancorado por elas."
  },
  Voice_143531_AwakerVoiceTitle = {
    Text = "Iluminar·Construção"
  },
  Voice_143531_UnlockDesc = {
    Text = "Nível de iluminação atingiu 11 para desbloquear"
  },
  Voice_143532_AwakerVoiceContent = {
    Text = "Abandone a ilusão de Fuga."
  },
  Voice_143532_AwakerVoiceTitle = {
    Text = "Habilidade Especial · Um"
  },
  Voice_143533_AwakerVoiceContent = {
    Text = "Você se tornará pó cinzento e branco."
  },
  Voice_143533_AwakerVoiceTitle = {
    Text = "Fúria Explosiva"
  },
  Voice_143534_AwakerVoiceContent = {Text = "Hmph!"},
  Voice_143534_AwakerVoiceTitle = {Text = "golpear"},
  Voice_143535_AwakerVoiceContent = {
    Text = "Que atitude inteligente, criança. Os seguidores de monstros estrangeiros são sempre tolos o suficiente para jogar cadáveres no mar — isso não conta como presente, não é mesmo?"
  },
  Voice_143535_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · I"
  },
  Voice_143536_AwakerVoiceContent = {
    Text = "Você já foi marcado."
  },
  Voice_143536_AwakerVoiceTitle = {
    Text = "Habilidade Especial · Dois"
  },
  Voice_143537_AwakerVoiceContent = {
    Text = "Mesmo sem querer admitir, em raríssimas ocasiões, sinto que o envelhecimento não é a única coisa que o tempo traz — é apenas um símbolo.\nPor isso, permito que ele exista em mim. Claro — apenas na aparência."
  },
  Voice_143537_AwakerVoiceTitle = {
    Text = "Conversa·Coisas favoritas"
  },
  Voice_143539_AwakerVoiceContent = {
    Text = "A Oração é eficaz. Imagine que, mesmo que insetos formem caracteres Reo diante de você, você ainda consideraria responder às súplicas dos insetos."
  },
  Voice_143539_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Três"
  },
  Voice_143539_UnlockDesc = {
    Text = "Nível de afinidade atingido 6 desbloqueado"
  },
  Voice_143540_AwakerVoiceContent = {
    Text = "Hahaha, tudo bem, não faça essa expressão, meu pequeno amigo.\nIsso é apenas uma tradição que os chamados \"velhos deuses\" devem seguir. Quanto a você, sem nenhum preço ou condição — estarei sempre do seu lado."
  },
  Voice_143540_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Cinco"
  },
  Voice_143540_UnlockDesc = {
    Text = "Nível de afinidade atingido 10 desbloqueado"
  },
  Voice_143554_AwakerVoiceContent = {
    Text = "Hmph, um monstrozinho que se mistura com monstros estrangeiros.\nAlgum idiota teve a audácia de me colocar no mesmo altar que ele — que insulto!"
  },
  Voice_143554_AwakerVoiceTitle = {
    Text = "Conversa: Sobre Tulu"
  },
  Voice_143554_UnlockDesc = {
    Text = "Desbloqueado após obter o Despertador \"Tulu\""
  },
  Voice_143555_AwakerVoiceContent = {
    Text = "O inimigo do meu inimigo é meu amigo. Se houver oportunidade, não me importo de fechar um bom negócio roubando o brinquedo favorito do meu rival."
  },
  Voice_143555_AwakerVoiceTitle = {
    Text = "Conversa: Sobre Ryker"
  },
  Voice_143555_UnlockDesc = {
    Text = "Após obter o despertador \"Ryker\", desbloqueado"
  },
  Voice_146158_AwakerVoiceContent = {
    Text = "Oh? Você quer lutar comigo, aqui? Pode ser."
  },
  Voice_146158_AwakerVoiceTitle = {
    Text = "Conversa·Toque"
  },
  Voice_146159_AwakerVoiceContent = {
    Text = "Mais — me dê mais força!"
  },
  Voice_146159_AwakerVoiceTitle = {
    Text = "Atualizar·II"
  },
  Voice_146160_AwakerVoiceContent = {
    Text = "Não gosto daqueles com um coração dividido, pois tal divisão geralmente significa fraqueza. Mas você é uma exceção. Já acreditei que aqueles que carregam demais jamais poderiam ir longe. Mas o caminho que você escolheu me surpreende… Talvez um oponente trilhando um caminho diferente seja mais digno de aprimoramento e desafio. Não concorda, \"oponente\"?"
  },
  Voice_146160_AwakerVoiceTitle = {
    Text = "Conversa·Sobre Guardião do Segredo"
  },
  Voice_146161_AwakerVoiceContent = {
    Text = "Cetus do Mar Astral — devore-os todos!"
  },
  Voice_146161_AwakerVoiceTitle = {
    Text = "Sobre-Exaltação Aliemus Explosão·II"
  },
  Voice_146162_AwakerVoiceContent = {
    Text = "Honre-se por enfrentar a mim!"
  },
  Voice_146162_AwakerVoiceTitle = {
    Text = "Habilidade·Um"
  },
  Voice_146163_AwakerVoiceContent = {
    Text = "Que as estrelas testemunhem a aniquilação!"
  },
  Voice_146163_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_146164_AwakerVoiceContent = {
    Text = "Não é suficiente. Longe de ser suficiente…"
  },
  Voice_146164_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · I"
  },
  Voice_146165_AwakerVoiceContent = {Text = "Heh."},
  Voice_146165_AwakerVoiceTitle = {
    Text = "Golpe·Quatro"
  },
  Voice_146166_AwakerVoiceContent = {Text = "Hmph."},
  Voice_146166_AwakerVoiceTitle = {
    Text = "Defesa · I"
  },
  Voice_146167_AwakerVoiceContent = {
    Text = "Importo-me pouco com o declínio deste mundo — mas não deixarei que ele atrapalhe minha busca pela força."
  },
  Voice_146167_AwakerVoiceTitle = {
    Text = "Conversa fiada·Sobre a crise"
  },
  Voice_146168_AwakerVoiceContent = {
    Text = "Duvidar do valor da existência simplesmente porque o esquecimento aguarda... Não tenho interesse em debates tão infantis. A Destruição não significa nada, tampouco a memória. A força em si é o significado."
  },
  Voice_146168_AwakerVoiceTitle = {
    Text = "Conversa: Sobre Doll: Inferno"
  },
  Voice_146168_UnlockDesc = {
    Text = "Após obter o despertador \"Derretido·Boneca\", desbloqueado"
  },
  Voice_146169_AwakerVoiceContent = {
    Text = "Vejo uma vontade alienígena em seus olhos. Impura, mas tenaz o suficiente. Venha, mostre-me que força ou anseio o trouxe até mim."
  },
  Voice_146169_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_146170_AwakerVoiceContent = {Text = "Ha!"},
  Voice_146170_AwakerVoiceTitle = {Text = "Ataque·Um"},
  Voice_146171_AwakerVoiceContent = {
    Text = "Honre-se por enfrentar a mim!"
  },
  Voice_146171_AwakerVoiceTitle = {
    Text = "Habilidade·Um"
  },
  Voice_146172_AwakerVoiceContent = {
    Text = "O cheiro do caos — que nostalgia… Desde o momento em que nasci deste vazio, minha busca nunca mudou."
  },
  Voice_146172_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexão"
  },
  Voice_146172_UnlockDesc = {
    Text = "Nível de iluminação atingiu 3 para desbloquear"
  },
  Voice_146173_AwakerVoiceContent = {
    Text = "Você deseja me desafiar? Admiro sua coragem, e lhe concederei a honra de ser derrotado. Considere isso meu respeito pelo \"Guardião do Misaq\"."
  },
  Voice_146173_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Dois"
  },
  Voice_146173_UnlockDesc = {
    Text = "Nível de afinidade atingido 4 desbloqueado"
  },
  Voice_146174_AwakerVoiceContent = {
    Text = "Uma falsa utopia, repleta de fracos, covardes e tolos que se iludem. Mas não importa. Este lugar me traz os oponentes mais emocionantes — e isso é suficiente."
  },
  Voice_146174_AwakerVoiceTitle = {
    Text = "Conversa·Sobre Missaga"
  },
  Voice_146175_AwakerVoiceContent = {
    Text = "Desperdiçar uma força imensa, aprisionando seu talento em um longo sonho por medo, culpa e fadiga. Que pena."
  },
  Voice_146175_AwakerVoiceTitle = {
    Text = "Conversa: Sobre Tulu"
  },
  Voice_146175_UnlockDesc = {
    Text = "Desbloqueado após obter o Despertador \"Tulu\""
  },
  Voice_146176_AwakerVoiceContent = {
    Text = "Mal vale meu tempo."
  },
  Voice_146176_AwakerVoiceTitle = {
    Text = "Investigação Bem-sucedida"
  },
  Voice_146177_AwakerVoiceContent = {
    Text = "O selo se afrouxa um pouco… A força das profundezas do universo está surgindo. Não sentia isso há eras…"
  },
  Voice_146177_AwakerVoiceTitle = {
    Text = "Iluminar·Visão Remota"
  },
  Voice_146177_UnlockDesc = {
    Text = "Nível de iluminação atingiu 1 para desbloquear"
  },
  Voice_146178_AwakerVoiceContent = {
    Text = "Cetus do Mar Astral — devore-os todos!"
  },
  Voice_146178_AwakerVoiceTitle = {
    Text = "Superexaltação"
  },
  Voice_146179_AwakerVoiceContent = {
    Text = "…Exaltante."
  },
  Voice_146179_AwakerVoiceTitle = {Text = "Acertar·1"},
  Voice_146180_AwakerVoiceContent = {
    Text = "Vaguei pelo vasto cosmos por eras; lancei todos aqueles \"poderosos\" no abismo. Você é único, mas para ficar ao meu lado, primeiro aprenda a manter a cabeça erguida. Não tenho uso para covardes."
  },
  Voice_146180_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Três"
  },
  Voice_146180_UnlockDesc = {
    Text = "Nível de afinidade atingido 6 desbloqueado"
  },
  Voice_146181_AwakerVoiceContent = {
    Text = "Corajoso ou covarde, forte ou frágil… Heh — não, não me importo com o tipo de pessoa que meu oponente é. Qualquer oponente digno me traz uma emoção genuína."
  },
  Voice_146181_AwakerVoiceTitle = {
    Text = "Conversa·Coisas favoritas"
  },
  Voice_146182_AwakerVoiceContent = {
    Text = "Fraqueza. De todas as coisas vis neste mundo, a fraqueza é o pecado mais miserável. Todos nascem com uma espada na mão; ninguém tem o direito de ceder antes do fim, nem de pisar no campo de batalha predestinado já resignado à derrota. Isso insulta tanto o seu oponente quanto a si mesmo."
  },
  Voice_146182_AwakerVoiceTitle = {
    Text = "Conversa·Coisas odiadas"
  },
  Voice_146183_AwakerVoiceContent = {
    Text = "Carcaça Astral corrompida — desperte!"
  },
  Voice_146183_AwakerVoiceTitle = {
    Text = "Despertar do Conhecimento Espiritual"
  },
  Voice_146184_AwakerVoiceContent = {
    Text = "Heh… Isso foi emocionante. Da próxima vez, não vou me conter."
  },
  Voice_146184_AwakerVoiceTitle = {
    Text = "Investigação Interrompida"
  },
  Voice_146185_AwakerVoiceContent = {
    Text = "Meus ossos tremem de alegria… Testemunhei seu esforço. E isso prova que você é digno de ficar ao meu lado, Guardião."
  },
  Voice_146185_AwakerVoiceTitle = {
    Text = "Iluminar: Insight"
  },
  Voice_146185_UnlockDesc = {
    Text = "Nível de iluminação atingiu 7 para desbloquear"
  },
  Voice_146186_AwakerVoiceContent = {
    Text = "Heh… Você vê claramente, Guardião. As correntes da força existem para ser despedaçadas!"
  },
  Voice_146186_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_146186_UnlockDesc = {
    Text = "Nível de iluminação atingiu 2 para desbloquear"
  },
  Voice_146187_AwakerVoiceContent = {Text = "Sim?"},
  Voice_146187_AwakerVoiceTitle = {
    Text = "Acertar · II"
  },
  Voice_146188_AwakerVoiceContent = {Text = "Sim?"},
  Voice_146188_AwakerVoiceTitle = {
    Text = "Acertar·III"
  },
  Voice_146189_AwakerVoiceContent = {
    Text = "Logo à frente… o zênite da força que persegui a vida toda… Você trilhou este caminho comigo e me guiou até este limiar. Estou ansioso para testemunhar esse dia derradeiro ao seu lado!"
  },
  Voice_146189_AwakerVoiceTitle = {
    Text = "Iluminar·Construção"
  },
  Voice_146189_UnlockDesc = {
    Text = "Nível de iluminação atingiu 11 para desbloquear"
  },
  Voice_146190_AwakerVoiceContent = {
    Text = "Talvez eu tenha julgado você precipitadamente... Seu crescimento e sua força oculta me surpreenderam. Observei incontáveis vidas se apagarem com o tempo, mas você... é verdadeiramente diferente. Estou bastante curioso sobre a verdadeira origem da sua força."
  },
  Voice_146190_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Quatro"
  },
  Voice_146190_UnlockDesc = {
    Text = "Nível de afinidade atingido 8 desbloqueado"
  },
  Voice_146192_AwakerVoiceContent = {
    Text = "Goela do Inferno, abra-se para mim!"
  },
  Voice_146192_AwakerVoiceTitle = {
    Text = "Fúria Explosiva"
  },
  Voice_146193_AwakerVoiceContent = {
    Text = "Ah, entendo… a força nunca teve um fim. O verdadeiro desafio apenas começou! Foi você quem me trouxe até aqui e me mostrou a realidade. Em breve, apresentarei um guerreiro ainda mais perfeito diante de você. Certifique-se de retornar ainda mais forte, meu \"oponente\"."
  },
  Voice_146193_AwakerVoiceTitle = {
    Text = "Iluminar·Florescer"
  },
  Voice_146193_UnlockDesc = {
    Text = "Nível de iluminação atingiu 15 para desbloquear"
  },
  Voice_146194_AwakerVoiceContent = {
    Text = "Truques mesquinhos."
  },
  Voice_146194_AwakerVoiceTitle = {Text = "Defesa·II"},
  Voice_146195_AwakerVoiceContent = {
    Text = "A força ferve em minha medula!"
  },
  Voice_146195_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · Três"
  },
  Voice_146196_AwakerVoiceContent = {
    Text = "Devorar — tudo isso!"
  },
  Voice_146196_AwakerVoiceTitle = {Text = "Ataque·II"},
  Voice_146197_AwakerVoiceContent = {
    Text = "Misericórdia, fraqueza, confusão… seus olhos estão turvos de impurezas. Aquele que vacila jamais poderá compreender o que é a força."
  },
  Voice_146197_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Um"
  },
  Voice_146197_UnlockDesc = {
    Text = "Nível de afinidade atingido 2 desbloqueado"
  },
  Voice_146198_AwakerVoiceContent = {
    Text = "A verdadeira Força nunca teve relação com vingança ou com ser Guardião. Força é Apenas Força — a outra eu jamais compreendeu \"verdadeiramente\" esse princípio. Esta é a raiz de sua fraqueza."
  },
  Voice_146198_AwakerVoiceTitle = {
    Text = "Conversa: Sobre Lotan"
  },
  Voice_146198_UnlockDesc = {
    Text = "Após obter o despertador \"Lotan\", desbloqueado"
  },
  Voice_146199_AwakerVoiceContent = {
    Text = "Ouça bem, direi isso apenas uma vez:\nEu, Lotan, considero você um oponente digno da minha paciência.\nAté que você alcance seu auge, serei sua lâmina mais confiável. Esta promessa não tem nada a ver com sentimento ou lealdade. Você é meu rival mais emocionante, e jamais permitirei que caia no caminho."
  },
  Voice_146199_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Cinco"
  },
  Voice_146199_UnlockDesc = {
    Text = "Nível de afinidade atingido 10 desbloqueado"
  },
  Voice_146200_AwakerVoiceContent = {
    Text = "Venha — me mate, ou seja morto."
  },
  Voice_146200_AwakerVoiceTitle = {
    Text = "Início da Investigação"
  },
  Voice_146201_AwakerVoiceContent = {
    Text = "Goela do Inferno, abra-se para mim!"
  },
  Voice_146201_AwakerVoiceTitle = {
    Text = "Exaltar · Dois"
  },
  Voice_146521_AwakerVoiceContent = {
    Text = "Onde a lâmina de osso aponta, tudo se desintegra!"
  },
  Voice_146521_AwakerVoiceTitle = {
    Text = "Habilidade Especial · Um"
  },
  Voice_147047_AwakerVoiceContent = {
    Text = "A força… não tem fim!"
  },
  Voice_147047_AwakerVoiceTitle = {
    Text = "Habilidade Especial · Dois"
  },
  Voice_147493_AwakerVoiceTitle = {
    Text = "Iluminar·Visão Remota"
  },
  Voice_147493_UnlockDesc = {
    Text = "Nível de iluminação atingiu 1 para desbloquear"
  },
  Voice_147494_AwakerVoiceContent = {
    Text = "(Uma canção rouca e suave)"
  },
  Voice_147494_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_147495_AwakerVoiceContent = {
    Text = "Mais espectadores, precisamos de mais espectadores"
  },
  Voice_147495_AwakerVoiceTitle = {
    Text = "Investigação Interrompida"
  },
  Voice_147496_AwakerVoiceContent = {
    Text = "Areia... Deserto branco... Aqui é perigoso, vamos sair juntos"
  },
  Voice_147496_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Dois"
  },
  Voice_147496_UnlockDesc = {
    Text = "Nível de afinidade atingido 4 desbloqueado"
  },
  Voice_147497_AwakerVoiceContent = {
    Text = "Ainda me lembro do mapa do novo lar, todo colorido e muito bonito. É para lá que devemos ir. Podemos cantar, podemos ser felizes"
  },
  Voice_147497_AwakerVoiceTitle = {
    Text = "Conversa·Coisas favoritas"
  },
  Voice_147498_AwakerVoiceContent = {Text = "Ah!"},
  Voice_147498_AwakerVoiceTitle = {
    Text = "Golpe·Quatro"
  },
  Voice_147499_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Cinco"
  },
  Voice_147499_UnlockDesc = {
    Text = "Nível de afinidade atingido 10 desbloqueado"
  },
  Voice_147500_AwakerVoiceContent = {Text = "Hmm...?"},
  Voice_147500_AwakerVoiceTitle = {Text = "Acertar·1"},
  Voice_147501_AwakerVoiceContent = {
    Text = "Aquilo é... a voz do cosmos"
  },
  Voice_147501_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · Três"
  },
  Voice_147502_AwakerVoiceContent = {
    Text = "Você voltou. Como antes, sente-se ao meu lado e espere comigo. Esperar o quê...? Apenas esperar"
  },
  Voice_147502_AwakerVoiceTitle = {
    Text = "Conversa·Sobre Guardião do Segredo"
  },
  Voice_147503_AwakerVoiceContent = {
    Text = "Ensaio perfeito, acho que estou pronto para o palco"
  },
  Voice_147503_AwakerVoiceTitle = {
    Text = "Iluminar·Construção"
  },
  Voice_147503_UnlockDesc = {
    Text = "Nível de iluminação atingiu 11 para desbloquear"
  },
  Voice_147504_AwakerVoiceContent = {Text = "Cair."},
  Voice_147504_AwakerVoiceTitle = {Text = "Ataque·Um"},
  Voice_147505_AwakerVoiceContent = {
    Text = "Dedicado à desolação e à morte."
  },
  Voice_147505_AwakerVoiceTitle = {
    Text = "Despertar do Conhecimento Espiritual"
  },
  Voice_147506_AwakerVoiceContent = {
    Text = "Não sou louco, nem nunca me senti triste. Não acredite em boatos absurdos"
  },
  Voice_147506_AwakerVoiceTitle = {
    Text = "Conversa·Coisas odiadas"
  },
  Voice_147507_AwakerVoiceContent = {
    Text = "Estranho, eles parecem temer minha canção"
  },
  Voice_147507_AwakerVoiceTitle = {
    Text = "Investigação Bem-sucedida"
  },
  Voice_147508_AwakerVoiceContent = {Text = "Shh..."},
  Voice_147508_AwakerVoiceTitle = {
    Text = "Habilidade·Um"
  },
  Voice_147509_AwakerVoiceContent = {
    Text = "Que figurino bonito, brilhante"
  },
  Voice_147509_AwakerVoiceTitle = {
    Text = "Iluminar: Insight"
  },
  Voice_147509_UnlockDesc = {
    Text = "Nível de iluminação atingiu 7 para desbloquear"
  },
  Voice_147510_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · I"
  },
  Voice_147511_AwakerVoiceContent = {
    Text = "Oh, cores das estrelas que permanecem até hoje"
  },
  Voice_147511_AwakerVoiceTitle = {
    Text = "Fúria Explosiva"
  },
  Voice_147512_AwakerVoiceContent = {Text = "Cante."},
  Voice_147512_AwakerVoiceTitle = {Text = "Ataque·II"},
  Voice_147513_AwakerVoiceContent = {
    Text = "Treinamento de voz correto...? Mas eu gosto da minha voz atual"
  },
  Voice_147513_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_147513_UnlockDesc = {
    Text = "Nível de iluminação atingiu 2 para desbloquear"
  },
  Voice_147514_AwakerVoiceTitle = {
    Text = "Conversa·Toque"
  },
  Voice_147515_AwakerVoiceContent = {
    Text = "A voz parece ter mudado"
  },
  Voice_147515_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexão"
  },
  Voice_147515_UnlockDesc = {
    Text = "Nível de iluminação atingiu 3 para desbloquear"
  },
  Voice_147516_AwakerVoiceContent = {
    Text = "Como está, minha voz é bonita?"
  },
  Voice_147516_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_147517_AwakerVoiceContent = {Text = "Durma bem"},
  Voice_147517_AwakerVoiceTitle = {
    Text = "Habilidade·Um"
  },
  Voice_147518_AwakerVoiceTitle = {
    Text = "Início da Investigação"
  },
  Voice_147519_AwakerVoiceContent = {Text = "Ok"},
  Voice_147519_AwakerVoiceTitle = {Text = "Defesa·II"},
  Voice_147520_AwakerVoiceContent = {Text = "Ah!"},
  Voice_147520_AwakerVoiceTitle = {
    Text = "Acertar·III"
  },
  Voice_147521_AwakerVoiceContent = {
    Text = "Obrigado... Devo agradecer?"
  },
  Voice_147521_AwakerVoiceTitle = {
    Text = "Atualizar·II"
  },
  Voice_147522_AwakerVoiceContent = {
    Text = "*suspiro*..."
  },
  Voice_147522_AwakerVoiceTitle = {
    Text = "Defesa · I"
  },
  Voice_147523_AwakerVoiceContent = {Text = "Brilhe"},
  Voice_147523_AwakerVoiceTitle = {
    Text = "Fúria Explosiva"
  },
  Voice_147524_AwakerVoiceContent = {
    Text = "A sensação há muito perdida... finalmente de volta ao palco. Obrigado, Guardião do Segredo"
  },
  Voice_147524_AwakerVoiceTitle = {
    Text = "Iluminar·Florescer"
  },
  Voice_147524_UnlockDesc = {
    Text = "Nível de iluminação atingiu 15 para desbloquear"
  },
  Voice_147525_AwakerVoiceContent = {
    Text = "Desculpe interromper... pode me tirar da árvore? Não me lembro por que subi, talvez por causa das nuvens nostálgicas"
  },
  Voice_147525_AwakerVoiceTitle = {
    Text = "Chat·Sobre a Universidade Mythag"
  },
  Voice_147526_AwakerVoiceContent = {
    Text = "Meu povo nunca me deixou, eles só foram para um lugar muito, muito distante"
  },
  Voice_147526_AwakerVoiceTitle = {
    Text = "Conversa Informal · Sobre os Membros do Clã"
  },
  Voice_147527_AwakerVoiceContent = {
    Text = "Você ouviu isso?"
  },
  Voice_147527_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_147528_AwakerVoiceContent = {Text = "Oh."},
  Voice_147528_AwakerVoiceTitle = {
    Text = "Acertar · II"
  },
  Voice_147529_AwakerVoiceContent = {
    Text = "Você parece sempre estar por perto... Eu sei, você deve ser meu fã"
  },
  Voice_147529_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Três"
  },
  Voice_147529_UnlockDesc = {
    Text = "Nível de afinidade atingido 6 desbloqueado"
  },
  Voice_147530_AwakerVoiceContent = {
    Text = "Lá lá lá~ O que? Existe um Clades que pode acabar com o mundo aqui? Ah... Eu preciso pentear meu cabelo e encontrar minha irmã..."
  },
  Voice_147530_AwakerVoiceTitle = {
    Text = "Bate-papo · Sobre Dissolução"
  },
  Voice_147531_AwakerVoiceContent = {
    Text = "Shh... Não fale, há vilões vindo. Eles vão nos capturar e não nos deixarão embarcar"
  },
  Voice_147531_AwakerVoiceTitle = {
    Text = "Conversas Ociosas · Sobre Segurança"
  },
  Voice_147532_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Um"
  },
  Voice_147532_UnlockDesc = {
    Text = "Nível de afinidade atingido 2 desbloqueado"
  },
  Voice_147533_AwakerVoiceContent = {
    Text = "Quando acordei, o planeta estava se destruindo. Vi o céu noturno se desintegrar, o mundo se tornou uma tela inflada pelo vento, primeiro deformando, depois rasgando e se despedaçando"
  },
  Voice_147533_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Quatro"
  },
  Voice_147533_UnlockDesc = {
    Text = "Nível de afinidade atingido 8 desbloqueado"
  },
  Voice_147534_AwakerVoiceContent = {
    Text = "Este é meu pôster assinado, desenhado pelo Sr. Pikman. Eu o apresento a você."
  },
  Voice_147534_AwakerVoiceTitle = {
    Text = "Bate-papo · Sobre Desmaio"
  },
  Voice_147534_UnlockDesc = {
    Text = "Após obter o despertador \"Desmaio\", desbloqueado"
  },
  Voice_149667_AwakerVoiceContent = {
    Text = "Hmm? Curioso, estamos? O cofre de tesouros de uma Madrinha não é para os olhos de estranhos, saiba. Se você está morrendo de vontade de saber o que está tão cheio lá dentro... por que não entrar para a Ordem Sagrada agora mesmo... Hehe."
  },
  Voice_149667_AwakerVoiceTitle = {
    Text = "Conversa·Toque"
  },
  Voice_149668_AwakerVoiceContent = {
    Text = "Você não acredita em mim? Buá-buá... Suponho que realmente não dá para enganar todo mundo... A verdade é que sou a filha bastarda de Bohemond VI de @1, vivendo escondida entre os mortais, e só afirmei ser uma fada para escapar da caça dos inimigos... Contei meu segredo mais precioso agora. Você não vai deixar de acreditar em mim... vai?"
  },
  Voice_149668_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Três"
  },
  Voice_149668_UnlockDesc = {
    Text = "Nível de afinidade atingido 6 desbloqueado"
  },
  Voice_149669_AwakerVoiceContent = {Text = "Ai~"},
  Voice_149669_AwakerVoiceTitle = {Text = "Acertar·1"},
  Voice_149670_AwakerVoiceContent = {
    Text = "Doces demais? Não, não, não, esse é o segredo da Madrinha para manter o sorriso, saiba. Como se eu fosse parar por causa de uma coisinha como uma cárie?"
  },
  Voice_149670_AwakerVoiceTitle = {
    Text = "Conversa·Coisas favoritas"
  },
  Voice_149671_AwakerVoiceContent = {
    Text = "Venha, fique aqui ao lado da sua Fada. O quê? Todos compartilham as oferendas e comem juntos? ...Bem. Se é o costume do Misaq... então eu... certamente não tenho nenhuma objeção. Vamos lá, todos, vamos fazer uma festa!"
  },
  Voice_149671_AwakerVoiceTitle = {
    Text = "Iluminar·Florescer"
  },
  Voice_149671_UnlockDesc = {
    Text = "Nível de iluminação atingiu 15 para desbloquear"
  },
  Voice_149672_AwakerVoiceContent = {
    Text = "Ora, ora, que cordeirinho devoto você é."
  },
  Voice_149672_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · I"
  },
  Voice_149673_AwakerVoiceContent = {
    Text = "Mais um pouquinho, e então a Fada vai abençoá-lo, hm?"
  },
  Voice_149673_AwakerVoiceTitle = {
    Text = "Atualizar·II"
  },
  Voice_149674_AwakerVoiceContent = {
    Text = "Vocês ainda são um pouco inexperientes~"
  },
  Voice_149674_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_149676_AwakerVoiceContent = {
    Text = "Esta cerimônia de adoração será mais grandiosa do que qualquer outra — e as oferendas também precisarão ser em maior número... Minha nossa, não vamos cortar os membros deles, claro! Sou uma fada bondosa; jamais faria algo para machucar alguém~"
  },
  Voice_149676_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexão"
  },
  Voice_149676_UnlockDesc = {
    Text = "Nível de iluminação atingiu 3 para desbloquear"
  },
  Voice_149677_AwakerVoiceContent = {
    Text = "Guardião do segredo, você está pronto para a confissão mais verdadeira de Caraboo, do fundo do seu coração?\nDe onde venho não importa nada. O que realmente importa é isto: Você é um presente que o céu me deu, e decidi ficar ao lado do meu precioso benfeitor, para sempre e sempre. \nIsso é mais uma mentira para impedir você de continuar vasculhando minha vida, você pergunta? Hehe, o que você acha?\nDe qualquer forma... acho que mereço um agradinho por compartilhar meus verdadeiros sentimentos com você. Uma bala de goma sabor maçã seria ótimo, por favor?"
  },
  Voice_149677_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Cinco"
  },
  Voice_149677_UnlockDesc = {
    Text = "Nível de afinidade atingido 10 desbloqueado"
  },
  Voice_149678_AwakerVoiceContent = {Text = "Hehe~"},
  Voice_149678_AwakerVoiceTitle = {Text = "Ataque·Um"},
  Voice_149680_AwakerVoiceContent = {
    Text = "Tudo bem! Da próxima vez, concentre-se em proteger sua Fada, e você não vai falhar~"
  },
  Voice_149680_AwakerVoiceTitle = {
    Text = "Investigação Interrompida"
  },
  Voice_149682_AwakerVoiceContent = {
    Text = "Nem tente me enganar!"
  },
  Voice_149682_AwakerVoiceTitle = {
    Text = "Defesa · I"
  },
  Voice_149683_AwakerVoiceContent = {
    Text = "Uauuu, tantas oferendas...! Ahem. Hehe, muito bem, você merece uma recompensa! Venha cá, vou te dar o beijo de uma fada! ...O que você está pensando? Na testa, obviamente!"
  },
  Voice_149683_AwakerVoiceTitle = {
    Text = "Iluminar: Insight"
  },
  Voice_149683_UnlockDesc = {
    Text = "Nível de iluminação atingiu 7 para desbloquear"
  },
  Voice_149684_AwakerVoiceContent = {
    Text = "Obrigada pelas oferendas, fiéis! Sua sempre compreensiva Madrinha mandará erguer uma estátua de ouro maciço de vocês no templo também. Minha nossa — para capturar aquela figura fria e elegante, terei que sair para recolher bem mais~"
  },
  Voice_149684_AwakerVoiceTitle = {
    Text = "Iluminar·Construção"
  },
  Voice_149684_UnlockDesc = {
    Text = "Nível de iluminação atingiu 11 para desbloquear"
  },
  Voice_149685_AwakerVoiceContent = {
    Text = "Você? ...Você é um dos nossos rebanhos, ainda não iluminado. Caraboo vai esperar, pacientemente, pelo dia em que você enxergar a verdadeira natureza do mundo. E quando esse dia chegar — lembre-se de oferecer seu corpo, sua lealdade e seus bens mundanos à Madrinha de todos. Hehe."
  },
  Voice_149685_AwakerVoiceTitle = {
    Text = "Conversa·Sobre Guardião do Segredo"
  },
  Voice_149686_AwakerVoiceContent = {
    Text = "Tudo na lista... já reunido? A fortuna de Misaq é mais profunda do que consigo imaginar... Se eu soubesse, teria... Hm? O que estou resmungando, você pergunta? Só agradecendo ao Lorde Dexter por sua generosidade, hehe~"
  },
  Voice_149686_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_149686_UnlockDesc = {
    Text = "Nível de iluminação atingiu 2 para desbloquear"
  },
  Voice_149687_AwakerVoiceContent = {
    Text = "O que eu mais odeio? Magos sem respeito por um contrato, obviamente. Um segredinho, só entre nós: todo mago sem exceção é um grande mentiroso. Todas as suas chamadas profecias e maldições? Só truques para te enganar e te deixar na miséria! E como você se protege...? Simples! É só deixar todo o seu dinheiro receber a bênção da Fada!"
  },
  Voice_149687_AwakerVoiceTitle = {
    Text = "Conversa·Coisas odiadas"
  },
  Voice_149688_AwakerVoiceContent = {
    Text = "Que prazer em conhecê-lo! Sou uma Fada Pálida de terras distantes. Quer saber mais? A bênção de uma fada vem em diferentes intensidades, dependendo do seu nível de membro, hehe~"
  },
  Voice_149688_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_149689_AwakerVoiceContent = {
    Text = "Nas cerimônias de adoração passadas, além do rito séptuplo e do voto tríplice, os fiéis me construíam um templo novinho em folha e apresentavam tributos suntuosos. Aqui está a lista!"
  },
  Voice_149689_AwakerVoiceTitle = {
    Text = "Iluminar·Visão Remota"
  },
  Voice_149689_UnlockDesc = {
    Text = "Nível de iluminação atingiu 1 para desbloquear"
  },
  Voice_149690_AwakerVoiceContent = {
    Text = "Vamos... enterre tudo o que deseja abandonar fundo na neve..."
  },
  Voice_149690_AwakerVoiceTitle = {
    Text = "Fúria Explosiva"
  },
  Voice_149691_AwakerVoiceContent = {
    Text = "Ouvi dizer que você anda perguntando sobre minha origem. Hehe, isso é um segredinho da Madrinha. Maaas, se você insistir em investigar, a Ordem Sagrada guarda uma biografia que escrevi eu mesma. Disponível para leitura por apenas cem mil Núcleos de prata. Quer tentar?"
  },
  Voice_149691_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Um"
  },
  Voice_149691_UnlockDesc = {
    Text = "Nível de afinidade atingido 2 desbloqueado"
  },
  Voice_149692_AwakerVoiceContent = {
    Text = "Oh, que lugar adorável — tantas crianças encantadoras, e subsídios de bem-estar generosos ao ponto do absurdo. Com tudo isso, logo terei juntado minha passagem para o Oriente..."
  },
  Voice_149692_AwakerVoiceTitle = {
    Text = "Conversa·Sobre Missaga"
  },
  Voice_149693_AwakerVoiceContent = {
    Text = "Não se esqueça de venerar sua Madrinha, hehe."
  },
  Voice_149693_AwakerVoiceTitle = {
    Text = "Despertar do Conhecimento Espiritual"
  },
  Voice_149694_AwakerVoiceContent = {
    Text = "Sinto muito, mas o domínio da Fada é terra sagrada — não recebemos lobisomens estranhos aqui... Algo sobre o ar cheirar a mentiras? O nariz dele deve estar com defeito."
  },
  Voice_149694_AwakerVoiceTitle = {
    Text = "Conversa: Sobre Ryker"
  },
  Voice_149694_UnlockDesc = {
    Text = "Após obter o despertador \"Ryker\", desbloqueado"
  },
  Voice_149695_AwakerVoiceContent = {
    Text = "Huh? Alguém está dizendo que sou uma fada falsa... Bem, fui descoberta. hehe. Mas sei que você não vai se importar... certo?"
  },
  Voice_149695_AwakerVoiceTitle = {
    Text = "Conversa: Sobre os Rumores"
  },
  Voice_149696_AwakerVoiceContent = {
    Text = "Mmm, delicioso~♪"
  },
  Voice_149696_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · Três"
  },
  Voice_149697_AwakerVoiceContent = {
    Text = "Calma, calma~"
  },
  Voice_149697_AwakerVoiceTitle = {Text = "Defesa·II"},
  Voice_149698_AwakerVoiceContent = {
    Text = "Cordeirinhos perdidos, sua Fada está aqui para lavar seus pecados, hehe~"
  },
  Voice_149698_AwakerVoiceTitle = {
    Text = "Investigação Bem-sucedida"
  },
  Voice_149699_AwakerVoiceContent = {
    Text = "Ainda não desistiu? Tudo bem, tudo bem — a própria Caraboo vai te contar. Veja bem, Caraboo é filha de Umapati, deusa de certo pico nevado que perfura as nuvens no Oriente... Hmm? Essa deusa tinha dois filhos e nenhuma filha? Bem, os registros do divino são sempre um pouco... incompletos, sabe."
  },
  Voice_149699_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Dois"
  },
  Voice_149699_UnlockDesc = {
    Text = "Nível de afinidade atingido 4 desbloqueado"
  },
  Voice_149700_AwakerVoiceContent = {
    Text = "Ta-dã~ a luz da Fada brilha sobre você agora. Vai em frente!"
  },
  Voice_149700_AwakerVoiceTitle = {
    Text = "Início da Investigação"
  },
  Voice_149701_AwakerVoiceContent = {
    Text = "Tudo bem, tudo bem, pare de investigar, tá bom? Seja um bom {Male=boy,Female=girl} e abandone essa investigaçãozinha rude, e eu vou secretamente compartilhar metade dos meus doces mais preciosos com você. Sabe, nos campos de batalha da Cruzada, doces eram um tesouro raro mesmo."
  },
  Voice_149701_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Quatro"
  },
  Voice_149701_UnlockDesc = {
    Text = "Nível de afinidade atingido 8 desbloqueado"
  },
  Voice_149702_AwakerVoiceContent = {
    Text = "A bênção de Caraboo pode curar todas as doenças do mundo — incluindo esta praga negra, claro... Claro que é verdade! Você só precisa ser devoto o suficiente, confiar em Caraboo o suficiente, hehe."
  },
  Voice_149702_AwakerVoiceTitle = {
    Text = "Conversa fiada·Sobre a crise"
  },
  Voice_149703_AwakerVoiceContent = {Text = "Ai~"},
  Voice_149703_AwakerVoiceTitle = {
    Text = "Acertar · II"
  },
  Voice_149704_AwakerVoiceContent = {
    Text = "Contemplem a luz da Fada!"
  },
  Voice_149704_AwakerVoiceTitle = {
    Text = "Habilidade·Um"
  },
  Voice_149705_AwakerVoiceContent = {
    Text = "O rito séptuplo, o voto tríplice — ofereça-os, e compre para si a absolvição da Fada!"
  },
  Voice_149705_AwakerVoiceTitle = {
    Text = "Superexaltação"
  },
  Voice_150079_AwakerVoiceContent = {
    Text = "Sinta isso!"
  },
  Voice_150079_AwakerVoiceTitle = {Text = "Ataque·II"},
  Voice_150104_AwakerVoiceContent = {
    Text = "Huh, como Ogier deixou você entrar? Ele prometeu que manteria todo mundo de fora. Você é o suserano dele...? Ugh, crianças pouco confiáveis são uma dor de cabeça. Trabalhei muito para preparar esta reunião, saiba. Digamos... cinquenta por cento das oferendas que arrecadarmos, e você faz vista grossa para mim?"
  },
  Voice_150104_AwakerVoiceTitle = {
    Text = "Conversa: Sobre Ogier"
  },
  Voice_150104_UnlockDesc = {
    Text = "Desbloqueia ao obter o despertador \"Ogier\""
  },
  Voice_22276_AwakerVoiceContent = {
    Text = "Apresse-se e termine. Não demore nas ruas."
  },
  Voice_22276_AwakerVoiceTitle = {
    Text = "Início da Investigação"
  },
  Voice_36679_AwakerVoiceContent = {
    Text = "Ele se juntou ao culto enquanto eu estava dormindo, então não tenho conexão com ele.\nNo entanto, ouvi que ele veio por conta própria, querendo abandonar sua forma humana para se tornar um \"Marinheiro\"... Hmph, mais um tolo cegado pelo poder."
  },
  Voice_36679_AwakerVoiceTitle = {
    Text = "Bate-papo · Sobre Caecus"
  },
  Voice_36679_UnlockDesc = {
    Text = "Desbloqueado após completar o Capítulo 6 da \"Operação de Investigação\""
  },
  Voice_36680_AwakerVoiceContent = {
    Text = "Goliath nunca foi um cachorro leal. Eu não consigo entender por que Miryam o valoriza tanto... Se não estivesse preso, ele seria o primeiro a correr."
  },
  Voice_36680_AwakerVoiceTitle = {
    Text = "Bate-papo · Sobre Golias"
  },
  Voice_36680_UnlockDesc = {
    Text = "Desbloqueado após completar o Capítulo 6 da \"Operação de Investigação\""
  },
  Voice_36681_AwakerVoiceContent = {
    Text = "Os marinheiros não nascem assim. Para se misturarem, passam a primeira metade de suas vidas como humanos...\nÉ melhor você ficar atento—o proprietário da sua confeitaria favorita pode ser um deles!"
  },
  Voice_36681_AwakerVoiceTitle = {
    Text = "Conversa Informal · Sobre o Marinheiro"
  },
  Voice_36681_UnlockDesc = {
    Text = "Desbloqueado após completar o Capítulo 6 da \"Operação de Investigação\""
  },
  Voice_36682_AwakerVoiceContent = {
    Text = "A canção de marinheiro desafinada de Celeste, o ensopado de peixe defumado característico do capitão, cobertores encharcados e endurecidos pelo vento do mar... Apesar de ser perigoso e tenso, eu jamais esquecerei os meses que passamos no exílio no mar."
  },
  Voice_36682_AwakerVoiceTitle = {
    Text = "Conversa · Sobre \"Navio Fantasma\""
  },
  Voice_36682_UnlockDesc = {
    Text = "Desbloqueado após completar o Capítulo 6 da \"Operação de Investigação\""
  },
  Voice_36683_AwakerVoiceContent = {
    Text = "Embora todos na escola pareçam muito ocupados...\nAqui, há uma sensação de paz que eu nunca experimentei antes.\nA sensação de se reunir para um mesmo objetivo e lutar juntos... Hmph, não é ruim."
  },
  Voice_36683_AwakerVoiceTitle = {
    Text = "Chat·Sobre a Universidade Mythag·II"
  },
  Voice_36683_UnlockDesc = {
    Text = "Desbloqueado após completar o Capítulo 6 da \"Operação de Investigação\""
  },
  Voice_36684_AwakerVoiceContent = {
    Text = "A cama é muito dura, o clima é muito frio, e o chá da tarde sempre tem gosto de água de enxágue de grama... Eu tenho mil razões para não gostar deste lugar. \nNo entanto, só porque \"você está aqui\", eu poderia ficar relutantemente."
  },
  Voice_36684_AwakerVoiceTitle = {
    Text = "Conversa Ociosa: Sobre o Guardião III"
  },
  Voice_36684_UnlockDesc = {
    Text = "Desbloqueado após completar o Capítulo 6 da \"Operação de Investigação\""
  },
  Voice_36685_AwakerVoiceContent = {
    Text = "Obrigado... Huh? Por que estou te agradecendo? Não é óbvio! É por tudo que você fez por mim no mar...\nEspere um minuto, por que você está rindo? Você só quer me ver envergonhado, não é?"
  },
  Voice_36685_AwakerVoiceTitle = {
    Text = "Conversa Ociosa · Sobre o Guardião · II"
  },
  Voice_36685_UnlockDesc = {
    Text = "Desbloqueado após completar o Capítulo 6 da \"Operação de Investigação\""
  },
  Voice_36686_AwakerVoiceContent = {
    Text = "Eu uma vez pensei que havia um laço familiar entre nós...\nMas após tudo o que aconteceu, percebi que aqueles momentos fugazes de calor não eram nada mais do que meu desejo de ilusão.\nO que você faz com ela é da sua conta, só não a deixe se aproximar de mim."
  },
  Voice_36686_AwakerVoiceTitle = {
    Text = "Chat·Sobre Miryam·II"
  },
  Voice_36686_UnlockDesc = {
    Text = "Desbloqueado após completar o Capítulo 6 da \"Operação de Investigação\""
  },
  Voice_36687_AwakerVoiceContent = {
    Text = "Como é estranho... Este sentimento é realmente estranho.\nMeu coração parou de bater, mas meu corpo ainda está quente... Ei, venha aqui e toque minha mão. Diga que isso não é uma ilusão."
  },
  Voice_36687_AwakerVoiceTitle = {
    Text = "Conversa Casual · Sobre \"Despertador\""
  },
  Voice_36687_UnlockDesc = {
    Text = "Desbloqueado após completar o Capítulo 6 da \"Operação de Investigação\""
  },
  Voice_45153_AwakerVoiceContent = {
    Text = "Eu posso não ter nascido no Reino de Leo, mas a Grande Igreja é onde recebi minha segunda vida. Portanto, por que não posso considerar este lugar meu lar?"
  },
  Voice_45153_AwakerVoiceTitle = {
    Text = "Conversa Ociosa · Sobre o Lar"
  },
  Voice_45154_AwakerVoiceContent = {
    Text = "Após anos de uma praga invisível, o Pai Deus finalmente ouviu minhas orações e me concedeu a \"Abençoar\" que pode contrariar o sofrimento.\nDe fato, concede vida, mas também exige um preço.\nComo executor, naturalmente devo suportar o peso em nome dos abençoados."
  },
  Voice_45154_AwakerVoiceTitle = {
    Text = "Conversa Casual · Sobre \"A Benção\""
  },
  Voice_45155_AwakerVoiceContent = {
    Text = "Para mim, o estado de ser um Despertar é um presente do Pai para a alma em Seu abraço. É uma segunda vida, uma oportunidade para corrigir arrependimentos do passado.\nContinuarei a obra do Pai, cumprirei meus deveres como Seu proxy e aliviarei mais sofrimentos."
  },
  Voice_45155_AwakerVoiceTitle = {
    Text = "Conversa Casual · Sobre \"Despertador\""
  },
  Voice_45156_AwakerVoiceContent = {
    Text = "Deixe-me expressar minha gratidão mais uma vez, Guardião, por respeitar meus desejos e manter meu segredo do Comitê. Se eles intervierem, temo que não me permitam continuar servindo a Igreja."
  },
  Voice_45156_AwakerVoiceTitle = {
    Text = "Conversa Ociosa · Sobre o Guardião · II"
  },
  Voice_45156_UnlockDesc = {
    Text = "Desbloqueado após completar a Operação Especial \"Primária de Sangue\""
  },
  Voice_45157_AwakerVoiceContent = {
    Text = "Aquela criança é sincera, firme e bondosa, com uma alma rara e brilhante. A última vez que conheci alguém assim foi no primeiro capítulo da minha vida."
  },
  Voice_45157_AwakerVoiceTitle = {
    Text = "Conversa Casual · Sobre Ogier"
  },
  Voice_45157_UnlockDesc = {
    Text = "Desbloqueado após completar a Operação Especial \"Primária de Sangue\""
  },
  Voice_45158_AwakerVoiceContent = {
    Text = "Perder a visão não significa que me tornei cego. Enquanto o Pai trouxe escuridão sobre mim, Ele também me permitiu ver a fraca luz das almas."
  },
  Voice_45158_AwakerVoiceTitle = {
    Text = "Chitchat·Sobre Visão"
  },
  Voice_45159_AwakerVoiceContent = {
    Text = "\nNaquela época, embora eu tivesse recebido \"A bênção\", eu era apenas uma pessoa comum. Havia muitos que sofriam, e muitos que precisavam de \"A bênção\". Eu queria salvá-los todos, mas falhei.\nEste é meu maior arrependimento e minha culpa eterna."
  },
  Voice_45159_AwakerVoiceTitle = {
    Text = "Chitchat·Sobre a Primeira Vida"
  },
  Voice_45160_AwakerVoiceContent = {
    Text = "Muitos na Igreja acreditam que a \"chama branca\" mencionada nas \"Sagradas Escrituras\" se refere à luz da lua: um mensageiro pálido aparecerá dela para nos guiar para fora do sofrimento.\nMas eu sei que a verdadeira chama é a alma ardendo dentro de você e de mim"
  },
  Voice_45160_AwakerVoiceTitle = {
    Text = "Conversa Casual · Sobre \"O Fogo Pálido\""
  },
  Voice_45161_AwakerVoiceContent = {
    Text = "Na verdade, o Arcebispo me disse para esconder minha verdadeira identidade. Ele não elaborou, mas me alertou: mesmo nos lugares mais puros, sombras podem existir, e é preciso manter-se cauteloso, mesmo ao fazer o bem. Claro, confio plenamente em você."
  },
  Voice_45161_AwakerVoiceTitle = {
    Text = "Conversa Casual: Sobre Esconder Identidade"
  },
  Voice_45161_UnlockDesc = {
    Text = "Desbloqueado após completar a Operação Especial \"Primária de Sangue\""
  },
  Voice_4908_AwakerVoiceContent = {
    Text = "Meu canto foi de alguma ajuda para você?"
  },
  Voice_4908_AwakerVoiceTitle = {
    Text = "Investigação Bem-sucedida"
  },
  Voice_4909_AwakerVoiceContent = {
    Text = "Droga, ele também é apenas uma criança! Por que vocês o respeitam tanto? Me mostrem o mesmo respeito, entendeu!"
  },
  Voice_4909_AwakerVoiceTitle = {
    Text = "Papo reto · Sobre Tulu"
  },
  Voice_4909_UnlockDesc = {
    Text = "Desbloqueado após obter o Despertador \"Tulu\""
  },
  Voice_4910_AwakerVoiceContent = {
    Text = "Ei, você sabe o que os outros Despertadores geralmente fazem? Não me leve a mal, eu não quero amigos, apenas... sim, apenas checando!"
  },
  Voice_4910_AwakerVoiceTitle = {
    Text = "Conversa Ociosa: Sobre a Vida Diária"
  },
  Voice_4911_AwakerVoiceContent = {
    Text = "Droga, droga, droga! Na próxima vez, jogarei os corpos para as aranhas se alimentarem!"
  },
  Voice_4911_AwakerVoiceTitle = {
    Text = "Investigação Interrompida"
  },
  Voice_4912_AwakerVoiceContent = {
    Text = "Após-brilho"
  },
  Voice_4912_AwakerVoiceTitle = {Text = "Defesa·II"},
  Voice_4913_AwakerVoiceContent = {Text = "Ritmo."},
  Voice_4913_AwakerVoiceTitle = {
    Text = "Defesa · I"
  },
  Voice_4914_AwakerVoiceContent = {
    Text = "Uma Tentativa Audaciosa"
  },
  Voice_4914_AwakerVoiceTitle = {
    Text = "Defesa · I"
  },
  Voice_4915_AwakerVoiceContent = {
    Text = "Não há necessidade de tanta pressa... Há algo que posso fazer por você?"
  },
  Voice_4915_AwakerVoiceTitle = {
    Text = "Conversa·Toque"
  },
  Voice_4916_AwakerVoiceContent = {
    Text = "Como você se atreve!"
  },
  Voice_4916_AwakerVoiceTitle = {Text = "Acertar·1"},
  Voice_4917_AwakerVoiceContent = {
    Text = "(Questionando com grande interesse)"
  },
  Voice_4917_AwakerVoiceTitle = {
    Text = "Acertar · II"
  },
  Voice_4918_AwakerVoiceContent = {
    Text = "A natureza é a fonte da minha suprema honra. Isso não parece comigo?"
  },
  Voice_4918_AwakerVoiceTitle = {
    Text = "Conversa·Coisas favoritas"
  },
  Voice_4919_AwakerVoiceContent = {
    Text = "O que você quer fazer?"
  },
  Voice_4919_AwakerVoiceTitle = {
    Text = "Golpe·Quatro"
  },
  Voice_4920_AwakerVoiceContent = {
    Text = "Não é mau, né? Agora, a recompensa. — O quê? Não existe almoço grátis!"
  },
  Voice_4920_AwakerVoiceTitle = {
    Text = "Investigação Bem-sucedida"
  },
  Voice_4921_AwakerVoiceContent = {
    Text = "Vá embora!"
  },
  Voice_4921_AwakerVoiceTitle = {Text = "Defesa·II"},
  Voice_4922_AwakerVoiceContent = {Text = "Cuidado!"},
  Voice_4922_AwakerVoiceTitle = {
    Text = "Defesa · I"
  },
  Voice_4923_AwakerVoiceContent = {
    Text = "Que vitória gloriosa... Eu irei gravar este momento na eternidade."
  },
  Voice_4923_AwakerVoiceTitle = {
    Text = "Investigação Bem-sucedida"
  },
  Voice_4924_AwakerVoiceContent = {
    Text = "Sentiu a fonte de impureza... Um passo mais perto da verdadeira forma... Ahhh, deixe-me despedaçar este mundo!"
  },
  Voice_4924_AwakerVoiceTitle = {
    Text = "Iluminar·Construção"
  },
  Voice_4924_UnlockDesc = {
    Text = "Nível de iluminação atingiu 11 para desbloquear"
  },
  Voice_4925_AwakerVoiceContent = {
    Text = "Estamos... prontos. Por favor, dê a ordem, Guardião."
  },
  Voice_4925_AwakerVoiceTitle = {
    Text = "Iluminar·Florescer"
  },
  Voice_4925_UnlockDesc = {
    Text = "Nível de iluminação atingiu 15 para desbloquear"
  },
  Voice_4926_AwakerVoiceContent = {
    Text = "Senhor, você é verdadeiramente gentil. Infelizmente, não tenho nada com que te recompensar, pois sou apenas uma pessoa sem valor..."
  },
  Voice_4926_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexão"
  },
  Voice_4926_UnlockDesc = {
    Text = "Nível de iluminação atingiu 3 para desbloquear"
  },
  Voice_4927_AwakerVoiceContent = {
    Text = "......Só um pouco mais, e eu estarei completamente separado de \"eles\"?"
  },
  Voice_4927_AwakerVoiceTitle = {
    Text = "Iluminar: Insight"
  },
  Voice_4927_UnlockDesc = {
    Text = "Nível de iluminação atingiu 7 para desbloquear"
  },
  Voice_4928_AwakerVoiceContent = {
    Text = "Huh, ainda estou vivo... Você realmente não vai roubar meus órgãos ou me usar para experimentos?"
  },
  Voice_4928_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_4928_UnlockDesc = {
    Text = "Nível de iluminação atingiu 2 para desbloquear"
  },
  Voice_4929_AwakerVoiceContent = {
    Text = "A espécie nativa de Winkle pode entrar no cérebro biológico, fazendo a vontade externa fundida comigo temê-la. Mas agora, ela é apenas uma pobre alma aprisionada em uma casca"
  },
  Voice_4929_AwakerVoiceTitle = {
    Text = "Bate-Papo·Sobre Búzio"
  },
  Voice_4929_UnlockDesc = {
    Text = "Após obter o despertador \"Búzio\", desbloqueado"
  },
  Voice_4930_AwakerVoiceContent = {
    Text = "Tudo, Aigis aprecia tudo. Seja todos reunidos ao redor da mesa para uma refeição e oração, ou a expectativa quando o Guardião está em uma missão, esperando seu triunfante retorno... O ar sempre está cheio de felicidade... Eu realmente mereço tal alegria?"
  },
  Voice_4930_AwakerVoiceTitle = {
    Text = "Conversa·Coisas favoritas"
  },
  Voice_4931_AwakerVoiceContent = {Text = "Afunde."},
  Voice_4931_AwakerVoiceTitle = {Text = "Ataque·Um"},
  Voice_4932_AwakerVoiceContent = {Text = "Florescer."},
  Voice_4932_AwakerVoiceTitle = {Text = "Ataque·II"},
  Voice_4933_AwakerVoiceContent = {
    Text = "\"Confiança,\" \"Obediência,\" \"Escravo,\" \"Afeição,\" \"Respeito\"... Reestruturando e aprendendo o módulo de linguagem. Por favor, Guardião, guie-me."
  },
  Voice_4933_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Quatro"
  },
  Voice_4933_UnlockDesc = {
    Text = "Nível de afinidade atingido 8 desbloqueado"
  },
  Voice_4934_AwakerVoiceContent = {
    Text = "Erica está atualmente em modo de espera. O corpo completará o resfriamento em 1 hora e 15 minutos. <Del:Para começar, troque seu coração> Início de emergência? ... Verificação de permissão em andamento... Autoridade máxima do Guardião verificada. Olá, Guardião."
  },
  Voice_4934_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Cinco"
  },
  Voice_4934_UnlockDesc = {
    Text = "Nível de afinidade atingido 10 desbloqueado"
  },
  Voice_4935_AwakerVoiceContent = {
    Text = "O índice médio de risco das tarefas de investigação é 7, com um consumo médio de 8 frascos de suplementos de alquimia e uma média de 10 horas necessárias para o manuseio de corpos.\nConclusão: O trabalho dos Guardiães é extremamente perigoso. Por favor, fique seguro durante as operações."
  },
  Voice_4935_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Dois"
  },
  Voice_4935_UnlockDesc = {
    Text = "Nível de afinidade atingido 4 desbloqueado"
  },
  Voice_4936_AwakerVoiceContent = {
    Text = "Buscando registros de professores: Erica Layfield, Professora de Mecatrônica e Automação Prata, Falecida—Isso não é o que você estava procurando? Ok, re-buscando a palavra-chave \"Erica\"."
  },
  Voice_4936_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Três"
  },
  Voice_4936_UnlockDesc = {
    Text = "Nível de afinidade atingido 6 desbloqueado"
  },
  Voice_4937_AwakerVoiceContent = {
    Text = "Se você precisar procurar informações, por favor, forneça o nome completo do arquivo. A função de busca difusa está temporariamente indisponível."
  },
  Voice_4937_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Um"
  },
  Voice_4937_UnlockDesc = {
    Text = "Nível de afinidade atingido 2 desbloqueado"
  },
  Voice_4938_AwakerVoiceContent = {
    Text = "(Exclamação)"
  },
  Voice_4938_AwakerVoiceTitle = {Text = "Acertar·1"},
  Voice_4939_AwakerVoiceContent = {Text = "Ah!"},
  Voice_4939_AwakerVoiceTitle = {
    Text = "Acertar·III"
  },
  Voice_4940_AwakerVoiceContent = {
    Text = "(Exclamação)"
  },
  Voice_4940_AwakerVoiceTitle = {
    Text = "Acertar · II"
  },
  Voice_4941_AwakerVoiceContent = {Text = "Ah!"},
  Voice_4941_AwakerVoiceTitle = {
    Text = "Golpe·Quatro"
  },
  Voice_4942_AwakerVoiceContent = {
    Text = "Carga completa, pronta para detonação."
  },
  Voice_4942_AwakerVoiceTitle = {
    Text = "Exaltar · Dois"
  },
  Voice_4943_AwakerVoiceContent = {
    Text = "Carga completa, pronta para detonação."
  },
  Voice_4943_AwakerVoiceTitle = {
    Text = "Fúria Explosiva"
  },
  Voice_4944_AwakerVoiceContent = {
    Text = "Não perturbe o descanso da princesa com tais questões triviais no futuro."
  },
  Voice_4944_AwakerVoiceTitle = {
    Text = "Investigação Bem-sucedida"
  },
  Voice_4945_AwakerVoiceContent = {
    Text = "Vou protegê-lo assim como protejo Tinct."
  },
  Voice_4945_AwakerVoiceTitle = {
    Text = "Início da Investigação"
  },
  Voice_4946_AwakerVoiceContent = {
    Text = "Eu não sou uma pessoa importante, apenas um humilde seguidor entre muitos... Enquanto eu puder servir aquele grande ser e atrair sua atenção, estou disposto a dar tudo de mim."
  },
  Voice_4946_AwakerVoiceTitle = {
    Text = "Conversas Ociosas·Sobre o Passado"
  },
  Voice_4946_UnlockDesc = {
    Text = "Desbloqueado após obter o Despertador \"Tulu\""
  },
  Voice_4947_AwakerVoiceContent = {
    Text = "Olhe para mim!"
  },
  Voice_4947_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_4948_AwakerVoiceContent = {
    Text = "Olhe para mim!"
  },
  Voice_4948_AwakerVoiceTitle = {
    Text = "Carta de Habilidade·Quatro"
  },
  Voice_4949_AwakerVoiceContent = {
    Text = "...Está tudo bem, desde que não me incomodem com sua adoração fanática. Compartilhar um quarto com eles não é fora de questão."
  },
  Voice_4949_AwakerVoiceTitle = {
    Text = "Conversa Informal · Sobre o Marinheiro"
  },
  Voice_4949_UnlockDesc = {
    Text = "Desbloqueado após obter qualquer um dos Despertadores \"Miryam\", \"Golias\", \"Caecus\", \"Sanga\" ou \"Faróis\"."
  },
  Voice_4950_AwakerVoiceContent = {
    Text = "Eu odeio aquela sensação sombria, como se meu coração estivesse ocado. A sensação não cumprida faz meu corpo todo coçar..."
  },
  Voice_4950_AwakerVoiceTitle = {
    Text = "Bate-papo · Sobre Dissolução"
  },
  Voice_4951_AwakerVoiceContent = {
    Text = "Não, não, não, não, não mencione isso..."
  },
  Voice_4951_AwakerVoiceTitle = {
    Text = "Bate-papo · Sobre Dissolução"
  },
  Voice_4953_AwakerVoiceContent = {Text = "Ha!"},
  Voice_4953_AwakerVoiceTitle = {Text = "Ataque·Um"},
  Voice_4954_AwakerVoiceContent = {
    Text = "...Tá bom!"
  },
  Voice_4954_AwakerVoiceTitle = {Text = "Ataque·Um"},
  Voice_4955_AwakerVoiceContent = {
    Text = "Historiadores proclamando em alto e bom som a extinção do Reino Divino são irritantes... Mas não importa; suas palavras não podem impedir a reavivação da glória do Reino Divino."
  },
  Voice_4955_AwakerVoiceTitle = {
    Text = "Conversa·Coisas odiadas"
  },
  Voice_4956_AwakerVoiceContent = {
    Text = "Na verdade... deixe-me contar um segredo. Não estou totalmente satisfeito com minha atual motocicleta—não é que eu não goste dela! É só que sinto que algo está faltando..."
  },
  Voice_4956_AwakerVoiceTitle = {
    Text = "Conversa·Coisas odiadas"
  },
  Voice_4957_AwakerVoiceContent = {Text = "Ha!"},
  Voice_4957_AwakerVoiceTitle = {
    Text = "Defesa · I"
  },
  Voice_4958_AwakerVoiceContent = {Text = "Corte!"},
  Voice_4958_AwakerVoiceTitle = {
    Text = "Habilidade·II·Mania"
  },
  Voice_4959_AwakerVoiceContent = {
    Text = "Desculpe... Eu não queria que isso acontecesse..."
  },
  Voice_4959_AwakerVoiceTitle = {
    Text = "Habilidade·II·Depressão"
  },
  Voice_4960_AwakerVoiceContent = {
    Text = "(Sussurro intrigado)"
  },
  Voice_4960_AwakerVoiceTitle = {
    Text = "Acertar·III"
  },
  Voice_4961_AwakerVoiceContent = {
    Text = "No ano @1@2, o Sr. Ward Phillips, Krelarkesh e Tawil fundaram juntos o Mythag College. Após um longo desenvolvimento, ele acabou dando origem a <Del:esta maldita prisão> Mythag University."
  },
  Voice_4961_AwakerVoiceTitle = {
    Text = "Chat·Sobre a Universidade Mythag"
  },
  Voice_4962_AwakerVoiceContent = {
    Text = "Justiça, lealdade, resiliência, disciplina. Estas estão há muito gravadas em meu coração."
  },
  Voice_4962_AwakerVoiceTitle = {
    Text = "Conversa·Coisas favoritas"
  },
  Voice_4963_AwakerVoiceContent = {
    Text = "Concluirei adequadamente a tarefa que você me designou."
  },
  Voice_4963_AwakerVoiceTitle = {
    Text = "Início da Investigação"
  },
  Voice_4964_AwakerVoiceContent = {
    Text = "Que tipo de pais irresponsáveis dariam o nome de Escudo da Banshee para a filha? Você diz que a criança não tem pais? Hmm... vamos manter essa conversa entre nós"
  },
  Voice_4964_AwakerVoiceTitle = {
    Text = "Bate-papo · Sobre Aigis"
  },
  Voice_4964_UnlockDesc = {
    Text = "Após obter o despertador \"Aigis\", desbloqueado"
  },
  Voice_4965_AwakerVoiceContent = {
    Text = "Se você está entediado, que tal \"me fazer companhia\" no labirinto? Afinal, sua vida sem esperança não é diferente deste labirinto sem fim!"
  },
  Voice_4965_AwakerVoiceTitle = {
    Text = "Bate-papo · Sobre o Labirinto"
  },
  Voice_4966_AwakerVoiceContent = {
    Text = "Quando a Boneca está por perto, a eficiência dos investigadores aumenta em 78,312%, mas mais pessoas também caem em crises emocionais. Como ela disse: \"Se algumas pessoas pudessem manter a boca fechada, o mundo funcionaria mais harmonicamente.\""
  },
  Voice_4966_AwakerVoiceTitle = {
    Text = "Bate-papo · Sobre Boneca"
  },
  Voice_4966_UnlockDesc = {
    Text = "Após obter o despertador \"Boneca\", desbloqueado"
  },
  Voice_4967_AwakerVoiceContent = {Text = "Chegada!"},
  Voice_4967_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_4968_AwakerVoiceContent = {Text = "E aí?"},
  Voice_4968_AwakerVoiceTitle = {
    Text = "Habilidade·Um"
  },
  Voice_4969_AwakerVoiceContent = {
    Text = "Quem não amaria uma aventura? Mergulhar em reinos misteriosos inexplorados, descobrir o desconhecido e tecer sua própria história... Que emocionante!"
  },
  Voice_4969_AwakerVoiceTitle = {
    Text = "Conversa Casual · Sobre Aventuras"
  },
  Voice_4970_AwakerVoiceContent = {
    Text = "Saudações, sou Nínfea de Febvre. Você me deu este corpo que respira livremente... O que posso fazer para retribuí-lo?"
  },
  Voice_4970_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_4971_AwakerVoiceContent = {
    Text = "Eu acho que acabei de ouvir aqueles que afirmam ser meus mestres choramingando novamente — que adorável."
  },
  Voice_4971_AwakerVoiceTitle = {
    Text = "Iluminar: Insight"
  },
  Voice_4971_UnlockDesc = {
    Text = "Nível de iluminação atingiu 7 para desbloquear"
  },
  Voice_4972_AwakerVoiceContent = {
    Text = "Posso pular os vegetais? Embora Tinta tenha dito para não ser exigente, não gosto das cores deles..."
  },
  Voice_4972_AwakerVoiceTitle = {
    Text = "Conversa·Coisas odiadas"
  },
  Voice_4973_AwakerVoiceContent = {
    Text = "Palavras de Deus Relíquia: Sofrimento não é minha criação. Suporte e dissolva-o, meu proxy, e construa uma terra sem sofrimento. Para isso, ofereço tudo, até mesmo a vida."
  },
  Voice_4973_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexão"
  },
  Voice_4973_UnlockDesc = {
    Text = "Nível de iluminação atingiu 3 para desbloquear"
  },
  Voice_4974_AwakerVoiceContent = {
    Text = "Diante da maldição derretente que tudo consome, outros sofrimentos empalidecem em comparação. Mesmo que eu não possa suportar a maldição pelos outros, farei o meu melhor para aliviar sua dor."
  },
  Voice_4974_AwakerVoiceTitle = {
    Text = "Iluminar: Insight"
  },
  Voice_4974_UnlockDesc = {
    Text = "Nível de iluminação atingiu 7 para desbloquear"
  },
  Voice_4975_AwakerVoiceContent = {
    Text = "Estou agora capaz de aliviar sua dor e confortar suas almas?"
  },
  Voice_4975_AwakerVoiceTitle = {
    Text = "Iluminar·Construção"
  },
  Voice_4975_UnlockDesc = {
    Text = "Nível de iluminação atingiu 11 para desbloquear"
  },
  Voice_4976_AwakerVoiceContent = {
    Text = "Assim, eu suportarei todo sofrimento, abrindo o caminho para todos os seres a uma terra livre de dor."
  },
  Voice_4976_AwakerVoiceTitle = {
    Text = "Iluminar·Florescer"
  },
  Voice_4976_UnlockDesc = {
    Text = "Nível de iluminação atingiu 15 para desbloquear"
  },
  Voice_4977_AwakerVoiceContent = {
    Text = "Este calor profundo dentro da minha alma... Obrigado por este presente, o Fogo Pálido. Com este Poder, talvez eu finalmente possa cumprir meu dever como Deputado e salvar mais pessoas."
  },
  Voice_4977_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_4977_UnlockDesc = {
    Text = "Nível de iluminação atingiu 2 para desbloquear"
  },
  Voice_4978_AwakerVoiceContent = {
    Text = "Posso realmente comer tudo isso?"
  },
  Voice_4978_AwakerVoiceTitle = {
    Text = "Iluminar·Visão Remota"
  },
  Voice_4978_UnlockDesc = {
    Text = "Nível de iluminação atingiu 1 para desbloquear"
  },
  Voice_4979_AwakerVoiceContent = {
    Text = "Hmm... Isso não é a morte; é apenas o seu futuro, meu futuro e o futuro deste mundo."
  },
  Voice_4979_AwakerVoiceTitle = {
    Text = "Bate-papo · Sobre Dissolução"
  },
  Voice_4980_AwakerVoiceContent = {
    Text = "Tinta... Ouvir sua canção triste faz você querer dançar..."
  },
  Voice_4980_AwakerVoiceTitle = {
    Text = "Chit-chat·Sobre a Tinta"
  },
  Voice_4980_UnlockDesc = {
    Text = "Após obter o despertador \"Tinta\", desbloqueado"
  },
  Voice_4981_AwakerVoiceContent = {
    Text = "O treinamento ordinário também pode despertar o potencial da linhagem de alguém? Isso é verdadeiramente além das minhas expectativas."
  },
  Voice_4981_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · I"
  },
  Voice_4982_AwakerVoiceContent = {
    Text = "A arma parece mais prática."
  },
  Voice_4982_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · Três"
  },
  Voice_4983_AwakerVoiceContent = {
    Text = "Não presuma que eu vou ser grato por isso; minha raça não permite."
  },
  Voice_4983_AwakerVoiceTitle = {
    Text = "Atualizar·II"
  },
  Voice_4984_AwakerVoiceContent = {Text = "Ah, uh!"},
  Voice_4984_AwakerVoiceTitle = {
    Text = "Despertar do Conhecimento Espiritual"
  },
  Voice_4985_AwakerVoiceContent = {
    Text = "Aquele homem... Ei, espere um momento, nossa aposta não acabou ainda, certo?"
  },
  Voice_4985_AwakerVoiceTitle = {
    Text = "Fala Ociosa · Sobre Outros"
  },
  Voice_4986_AwakerVoiceContent = {
    Text = "Eu realmente gosto do gravador da academia. Se ao menos eu pudesse criar uma versão portátil que me lembrasse em tempo real do que eu esqueci..."
  },
  Voice_4986_AwakerVoiceTitle = {
    Text = "Chat·Sobre a Universidade Mythag"
  },
  Voice_4987_AwakerVoiceContent = {
    Text = "Migalhas por toda parte... Não, nem migalhas, apenas remanescentes, fornecendo sustento para Sua chegada."
  },
  Voice_4987_AwakerVoiceTitle = {
    Text = "Chat·Sobre a Universidade Mythag"
  },
  Voice_4988_AwakerVoiceContent = {
    Text = "Os suprimentos están aqui."
  },
  Voice_4988_AwakerVoiceTitle = {
    Text = "Habilidade·Um"
  },
  Voice_4989_AwakerVoiceContent = {
    Text = "Os suprimentos están aqui."
  },
  Voice_4989_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_4990_AwakerVoiceContent = {
    Text = "Hmm... Mais difícil, mais difícil. Sim, assim mesmo..."
  },
  Voice_4990_AwakerVoiceTitle = {
    Text = "Conversa·Toque"
  },
  Voice_4991_AwakerVoiceContent = {
    Text = "Ainda não totalmente Despertado, mas a vitória veio sem esforço."
  },
  Voice_4991_AwakerVoiceTitle = {
    Text = "Investigação Bem-sucedida"
  },
  Voice_4992_AwakerVoiceContent = {
    Text = "Oh não, meu chapéu está torto... Hmm, isso está melhor? Perfeito!"
  },
  Voice_4992_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_4992_UnlockDesc = {
    Text = "Nível de iluminação atingiu 2 para desbloquear"
  },
  Voice_4993_AwakerVoiceContent = {
    Text = "\"Com tal habilidade, sou realmente ainda humano?\" Desde que comecei o treinamento de batalha, tenho me perguntado isso todos os dias. Eu amo este mundo, apesar de sua escuridão, sujeira e monotonia, mas sua presença o faz brilhar como diamantes em meio à poeira.\nEu temia que, à medida que meu poder crescesse, minha posição como humano mudasse... Agora, sou grato por tê-lo ao meu lado. Nossa ligação me ancora firmemente ao mundo humano. Por favor, continue a cuidar de mim, Guardião."
  },
  Voice_4993_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Cinco"
  },
  Voice_4993_UnlockDesc = {
    Text = "Nível de afinidade atingido 10 desbloqueado"
  },
  Voice_4994_AwakerVoiceContent = {
    Text = "Ah... É natural que você tenha preocupações. Eu não pensei nisso. Como seu parceiro, eu deveria ter explicado isso desde o começo. Como você pode ver, eu possuo algumas características incomuns, provavelmente ligadas ao meu passado. É impossível não ser curioso, certo? Mas ter um lugar como a academia é uma bênção para mim, então escolho não levantar o véu do destino."
  },
  Voice_4994_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Quatro"
  },
  Voice_4994_UnlockDesc = {
    Text = "Nível de afinidade atingido 8 desbloqueado"
  },
  Voice_4995_AwakerVoiceContent = {
    Text = "Você conheceu aquela mulher, certo? A Despertadora de véu branco—ela é uma das fundadoras da universidade...\nMas, honestamente, eu não gosto dela. Essa atitude distante, como se não se importasse com o mundo, realmente me irrita... Oh, você acha que ela se parece comigo? Vamos levar seus olhos para checar na clínica do campus."
  },
  Voice_4995_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Três"
  },
  Voice_4995_UnlockDesc = {
    Text = "Nível de afinidade atingido 6 desbloqueado"
  },
  Voice_4996_AwakerVoiceContent = {
    Text = "Você está curioso sobre meu relacionamento com o professor? Não é segredo, então eu vou te contar. O professor Dexter é meu pai adotivo. Quanto à minha mãe adotiva... Eu cresci na escola e fui cuidada por todos os professores. No entanto, entre eles, eu sou mais próxima de Boneca."
  },
  Voice_4996_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Dois"
  },
  Voice_4996_UnlockDesc = {
    Text = "Nível de afinidade atingido 4 desbloqueado"
  },
  Voice_4997_AwakerVoiceContent = {
    Text = "Seja nos procedimentos do Escritório de Assuntos Despertadores ou na data para comida indiana na cantina, posso responder a qualquer pergunta sobre os assuntos da academia—não se preocupe em me incomodar. Eu pareço tão inatingível?"
  },
  Voice_4997_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Um"
  },
  Voice_4997_UnlockDesc = {
    Text = "Nível de afinidade atingido 2 desbloqueado"
  },
  Voice_4998_AwakerVoiceContent = {
    Text = "Espelho, espelho, quem é o maior mágico do mundo? Eu? Isso mesmo!"
  },
  Voice_4998_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexão"
  },
  Voice_4998_UnlockDesc = {
    Text = "Nível de iluminação atingiu 3 para desbloquear"
  },
  Voice_4999_AwakerVoiceContent = {Text = "Nada mal."},
  Voice_4999_AwakerVoiceTitle = {
    Text = "Habilidade·Um"
  },
  Voice_5000_AwakerVoiceContent = {
    Text = "Muito legal~"
  },
  Voice_5000_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_5001_AwakerVoiceContent = {
    Text = "(Exclamação)"
  },
  Voice_5001_AwakerVoiceTitle = {
    Text = "Acertar·III"
  },
  Voice_5002_AwakerVoiceContent = {
    Text = "Isso... funcionou? Eu consegui te ajudar?"
  },
  Voice_5002_AwakerVoiceTitle = {
    Text = "Investigação Bem-sucedida"
  },
  Voice_5003_AwakerVoiceContent = {Text = "Inútil!"},
  Voice_5003_AwakerVoiceTitle = {Text = "Acertar·1"},
  Voice_5004_AwakerVoiceContent = {Text = "(Suportar)"},
  Voice_5004_AwakerVoiceTitle = {
    Text = "Golpe·Quatro"
  },
  Voice_5005_AwakerVoiceContent = {
    Text = "Olhe para cá!"
  },
  Voice_5005_AwakerVoiceTitle = {
    Text = "Habilidade Especial · Um"
  },
  Voice_5006_AwakerVoiceContent = {
    Text = "Deixe este lugar se tornar um mar de empolgação para todos!"
  },
  Voice_5006_AwakerVoiceTitle = {
    Text = "Exaltar · Dois"
  },
  Voice_5007_AwakerVoiceContent = {
    Text = "Precisa de um guardião para acompanhá-lo? Se sua busca for justa, eu o ajudarei."
  },
  Voice_5007_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_5008_AwakerVoiceContent = {
    Text = "Não pode ser completamente queimado."
  },
  Voice_5008_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_5009_AwakerVoiceContent = {
    Text = "Não pode ser completamente queimado."
  },
  Voice_5009_AwakerVoiceTitle = {
    Text = "Habilidade·Um"
  },
  Voice_5010_AwakerVoiceContent = {
    Text = "Você quer um abraço?"
  },
  Voice_5010_AwakerVoiceTitle = {
    Text = "Conversa·Toque"
  },
  Voice_5011_AwakerVoiceContent = {
    Text = "Olhe para essas algemas em mim—não são decorações, mas lembranças. Lembranças de traição e humilhação."
  },
  Voice_5011_AwakerVoiceTitle = {
    Text = "Conversa·Coisas odiadas"
  },
  Voice_5012_AwakerVoiceContent = {
    Text = "Se você quiser saber sobre o passado da academia, sugiro que consulte os arquivos.\nVamos lá, incluindo seu predecessor, isso é uma história que abrange 300 anos! Você realmente não espera que eu a conte ano a ano, espera?"
  },
  Voice_5012_AwakerVoiceTitle = {
    Text = "Chat·Sobre a Universidade Mythag"
  },
  Voice_5013_AwakerVoiceContent = {
    Text = "Isso é uma provocação? Estou pronto a qualquer momento!"
  },
  Voice_5013_AwakerVoiceTitle = {
    Text = "Início da Investigação"
  },
  Voice_5014_AwakerVoiceContent = {
    Text = "Aequor lhe concede descanso eterno."
  },
  Voice_5014_AwakerVoiceTitle = {
    Text = "Fúria Explosiva"
  },
  Voice_5015_AwakerVoiceContent = {
    Text = "Aequor lhe concede descanso eterno."
  },
  Voice_5015_AwakerVoiceTitle = {
    Text = "Exaltar · Dois"
  },
  Voice_5016_AwakerVoiceContent = {
    Text = "Afunde e queime! Dança para a destruição!"
  },
  Voice_5016_AwakerVoiceTitle = {
    Text = "Fúria Explosiva"
  },
  Voice_5017_AwakerVoiceContent = {
    Text = "Aqui apresento a Dança da Destruição da Chama Verde Eterna!"
  },
  Voice_5017_AwakerVoiceTitle = {
    Text = "Fúria Explosiva"
  },
  Voice_5018_AwakerVoiceContent = {
    Text = "Aquela dama, como um farol... Se eu pudesse ter visto sua luz deslumbrante durante a viagem noturna eterna, talvez eu não tivesse me perdido..."
  },
  Voice_5018_AwakerVoiceTitle = {
    Text = "Bate-Papo·Sobre Faróis"
  },
  Voice_5018_UnlockDesc = {
    Text = "Após obter o despertador \"Faróis\", desbloqueado"
  },
  Voice_5019_AwakerVoiceContent = {
    Text = "Você melhor provar que é digno de me fazer deixar o laboratório, novo Guardião."
  },
  Voice_5019_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_5020_AwakerVoiceContent = {
    Text = "Eu sou o mestre, e você é o servo. O que quer que eu deseje deve ser entregue imediatamente. Qual é o problema? Você espera uma recompensa? Muito bem, muito bem, leve-a!"
  },
  Voice_5020_AwakerVoiceTitle = {
    Text = "Conversa·Sobre Guardião do Segredo"
  },
  Voice_5021_AwakerVoiceContent = {
    Text = "(Exclamação)"
  },
  Voice_5021_AwakerVoiceTitle = {
    Text = "Golpe·Quatro"
  },
  Voice_5022_AwakerVoiceContent = {
    Text = "Desgraça, deixe este movimento te purificar!"
  },
  Voice_5022_AwakerVoiceTitle = {
    Text = "Fúria Explosiva"
  },
  Voice_5023_AwakerVoiceContent = {
    Text = "(Exclamação)"
  },
  Voice_5023_AwakerVoiceTitle = {
    Text = "Acertar · II"
  },
  Voice_5024_AwakerVoiceContent = {
    Text = "(Exclamação)"
  },
  Voice_5024_AwakerVoiceTitle = {
    Text = "Acertar·III"
  },
  Voice_5025_AwakerVoiceContent = {
    Text = "Dar é receber."
  },
  Voice_5025_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_5026_AwakerVoiceContent = {
    Text = "Dar é receber."
  },
  Voice_5026_AwakerVoiceTitle = {
    Text = "Habilidade·Um"
  },
  Voice_5027_AwakerVoiceContent = {
    Text = "Você vai se machucar!"
  },
  Voice_5027_AwakerVoiceTitle = {
    Text = "Defesa · I"
  },
  Voice_5028_AwakerVoiceContent = {
    Text = "Não chegue mais perto!"
  },
  Voice_5028_AwakerVoiceTitle = {Text = "Defesa·II"},
  Voice_5029_AwakerVoiceContent = {
    Text = "Eu amo a luz dourada da lua cheia. É misteriosa e suave. Quando o vento sopra, o mar brilha com uma fosforescência dourada, como um romance onírico."
  },
  Voice_5029_AwakerVoiceTitle = {
    Text = "Conversa·Coisas favoritas"
  },
  Voice_5030_AwakerVoiceContent = {
    Text = "Se nossa casa não tivesse passado pela Dissolução, Tinct e eu não estaríamos separados... Eu odeio a Dissolução mais do que odeio vegetais."
  },
  Voice_5030_AwakerVoiceTitle = {
    Text = "Bate-papo · Sobre Dissolução"
  },
  Voice_5031_AwakerVoiceContent = {
    Text = "Se o que está à frente é tesouro ou um porto, não faz diferença para mim. Minha missão é garantir seu retorno seguro."
  },
  Voice_5031_AwakerVoiceTitle = {
    Text = "Iluminar: Insight"
  },
  Voice_5031_UnlockDesc = {
    Text = "Nível de iluminação atingiu 7 para desbloquear"
  },
  Voice_5032_AwakerVoiceContent = {
    Text = "Siga a trilha do pássaro do paraíso; o destino está à frente no azul celeste."
  },
  Voice_5032_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexão"
  },
  Voice_5032_UnlockDesc = {
    Text = "Nível de iluminação atingiu 3 para desbloquear"
  },
  Voice_5033_AwakerVoiceContent = {
    Text = "Frequentemente olho para o horizonte, imaginando as cenas além—uma terra distante à qual me aproximo, mas que nunca posso alcançar. Se aquele dia algum dia chegar, por favor, vá comigo para vê-la."
  },
  Voice_5033_AwakerVoiceTitle = {
    Text = "Iluminar·Florescer"
  },
  Voice_5033_UnlockDesc = {
    Text = "Nível de iluminação atingiu 15 para desbloquear"
  },
  Voice_5034_AwakerVoiceContent = {
    Text = "Obrigado pela sua bondade. Agora, nem mesmo o mar revolto pode me impedir de entregar minhas bênçãos firmes a você."
  },
  Voice_5034_AwakerVoiceTitle = {
    Text = "Iluminar·Construção"
  },
  Voice_5034_UnlockDesc = {
    Text = "Nível de iluminação atingiu 11 para desbloquear"
  },
  Voice_5035_AwakerVoiceContent = {
    Text = "Sente como se estivesse ouvindo as canções dos remadores, o gosto familiar de casa."
  },
  Voice_5035_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_5035_UnlockDesc = {
    Text = "Nível de iluminação atingiu 2 para desbloquear"
  },
  Voice_5036_AwakerVoiceContent = {
    Text = "Você está aqui para me salvar? Do mundo em decadência, do ódio que mancha meus olhos, das chamas verdes eternas..."
  },
  Voice_5036_AwakerVoiceTitle = {
    Text = "Conversa·Sobre Guardião do Segredo"
  },
  Voice_5037_AwakerVoiceContent = {
    Text = "Rogue insolente!"
  },
  Voice_5037_AwakerVoiceTitle = {Text = "Ataque·Um"},
  Voice_5038_AwakerVoiceContent = {
    Text = "Eu considero isso meu juramento de lealdade a você."
  },
  Voice_5038_AwakerVoiceTitle = {
    Text = "Iluminar·Visão Remota"
  },
  Voice_5038_UnlockDesc = {
    Text = "Nível de iluminação atingiu 1 para desbloquear"
  },
  Voice_5039_AwakerVoiceContent = {
    Text = "Aprenda a sua lição!"
  },
  Voice_5039_AwakerVoiceTitle = {
    Text = "Habilidade·Um"
  },
  Voice_5040_AwakerVoiceContent = {Text = "(Gemido)"},
  Voice_5040_AwakerVoiceTitle = {Text = "Acertar·1"},
  Voice_5041_AwakerVoiceContent = {Text = "(Gemido)"},
  Voice_5041_AwakerVoiceTitle = {
    Text = "Acertar · II"
  },
  Voice_5042_AwakerVoiceContent = {Text = "(Gemido)"},
  Voice_5042_AwakerVoiceTitle = {
    Text = "Acertar·III"
  },
  Voice_5043_AwakerVoiceTitle = {
    Text = "Golpe·Quatro"
  },
  Voice_5044_AwakerVoiceContent = {
    Text = "Sinta o poder do rato!"
  },
  Voice_5044_AwakerVoiceTitle = {
    Text = "Fúria Explosiva"
  },
  Voice_5045_AwakerVoiceContent = {
    Text = "Sinta o poder do rato!"
  },
  Voice_5045_AwakerVoiceTitle = {
    Text = "Exaltar · Dois"
  },
  Voice_5046_AwakerVoiceContent = {
    Text = "O dado foi lançado. Então, vamos terminar isso rapidamente!"
  },
  Voice_5046_AwakerVoiceTitle = {
    Text = "Início da Investigação"
  },
  Voice_5047_AwakerVoiceContent = {
    Text = "Incorporarei seu nome nos meus agradecimentos. Foi você quem permitiu que estes pés, manchados de sangue sombrio, pisassem mais uma vez no maravilhoso mundo do balé. A partir de agora, por favor, assista-me dançar, Guardião."
  },
  Voice_5047_AwakerVoiceTitle = {
    Text = "Iluminar·Florescer"
  },
  Voice_5047_UnlockDesc = {
    Text = "Nível de iluminação atingiu 15 para desbloquear"
  },
  Voice_5048_AwakerVoiceContent = {
    Text = "Não importa o quanto você se esforce, você não pode desafiar o destino. Mas aquele momento fugaz de brilho será congelado na eternidade."
  },
  Voice_5048_AwakerVoiceTitle = {
    Text = "Iluminar·Construção"
  },
  Voice_5048_UnlockDesc = {
    Text = "Nível de iluminação atingiu 11 para desbloquear"
  },
  Voice_5049_AwakerVoiceContent = {
    Text = "O que devemos fazer com estes derrotados?"
  },
  Voice_5049_AwakerVoiceTitle = {
    Text = "Investigação Bem-sucedida"
  },
  Voice_5050_AwakerVoiceContent = {
    Text = "Mesmo que meu coração não tenha mais desejos, ainda assim vou desempenhar o papel do cisne."
  },
  Voice_5050_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexão"
  },
  Voice_5050_UnlockDesc = {
    Text = "Nível de iluminação atingiu 3 para desbloquear"
  },
  Voice_5051_AwakerVoiceContent = {
    Text = "Feche os olhos e me diga, o que você vê? Luz do luar imaculada, um lago tranquilo..."
  },
  Voice_5051_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_5051_UnlockDesc = {
    Text = "Nível de iluminação atingiu 2 para desbloquear"
  },
  Voice_5052_AwakerVoiceContent = {
    Text = "Por que as calamidades de destruição e infortúnio se entrelaçam entre mim e minha irmã?"
  },
  Voice_5052_AwakerVoiceTitle = {
    Text = "Bate-papo · Sobre Dissolução"
  },
  Voice_5053_AwakerVoiceContent = {
    Text = "Aceite meu afeto."
  },
  Voice_5053_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_5054_AwakerVoiceContent = {
    Text = "Aceite meu afeto."
  },
  Voice_5054_AwakerVoiceTitle = {
    Text = "Habilidade·Um"
  },
  Voice_5055_AwakerVoiceContent = {
    Text = "Eu me sinto muito melhor agora, obrigado."
  },
  Voice_5055_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · I"
  },
  Voice_5056_AwakerVoiceContent = {Text = "(Gemido)"},
  Voice_5056_AwakerVoiceTitle = {
    Text = "Acertar · II"
  },
  Voice_5057_AwakerVoiceContent = {
    Text = "Se possível, eu gostaria de lhe apresentar uma lírio d'água lilás pálido como um símbolo da minha gratidão."
  },
  Voice_5057_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · Três"
  },
  Voice_5058_AwakerVoiceContent = {
    Text = "Posso me tornar mais forte também?"
  },
  Voice_5058_AwakerVoiceTitle = {
    Text = "Atualizar·II"
  },
  Voice_5059_AwakerVoiceContent = {
    Text = "Aqui vamos nós...!"
  },
  Voice_5059_AwakerVoiceTitle = {Text = "Ataque·Um"},
  Voice_5060_AwakerVoiceContent = {Text = "(Gemido)"},
  Voice_5060_AwakerVoiceTitle = {
    Text = "Golpe·Quatro"
  },
  Voice_5061_AwakerVoiceContent = {
    Text = "Essa perna machucada? Estou surpreso que você tenha notado. É do campo de batalha antes de eu me tornar um Despertador.\nNão se preocupe, isso não interfere mais nas minhas batalhas.\nDor? Não, eu não pensei sobre isso."
  },
  Voice_5061_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Dois"
  },
  Voice_5061_UnlockDesc = {
    Text = "Nível de afinidade atingido 4 desbloqueado"
  },
  Voice_5062_AwakerVoiceContent = {
    Text = "A Sylvia perguntou sobre meu estado mental, foi você que a chamou, não foi? Admito que a dor fantasma aparece de vez em quando. Mas não se preocupe com meus sentimentos. Sou sua espada, sua lâmina, enquanto puder lutar pela justiça, a dor não me afetará"
  },
  Voice_5062_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Três"
  },
  Voice_5062_UnlockDesc = {
    Text = "Nível de afinidade atingido 6 desbloqueado"
  },
  Voice_5063_AwakerVoiceContent = {
    Text = "Chá, chá, vamos fazer uma festa do chá! Peguei muitas folhas de chá e doces da Sylvia! Sim, troquei por uma dança de Fortwoken!"
  },
  Voice_5063_AwakerVoiceTitle = {
    Text = "Conversa·Coisas favoritas"
  },
  Voice_5064_AwakerVoiceContent = {
    Text = "Meu título autoproclamado? Você realmente está tão interessado em meus assuntos pessoais? Apenas quer conversar... tudo bem.\nNo exército, não diferenciamos entre camaradas com base no gênero, incluindo força e velocidade, e naturalmente, também penteados e títulos. Com o tempo, me acostumei a essa forma de expressão."
  },
  Voice_5064_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Um"
  },
  Voice_5064_UnlockDesc = {
    Text = "Nível de afinidade atingido 2 desbloqueado"
  },
  Voice_5065_AwakerVoiceContent = {
    Text = "Interessante... Você não tem medo de eu despedaçá-lo e alimentar os peixes uma vez que eu ganhe poder?"
  },
  Voice_5065_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · I"
  },
  Voice_5066_AwakerVoiceContent = {
    Text = "Para ser digno de ser meu Guardião, você certamente trabalhou duro!"
  },
  Voice_5066_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · Três"
  },
  Voice_5067_AwakerVoiceContent = {
    Text = "É hora de rasgar as gargantas de alguns fracos e testar isso."
  },
  Voice_5067_AwakerVoiceTitle = {
    Text = "Atualizar·II"
  },
  Voice_5068_AwakerVoiceContent = {
    Text = "A dança é pura. Palavras podem levar a mal-entendidos, mas os passos de dança nunca levam."
  },
  Voice_5068_AwakerVoiceTitle = {
    Text = "Fala Ociosa · Sobre Dança"
  },
  Voice_5069_AwakerVoiceContent = {
    Text = "Eu odeio o mar, e com boa razão. O oceano devorou tudo que eu amava..."
  },
  Voice_5069_AwakerVoiceTitle = {
    Text = "Conversa·Coisas odiadas"
  },
  Voice_5070_AwakerVoiceContent = {
    Text = "Seja esquecimento ou perda, desta vez nós definitivamente retornaremos!"
  },
  Voice_5070_AwakerVoiceTitle = {
    Text = "Exaltar · Dois"
  },
  Voice_5071_AwakerVoiceContent = {
    Text = "Seja esquecimento ou perda, desta vez nós definitivamente retornaremos!"
  },
  Voice_5071_AwakerVoiceTitle = {
    Text = "Fúria Explosiva"
  },
  Voice_5072_AwakerVoiceContent = {
    Text = "Por favor, por favor, não se aproxime mais. É perigoso."
  },
  Voice_5072_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_5073_AwakerVoiceContent = {
    Text = "Sinta-se à vontade para tocar... Essas são cicatrizes da arena, um emblema de honra do homem!"
  },
  Voice_5073_AwakerVoiceTitle = {
    Text = "Conversa·Toque"
  },
  Voice_5074_AwakerVoiceContent = {
    Text = "(Grito de dor)"
  },
  Voice_5074_AwakerVoiceTitle = {Text = "Acertar·1"},
  Voice_5075_AwakerVoiceContent = {
    Text = "Ai, ai, ai!"
  },
  Voice_5075_AwakerVoiceTitle = {
    Text = "Acertar · II"
  },
  Voice_5076_AwakerVoiceContent = {
    Text = "(grunhido de dor)"
  },
  Voice_5076_AwakerVoiceTitle = {
    Text = "Acertar·III"
  },
  Voice_5077_AwakerVoiceContent = {
    Text = "(Grunhido despreocupado)"
  },
  Voice_5077_AwakerVoiceTitle = {
    Text = "Golpe·Quatro"
  },
  Voice_5078_AwakerVoiceContent = {
    Text = "Sente como se algo estivesse fervendo dentro do Corpo. É assim que se sente ao passar por Iluminar?"
  },
  Voice_5078_AwakerVoiceTitle = {
    Text = "Iluminar·Visão Remota"
  },
  Voice_5078_UnlockDesc = {
    Text = "Nível de iluminação atingiu 1 para desbloquear"
  },
  Voice_5079_AwakerVoiceContent = {
    Text = "Esta é algum tipo de nova tecnologia? Minha prótese parece muito mais leve."
  },
  Voice_5079_AwakerVoiceTitle = {
    Text = "Iluminar·Visão Remota"
  },
  Voice_5079_UnlockDesc = {
    Text = "Nível de iluminação atingiu 1 para desbloquear"
  },
  Voice_5080_AwakerVoiceContent = {
    Text = "A brisa salgada do mar me diz que minha terra natal não está longe."
  },
  Voice_5080_AwakerVoiceTitle = {
    Text = "Iluminar: Insight"
  },
  Voice_5080_UnlockDesc = {
    Text = "Nível de iluminação atingiu 7 para desbloquear"
  },
  Voice_5081_AwakerVoiceContent = {
    Text = "Os camaradas falecidos podem encontrar seu caminho de volta seguindo esta luz?"
  },
  Voice_5081_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexão"
  },
  Voice_5081_UnlockDesc = {
    Text = "Nível de iluminação atingiu 3 para desbloquear"
  },
  Voice_5082_AwakerVoiceContent = {
    Text = "Eu tenho procurado por dezenas de milhares de anos; um século passageiro não é nada. Até eu chegar à sua costa, continuarei a te ajudar."
  },
  Voice_5082_AwakerVoiceTitle = {
    Text = "Iluminar·Florescer"
  },
  Voice_5082_UnlockDesc = {
    Text = "Nível de iluminação atingiu 15 para desbloquear"
  },
  Voice_5083_AwakerVoiceContent = {
    Text = "Brilharei apenas pela minha pátria. Você..."
  },
  Voice_5083_AwakerVoiceTitle = {
    Text = "Iluminar·Construção"
  },
  Voice_5083_UnlockDesc = {
    Text = "Nível de iluminação atingiu 11 para desbloquear"
  },
  Voice_5084_AwakerVoiceContent = {
    Text = "Eu senti a brisa, carregando areia fina sobre meus pés."
  },
  Voice_5084_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_5084_UnlockDesc = {
    Text = "Nível de iluminação atingiu 2 para desbloquear"
  },
  Voice_5085_AwakerVoiceContent = {
    Text = "A extensão da minha contribuição para o seu poder termina aqui. Ser muito ganancioso não é uma coisa boa, você sabe?"
  },
  Voice_5085_AwakerVoiceTitle = {
    Text = "Iluminar·Construção"
  },
  Voice_5085_UnlockDesc = {
    Text = "Nível de iluminação atingiu 11 para desbloquear"
  },
  Voice_5086_AwakerVoiceContent = {
    Text = "O que você espera que eu devolva? Apenas uma batalha?"
  },
  Voice_5086_AwakerVoiceTitle = {
    Text = "Iluminar·Florescer"
  },
  Voice_5086_UnlockDesc = {
    Text = "Nível de iluminação atingiu 15 para desbloquear"
  },
  Voice_5087_AwakerVoiceContent = {
    Text = "Crânio do Amor, Crânio do Ressentimento, Crânio do Ódio, Crânio do Desejo... Oh, você voltou?"
  },
  Voice_5087_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexão"
  },
  Voice_5087_UnlockDesc = {
    Text = "Nível de iluminação atingiu 3 para desbloquear"
  },
  Voice_5088_AwakerVoiceContent = {
    Text = "Como é uma transação, não posso simplesmente aceitar seu presente. Você gostaria de escolher algo na loja?"
  },
  Voice_5088_AwakerVoiceTitle = {
    Text = "Iluminar: Insight"
  },
  Voice_5088_UnlockDesc = {
    Text = "Nível de iluminação atingiu 7 para desbloquear"
  },
  Voice_50898_AwakerVoiceContent = {
    Text = "Eu lhe ensinarei alegria, diversão, a emoção de alcançar o pico... Em troca, você deve revelar seus desejos com sinceridade, certo?"
  },
  Voice_50898_AwakerVoiceTitle = {
    Text = "Conversa Ociosa: Sobre o Guardião 2"
  },
  Voice_50899_AwakerVoiceContent = {
    Text = "Eu sou a Árvore Mãe, e a Árvore Mãe sou eu. A seiva flui em minhas veias, e a vontade da árvore permanece em minha mente..."
  },
  Voice_50899_AwakerVoiceTitle = {
    Text = "Conversa Ociosa · Sobre a Árvore Mãe"
  },
  Voice_50899_UnlockDesc = {
    Text = "Desbloqueado após completar o Capítulo 7 da \"Operação de Investigação\""
  },
  Voice_5089_AwakerVoiceContent = {
    Text = "Pague o preço pela sua traição!"
  },
  Voice_5089_AwakerVoiceTitle = {
    Text = "Exaltar · Dois"
  },
  Voice_50900_AwakerVoiceContent = {
    Text = "Eu acho que vi sua lápide enquanto procurava um local escondido na Tumba Chave... Minha múmia também será enterrada aqui? Não? Que pena."
  },
  Voice_50900_AwakerVoiceTitle = {
    Text = "Conversa Ociosa: Sobre o Monte da Chave"
  },
  Voice_50900_UnlockDesc = {
    Text = "Desbloqueado após completar o Capítulo 7 da \"Operação de Investigação\""
  },
  Voice_50901_AwakerVoiceContent = {
    Text = "O cara-lobo... Ele tem uma relação ambígua com aquele N..."
  },
  Voice_50901_AwakerVoiceTitle = {
    Text = "Chat·Sobre Ryker"
  },
  Voice_50901_UnlockDesc = {
    Text = "Após obter o despertador \"Ryker\", desbloqueado"
  },
  Voice_50902_AwakerVoiceContent = {
    Text = "Aproxime-se, abrace-me, prove-me... não se esqueça de mim."
  },
  Voice_50902_AwakerVoiceTitle = {
    Text = "Conversa Ociosa: Sobre o Guardião 3"
  },
  Voice_50902_UnlockDesc = {
    Text = "Desbloqueado após completar o Capítulo 7 da \"Operação de Investigação\""
  },
  Voice_50903_AwakerVoiceContent = {
    Text = "Ela era uma criança excessivamente diligente e cautelosa. Claro, eu não a culparia~ Sem ela, a tribo de espírito livre teria sido destruída nas mudanças há muito tempo, certo?"
  },
  Voice_50903_AwakerVoiceTitle = {
    Text = "Papo reto: Sobre Alva"
  },
  Voice_50903_UnlockDesc = {
    Text = "Após obter o despertador \"Alva\", desbloqueado"
  },
  Voice_50904_AwakerVoiceContent = {
    Text = "Nascida das areias amarelas, e às areias amarelas você retornará. Nesta breve jornada, você não deveria deixar algo para trás e semear algumas sementes?"
  },
  Voice_50904_AwakerVoiceTitle = {
    Text = "Conversa Informal·Sobre o Deserto"
  },
  Voice_50905_AwakerVoiceContent = {
    Text = "Os desejos todas nascem do amor; o amor é a semente inicial antes que a árvore imponente venha à existência."
  },
  Voice_50905_AwakerVoiceTitle = {
    Text = "Conversas Ociosas: Sobre Desejo"
  },
  Voice_50906_AwakerVoiceContent = {
    Text = "Oh querido, um rato fofo acabou de passar correndo... Ouvi dizer que os ratos adoram se esgueirar, mas, infelizmente, este ainda é muito jovem, praticamente um recém-nascido."
  },
  Voice_50906_AwakerVoiceTitle = {
    Text = "Fofocas · Sobre Jenki"
  },
  Voice_50906_UnlockDesc = {
    Text = "Desbloqueado após adquirir o Despertar \"Jenkin\""
  },
  Voice_50907_AwakerVoiceContent = {
    Text = "Eles carregaram meu sangue e linhagem, transformando-se nas águas prósperas de Lemwahi... A partir de hoje, cabe a você garantir que meu legado perdure."
  },
  Voice_50907_AwakerVoiceTitle = {
    Text = "Conversa Informal·Sobre Alan"
  },
  Voice_50907_UnlockDesc = {
    Text = "Desbloqueado após completar o Capítulo 7 da \"Operação de Investigação\""
  },
  Voice_50908_AwakerVoiceContent = {
    Text = "Aranhas... aranhas. Hmm~ Eu amo aranhas. Elas nascem com o poder de andar, e suas habilidades reprodutivas e de sobrevivência são realmente invejáveis..."
  },
  Voice_50908_AwakerVoiceTitle = {
    Text = "Fala Ociosa · Sobre Agrippa"
  },
  Voice_50908_UnlockDesc = {
    Text = "Após obter o despertador \"Agrippa\", desbloqueado"
  },
  Voice_50909_AwakerVoiceContent = {
    Text = "Todos os seres com o sangue da árvore flutuante são meus filhos. Isso inclui você, que engoliu as sementes da árvore, certo?"
  },
  Voice_50909_AwakerVoiceTitle = {
    Text = "Conversa Casual · Sobre Descendentes"
  },
  Voice_50909_UnlockDesc = {
    Text = "Desbloqueado após completar o Capítulo 7 da \"Operação de Investigação\""
  },
  Voice_5090_AwakerVoiceContent = {
    Text = "Minhas mercadorias? Você poderia dizer que eu tenho tudo para satisfazer todos os seus desejos... por um preço."
  },
  Voice_5090_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_5090_UnlockDesc = {
    Text = "Nível de iluminação atingiu 2 para desbloquear"
  },
  Voice_50910_AwakerVoiceContent = {
    Text = "Oh querido, devo admitir que eu perdi para ela desta vez... Mas felizmente, como ela escolheu você, você vai beber a seiva da árvore e levar meu sangue e sementes para um novo mundo, certo?"
  },
  Voice_50910_AwakerVoiceTitle = {
    Text = "Conversas Ociosas·Sobre Tawil"
  },
  Voice_50910_UnlockDesc = {
    Text = "Desbloqueado após obter o Despertador \"Ramona\""
  },
  Voice_50911_AwakerVoiceContent = {
    Text = "Como uma das três essências principais, aquele cara é um monstro enigmático. Não se deixe enganar por suas palavras doces, ou eu ficarei de coração partido..."
  },
  Voice_50911_AwakerVoiceTitle = {
    Text = "Papo reto · Sobre N"
  },
  Voice_50912_AwakerVoiceContent = {
    Text = "Enquanto houver consciência, há desejo. Mesmo seres mecânicos não são exceção, certo?"
  },
  Voice_50912_AwakerVoiceTitle = {
    Text = "Conversas Ociosas·Sobre Erica"
  },
  Voice_50912_UnlockDesc = {
    Text = "Desbloqueado após adquirir o Despertar \"Erica\""
  },
  Voice_5091_AwakerVoiceContent = {
    Text = "Pague o preço pela sua traição!"
  },
  Voice_5091_AwakerVoiceTitle = {
    Text = "Fúria Explosiva"
  },
  Voice_5092_AwakerVoiceContent = {
    Text = "Bem-vindo ao reino incrível!"
  },
  Voice_5092_AwakerVoiceTitle = {
    Text = "Fúria Explosiva"
  },
  Voice_5093_AwakerVoiceContent = {
    Text = "(Número baixo)"
  },
  Voice_5093_AwakerVoiceTitle = {
    Text = "Golpe·Quatro"
  },
  Voice_5094_AwakerVoiceContent = {
    Text = "Eu estou bem familiarizado com a dor de esculpir e a queima da transformação. No entanto, tudo isso se torna insignificante quando comparado à beleza eterna."
  },
  Voice_5094_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_5094_UnlockDesc = {
    Text = "Nível de iluminação atingiu 2 para desbloquear"
  },
  Voice_5095_AwakerVoiceTitle = {
    Text = "Golpe·Quatro"
  },
  Voice_5096_AwakerVoiceContent = {
    Text = "As palavras não ditas serão transmitidas a você através do meu trabalho."
  },
  Voice_5096_AwakerVoiceTitle = {
    Text = "Iluminar: Insight"
  },
  Voice_5096_UnlockDesc = {
    Text = "Nível de iluminação atingiu 7 para desbloquear"
  },
  Voice_5097_AwakerVoiceContent = {
    Text = "(Exclamação)"
  },
  Voice_5097_AwakerVoiceTitle = {
    Text = "Acertar · II"
  },
  Voice_5098_AwakerVoiceContent = {
    Text = "O soberano adormecido murmura em meu ouvido, as ruínas do fundo do mar se reconstituindo constantemente diante dos meus olhos... As inúmeras cenas de sonho finalmente se tornaram realidade?"
  },
  Voice_5098_AwakerVoiceTitle = {
    Text = "Iluminar·Florescer"
  },
  Voice_5098_UnlockDesc = {
    Text = "Nível de iluminação atingiu 15 para desbloquear"
  },
  Voice_5099_AwakerVoiceContent = {
    Text = "Obrigado por preparar o estúdio para mim. Tudo aqui está banhado pela luz do sol. Parece que cada peça de trabalho, cada faca de entalhe, brilha com uma luz dourada. Oh, a primavera é dourada."
  },
  Voice_5099_AwakerVoiceTitle = {
    Text = "Iluminar·Construção"
  },
  Voice_5099_UnlockDesc = {
    Text = "Nível de iluminação atingiu 11 para desbloquear"
  },
  Voice_5100_AwakerVoiceContent = {
    Text = "Embora nossos temperamentos diferem, eu realmente admiro aquela criança. Ela possui uma coragem que transcende todas as dificuldades e limitações. Se eu tivesse sido tão corajoso e resiliente quanto ela, talvez eu não tivesse escolhido acabar com minha vida no mar..."
  },
  Voice_5100_AwakerVoiceTitle = {
    Text = "Conversas Ociosas·Sobre Murphy"
  },
  Voice_5100_UnlockDesc = {
    Text = "Desbloqueado após obter Despertador \"Murphy\""
  },
  Voice_5101_AwakerVoiceContent = {
    Text = "A Dama Vermelha é diferente de qualquer senhor que já servi... Não, não é que eu a desagrade; é apenas... apenas um pouco difícil de lidar..."
  },
  Voice_5101_AwakerVoiceTitle = {
    Text = "Conversa Informal·Sobre Sorel"
  },
  Voice_5101_UnlockDesc = {
    Text = "Desbloqueado após obter Despertar\"Sorel\""
  },
  Voice_5102_AwakerVoiceContent = {
    Text = "Abrace a loucura!"
  },
  Voice_5102_AwakerVoiceTitle = {
    Text = "Carta de Habilidade·Quatro"
  },
  Voice_5103_AwakerVoiceContent = {
    Text = "Mal segurando."
  },
  Voice_5103_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_5104_AwakerVoiceContent = {Text = "Extermine!"},
  Voice_5104_AwakerVoiceTitle = {
    Text = "Despertar do Conhecimento Espiritual"
  },
  Voice_5105_AwakerVoiceContent = {
    Text = "Você não precisa..."
  },
  Voice_5105_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · I"
  },
  Voice_5106_AwakerVoiceContent = {
    Text = "O coração é um abismo sem fundo, nunca a ser preenchido."
  },
  Voice_5106_AwakerVoiceTitle = {
    Text = "Atualizar·II"
  },
  Voice_5107_AwakerVoiceContent = {
    Text = "Sem dor, sem coceira, mas... ainda extremamente grato."
  },
  Voice_5107_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · Três"
  },
  Voice_5108_AwakerVoiceContent = {
    Text = "Ah... Você está se dirigindo a mim? Desculpe, eu estava apenas relembrando a vista do mastro. Você poderia repetir sua pergunta?"
  },
  Voice_5108_AwakerVoiceTitle = {
    Text = "Conversas Ociosas·Sobre o Passado"
  },
  Voice_5109_AwakerVoiceContent = {
    Text = "Tanto um mestre quanto uma mãe."
  },
  Voice_5109_AwakerVoiceTitle = {
    Text = "Conversa·Sobre Guardião do Segredo"
  },
  Voice_5110_AwakerVoiceContent = {
    Text = "Uma abertura!"
  },
  Voice_5110_AwakerVoiceTitle = {
    Text = "Carta de Habilidade·Quatro"
  },
  Voice_5111_AwakerVoiceContent = {
    Text = "Uma abertura!"
  },
  Voice_5111_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_5112_AwakerVoiceContent = {Text = "Pronto—"},
  Voice_5112_AwakerVoiceTitle = {Text = "Ataque·Um"},
  Voice_5113_AwakerVoiceContent = {Text = "Ha!"},
  Voice_5113_AwakerVoiceTitle = {Text = "Ataque·Um"},
  Voice_5114_AwakerVoiceContent = {
    Text = "Empurre um pouco mais forte~"
  },
  Voice_5114_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_5115_AwakerVoiceContent = {
    Text = "Amor Escaldante!"
  },
  Voice_5115_AwakerVoiceTitle = {
    Text = "Habilidade·Um"
  },
  Voice_5116_AwakerVoiceContent = {
    Text = "D-fenômeno... Não posso revelar muito. No entanto, sua aparição é muito anterior ao que você pensa."
  },
  Voice_5116_AwakerVoiceTitle = {
    Text = "Bate-papo · Sobre Dissolução"
  },
  Voice_5118_AwakerVoiceContent = {Text = "Hmm—"},
  Voice_5118_AwakerVoiceTitle = {
    Text = "Despertar do Conhecimento Espiritual"
  },
  Voice_5119_AwakerVoiceContent = {Text = "Bom."},
  Voice_5119_AwakerVoiceTitle = {Text = "Ataque·Um"},
  Voice_5120_AwakerVoiceContent = {
    Text = "Vamos partir."
  },
  Voice_5120_AwakerVoiceTitle = {Text = "Ataque·Um"},
  Voice_5121_AwakerVoiceContent = {
    Text = "Heh, nossa princesa marionete está chorando de novo. A garrafa não está cabendo ou a canção de ninar está desafinada?"
  },
  Voice_5121_AwakerVoiceTitle = {
    Text = "Conversas Ociosas·Sobre Murphy"
  },
  Voice_5121_UnlockDesc = {
    Text = "Desbloqueado após obter Despertador \"Murphy\""
  },
  Voice_5122_AwakerVoiceContent = {
    Text = "Boohoo... Eu não quero enfrentar aquelas coisas..."
  },
  Voice_5122_AwakerVoiceTitle = {
    Text = "Início da Investigação"
  },
  Voice_5123_AwakerVoiceContent = {
    Text = "Agora, é a minha vez de retribuir a você."
  },
  Voice_5123_AwakerVoiceTitle = {
    Text = "Despertar do Conhecimento Espiritual"
  },
  Voice_5124_AwakerVoiceContent = {
    Text = "A onda de poder se sente como chamas abrasadoras queimando nos ossos."
  },
  Voice_5124_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · I"
  },
  Voice_5125_AwakerVoiceContent = {
    Text = "Ah... Desculpe, por favor não se mova!"
  },
  Voice_5125_AwakerVoiceTitle = {
    Text = "Fúria Explosiva"
  },
  Voice_5126_AwakerVoiceContent = {
    Text = "O calor ao alcance..."
  },
  Voice_5126_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · Três"
  },
  Voice_5127_AwakerVoiceContent = {
    Text = "As rosas no pátio estão em plena flor."
  },
  Voice_5127_AwakerVoiceTitle = {
    Text = "Atualizar·II"
  },
  Voice_5128_AwakerVoiceContent = {
    Text = "Bom trabalho! Você ainda tem energia para continuar?"
  },
  Voice_5128_AwakerVoiceTitle = {
    Text = "Investigação Bem-sucedida"
  },
  Voice_5129_AwakerVoiceContent = {
    Text = "O cavaleiro é uma entidade intangível, moldada pela lealdade, bravura e virtude. Minha arma é a mesma, dada forma pela vontade de proteger: uma lança e um escudo."
  },
  Voice_5129_AwakerVoiceTitle = {
    Text = "Papo reto: Sobre os Cavaleiros"
  },
  Voice_5130_AwakerVoiceContent = {
    Text = "Jenkin, Diana, Mike, Tyug, Marrom... Uau! Desculpe, eu só estava conversando comigo mesma! Você pergunta por que estou recitando esses nomes? Porque Aigis não quer esquecer de ninguém..."
  },
  Voice_5130_AwakerVoiceTitle = {
    Text = "Conversa Casual · Sobre Amigos"
  },
  Voice_5131_AwakerVoiceContent = {
    Text = "Não se aproxime de mim!"
  },
  Voice_5131_AwakerVoiceTitle = {Text = "Ataque·Um"},
  Voice_5132_AwakerVoiceContent = {
    Text = "Não consigo suportar isso!"
  },
  Voice_5132_AwakerVoiceTitle = {Text = "Ataque·II"},
  Voice_5133_AwakerVoiceContent = {Text = "Ah~ Ei!"},
  Voice_5133_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_5134_AwakerVoiceContent = {Text = "Ah~ Ei!"},
  Voice_5134_AwakerVoiceTitle = {
    Text = "Carta de Habilidade·Quatro"
  },
  Voice_5135_AwakerVoiceContent = {
    Text = "Obrigado pela sua convocação. Se houver uma ocasião em que minha voz for necessária, por favor, me notifique com antecedência."
  },
  Voice_5135_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_5137_AwakerVoiceContent = {
    Text = "Isso... é o líquido viscoso preto correndo pelas veias, o poder supremo que silencia todos os gemidos! \"Eu\" nasci disso, nasci para destruir! Hahaha!"
  },
  Voice_5137_AwakerVoiceTitle = {
    Text = "Bate-papo · Sobre Dissolução"
  },
  Voice_5138_AwakerVoiceContent = {
    Text = "Me chamando, quer apostar? ...O que, uma investigação? De jeito nenhum, isso é um desperdício de sorte..."
  },
  Voice_5138_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_5139_AwakerVoiceContent = {
    Text = "A aula teórica é bem chata. Eu secretamente li os registros da investigação na parte de trás da sala de aula. Só te dizendo, não deixe a Boneca saber."
  },
  Voice_5139_AwakerVoiceTitle = {
    Text = "Conversa·Coisas odiadas"
  },
  Voice_5140_AwakerVoiceContent = {
    Text = "Sinta as amargas consequências!"
  },
  Voice_5140_AwakerVoiceTitle = {
    Text = "Carta de Habilidade·Quatro"
  },
  Voice_5141_AwakerVoiceContent = {
    Text = "Sinta as amargas consequências!"
  },
  Voice_5141_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_5142_AwakerVoiceContent = {
    Text = "Eu nunca culpei Juliette; ela foi apenas uma vítima do sofrimento negro. Mas... ela não parece querer ouvir isso de mim. Você poderia transmitir isso a ela por mim, Mensageiro?"
  },
  Voice_5142_AwakerVoiceTitle = {
    Text = "Fofoca · Sobre Juliette"
  },
  Voice_5142_UnlockDesc = {
    Text = "Voz ainda não implementada"
  },
  Voice_5143_AwakerVoiceContent = {
    Text = "Desacelere."
  },
  Voice_5143_AwakerVoiceTitle = {
    Text = "Defesa · I"
  },
  Voice_5144_AwakerVoiceContent = {Text = "Bom."},
  Voice_5144_AwakerVoiceTitle = {Text = "Defesa·II"},
  Voice_5145_AwakerVoiceContent = {
    Text = "Ei! Pare de tocar nas coisas, você está bagunçando! ...Ah bem, vou deixar passar desta vez já que sou generoso."
  },
  Voice_5145_AwakerVoiceTitle = {
    Text = "Conversa·Toque"
  },
  Voice_5146_AwakerVoiceContent = {
    Text = "Não há necessidade!"
  },
  Voice_5146_AwakerVoiceTitle = {Text = "Defesa·II"},
  Voice_5147_AwakerVoiceContent = {Text = "Tsk!"},
  Voice_5147_AwakerVoiceTitle = {
    Text = "Defesa · I"
  },
  Voice_5148_AwakerVoiceContent = {
    Text = "Desde o dia em que você me despertou da escuridão, tenho certeza de que você pode salvar todos da desgraça conhecida como Dissolução e guiá-los para as terras Puras. Eu aguardo por esse dia."
  },
  Voice_5148_AwakerVoiceTitle = {
    Text = "Conversa Ociosa · Sobre o Guardião · I"
  },
  Voice_5149_AwakerVoiceContent = {
    Text = "Eu cheiro... o cheiro de sangue."
  },
  Voice_5149_AwakerVoiceTitle = {
    Text = "Início da Investigação"
  },
  Voice_5150_AwakerVoiceContent = {
    Text = "Onde está o alvo? Como um símbolo de gratidão por me despertar, cuidarei deles para você."
  },
  Voice_5150_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_5151_AwakerVoiceContent = {
    Text = "Meu chapéu não pode esperar mais!"
  },
  Voice_5151_AwakerVoiceTitle = {
    Text = "Início da Investigação"
  },
  Voice_5152_AwakerVoiceContent = {
    Text = "Esta concha não deveria se agitar para ninguém além Dele... Mas sua warmth..."
  },
  Voice_5152_AwakerVoiceTitle = {
    Text = "Conversa·Toque"
  },
  Voice_5153_AwakerVoiceContent = {
    Text = "Que tal uma luta?"
  },
  Voice_5153_AwakerVoiceTitle = {
    Text = "Conversa·Toque"
  },
  Voice_5154_AwakerVoiceContent = {
    Text = "Profanador..."
  },
  Voice_5154_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_5155_AwakerVoiceContent = {
    Text = "Imperdoável."
  },
  Voice_5155_AwakerVoiceTitle = {
    Text = "Habilidade·Um"
  },
  Voice_5156_AwakerVoiceContent = {
    Text = "Erica está funcionando normalmente e está bem conectada ao equipamento elétrico da Universidade Mythag. Você precisa que eu ligue as luzes do dormitório?"
  },
  Voice_5156_AwakerVoiceTitle = {
    Text = "Conversas Ociosas·Sobre Erica"
  },
  Voice_5157_AwakerVoiceContent = {
    Text = "Próximo, é hora de uma refeição, hehe..."
  },
  Voice_5157_AwakerVoiceTitle = {
    Text = "Investigação Bem-sucedida"
  },
  Voice_5159_AwakerVoiceContent = {
    Text = "Não deixe a mulher de chapéu roxo de aba larga perto do palco! Sem perguntas—apenas mantenha-a longe se não quiser que uma massa cinza pegajosa derrame de seu chapéu!"
  },
  Voice_5159_AwakerVoiceTitle = {
    Text = "Conversa Casual · Sobre Narciso"
  },
  Voice_5159_UnlockDesc = {
    Text = "Desbloqueado após adquirir o Despertar \"Narciso\""
  },
  Voice_5160_AwakerVoiceContent = {
    Text = "Você sempre é assim? Confiando em todos e virando as costas para eles? Muito ingênuo."
  },
  Voice_5160_AwakerVoiceTitle = {
    Text = "Conversa·Sobre Guardião do Segredo"
  },
  Voice_5161_AwakerVoiceContent = {
    Text = "O ódio pode ser aliviado, mas nunca pode ser apagado."
  },
  Voice_5161_AwakerVoiceTitle = {
    Text = "Investigação Bem-sucedida"
  },
  Voice_5162_AwakerVoiceContent = {
    Text = "Despertador? Hmm... Sim, 7 da manhã é o melhor horário para acordar! Vamos coletar conchas na praia amanhã de manhã às 7!"
  },
  Voice_5162_AwakerVoiceTitle = {
    Text = "Conversa · Sobre Despertador"
  },
  Voice_5163_AwakerVoiceContent = {
    Text = "Conceda-lhe a vida eterna!"
  },
  Voice_5163_AwakerVoiceTitle = {
    Text = "Despertar do Conhecimento Espiritual"
  },
  Voice_5164_AwakerVoiceContent = {Text = "Hah!"},
  Voice_5164_AwakerVoiceTitle = {
    Text = "Habilidade·Um"
  },
  Voice_5165_AwakerVoiceContent = {Text = "Hah!"},
  Voice_5165_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_5166_AwakerVoiceContent = {
    Text = "Desculpe, se Aigis estiver te causando problemas, eu vou embora imediatamente!"
  },
  Voice_5166_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Um"
  },
  Voice_5166_UnlockDesc = {
    Text = "Nível de afinidade atingido 2 desbloqueado"
  },
  Voice_5167_AwakerVoiceContent = {
    Text = "Você me forneceu um lugar para ficar, e sou grato. Mas perdoe-me, não mereço mais estar no palco novamente."
  },
  Voice_5167_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_5168_AwakerVoiceContent = {
    Text = "Obrigado por me permitir ficar aqui. Se houver alguma forma de eu retribuir, por favor, avise Aigis. Gostaria de um pouco de chá?"
  },
  Voice_5168_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Três"
  },
  Voice_5168_UnlockDesc = {
    Text = "Nível de afinidade atingido 6 desbloqueado"
  },
  Voice_5169_AwakerVoiceContent = {
    Text = "Está tão quente que não quero ir embora. Quando estou sozinho, fica realmente escuro, frio e assustador..."
  },
  Voice_5169_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Quatro"
  },
  Voice_5169_UnlockDesc = {
    Text = "Nível de afinidade atingido 8 desbloqueado"
  },
  Voice_5170_AwakerVoiceContent = {
    Text = "Aigis... Posso realmente voltar para a multidão? Eu ainda não estou pronta, mas você já me aceitou... Nesse caso, por favor, continue a cuidar de mim... Guardião."
  },
  Voice_5170_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Cinco"
  },
  Voice_5170_UnlockDesc = {
    Text = "Nível de afinidade atingido 10 desbloqueado"
  },
  Voice_5171_AwakerVoiceContent = {
    Text = "Eu lembro, eu lembro...! O sangue imundo dos humanos me prendeu... Eu não consegui me transformar! Como, como... onde estão minhas brânquias? Por que não estão se movendo?! Por quê!"
  },
  Voice_5171_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_5172_AwakerVoiceContent = {
    Text = "Eu amo polvo grelhado, polvo cozido, polvo frito... Alguns dizem que estou cometendo uma blasfêmia. Desculpe, mas polvo é tão delicioso, ha ha ha!"
  },
  Voice_5172_AwakerVoiceTitle = {
    Text = "Conversa·Coisas favoritas"
  },
  Voice_5173_AwakerVoiceContent = {
    Text = "Vermes. Estrelas. Eu sou... Uvhash! Mate... deixe-me matar!"
  },
  Voice_5173_AwakerVoiceTitle = {
    Text = "Iluminar·Florescer"
  },
  Voice_5173_UnlockDesc = {
    Text = "Nível de iluminação atingiu 15 para desbloquear"
  },
  Voice_5174_AwakerVoiceContent = {
    Text = "Corpo carmesim, tentáculos pulsantes, partes da boca abrindo e fechando constantemente... Ótimo, ótimo! Mal posso esperar para rasgar a garganta de alguém!"
  },
  Voice_5174_AwakerVoiceTitle = {
    Text = "Iluminar·Construção"
  },
  Voice_5174_UnlockDesc = {
    Text = "Nível de iluminação atingiu 11 para desbloquear"
  },
  Voice_5175_AwakerVoiceContent = {
    Text = "Hahaha, essa é a sensação! Me dê mais... o dobro, não, dez vezes a dose!"
  },
  Voice_5175_AwakerVoiceTitle = {
    Text = "Iluminar: Insight"
  },
  Voice_5175_UnlockDesc = {
    Text = "Nível de iluminação atingiu 7 para desbloquear"
  },
  Voice_5176_AwakerVoiceContent = {
    Text = "Irei suportá-lo."
  },
  Voice_5176_AwakerVoiceTitle = {
    Text = "Despertar do Conhecimento Espiritual"
  },
  Voice_5177_AwakerVoiceContent = {
    Text = "Esta estranha sensação... não é ruim. Melhor do que a beladona do mago levantino."
  },
  Voice_5177_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_5177_UnlockDesc = {
    Text = "Nível de iluminação atingiu 2 para desbloquear"
  },
  Voice_5178_AwakerVoiceContent = {
    Text = "Companheiros? Hmph... Eu não preciso de nenhum. Não serei sobrecarregado pelo mesmo fardo duas vezes."
  },
  Voice_5178_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Um"
  },
  Voice_5178_UnlockDesc = {
    Text = "Nível de afinidade atingido 2 desbloqueado"
  },
  Voice_5179_AwakerVoiceContent = {
    Text = "Eu cooperarei com você apenas porque você demonstrou força suficiente para igualar a minha. Não se esqueça, este contrato terminará quando seu poder diminuir, e eu não hesitarei em cortar sua cabeça."
  },
  Voice_5179_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Dois"
  },
  Voice_5179_UnlockDesc = {
    Text = "Nível de afinidade atingido 4 desbloqueado"
  },
  Voice_5180_AwakerVoiceContent = {
    Text = "Em seus olhos... Eu vejo um brilho, o fogo feroz da ambição e do desejo. Mortal, conhece-te a ti mesmo! Somos espíritos afins!"
  },
  Voice_5180_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Três"
  },
  Voice_5180_UnlockDesc = {
    Text = "Nível de afinidade atingido 6 desbloqueado"
  },
  Voice_5181_AwakerVoiceContent = {
    Text = "Conhece o Albatroz? Eles enfrentam corajosamente as tempestades, mas uma vez banidos ao chão, cercados de zombaria, aquelas asas gigantes e caídas tornam-se ironicamente um obstáculo patético. Enfim, esta história não significa nada... Apenas me veio à mente porque me sinto muito relaxado ao estar com você — apenas uma conversa casual."
  },
  Voice_5181_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Quatro"
  },
  Voice_5181_UnlockDesc = {
    Text = "Nível de afinidade atingido 8 desbloqueado"
  },
  Voice_5182_AwakerVoiceContent = {
    Text = "Talvez, os tempos realmente mudaram. Agora, até os fracos podem superar os recifes, comandar as ondas e se tornar o Rei dos Céus.\nMortal, aguardo o dia em que você reescreverá a história. Será uma honra para mim me tornar a poderosa lâmina em sua mão!"
  },
  Voice_5182_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Cinco"
  },
  Voice_5182_UnlockDesc = {
    Text = "Nível de afinidade atingido 10 desbloqueado"
  },
  Voice_5183_AwakerVoiceContent = {
    Text = "A taxa de conversão é muito baixa. Apresente-se no meu escritório amanhã para requalificação."
  },
  Voice_5183_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · I"
  },
  Voice_5184_AwakerVoiceContent = {
    Text = "Você conheceu outra Boneca? A chamada \"verdade do mundo\" pode transformar uma Boneca tão calma e racional em uma pessoa completamente diferente... No final, você e eu também nos tornaremos assim?"
  },
  Voice_5184_AwakerVoiceTitle = {
    Text = "Conversas Ociosas·Sobre @2"
  },
  Voice_5184_UnlockDesc = {
    Text = "Desbloqueado após obter Despertador@2"
  },
  Voice_5185_AwakerVoiceContent = {
    Text = "Mestre... eu preciso de ordens. Por favor, me dê ordens."
  },
  Voice_5185_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_5186_AwakerVoiceContent = {
    Text = "O desempenho do mech foi aprimorado."
  },
  Voice_5186_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · Três"
  },
  Voice_5189_AwakerVoiceContent = {
    Text = "Hmm-hmm-hmm!"
  },
  Voice_5189_AwakerVoiceTitle = {
    Text = "Defesa · I"
  },
  Voice_5190_AwakerVoiceContent = {
    Text = "Mais Aliados!"
  },
  Voice_5190_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_5191_AwakerVoiceContent = {
    Text = "Mais Aliados!"
  },
  Voice_5191_AwakerVoiceTitle = {
    Text = "Habilidade·Um"
  },
  Voice_5192_AwakerVoiceContent = {
    Text = "Desculpe, eu não posso deixar o berço... Isso pode bloquear a visão de todos, então eu vou ficar na parte de trás da sala de aula."
  },
  Voice_5192_AwakerVoiceTitle = {
    Text = "Chat·Sobre a Universidade Mythag"
  },
  Voice_5193_AwakerVoiceContent = {
    Text = "O que! Não tem um único tapete de Constantinopla, chá de Ceilão ou churros de Andalucía...? Ugh... essa mulher sempre consegue essas coisas tão facilmente. Eu pensei que elas eram comuns..."
  },
  Voice_5193_AwakerVoiceTitle = {
    Text = "Conversa·Coisas favoritas"
  },
  Voice_5194_AwakerVoiceContent = {
    Text = "Estou longe de minha forma original."
  },
  Voice_5194_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_5194_UnlockDesc = {
    Text = "Nível de iluminação atingiu 2 para desbloquear"
  },
  Voice_5195_AwakerVoiceContent = {
    Text = "Tão ansioso, parece um pouco grosseiro para alguém do seu calibre."
  },
  Voice_5195_AwakerVoiceTitle = {
    Text = "Conversa·Toque"
  },
  Voice_5196_AwakerVoiceContent = {
    Text = "Não importa quão muito melhore, a aparência desta besta não mudará. Afinal, é apenas uma manifestação do meu poder."
  },
  Voice_5196_AwakerVoiceTitle = {
    Text = "Iluminar: Insight"
  },
  Voice_5196_UnlockDesc = {
    Text = "Nível de iluminação atingiu 7 para desbloquear"
  },
  Voice_5197_AwakerVoiceContent = {
    Text = "Parece que estou de volta ao oceano caótico, não é ruim"
  },
  Voice_5197_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexão"
  },
  Voice_5197_UnlockDesc = {
    Text = "Nível de iluminação atingiu 3 para desbloquear"
  },
  Voice_5198_AwakerVoiceContent = {
    Text = "Em vista dos seus enormes esforços, vou relutantemente aceitá-lo como um companheiro."
  },
  Voice_5198_AwakerVoiceTitle = {
    Text = "Iluminar·Florescer"
  },
  Voice_5198_UnlockDesc = {
    Text = "Nível de iluminação atingiu 15 para desbloquear"
  },
  Voice_5199_AwakerVoiceContent = {
    Text = "Rompa as barreiras do Poder, assim como quebrando as paredes de um Labirinto."
  },
  Voice_5199_AwakerVoiceTitle = {
    Text = "Iluminar·Construção"
  },
  Voice_5199_UnlockDesc = {
    Text = "Nível de iluminação atingiu 11 para desbloquear"
  },
  Voice_5200_AwakerVoiceContent = {
    Text = "Você não pode rasgar a comida ou esmagar os bancos da cafeteria... Tudo bem, Lily não fará isso da próxima vez."
  },
  Voice_5200_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Dois"
  },
  Voice_5200_UnlockDesc = {
    Text = "Nível de afinidade atingido 4 desbloqueado"
  },
  Voice_5201_AwakerVoiceContent = {
    Text = "Posso chamá-la de Mãe?"
  },
  Voice_5201_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Três"
  },
  Voice_5201_UnlockDesc = {
    Text = "Nível de afinidade atingido 6 desbloqueado"
  },
  Voice_5202_AwakerVoiceContent = {
    Text = "Há algum comando, mestre? \n\"Não os leve para fora, todos ficarão assustados?\"\nLily entende e irá escondê-los imediatamente."
  },
  Voice_5202_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Um"
  },
  Voice_5202_UnlockDesc = {
    Text = "Nível de afinidade atingido 2 desbloqueado"
  },
  Voice_5203_AwakerVoiceContent = {
    Text = "Então, é assim que é se tornar um Despertador."
  },
  Voice_5203_AwakerVoiceTitle = {
    Text = "Iluminar·Visão Remota"
  },
  Voice_5203_UnlockDesc = {
    Text = "Nível de iluminação atingiu 1 para desbloquear"
  },
  Voice_5204_AwakerVoiceContent = {
    Text = "Mãe, posso dormir ao seu lado? Quando estou sozinho, tenho sonhos escuros e assustadores. As mãos e os pés de Lily caíram... Dói muito."
  },
  Voice_5204_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Cinco"
  },
  Voice_5204_UnlockDesc = {
    Text = "Nível de afinidade atingido 10 desbloqueado"
  },
  Voice_5205_AwakerVoiceContent = {
    Text = "Ah! Obrigada pela sua bondade, Karen é apenas uma humilde criada..."
  },
  Voice_5205_AwakerVoiceTitle = {
    Text = "Iluminar·Visão Remota"
  },
  Voice_5205_UnlockDesc = {
    Text = "Nível de iluminação atingiu 1 para desbloquear"
  },
  Voice_5206_AwakerVoiceContent = {Text = "Hmph~"},
  Voice_5206_AwakerVoiceTitle = {Text = "Defesa·II"},
  Voice_5207_AwakerVoiceContent = {
    Text = "Eu preciso reunir alguns materiais para esculpir, de preferência frescos."
  },
  Voice_5207_AwakerVoiceTitle = {
    Text = "Início da Investigação"
  },
  Voice_5208_AwakerVoiceContent = {
    Text = "Por favor, fique quieto."
  },
  Voice_5208_AwakerVoiceTitle = {
    Text = "Defesa · I"
  },
  Voice_5209_AwakerVoiceContent = {
    Text = "Aqueles que se mantêm teimosos em sua tolice realizam feitos fúteis."
  },
  Voice_5209_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_5209_UnlockDesc = {
    Text = "Nível de iluminação atingiu 2 para desbloquear"
  },
  Voice_5210_AwakerVoiceContent = {
    Text = "Neste ponto, eu consigo entender um pouco sua intenção. Está tudo bem, continue."
  },
  Voice_5210_AwakerVoiceTitle = {
    Text = "Iluminar·Construção"
  },
  Voice_5210_UnlockDesc = {
    Text = "Nível de iluminação atingiu 11 para desbloquear"
  },
  Voice_5211_AwakerVoiceContent = {
    Text = "Eu vejo sua determinação. Antes de adormecer novamente, serei seu testemunho, testemunhando a desafiança do destino pelo filho do homem. Mas por enquanto, preciso de um descanso."
  },
  Voice_5211_AwakerVoiceTitle = {
    Text = "Iluminar·Florescer"
  },
  Voice_5211_UnlockDesc = {
    Text = "Nível de iluminação atingiu 15 para desbloquear"
  },
  Voice_5212_AwakerVoiceContent = {
    Text = "Não é bom seguir a vontade dos céus? Por que resistir à vontade do destino?"
  },
  Voice_5212_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexão"
  },
  Voice_5212_UnlockDesc = {
    Text = "Nível de iluminação atingiu 3 para desbloquear"
  },
  Voice_5213_AwakerVoiceContent = {
    Text = "Para realizar seu desejo, você está disposto a sacrificar tanto..."
  },
  Voice_5213_AwakerVoiceTitle = {
    Text = "Iluminar: Insight"
  },
  Voice_5213_UnlockDesc = {
    Text = "Nível de iluminação atingiu 7 para desbloquear"
  },
  Voice_5214_AwakerVoiceContent = {
    Text = "Huh? Não é irritante? Pare de me incomodar sobre aquele cara! ... Tudo bem, faça o que quiser. É só para passar o tempo mesmo."
  },
  Voice_5214_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_5215_AwakerVoiceContent = {
    Text = "Dissolução... Esses líquidos negros imundos frequentemente invadem meus sonhos, verdadeiramente insuportáveis."
  },
  Voice_5215_AwakerVoiceTitle = {
    Text = "Bate-papo · Sobre Dissolução"
  },
  Voice_5216_AwakerVoiceContent = {
    Text = "O poder é uma espada de dois gumes. Como eu não poderia entender? É só que percebi isso tarde demais, muito tarde. Uma vez que eu soltar, eles me despedaçarão... Se eu tivesse sido tão lúcido quanto você desde o início, não teria tido um fim tão trágico. Eh, eh? Você diz que no futuro eu posso sediar salões no lounge?! Isso é... Como mais posso retribuí-lo além de servi-lo pessoalmente..."
  },
  Voice_5216_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Cinco"
  },
  Voice_5216_UnlockDesc = {
    Text = "Nível de afinidade atingido 10 desbloqueado"
  },
  Voice_5217_AwakerVoiceContent = {
    Text = "Você é um hóspede bastante inflexível. O que devo fazer para que você renuncie ao privilégio em suas mãos? Poder apenas convida problemas — uma verdade tão simples, com certeza você entende, não entende?"
  },
  Voice_5217_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Quatro"
  },
  Voice_5217_UnlockDesc = {
    Text = "Nível de afinidade atingido 8 desbloqueado"
  },
  Voice_5218_AwakerVoiceContent = {
    Text = "Antes do salão começar, você gostaria de ouvir uma história? Um conto de como uma garota de vila reivindicou a coroa do poder... Por onde devemos começar? Do seus pais forçando-a a se casar com um homem idoso, ou talvez você prefira a parte onde ela floresce no jardim nobre?"
  },
  Voice_5218_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Três"
  },
  Voice_5218_UnlockDesc = {
    Text = "Nível de afinidade atingido 6 desbloqueado"
  },
  Voice_5219_AwakerVoiceContent = {
    Text = "No passado, os convidados me chamavam de \"Dama Vermelha\". Claro, você também pode me chamar de \"Sorel\", afinal, você é meu convidado mais especial..."
  },
  Voice_5219_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Dois"
  },
  Voice_5219_UnlockDesc = {
    Text = "Nível de afinidade atingido 4 desbloqueado"
  },
  Voice_5220_AwakerVoiceContent = {
    Text = "Como a anfitriã do salão, é meu dever garantir que cada convidado esteja satisfeito."
  },
  Voice_5220_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Um"
  },
  Voice_5220_UnlockDesc = {
    Text = "Nível de afinidade atingido 2 desbloqueado"
  },
  Voice_5221_AwakerVoiceContent = {Text = "Ah!"},
  Voice_5221_AwakerVoiceTitle = {
    Text = "Golpe·Quatro"
  },
  Voice_5222_AwakerVoiceContent = {
    Text = "Mestre? Há algo errado com a minha postura?"
  },
  Voice_5222_AwakerVoiceTitle = {
    Text = "Conversa·Toque"
  },
  Voice_5223_AwakerVoiceContent = {Text = "Oops!"},
  Voice_5223_AwakerVoiceTitle = {Text = "Acertar·1"},
  Voice_5224_AwakerVoiceContent = {Text = "Mau sorte~"},
  Voice_5224_AwakerVoiceTitle = {
    Text = "Acertar · II"
  },
  Voice_5225_AwakerVoiceContent = {Text = "Ah!"},
  Voice_5225_AwakerVoiceTitle = {
    Text = "Acertar·III"
  },
  Voice_5226_AwakerVoiceContent = {
    Text = "Eu lembro desse sentimento... O glorioso momento está se aproximando."
  },
  Voice_5226_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_5226_UnlockDesc = {
    Text = "Nível de iluminação atingiu 2 para desbloquear"
  },
  Voice_5227_AwakerVoiceContent = {
    Text = "Embora as marcas branquiais ainda não tenham aparecido, eu não me sinto mais ansioso a respeito. Esta asa membranosa se transformará em um escudo para protegê-lo, Guardião."
  },
  Voice_5227_AwakerVoiceTitle = {
    Text = "Iluminar·Florescer"
  },
  Voice_5227_UnlockDesc = {
    Text = "Nível de iluminação atingiu 15 para desbloquear"
  },
  Voice_5228_AwakerVoiceContent = {
    Text = "Você... é realmente mais paciente do que outros humanos... Você realmente investiu tantos recursos em mim. Você realmente... não me odeia?"
  },
  Voice_5228_AwakerVoiceTitle = {
    Text = "Iluminar·Construção"
  },
  Voice_5228_UnlockDesc = {
    Text = "Nível de iluminação atingiu 11 para desbloquear"
  },
  Voice_5229_AwakerVoiceContent = {
    Text = "Huh? O ritual acabou, mas eu ainda não cresci brânquias? A transformação falhou de novo?! Droga! Droga! Droga!"
  },
  Voice_5229_AwakerVoiceTitle = {
    Text = "Iluminar: Insight"
  },
  Voice_5229_UnlockDesc = {
    Text = "Nível de iluminação atingiu 7 para desbloquear"
  },
  Voice_5230_AwakerVoiceContent = {
    Text = "Aquela voz está me chamando novamente... o som etéreo do profundo Aequor!"
  },
  Voice_5230_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexão"
  },
  Voice_5230_UnlockDesc = {
    Text = "Nível de iluminação atingiu 3 para desbloquear"
  },
  Voice_5231_AwakerVoiceContent = {
    Text = "Adivinhe—errado—novamente—"
  },
  Voice_5231_AwakerVoiceTitle = {
    Text = "Carta de Habilidade·Quatro"
  },
  Voice_5232_AwakerVoiceContent = {
    Text = "Sanga, a escultora de Cité, te oferece seu cinzel. Você pode ser imperfeito, mas ainda vale a pena esculpir."
  },
  Voice_5232_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_5238_AwakerVoiceContent = {
    Text = "Crianças que não escutam, reunam-se~"
  },
  Voice_5238_AwakerVoiceTitle = {
    Text = "Início da Investigação"
  },
  Voice_5239_AwakerVoiceContent = {
    Text = "A verdadeira arte não precisa de explicação."
  },
  Voice_5239_AwakerVoiceTitle = {
    Text = "Exaltar · Dois"
  },
  Voice_5240_AwakerVoiceContent = {
    Text = "A verdadeira arte não precisa de explicação."
  },
  Voice_5240_AwakerVoiceTitle = {
    Text = "Fúria Explosiva"
  },
  Voice_5241_AwakerVoiceContent = {
    Text = "Aurita, você pode ajudar?"
  },
  Voice_5241_AwakerVoiceTitle = {
    Text = "Despertar do Conhecimento Espiritual"
  },
  Voice_5242_AwakerVoiceContent = {
    Text = "Toquem a trompa!"
  },
  Voice_5242_AwakerVoiceTitle = {
    Text = "Habilidade·Um"
  },
  Voice_5243_AwakerVoiceContent = {
    Text = "A qualquer custo!"
  },
  Voice_5243_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_5244_AwakerVoiceContent = {
    Text = "A sensação de estar banhado pela luz do sol... tão suave, que traz lágrimas aos seus olhos."
  },
  Voice_5244_AwakerVoiceTitle = {
    Text = "Iluminar·Construção"
  },
  Voice_5244_UnlockDesc = {
    Text = "Nível de iluminação atingiu 11 para desbloquear"
  },
  Voice_5245_AwakerVoiceContent = {
    Text = "Para expressar minha gratidão... vou construir um altar escondido para você nas profundezas da minha angústia."
  },
  Voice_5245_AwakerVoiceTitle = {
    Text = "Iluminar·Florescer"
  },
  Voice_5245_UnlockDesc = {
    Text = "Nível de iluminação atingiu 15 para desbloquear"
  },
  Voice_5246_AwakerVoiceContent = {
    Text = "O Caro de meu irmão e meu Corpo estão se fundindo de forma mais perfeita e apertada..."
  },
  Voice_5246_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexão"
  },
  Voice_5246_UnlockDesc = {
    Text = "Nível de iluminação atingiu 3 para desbloquear"
  },
  Voice_5247_AwakerVoiceContent = {
    Text = "Sou mais resistente do que você pensa. Então, ao me usar, você pode aplicar mais força. Não se segure."
  },
  Voice_5247_AwakerVoiceTitle = {
    Text = "Iluminar: Insight"
  },
  Voice_5247_UnlockDesc = {
    Text = "Nível de iluminação atingiu 7 para desbloquear"
  },
  Voice_5248_AwakerVoiceContent = {
    Text = "É apenas a minha imaginação? A ânsia por sangue parece ter diminuído um pouco."
  },
  Voice_5248_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_5248_UnlockDesc = {
    Text = "Nível de iluminação atingiu 2 para desbloquear"
  },
  Voice_5249_AwakerVoiceContent = {
    Text = "Até mesmo antes de começarmos oficialmente, eu já estava ansioso pela sua chegada. Parece que estamos trabalhando juntos muito bem, né? Parceiro."
  },
  Voice_5249_AwakerVoiceTitle = {
    Text = "Conversa·Sobre Guardião do Segredo"
  },
  Voice_5250_AwakerVoiceContent = {
    Text = "Isso é vergonhoso."
  },
  Voice_5250_AwakerVoiceTitle = {Text = "Defesa·II"},
  Voice_5251_AwakerVoiceContent = {Text = "Aah!"},
  Voice_5251_AwakerVoiceTitle = {
    Text = "Defesa · I"
  },
  Voice_5252_AwakerVoiceContent = {Text = "Hahaha!"},
  Voice_5252_AwakerVoiceTitle = {
    Text = "Ataque·Mania"
  },
  Voice_5253_AwakerVoiceContent = {Text = "Hmm..."},
  Voice_5253_AwakerVoiceTitle = {
    Text = "Ataque·Depressão"
  },
  Voice_5254_AwakerVoiceContent = {
    Text = "Me machuque o quanto quiser!"
  },
  Voice_5254_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_5255_AwakerVoiceContent = {
    Text = "Aigis está realmente assustada. Não, não de todos vocês, mas de si mesma trazer medo e tristeza para você novamente."
  },
  Voice_5255_AwakerVoiceTitle = {
    Text = "Chat·Sobre a Universidade Mythag"
  },
  Voice_5256_AwakerVoiceContent = {
    Text = "Os livros de contos de fadas desta era são muito mais interessantes do que os que eu lia naquela época! Ah, ah! Meu senhor, por favor, não me interprete mal! Já passei da idade para contos de ninar!"
  },
  Voice_5256_AwakerVoiceTitle = {
    Text = "Conversa·Coisas favoritas"
  },
  Voice_5257_AwakerVoiceContent = {
    Text = "Me machuque o quanto quiser!"
  },
  Voice_5257_AwakerVoiceTitle = {
    Text = "Carta de Habilidade·Quatro"
  },
  Voice_5258_AwakerVoiceContent = {
    Text = "Ufa... A Aigis deu algum trabalho a todos?"
  },
  Voice_5258_AwakerVoiceTitle = {
    Text = "Investigação Bem-sucedida"
  },
  Voice_5259_AwakerVoiceContent = {
    Text = "Você sempre se agarrou a essa divertida confiança e ficou ao meu lado... Tudo bem, talvez não seja uma má ideia colocá-lo para trabalhar. Mas lembre-se disto: não posso tolerar nenhuma traição, especialmente a partir de você."
  },
  Voice_5259_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Cinco"
  },
  Voice_5259_UnlockDesc = {
    Text = "Nível de afinidade atingido 10 desbloqueado"
  },
  Voice_5260_AwakerVoiceContent = {
    Text = "Eu só lamento não ter empalado seus cadáveres em estacas e pendurado nas paredes! Não pouperei nenhum que me traiu, pisoteou ou insultou!"
  },
  Voice_5260_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Quatro"
  },
  Voice_5260_UnlockDesc = {
    Text = "Nível de afinidade atingido 8 desbloqueado"
  },
  Voice_5261_AwakerVoiceContent = {
    Text = "Sim, eu me rebaixei diante daquelas pessoas; não posso negar. Eles aproveitaram minha ignorância, e eu fiz eles pagarem por isso."
  },
  Voice_5261_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Três"
  },
  Voice_5261_UnlockDesc = {
    Text = "Nível de afinidade atingido 6 desbloqueado"
  },
  Voice_5262_AwakerVoiceContent = {
    Text = "Você acha que algumas palavras doces e alguns dias de falsa bondade vão me fazer colocar as correntes novamente e me tornar seu brinquedo?"
  },
  Voice_5262_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Dois"
  },
  Voice_5262_UnlockDesc = {
    Text = "Nível de afinidade atingido 4 desbloqueado"
  },
  Voice_5263_AwakerVoiceContent = {
    Text = "Todos que tentaram me controlar ou usar acabaram no submundo pelas minhas próprias mãos — não me importo em enviar você para lá também."
  },
  Voice_5263_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Um"
  },
  Voice_5263_UnlockDesc = {
    Text = "Nível de afinidade atingido 2 desbloqueado"
  },
  Voice_5264_AwakerVoiceContent = {
    Text = "Ah... Desculpe, por favor não se mova!"
  },
  Voice_5264_AwakerVoiceTitle = {
    Text = "Exaltar · Dois"
  },
  Voice_5265_AwakerVoiceContent = {
    Text = "Não me toque!"
  },
  Voice_5265_AwakerVoiceTitle = {
    Text = "Defesa · I"
  },
  Voice_5266_AwakerVoiceContent = {
    Text = "Desrespeito!"
  },
  Voice_5266_AwakerVoiceTitle = {Text = "Defesa·II"},
  Voice_5267_AwakerVoiceContent = {
    Text = "Renda-se... Bem-vindo ao reino do prazer e dos sonhos."
  },
  Voice_5267_AwakerVoiceTitle = {
    Text = "Fúria Explosiva"
  },
  Voice_5268_AwakerVoiceContent = {
    Text = "Esta é a cidade onde inúmeras almas perdidas vagam, incapazes de encontrar o caminho de casa."
  },
  Voice_5268_AwakerVoiceTitle = {
    Text = "Exaltar · Dois"
  },
  Voice_5269_AwakerVoiceContent = {
    Text = "Aigis fará o seu melhor!"
  },
  Voice_5269_AwakerVoiceTitle = {
    Text = "Início da Investigação"
  },
  Voice_5270_AwakerVoiceContent = {
    Text = "Umm... eu não consigo controlar minha habilidade de absorver força vital, então por favor, não coloque sua mão no berço, ou você ficará doente."
  },
  Voice_5270_AwakerVoiceTitle = {
    Text = "Conversa·Toque"
  },
  Voice_5271_AwakerVoiceContent = {
    Text = "Espero que ela não apresente falhas durante nossa conversa. Minha adorável, mas irritante assistente, não há mais laboratórios sobressalentes para ela explodir."
  },
  Voice_5271_AwakerVoiceTitle = {
    Text = "Conversas Ociosas·Sobre Erica"
  },
  Voice_5271_UnlockDesc = {
    Text = "Desbloqueado após adquirir o Despertar \"Erica\""
  },
  Voice_5272_AwakerVoiceContent = {
    Text = "Braços, esses braços incômodos! Eles sempre agarram meu cabelo. Não consigo nem controlar minhas próprias mãos—que cara inútil eu sou... Talvez eu deva..."
  },
  Voice_5272_AwakerVoiceTitle = {
    Text = "Papo reto · Sobre Mim"
  },
  Voice_5274_AwakerVoiceContent = {
    Text = "Obrigado pela sua orientação. Finalmente entendo a escolha de Desmaio. Eu tomei tudo como garantido, sem perceber o peso mental que isso impôs a ela. A partir de agora, tentarei viver para mim mesmo..."
  },
  Voice_5274_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Quatro"
  },
  Voice_5274_UnlockDesc = {
    Text = "Nível de afinidade atingido 8 desbloqueado"
  },
  Voice_5275_AwakerVoiceContent = {
    Text = "Através dos longos e intermináveis tempos, Desmaio e eu só tivemos um ao outro... Mas agora, eu tenho novas pessoas importantes... Guardião, por favor, permita-me retratar minhas palavras anteriores. Você é diferente. Você não se importa apenas com a minha voz cantando ou meu vestido formal; você realmente me vê. Portanto, eu também vou cuidar de você."
  },
  Voice_5275_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Cinco"
  },
  Voice_5275_UnlockDesc = {
    Text = "Nível de afinidade atingido 10 desbloqueado"
  },
  Voice_5276_AwakerVoiceContent = {
    Text = "As estrelas no sonho, indo para onde deveriam, apontam para o reino de Deus!"
  },
  Voice_5276_AwakerVoiceTitle = {
    Text = "Exaltar · Dois"
  },
  Voice_5277_AwakerVoiceContent = {
    Text = "Por que estou sempre vestida com este vestido? Para que eu possa cantar para você a qualquer momento."
  },
  Voice_5277_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Um"
  },
  Voice_5277_UnlockDesc = {
    Text = "Nível de afinidade atingido 2 desbloqueado"
  },
  Voice_5278_AwakerVoiceContent = {
    Text = "O que eu quero fazer? ......Desculpe, não entendo o que você quer dizer......Na verdade, Faint já me fez essa pergunta muitas vezes, mas tudo o que eu quero é que ela se recupere logo......"
  },
  Voice_5278_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Dois"
  },
  Voice_5278_UnlockDesc = {
    Text = "Nível de afinidade atingido 4 desbloqueado"
  },
  Voice_5279_AwakerVoiceContent = {
    Text = "Durante nosso tempo no planeta desolado, a compaixão dessas figuras influentes proporcionou a mim e minha irmã os recursos para sobreviver. No final, eles também me deram a chance de escapar do planeta, embora fosse limitado a uma pessoa. Eles são todos meus benfeitores, assim como você, Guardião, que me deu um lugar para ficar."
  },
  Voice_5279_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Três"
  },
  Voice_5279_UnlockDesc = {
    Text = "Nível de afinidade atingido 6 desbloqueado"
  },
  Voice_5280_AwakerVoiceContent = {
    Text = "Você é a pessoa gentil que me fornece um lugar para ficar. Aigis ouvirá você. Se ao menos Aigis pudesse ser um pouco mais útil..."
  },
  Voice_5280_AwakerVoiceTitle = {
    Text = "Conversa·Sobre Guardião do Segredo"
  },
  Voice_5281_AwakerVoiceContent = {
    Text = "Não esqueça de preparar o local. O que você reservou não é menor do que o de Elworth, certo?"
  },
  Voice_5281_AwakerVoiceTitle = {
    Text = "Iluminar·Visão Remota"
  },
  Voice_5281_UnlockDesc = {
    Text = "Nível de iluminação atingiu 1 para desbloquear"
  },
  Voice_5282_AwakerVoiceContent = {
    Text = "Bom, Karen agora está mais motivada e pode limpar vinte quartos por dia!"
  },
  Voice_5282_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_5282_UnlockDesc = {
    Text = "Nível de iluminação atingiu 2 para desbloquear"
  },
  Voice_5283_AwakerVoiceContent = {
    Text = "Esta é a música que é tão antiga quanto as águas do lago, pertencente a \"nós\". Mestre, vamos dançar juntos! Antes que a voz de Karen seja tirada por \"Ele\"..."
  },
  Voice_5283_AwakerVoiceTitle = {
    Text = "Iluminar·Construção"
  },
  Voice_5283_UnlockDesc = {
    Text = "Nível de iluminação atingiu 11 para desbloquear"
  },
  Voice_5284_AwakerVoiceContent = {
    Text = "Mestre! A voz da Karen... desaparecendo... Ajude..."
  },
  Voice_5284_AwakerVoiceTitle = {
    Text = "Iluminar·Florescer"
  },
  Voice_5284_UnlockDesc = {
    Text = "Nível de iluminação atingiu 15 para desbloquear"
  },
  Voice_5285_AwakerVoiceContent = {
    Text = "A visão de Karen melhorou... Mestre, você esqueceu de pentear o cabelo novamente!"
  },
  Voice_5285_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexão"
  },
  Voice_5285_UnlockDesc = {
    Text = "Nível de iluminação atingiu 3 para desbloquear"
  },
  Voice_5286_AwakerVoiceContent = {
    Text = "Mesmo que ela fique mais forte, Karen não quer vingança alguma. Karen só quer cantar! Dançar! Festear!"
  },
  Voice_5286_AwakerVoiceTitle = {
    Text = "Iluminar: Insight"
  },
  Voice_5286_UnlockDesc = {
    Text = "Nível de iluminação atingiu 7 para desbloquear"
  },
  Voice_5287_AwakerVoiceContent = {
    Text = "Para sobreviver após a destruição total, compartilhei meu espírito e sangue com muitas pessoas. Meu poder atual está longe do que era quando aceitei esta vontade pela primeira vez."
  },
  Voice_5287_AwakerVoiceTitle = {
    Text = "Conversas Ociosas·Sobre o Passado"
  },
  Voice_5288_AwakerVoiceContent = {
    Text = "Não espere me encontrar no prédio de ensino. Ele está cheio do fedor de acadêmicos mofados; não consigo suportar estar lá por nem um dia."
  },
  Voice_5288_AwakerVoiceTitle = {
    Text = "Chat·Sobre a Universidade Mythag"
  },
  Voice_5289_AwakerVoiceContent = {
    Text = "Não corra."
  },
  Voice_5289_AwakerVoiceTitle = {Text = "Ataque·II"},
  Voice_5290_AwakerVoiceContent = {
    Text = "Minha terra natal adora os \"Deuses\", e, consequentemente, o rei que sigo é naturalmente um \"comunicador divino\"."
  },
  Voice_5290_AwakerVoiceTitle = {
    Text = "Conversas Ociosas: Sobre o Reino Eterno"
  },
  Voice_5291_AwakerVoiceContent = {
    Text = "Você tem uma reunião bastante talentosa aqui, digna de um grande salão... Pode ficar tranquilo, o convite será entregue a você pelo meu servo."
  },
  Voice_5291_AwakerVoiceTitle = {
    Text = "Chat·Sobre a Universidade Mythag"
  },
  Voice_5292_AwakerVoiceContent = {Text = "Vamos lá!"},
  Voice_5292_AwakerVoiceTitle = {Text = "Ataque·Um"},
  Voice_5293_AwakerVoiceContent = {
    Text = "Se houvesse mais companheiros..."
  },
  Voice_5293_AwakerVoiceTitle = {
    Text = "Investigação Interrompida"
  },
  Voice_5294_AwakerVoiceContent = {
    Text = "Não sou como ela. Ela oferece apenas arrepios hostis e medo, enquanto eu te dou uma dor íntima, doce, ardente e amor."
  },
  Voice_5294_AwakerVoiceTitle = {
    Text = "Conversa Informal·Sobre Wanda"
  },
  Voice_5294_UnlockDesc = {
    Text = "Desbloqueado após obter o Despertador \"Wanda\""
  },
  Voice_5295_AwakerVoiceContent = {
    Text = "Não pense que isso acabou! Eu vou fazer você pagar por cada grama dessa humilhação!"
  },
  Voice_5295_AwakerVoiceTitle = {
    Text = "Investigação Interrompida"
  },
  Voice_5296_AwakerVoiceContent = {
    Text = "Suas mãos, assim como sua alma, estão quentes. O fogo pálido... Aprecio seu toque."
  },
  Voice_5296_AwakerVoiceTitle = {
    Text = "Conversa·Toque"
  },
  Voice_5297_AwakerVoiceContent = {
    Text = "Qual é o problema em jogar truco na sala de aula? Tem uma mesa, pessoas, e eu trouxe as cartas. Isso significa \"Jogo Abertos\"!"
  },
  Voice_5297_AwakerVoiceTitle = {
    Text = "Chat·Sobre a Universidade Mythag"
  },
  Voice_5299_AwakerVoiceContent = {Text = "Não..."},
  Voice_5299_AwakerVoiceTitle = {
    Text = "Acertar · II"
  },
  Voice_5300_AwakerVoiceContent = {
    Text = "Olhe para o Abismo!"
  },
  Voice_5300_AwakerVoiceTitle = {
    Text = "Fúria Explosiva"
  },
  Voice_5301_AwakerVoiceContent = {
    Text = "Olhe para o Abismo!"
  },
  Voice_5301_AwakerVoiceTitle = {
    Text = "Exaltar · Dois"
  },
  Voice_5302_AwakerVoiceContent = {Text = "(Gemido)"},
  Voice_5302_AwakerVoiceTitle = {
    Text = "Acertar·III"
  },
  Voice_5303_AwakerVoiceContent = {Text = "(Gemido)"},
  Voice_5303_AwakerVoiceTitle = {
    Text = "Acertar · II"
  },
  Voice_5304_AwakerVoiceContent = {Text = "(Gemido)"},
  Voice_5304_AwakerVoiceTitle = {Text = "Acertar·1"},
  Voice_5305_AwakerVoiceContent = {Text = "(Gemido)"},
  Voice_5305_AwakerVoiceTitle = {
    Text = "Golpe·Quatro"
  },
  Voice_5306_AwakerVoiceContent = {
    Text = "Banha-se na luz divina!"
  },
  Voice_5306_AwakerVoiceTitle = {
    Text = "Defesa · I"
  },
  Voice_5307_AwakerVoiceContent = {Text = "Oi!"},
  Voice_5307_AwakerVoiceTitle = {Text = "Defesa·II"},
  Voice_5308_AwakerVoiceContent = {
    Text = "As almas fracas se reúnem, mas de que adianta seu barulho? Suspiro..."
  },
  Voice_5308_AwakerVoiceTitle = {
    Text = "Investigação Interrompida"
  },
  Voice_5311_AwakerVoiceContent = {
    Text = "A guerra sempre traz dor, e suportar o sofrimento é um dever do guerreiro. Mesmo que eu perca minhas mãos, meus pés e tudo o mais, ainda lutarei por você e pela justiça do mundo."
  },
  Voice_5311_AwakerVoiceTitle = {
    Text = "Bate-papo · Sobre Dissolução"
  },
  Voice_5312_AwakerVoiceContent = {
    Text = "É essa a homenagem que você oferece a Ele?"
  },
  Voice_5312_AwakerVoiceTitle = {
    Text = "Atualizar·II"
  },
  Voice_5313_AwakerVoiceContent = {
    Text = "Você acha que isso pode mudar o futuro?"
  },
  Voice_5313_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · Três"
  },
  Voice_5314_AwakerVoiceContent = {
    Text = "Sua gestação... dentro do meu útero..."
  },
  Voice_5314_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · I"
  },
  Voice_5315_AwakerVoiceContent = {
    Text = "Heh, você é mais inteligente do que eu pensei."
  },
  Voice_5315_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · I"
  },
  Voice_5316_AwakerVoiceContent = {
    Text = "Prestar homenagem ao mestre é algo natural."
  },
  Voice_5316_AwakerVoiceTitle = {
    Text = "Atualizar·II"
  },
  Voice_5317_AwakerVoiceContent = {
    Text = "Você parece bem fofo quando tenta me agradar."
  },
  Voice_5317_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · Três"
  },
  Voice_5318_AwakerVoiceContent = {
    Text = "Brownie, pudim de caramelo, Sachertorte, mousse de chocolate, biscoitos... Cada mesa deve ter isso!"
  },
  Voice_5318_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_5318_UnlockDesc = {
    Text = "Nível de iluminação atingiu 2 para desbloquear"
  },
  Voice_5319_AwakerVoiceContent = {
    Text = "Verifique minha saia para mim, pode ser? Sem rugas, sem folgas... O que há de errado? Você está insatisfeito?"
  },
  Voice_5319_AwakerVoiceTitle = {
    Text = "Iluminar·Construção"
  },
  Voice_5319_UnlockDesc = {
    Text = "Nível de iluminação atingiu 11 para desbloquear"
  },
  Voice_5320_AwakerVoiceContent = {
    Text = "Bem-vindo à minha última cerimônia de Iluminação! Tudo isso foi meticulosamente projetado por mim. Claro, o Guardião contribuiu apenas um pouco..."
  },
  Voice_5320_AwakerVoiceTitle = {
    Text = "Iluminar·Florescer"
  },
  Voice_5320_UnlockDesc = {
    Text = "Nível de iluminação atingiu 15 para desbloquear"
  },
  Voice_5321_AwakerVoiceContent = {
    Text = "As mesas e cadeiras devem ser adornadas com rendas que combinem com meu temperamento, e as plantas em vasos devem apresentar plantas-aranha vermelhas... Acelere-se e prepare-se!"
  },
  Voice_5321_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexão"
  },
  Voice_5321_UnlockDesc = {
    Text = "Nível de iluminação atingiu 3 para desbloquear"
  },
  Voice_5322_AwakerVoiceContent = {
    Text = "Vá e faça a reserva para o convidado! Como você poderia estragar uma tarefa tão simples?"
  },
  Voice_5322_AwakerVoiceTitle = {
    Text = "Iluminar: Insight"
  },
  Voice_5322_UnlockDesc = {
    Text = "Nível de iluminação atingiu 7 para desbloquear"
  },
  Voice_5323_AwakerVoiceContent = {
    Text = "Sem escapar!"
  },
  Voice_5323_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_5324_AwakerVoiceContent = {
    Text = "Sem escapar!"
  },
  Voice_5324_AwakerVoiceTitle = {
    Text = "Carta de Habilidade·Quatro"
  },
  Voice_5325_AwakerVoiceContent = {
    Text = "Farei o meu melhor! Para corresponder às expectativas do meu senhor."
  },
  Voice_5325_AwakerVoiceTitle = {
    Text = "Iluminar·Visão Remota"
  },
  Voice_5325_UnlockDesc = {
    Text = "Nível de iluminação atingiu 1 para desbloquear"
  },
  Voice_5326_AwakerVoiceContent = {
    Text = "Eu gosto bastante daquela mulher. Temos aquele... aquele... certo, uma língua comum!"
  },
  Voice_5326_AwakerVoiceTitle = {
    Text = "Conversa Informal·Sobre Wanda"
  },
  Voice_5326_UnlockDesc = {
    Text = "Desbloqueado após obter o Despertador \"Wanda\""
  },
  Voice_5327_AwakerVoiceContent = {
    Text = "Você insolente tolo!"
  },
  Voice_5327_AwakerVoiceTitle = {
    Text = "Habilidade·Um"
  },
  Voice_5328_AwakerVoiceContent = {
    Text = "Você insolente tolo!"
  },
  Voice_5328_AwakerVoiceTitle = {
    Text = "Carta de Habilidade·Quatro"
  },
  Voice_5329_AwakerVoiceContent = {
    Text = "Transformado em destroços."
  },
  Voice_5329_AwakerVoiceTitle = {Text = "Ataque·II"},
  Voice_5330_AwakerVoiceContent = {
    Text = "Desintegrar."
  },
  Voice_5330_AwakerVoiceTitle = {Text = "Ataque·Um"},
  Voice_5331_AwakerVoiceContent = {
    Text = "Rompe as barreiras da realidade!"
  },
  Voice_5331_AwakerVoiceTitle = {
    Text = "Despertar do Conhecimento Espiritual"
  },
  Voice_5332_AwakerVoiceContent = {
    Text = "Você está planejando zarpar em breve? Poderia conceder meu humilde pedido e me deixar ir com você? Apenas me deixe chegar ao mar..."
  },
  Voice_5332_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Dois"
  },
  Voice_5332_UnlockDesc = {
    Text = "Nível de afinidade atingido 4 desbloqueado"
  },
  Voice_5333_AwakerVoiceContent = {
    Text = "Se você ainda confia em mim, por favor, me permita ser a luz guia nesta jornada. No entanto, mesmo em uma tarefa tão simples, eu já falhei antes..."
  },
  Voice_5333_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Três"
  },
  Voice_5333_UnlockDesc = {
    Text = "Nível de afinidade atingido 6 desbloqueado"
  },
  Voice_5334_AwakerVoiceContent = {
    Text = "Não sente vontade de sair para o mar? Deixe-me verificar o mapa atual... 47°9' S, 126°43' W, bem aqui."
  },
  Voice_5334_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Um"
  },
  Voice_5334_UnlockDesc = {
    Text = "Nível de afinidade atingido 2 desbloqueado"
  },
  Voice_5335_AwakerVoiceContent = {
    Text = "Causuei muitas desastres no passado, quase trazendo destruição a certas civilizações... Se eu disser que não foi intencional, já é tarde demais?"
  },
  Voice_5335_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Quatro"
  },
  Voice_5335_UnlockDesc = {
    Text = "Nível de afinidade atingido 8 desbloqueado"
  },
  Voice_5336_AwakerVoiceContent = {
    Text = "Eu sou o guardião da entrada para o Reino Eterno, guiando aqueles que voltam para casa. Que irônico que alguém com tal dever tenha esquecido o caminho de casa...\nVocê será... meu farol?"
  },
  Voice_5336_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Cinco"
  },
  Voice_5336_UnlockDesc = {
    Text = "Nível de afinidade atingido 10 desbloqueado"
  },
  Voice_5337_AwakerVoiceContent = {
    Text = "Agregados de estrelas."
  },
  Voice_5337_AwakerVoiceTitle = {Text = "Defesa·II"},
  Voice_5338_AwakerVoiceContent = {Text = "Ah!"},
  Voice_5338_AwakerVoiceTitle = {
    Text = "Golpe·Quatro"
  },
  Voice_5339_AwakerVoiceContent = {
    Text = "Neblina densa."
  },
  Voice_5339_AwakerVoiceTitle = {
    Text = "Defesa · I"
  },
  Voice_5340_AwakerVoiceContent = {Text = "Hmph."},
  Voice_5340_AwakerVoiceTitle = {Text = "Acertar·1"},
  Voice_5341_AwakerVoiceContent = {
    Text = "Para a maioria das pessoas, ser um acompanhante de guardião não faz diferença, mas aquela mulher é uma exceção. Se possível, por favor, arranje outra rota para mim."
  },
  Voice_5341_AwakerVoiceTitle = {
    Text = "Chat·Sobre Miryam"
  },
  Voice_5341_UnlockDesc = {
    Text = "Após obter o despertador \"Miryam\", desbloqueado"
  },
  Voice_5342_AwakerVoiceContent = {Text = "Ah!"},
  Voice_5342_AwakerVoiceTitle = {
    Text = "Acertar·III"
  },
  Voice_5343_AwakerVoiceContent = {
    Text = "Não importa."
  },
  Voice_5343_AwakerVoiceTitle = {
    Text = "Acertar · II"
  },
  Voice_5344_AwakerVoiceContent = {
    Text = "Tire suas mãos."
  },
  Voice_5344_AwakerVoiceTitle = {
    Text = "Conversa·Toque"
  },
  Voice_5345_AwakerVoiceContent = {
    Text = "Antes de eu voltar ao Palácio Aequor, emprestarei a você, um humilde humano, um pouco do poder de Aequor, mas apenas esta vez."
  },
  Voice_5345_AwakerVoiceTitle = {
    Text = "Conversa·Sobre Guardião do Segredo"
  },
  Voice_5346_AwakerVoiceContent = {Text = "Vai!"},
  Voice_5346_AwakerVoiceTitle = {
    Text = "Despertar do Conhecimento Espiritual"
  },
  Voice_5347_AwakerVoiceContent = {
    Text = "Gosta disso? Eu gosto da dor— a sensação da pele inchada e ardente, os gemidos misturando prazer e sofrimento. A dor é o desejo mais primitivo e genuíno, não é?"
  },
  Voice_5347_AwakerVoiceTitle = {
    Text = "Conversa·Coisas favoritas"
  },
  Voice_5348_AwakerVoiceContent = {
    Text = "Junte-se à Aurita!"
  },
  Voice_5348_AwakerVoiceTitle = {
    Text = "Carta de Habilidade·Quatro"
  },
  Voice_5349_AwakerVoiceContent = {
    Text = "Junte-se à Aurita!"
  },
  Voice_5349_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_5350_AwakerVoiceContent = {
    Text = "Aquela irmã mais velha sempre me lança olhares intensos. Mas, por algum motivo, sinto uma sensação de familiaridade. Será porque ela me lembra minha mãe?"
  },
  Voice_5350_AwakerVoiceTitle = {
    Text = "Conversa Ociosa · Sobre Hilota"
  },
  Voice_5350_UnlockDesc = {
    Text = "Após obter o despertador \"hilota\", desbloqueado"
  },
  Voice_5351_AwakerVoiceContent = {
    Text = "Minha mente parece mais afiada, não está ruim."
  },
  Voice_5351_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_5351_UnlockDesc = {
    Text = "Nível de iluminação atingiu 2 para desbloquear"
  },
  Voice_5352_AwakerVoiceContent = {
    Text = "Prefiro trabalho de laboratório a dever de campo—você achou que aquelas ferramentas de assistência foram pescadas do mar?"
  },
  Voice_5352_AwakerVoiceTitle = {
    Text = "Iluminar: Insight"
  },
  Voice_5352_UnlockDesc = {
    Text = "Nível de iluminação atingiu 7 para desbloquear"
  },
  Voice_5353_AwakerVoiceContent = {
    Text = "Sejam parafusos ou pregos, quanto mais, melhor!"
  },
  Voice_5353_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · Três"
  },
  Voice_5354_AwakerVoiceContent = {
    Text = "O corpo mal consegue lidar com este Poder, mas ainda não é hora de trocar de marionete. Por que você está parado aí? Ajude-me a segurar esta perna; preciso fazer alguns ajustes."
  },
  Voice_5354_AwakerVoiceTitle = {
    Text = "Iluminar·Florescer"
  },
  Voice_5354_UnlockDesc = {
    Text = "Nível de iluminação atingiu 15 para desbloquear"
  },
  Voice_5355_AwakerVoiceContent = {
    Text = "O fardo da luz guia pode sobrecarregar até os santos mais puros. Se você se sentir cansado, minha chama pálida, por favor, não hesite em me confiar. Farei tudo ao meu alcance para aliviar seu fardo e compartilhar o peso dessas inúmeras bênçãos."
  },
  Voice_5355_AwakerVoiceTitle = {
    Text = "Conversa Ociosa · Sobre Fadiga"
  },
  Voice_5356_AwakerVoiceContent = {
    Text = "Sua aprovação é a razão da minha existência como cavaleiro."
  },
  Voice_5356_AwakerVoiceTitle = {
    Text = "Iluminar·Florescer"
  },
  Voice_5356_UnlockDesc = {
    Text = "Nível de iluminação atingiu 15 para desbloquear"
  },
  Voice_5357_AwakerVoiceContent = {
    Text = "Banho no brilho dos deuses, é este o poder divino do meu Senhor? Tão vasto, tão sagrado"
  },
  Voice_5357_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_5357_UnlockDesc = {
    Text = "Nível de iluminação atingiu 2 para desbloquear"
  },
  Voice_5358_AwakerVoiceContent = {
    Text = "A porta para o divino está ao seu alcance."
  },
  Voice_5358_AwakerVoiceTitle = {
    Text = "Iluminar: Insight"
  },
  Voice_5358_UnlockDesc = {
    Text = "Nível de iluminação atingiu 7 para desbloquear"
  },
  Voice_5359_AwakerVoiceContent = {
    Text = "Mais brilhante e mais claro..."
  },
  Voice_5359_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexão"
  },
  Voice_5359_UnlockDesc = {
    Text = "Nível de iluminação atingiu 3 para desbloquear"
  },
  Voice_5360_AwakerVoiceContent = {
    Text = "Para recuperar minha forma humana completa como Despertador... Já ouvi a melodia sagrada tocada para mim pelo Reino Divino..."
  },
  Voice_5360_AwakerVoiceTitle = {
    Text = "Iluminar·Florescer"
  },
  Voice_5360_UnlockDesc = {
    Text = "Nível de iluminação atingiu 15 para desbloquear"
  },
  Voice_5361_AwakerVoiceContent = {
    Text = "Me receberá na Igreja, concedendo-me um descanso pacífico..."
  },
  Voice_5361_AwakerVoiceTitle = {
    Text = "Iluminar·Construção"
  },
  Voice_5361_UnlockDesc = {
    Text = "Nível de iluminação atingiu 11 para desbloquear"
  },
  Voice_5362_AwakerVoiceContent = {
    Text = "Não se preocupe, todos nós somos bastante úteis. Eu posso costurar e limpar, uma outra parte de mim se destaca em combate, e os outros..."
  },
  Voice_5362_AwakerVoiceTitle = {
    Text = "Conversa·Sobre Guardião do Segredo"
  },
  Voice_5363_AwakerVoiceContent = {
    Text = "Eu odeio coisas brilhantes e suaves. A gentileza é como um espelho, revelando toda a feiura, ganância e fragilidade."
  },
  Voice_5363_AwakerVoiceTitle = {
    Text = "Conversa·Coisas odiadas"
  },
  Voice_5364_AwakerVoiceContent = {
    Text = "Quer acariciar a Brown? Não posso tomar essa decisão por você. Você precisa perguntar a ela mesmo."
  },
  Voice_5364_AwakerVoiceTitle = {
    Text = "Conversa·Toque"
  },
  Voice_5365_AwakerVoiceContent = {
    Text = "Quer me agradar? Então ajoelhe-se, ofereça seu pescoço e permaneça em silêncio até eu terminar de esvaziá-lo."
  },
  Voice_5365_AwakerVoiceTitle = {
    Text = "Conversa·Sobre Guardião do Segredo"
  },
  Voice_5366_AwakerVoiceContent = {Text = "Hah!"},
  Voice_5366_AwakerVoiceTitle = {Text = "Ataque·Um"},
  Voice_5367_AwakerVoiceContent = {
    Text = "Tive um sonho na noite passada; ele marcou o início da minha jornada através das estrelas."
  },
  Voice_5367_AwakerVoiceTitle = {
    Text = "Iluminar·Visão Remota"
  },
  Voice_5367_UnlockDesc = {
    Text = "Nível de iluminação atingiu 1 para desbloquear"
  },
  Voice_5368_AwakerVoiceContent = {
    Text = "A Aigis pode ajudar?"
  },
  Voice_5368_AwakerVoiceTitle = {
    Text = "Iluminar·Visão Remota"
  },
  Voice_5368_UnlockDesc = {
    Text = "Nível de iluminação atingiu 1 para desbloquear"
  },
  Voice_5369_AwakerVoiceContent = {
    Text = "Posso sentir~"
  },
  Voice_5369_AwakerVoiceTitle = {
    Text = "Acertar · II"
  },
  Voice_5370_AwakerVoiceContent = {Text = "Toque!"},
  Voice_5370_AwakerVoiceTitle = {
    Text = "Carta de Habilidade·Três"
  },
  Voice_5371_AwakerVoiceContent = {Text = "Cuidado!"},
  Voice_5371_AwakerVoiceTitle = {
    Text = "Defesa · I"
  },
  Voice_5372_AwakerVoiceContent = {Text = "Afaste-se."},
  Voice_5372_AwakerVoiceTitle = {Text = "Defesa·II"},
  Voice_5373_AwakerVoiceContent = {
    Text = "Ninguém será ferido... neste... mundo..."
  },
  Voice_5373_AwakerVoiceTitle = {
    Text = "Fúria Explosiva"
  },
  Voice_5374_AwakerVoiceContent = {
    Text = "(coqueteiramente)"
  },
  Voice_5374_AwakerVoiceTitle = {Text = "Acertar·1"},
  Voice_5375_AwakerVoiceContent = {
    Text = "Por favor, permita-me colocar um altar para meu Senhor. É uma estátua esculpida por seguidores devotos e não trará maldições sobre você."
  },
  Voice_5375_AwakerVoiceTitle = {
    Text = "Conversa·Coisas favoritas"
  },
  Voice_5376_AwakerVoiceContent = {
    Text = "Apenas um pouquinho..."
  },
  Voice_5376_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_5377_AwakerVoiceContent = {
    Text = "Minha chave inglesa ainda não está na posição!"
  },
  Voice_5377_AwakerVoiceTitle = {
    Text = "Início da Investigação"
  },
  Voice_5378_AwakerVoiceContent = {
    Text = "Química, física, aplicações de Prata... Nesta era, não é mais necessário aprender as Sete Habilidades Cavaleirescas? Eu entendo. Nesse caso, por favor, organize os cursos correspondentes para mim, meu senhor!"
  },
  Voice_5378_AwakerVoiceTitle = {
    Text = "Chat·Sobre a Universidade Mythag"
  },
  Voice_5379_AwakerVoiceContent = {
    Text = "Aurita viajou! Não levada pelas ondas, mas viajando com uma caravana!"
  },
  Voice_5379_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Um"
  },
  Voice_5379_UnlockDesc = {
    Text = "Nível de afinidade atingido 2 desbloqueado"
  },
  Voice_5380_AwakerVoiceContent = {
    Text = "Água-viva do farol, água-viva coroa, água-viva de flor de pêssego—todas se movem em grupos. Claro que Aurita também! Aurita quer estar com todos!"
  },
  Voice_5380_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Dois"
  },
  Voice_5380_UnlockDesc = {
    Text = "Nível de afinidade atingido 4 desbloqueado"
  },
  Voice_5381_AwakerVoiceContent = {
    Text = "Eventos passados? Difícil de recordar... Mas Aurita lembra-se de ter trabalhado em um aquário! O salário diário era de 2 Pensh!"
  },
  Voice_5381_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Três"
  },
  Voice_5381_UnlockDesc = {
    Text = "Nível de afinidade atingido 6 desbloqueado"
  },
  Voice_5382_AwakerVoiceContent = {
    Text = "Deixe-me contar um segredo: Aurita é na verdade uma Aram, Trans... hum, basicamente, Aurita é uma pessoa do mar! Se Aurita se comportar, comer legumes e fazer amigos, Atlanta a receberá!"
  },
  Voice_5382_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Quatro"
  },
  Voice_5382_UnlockDesc = {
    Text = "Nível de afinidade atingido 8 desbloqueado"
  },
  Voice_5383_AwakerVoiceContent = {
    Text = "A casa de Aurita, os amigos aquários, sua medusa favorita—todos se foram... Você também vai desaparecer? Não pode ficar com Aurita para sempre?"
  },
  Voice_5383_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Cinco"
  },
  Voice_5383_UnlockDesc = {
    Text = "Nível de afinidade atingido 10 desbloqueado"
  },
  Voice_5384_AwakerVoiceContent = {
    Text = "Nós ganhamos? Isso é maravilhoso..."
  },
  Voice_5384_AwakerVoiceTitle = {
    Text = "Investigação Bem-sucedida"
  },
  Voice_5387_AwakerVoiceContent = {Text = "Por paz."},
  Voice_5387_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_5388_AwakerVoiceContent = {
    Text = "Por justiça."
  },
  Voice_5388_AwakerVoiceTitle = {
    Text = "Carta de Habilidade·Quatro"
  },
  Voice_5389_AwakerVoiceContent = {
    Text = "Eu sei que você está dentro de mim!"
  },
  Voice_5389_AwakerVoiceTitle = {
    Text = "Fúria Explosiva"
  },
  Voice_5390_AwakerVoiceContent = {
    Text = "Humanos, falsos deuses, Despertadores e até mesmo Dissolução... Todos servirão como a fundação da minha terra eterna."
  },
  Voice_5390_AwakerVoiceTitle = {
    Text = "Bate-papo · Sobre Dissolução"
  },
  Voice_5391_AwakerVoiceContent = {
    Text = "Despertar, despertar! Eu sei que você está dentro de mim!"
  },
  Voice_5391_AwakerVoiceTitle = {
    Text = "Exaltar · Dois"
  },
  Voice_5392_AwakerVoiceContent = {
    Text = "Uvhash... Ele me lembra meu irmão, trazendo de volta memórias de dias escuros, frios e sem sono."
  },
  Voice_5392_AwakerVoiceTitle = {
    Text = "Chat·Sobre Uvhash"
  },
  Voice_5392_UnlockDesc = {
    Text = "Após obter o despertador \"uvhash\", desbloqueado"
  },
  Voice_5393_AwakerVoiceContent = {
    Text = "Nosso relacionamento é como o de Sherlock Holmes e Dr. Watson, certo? Você tem acompanhado as últimas revistas populares?"
  },
  Voice_5393_AwakerVoiceTitle = {
    Text = "Conversa·Sobre Guardião do Segredo"
  },
  Voice_5394_AwakerVoiceContent = {
    Text = "Ajoelhe-se para a beleza."
  },
  Voice_5394_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_5395_AwakerVoiceContent = {
    Text = "Ajoelhe-se para a beleza."
  },
  Voice_5395_AwakerVoiceTitle = {
    Text = "Carta de Habilidade·Quatro"
  },
  Voice_5396_AwakerVoiceContent = {
    Text = "Aversão, um verbo descritivo, significa desenvolver uma aversão por algo. Desgosto, um verbo, refere-se ao sentimento de aversão quando algo é desagradado e evitado. Aversão, um substantivo, o sentimento de desgosto, <Del:Desgosto sendo suprimido me faz destruir me faz destruir me> — Desculpe, mas temo que não entendo o que \"desgosto\" significa."
  },
  Voice_5396_AwakerVoiceTitle = {
    Text = "Conversa·Coisas odiadas"
  },
  Voice_5397_AwakerVoiceContent = {
    Text = "No final..."
  },
  Voice_5397_AwakerVoiceTitle = {
    Text = "Atualizar·II"
  },
  Voice_5398_AwakerVoiceContent = {
    Text = "Se tornar ainda mais distinto."
  },
  Voice_5398_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · Três"
  },
  Voice_5399_AwakerVoiceContent = {
    Text = "Lembre-se do meu nome, Golias. Este nome está destinado a pisotear a insignificante história da humanidade."
  },
  Voice_5399_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_5400_AwakerVoiceContent = {
    Text = "Por favor, não tenha nenhuma preocupação."
  },
  Voice_5400_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · I"
  },
  Voice_5401_AwakerVoiceContent = {
    Text = "Espero que você não decepcione seu potencial e as expectativas da humanidade, novo Guardião."
  },
  Voice_5401_AwakerVoiceTitle = {
    Text = "Conversa·Sobre Guardião do Segredo"
  },
  Voice_5402_AwakerVoiceContent = {
    Text = "Sobrecarga."
  },
  Voice_5402_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_5403_AwakerVoiceContent = {Text = "Sobrecarga"},
  Voice_5403_AwakerVoiceTitle = {
    Text = "Carta de Habilidade·Quatro"
  },
  Voice_5404_AwakerVoiceContent = {
    Text = "Hmm, a foto que você encontrou na sua carteira? Ah, esse é o velho eu. Minha aparência atual foi moldada pelo meu amigo de apostas e rival."
  },
  Voice_5404_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Três"
  },
  Voice_5404_UnlockDesc = {
    Text = "Nível de afinidade atingido 6 desbloqueado"
  },
  Voice_5405_AwakerVoiceContent = {
    Text = "Perfeito—quer apostar? Se você ganhar, eu compartilho um segredo com você.\nMas tenha cuidado, Alva pode te pegar~"
  },
  Voice_5405_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Dois"
  },
  Voice_5405_UnlockDesc = {
    Text = "Nível de afinidade atingido 4 desbloqueado"
  },
  Voice_5406_AwakerVoiceContent = {
    Text = "Você se importa com este pelo? Quer tocá-lo? Não se preocupe, sou muito generoso!"
  },
  Voice_5406_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Um"
  },
  Voice_5406_UnlockDesc = {
    Text = "Nível de afinidade atingido 2 desbloqueado"
  },
  Voice_5407_AwakerVoiceContent = {
    Text = "Claro, há benefícios. Eu não conheci meu Watson? Comparado a isso, a vida e a aparência não importam, certo?"
  },
  Voice_5407_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Cinco"
  },
  Voice_5407_UnlockDesc = {
    Text = "Nível de afinidade atingido 10 desbloqueado"
  },
  Voice_5408_AwakerVoiceContent = {
    Text = "Eu me arrependo? De jeito nenhum. A vida seria muito entediante se tudo sempre saísse perfeitamente, não acha?"
  },
  Voice_5408_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Quatro"
  },
  Voice_5408_UnlockDesc = {
    Text = "Nível de afinidade atingido 8 desbloqueado"
  },
  Voice_5409_AwakerVoiceContent = {
    Text = "No meu tempo, as escolas eram lugares para treinar guerreiros. Parece que isso ainda é verdade agora."
  },
  Voice_5409_AwakerVoiceTitle = {
    Text = "Chat·Sobre a Universidade Mythag"
  },
  Voice_5410_AwakerVoiceContent = {
    Text = "Mason... Não, está tudo bem. Pelo menos podemos estar juntos novamente, \"24\"."
  },
  Voice_5410_AwakerVoiceTitle = {
    Text = "Conversa Ociosa · Sobre \"24\""
  },
  Voice_5410_UnlockDesc = {
    Text = "Desbloqueado após obter Despertador \"24\""
  },
  Voice_5411_AwakerVoiceContent = {
    Text = "Não é mau, né? Agora, a recompensa. — O quê? Não existe almoço grátis!"
  },
  Voice_5411_AwakerVoiceTitle = {
    Text = "Investigação Bem-sucedida"
  },
  Voice_5412_AwakerVoiceContent = {
    Text = "Sou de Cité. Lá, todos querem ser atores; ninguém se contenta em apenas assistir. Na realidade, somos meras notas de rodapé da cidade."
  },
  Voice_5412_AwakerVoiceTitle = {
    Text = "Conversas Ociosas·Sobre o Passado"
  },
  Voice_5413_AwakerVoiceContent = {
    Text = "Você já viu antiguidades esculpidas em pedra? Fundidas com as montanhas, sobrevivendo à passagem do tempo através da natureza, essas relíquias maravilhosas... mas ainda não é o suficiente..."
  },
  Voice_5413_AwakerVoiceTitle = {
    Text = "Conversa·Coisas favoritas"
  },
  Voice_5414_AwakerVoiceContent = {
    Text = "O pombo não voltou..."
  },
  Voice_5414_AwakerVoiceTitle = {
    Text = "Investigação Interrompida"
  },
  Voice_5415_AwakerVoiceContent = {Text = "Afaste-se!"},
  Voice_5415_AwakerVoiceTitle = {Text = "Ataque·II"},
  Voice_5416_AwakerVoiceContent = {Text = "Hmph!"},
  Voice_5416_AwakerVoiceTitle = {Text = "Ataque·Um"},
  Voice_5417_AwakerVoiceContent = {
    Text = "Execute o comando!"
  },
  Voice_5417_AwakerVoiceTitle = {Text = "Ataque·Um"},
  Voice_5418_AwakerVoiceContent = {Text = "Tolo"},
  Voice_5418_AwakerVoiceTitle = {Text = "Ataque·Um"},
  Voice_5419_AwakerVoiceContent = {
    Text = "...Hã? Você está me chamando? Não ouvi enquanto consertava a motocicleta... A propósito, estranho gentil, você viu minha chave inglesa?"
  },
  Voice_5419_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Um"
  },
  Voice_5419_UnlockDesc = {
    Text = "Nível de afinidade atingido 2 desbloqueado"
  },
  Voice_5420_AwakerVoiceContent = {
    Text = "Minha memória é sempre nebulosa, e só consigo me concentrar no que está bem na minha frente. No entanto, farei o meu melhor para gravar seu nome na minha mente... Qual era mesmo?"
  },
  Voice_5420_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Três"
  },
  Voice_5420_UnlockDesc = {
    Text = "Nível de afinidade atingido 6 desbloqueado"
  },
  Voice_5421_AwakerVoiceContent = {
    Text = "Você parece um pouco familiar, mas não consigo lembrar seu nome... Você é meu assistente? Poderia me trazer sete parafusos?"
  },
  Voice_5421_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Dois"
  },
  Voice_5421_UnlockDesc = {
    Text = "Nível de afinidade atingido 4 desbloqueado"
  },
  Voice_5422_AwakerVoiceContent = {
    Text = "Eu gravei seu nome no Fantasma. Quando formos em aventuras algum dia, não esquecerei como me dirigir a você."
  },
  Voice_5422_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Cinco"
  },
  Voice_5422_UnlockDesc = {
    Text = "Nível de afinidade atingido 10 desbloqueado"
  },
  Voice_5423_AwakerVoiceContent = {
    Text = "Tão familiar, tão familiar. Algo deve ter acontecido entre nós, certo? Dê-me um momento para lembrar... Ah, é você, o Guardião!"
  },
  Voice_5423_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Quatro"
  },
  Voice_5423_UnlockDesc = {
    Text = "Nível de afinidade atingido 8 desbloqueado"
  },
  Voice_5424_AwakerVoiceContent = {
    Text = "Você realmente é uma criança desonesta. Felizmente, eu tenho tempo e paciência suficientes para esperar por você..."
  },
  Voice_5424_AwakerVoiceTitle = {
    Text = "Conversa·Sobre Guardião do Segredo"
  },
  Voice_5425_AwakerVoiceContent = {
    Text = "\"Todos estão felizes,\" certo?"
  },
  Voice_5425_AwakerVoiceTitle = {
    Text = "Investigação Bem-sucedida"
  },
  Voice_5426_AwakerVoiceContent = {
    Text = "Consegui um troféu decente... Embora não possa se comparar à minha melhor coleção, a emoção de caçar novas peças é sempre empolgante. Me convide da próxima vez também."
  },
  Voice_5426_AwakerVoiceTitle = {
    Text = "Investigação Bem-sucedida"
  },
  Voice_5427_AwakerVoiceContent = {Text = "Hmm..."},
  Voice_5427_AwakerVoiceTitle = {
    Text = "Habilidade·Um"
  },
  Voice_5428_AwakerVoiceContent = {
    Text = "Uma empregada profissional irá limpar tudo para seu mestre, incluindo os vilões~"
  },
  Voice_5428_AwakerVoiceTitle = {
    Text = "Investigação Bem-sucedida"
  },
  Voice_5429_AwakerVoiceContent = {
    Text = "Agora somos cúmplices, certo? Se você acabar na rua, não vou deixar você sobreviver de lixo."
  },
  Voice_5429_AwakerVoiceTitle = {
    Text = "Conversa·Sobre Guardião do Segredo"
  },
  Voice_5430_AwakerVoiceContent = {
    Text = "Cresça e floresça, minha pequena muda."
  },
  Voice_5430_AwakerVoiceTitle = {
    Text = "Exaltar · Dois"
  },
  Voice_5431_AwakerVoiceContent = {
    Text = "Cresça e floresça, minha pequena muda."
  },
  Voice_5431_AwakerVoiceTitle = {
    Text = "Fúria Explosiva"
  },
  Voice_5432_AwakerVoiceContent = {
    Text = "Sente-se como se minha sorte com os dados melhorasse um pouco!"
  },
  Voice_5432_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · I"
  },
  Voice_5433_AwakerVoiceContent = {
    Text = "Uau! Sua sorte está ardendo em chamas!"
  },
  Voice_5433_AwakerVoiceTitle = {
    Text = "Atualizar·II"
  },
  Voice_5434_AwakerVoiceContent = {Text = "Sortudo~"},
  Voice_5434_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · Três"
  },
  Voice_5435_AwakerVoiceContent = {
    Text = "Não chegue perto de mim."
  },
  Voice_5435_AwakerVoiceTitle = {
    Text = "Habilidade·Um"
  },
  Voice_5436_AwakerVoiceContent = {
    Text = "Não chegue perto de mim."
  },
  Voice_5436_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_5437_AwakerVoiceContent = {
    Text = "Eu devo acusá-lo, Guardião. Sua bondade me deixa desconfortável—apenas a dor física é verdadeiramente eterna para mim."
  },
  Voice_5437_AwakerVoiceTitle = {
    Text = "Conversa·Sobre Guardião do Segredo"
  },
  Voice_5438_AwakerVoiceContent = {
    Text = "Muito bom, bem feito."
  },
  Voice_5438_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · I"
  },
  Voice_5439_AwakerVoiceContent = {
    Text = "Este nível está longe de ser suficiente."
  },
  Voice_5439_AwakerVoiceTitle = {
    Text = "Atualizar·II"
  },
  Voice_5440_AwakerVoiceContent = {
    Text = "Então, que recompensa você deseja?"
  },
  Voice_5440_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · Três"
  },
  Voice_5441_AwakerVoiceContent = {
    Text = "Ugh! A sujeira e desordem por todo lado... Eu não consigo encontrar um lugar limpo para colocar meus pés. Muito bem, ofereça-me suas costas macias, mortal."
  },
  Voice_5441_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_5442_AwakerVoiceContent = {
    Text = "Finalmente... encontrei!"
  },
  Voice_5442_AwakerVoiceTitle = {
    Text = "Despertar do Conhecimento Espiritual"
  },
  Voice_5443_AwakerVoiceContent = {
    Text = "Até a pelagem de Marrom se tornou mais suave."
  },
  Voice_5443_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_5443_UnlockDesc = {
    Text = "Nível de iluminação atingiu 2 para desbloquear"
  },
  Voice_5444_AwakerVoiceContent = {
    Text = "Ser um segurança pode ser um pouco difícil, mas pode deixar todas as tarefas e entregas comigo."
  },
  Voice_5444_AwakerVoiceTitle = {
    Text = "Iluminar·Construção"
  },
  Voice_5444_UnlockDesc = {
    Text = "Nível de iluminação atingiu 11 para desbloquear"
  },
  Voice_5445_AwakerVoiceContent = {
    Text = "Olhe para você ao enfrentar o Brown.\n...Hehe, o Lord Brown vai comer os dedos de um covarde esta noite. Vamos ver quem será o azarado."
  },
  Voice_5445_AwakerVoiceTitle = {
    Text = "Iluminar·Florescer"
  },
  Voice_5445_UnlockDesc = {
    Text = "Nível de iluminação atingiu 15 para desbloquear"
  },
  Voice_5446_AwakerVoiceContent = {
    Text = "Eu me pergunto se eu posso crescer um pouco mais."
  },
  Voice_5446_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexão"
  },
  Voice_5446_UnlockDesc = {
    Text = "Nível de iluminação atingiu 3 para desbloquear"
  },
  Voice_5447_AwakerVoiceContent = {
    Text = "Pronto para trabalhar? Tudo bem, Brown, vamos nos animar!"
  },
  Voice_5447_AwakerVoiceTitle = {
    Text = "Iluminar: Insight"
  },
  Voice_5447_UnlockDesc = {
    Text = "Nível de iluminação atingiu 7 para desbloquear"
  },
  Voice_5448_AwakerVoiceContent = {
    Text = "Agrippa? Desculpe, enviei muitas pessoas embora eu mesma. A maioria delas não tem rosto e não vale a pena lembrar."
  },
  Voice_5448_AwakerVoiceTitle = {
    Text = "Fala Ociosa · Sobre Agrippa"
  },
  Voice_5448_UnlockDesc = {
    Text = "Após obter o despertador \"Agrippa\", desbloqueado"
  },
  Voice_5449_AwakerVoiceContent = {
    Text = "Membros da tripulação perigosos... Não, é apenas do ponto de vista da segurança da navegação..."
  },
  Voice_5449_AwakerVoiceTitle = {
    Text = "Bate-Papo·Sobre Faróis"
  },
  Voice_5449_UnlockDesc = {
    Text = "Após obter o despertador \"Faróis\", desbloqueado"
  },
  Voice_5450_AwakerVoiceContent = {
    Text = "Não chegue mais perto!"
  },
  Voice_5450_AwakerVoiceTitle = {Text = "Defesa·II"},
  Voice_5451_AwakerVoiceContent = {Text = "Cuidado!"},
  Voice_5451_AwakerVoiceTitle = {
    Text = "Defesa · I"
  },
  Voice_5452_AwakerVoiceContent = {
    Text = "Completei suas instruções... Ah, fiz uma bagunça de novo, não fiz?"
  },
  Voice_5452_AwakerVoiceTitle = {
    Text = "Investigação Bem-sucedida"
  },
  Voice_5453_AwakerVoiceContent = {
    Text = "Ah, esta é exatamente a parte que eu precisava, obrigado! ...Huh? Eu pedi para você encontrar isso? Não me lembro disso. Você tem certeza de que não está enganado?"
  },
  Voice_5453_AwakerVoiceTitle = {
    Text = "Fala Ociosa · Sobre Partes"
  },
  Voice_5454_AwakerVoiceContent = {
    Text = "Inspiração, fluindo sem fim"
  },
  Voice_5454_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · Três"
  },
  Voice_5455_AwakerVoiceContent = {Text = "Bom gosto."},
  Voice_5455_AwakerVoiceTitle = {
    Text = "Atualizar·II"
  },
  Voice_5456_AwakerVoiceContent = {
    Text = "Você escolheu a faca de entalhe perfeita para mim."
  },
  Voice_5456_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · I"
  },
  Voice_5457_AwakerVoiceContent = {
    Text = "Eu odeio perder o controle. No entanto, sua presença me mostrou que um toque de caos sutil pode trazer um tipo único de prazer."
  },
  Voice_5457_AwakerVoiceTitle = {
    Text = "Conversa·Coisas odiadas"
  },
  Voice_5458_AwakerVoiceContent = {
    Text = "Você cresceu um pouco?"
  },
  Voice_5458_AwakerVoiceTitle = {
    Text = "Atualizar·II"
  },
  Voice_5459_AwakerVoiceContent = {
    Text = "Desculpe, é difícil para mim desenvolver meu corpo..."
  },
  Voice_5459_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · Três"
  },
  Voice_54601_AwakerVoiceContent = {
    Text = "Para compreender o mundo."
  },
  Voice_54601_AwakerVoiceTitle = {
    Text = "Sobre-Exaltação Aliemus Explosão·II"
  },
  Voice_54602_AwakerVoiceContent = {
    Text = "Para compreender o mundo."
  },
  Voice_54602_AwakerVoiceTitle = {
    Text = "Superexaltação"
  },
  Voice_54605_AwakerVoiceContent = {
    Text = "Aproveite sua refeição, senhor!"
  },
  Voice_54605_AwakerVoiceTitle = {
    Text = "Superexaltação"
  },
  Voice_54606_AwakerVoiceContent = {
    Text = "Aproveite sua refeição, senhor!"
  },
  Voice_54606_AwakerVoiceTitle = {
    Text = "Sobre-Exaltação Aliemus Explosão·II"
  },
  Voice_54607_AwakerVoiceContent = {
    Text = "Próximo, analise a essência do mundo!"
  },
  Voice_54607_AwakerVoiceTitle = {
    Text = "Sobre-Exaltação Aliemus Explosão·II"
  },
  Voice_54608_AwakerVoiceContent = {
    Text = "Próximo, analise a essência do mundo!"
  },
  Voice_54608_AwakerVoiceTitle = {
    Text = "Superexaltação"
  },
  Voice_54609_AwakerVoiceContent = {
    Text = "Sacrifício! Retorne ao meu mestre—"
  },
  Voice_54609_AwakerVoiceTitle = {
    Text = "Sobre-Exaltação Aliemus Explosão·II"
  },
  Voice_5460_AwakerVoiceContent = {
    Text = "E-obrigado pela refeição..."
  },
  Voice_5460_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · I"
  },
  Voice_54610_AwakerVoiceContent = {
    Text = "Sacrifício! Retorne ao meu mestre—"
  },
  Voice_54610_AwakerVoiceTitle = {
    Text = "Superexaltação"
  },
  Voice_54611_AwakerVoiceContent = {
    Text = "Não me impeça!"
  },
  Voice_54611_AwakerVoiceTitle = {
    Text = "Sobre-Exaltação Aliemus Explosão·II"
  },
  Voice_54612_AwakerVoiceContent = {
    Text = "No abismo... haverá uma luz de justiça."
  },
  Voice_54612_AwakerVoiceTitle = {
    Text = "Sobre-Exaltação Aliemus Explosão·II"
  },
  Voice_54613_AwakerVoiceContent = {
    Text = "Não me impeça!"
  },
  Voice_54613_AwakerVoiceTitle = {
    Text = "Superexaltação"
  },
  Voice_54614_AwakerVoiceContent = {
    Text = "Entregue-se a esta dor única!"
  },
  Voice_54614_AwakerVoiceTitle = {
    Text = "Superexaltação"
  },
  Voice_54615_AwakerVoiceContent = {
    Text = "Entregue-se a esta dor única!"
  },
  Voice_54615_AwakerVoiceTitle = {
    Text = "Sobre-Exaltação Aliemus Explosão·II"
  },
  Voice_54616_AwakerVoiceContent = {
    Text = "\"Sim, criança, você pereceu no rio furioso!\""
  },
  Voice_54616_AwakerVoiceTitle = {
    Text = "Superexaltação"
  },
  Voice_54617_AwakerVoiceContent = {
    Text = "\"Sim, criança, você pereceu no rio furioso!\""
  },
  Voice_54617_AwakerVoiceTitle = {
    Text = "Sobre-Exaltação Aliemus Explosão·II"
  },
  Voice_54618_AwakerVoiceContent = {
    Text = "Ó entidade sem forma, torne-se um escudo de proteção!"
  },
  Voice_54618_AwakerVoiceTitle = {
    Text = "Superexaltação"
  },
  Voice_54619_AwakerVoiceContent = {
    Text = "Ó entidade sem forma, torne-se um escudo de proteção!"
  },
  Voice_54619_AwakerVoiceTitle = {
    Text = "Sobre-Exaltação Aliemus Explosão·II"
  },
  Voice_5461_AwakerVoiceContent = {
    Text = "Eu ficaria grato pelo seu esforço."
  },
  Voice_5461_AwakerVoiceTitle = {
    Text = "Iluminar·Visão Remota"
  },
  Voice_5461_UnlockDesc = {
    Text = "Nível de iluminação atingiu 1 para desbloquear"
  },
  Voice_54620_AwakerVoiceContent = {
    Text = "Besta do Abismo, devore tudo!"
  },
  Voice_54620_AwakerVoiceTitle = {
    Text = "Sobre-Exaltação Aliemus Explosão·II"
  },
  Voice_54621_AwakerVoiceContent = {
    Text = "Besta do Abismo, devore tudo!"
  },
  Voice_54621_AwakerVoiceTitle = {
    Text = "Superexaltação"
  },
  Voice_54622_AwakerVoiceContent = {
    Text = "No abismo... haverá uma luz de justiça."
  },
  Voice_54622_AwakerVoiceTitle = {
    Text = "Superexaltação"
  },
  Voice_54623_AwakerVoiceContent = {
    Text = "Sou quem rasga as correntes—Tokuli—Li!"
  },
  Voice_54623_AwakerVoiceTitle = {
    Text = "Superexaltação"
  },
  Voice_54624_AwakerVoiceContent = {
    Text = "Sou quem rasga as correntes—Tokuli—Li!"
  },
  Voice_54624_AwakerVoiceTitle = {
    Text = "Sobre-Exaltação Aliemus Explosão·II"
  },
  Voice_54625_AwakerVoiceContent = {
    Text = "Este corpo é aquele que revela o futuro!"
  },
  Voice_54625_AwakerVoiceTitle = {
    Text = "Superexaltação"
  },
  Voice_54626_AwakerVoiceContent = {
    Text = "Este corpo é aquele que revela o futuro!"
  },
  Voice_54626_AwakerVoiceTitle = {
    Text = "Sobre-Exaltação Aliemus Explosão·II"
  },
  Voice_54627_AwakerVoiceContent = {
    Text = "Ajoelhe-se e beije as pontas dos meus pés!"
  },
  Voice_54627_AwakerVoiceTitle = {
    Text = "Sobre-Exaltação Aliemus Explosão·II"
  },
  Voice_54628_AwakerVoiceContent = {
    Text = "Todas as conchas estão aqui!"
  },
  Voice_54628_AwakerVoiceTitle = {
    Text = "Sobre-Exaltação Aliemus Explosão·II"
  },
  Voice_54629_AwakerVoiceContent = {
    Text = "Todas as conchas estão aqui!"
  },
  Voice_54629_AwakerVoiceTitle = {
    Text = "Superexaltação"
  },
  Voice_5462_AwakerVoiceContent = {
    Text = "O poder extraordinário só pode ser suportado por um Aequor. Você deve me invejar, haha. Não é sua culpa por ser um frágil humano; apenas aceite isso."
  },
  Voice_5462_AwakerVoiceTitle = {
    Text = "Iluminar·Visão Remota"
  },
  Voice_5462_UnlockDesc = {
    Text = "Nível de iluminação atingiu 1 para desbloquear"
  },
  Voice_54630_AwakerVoiceContent = {
    Text = "Ajoelhe-se e beije as pontas dos meus pés!"
  },
  Voice_54630_AwakerVoiceTitle = {
    Text = "Superexaltação"
  },
  Voice_5463_AwakerVoiceContent = {
    Text = "Posso transformar esses indivíduos derrotados em meus escravos?"
  },
  Voice_5463_AwakerVoiceTitle = {
    Text = "Investigação Bem-sucedida"
  },
  Voice_5464_AwakerVoiceContent = {Text = "Heh."},
  Voice_5464_AwakerVoiceTitle = {Text = "Acertar·1"},
  Voice_5465_AwakerVoiceContent = {
    Text = "Assim como esperado."
  },
  Voice_5465_AwakerVoiceTitle = {
    Text = "Acertar · II"
  },
  Voice_5466_AwakerVoiceContent = {Text = "Ah!"},
  Voice_5466_AwakerVoiceTitle = {
    Text = "Acertar·III"
  },
  Voice_5467_AwakerVoiceContent = {Text = "Ah!"},
  Voice_5467_AwakerVoiceTitle = {
    Text = "Golpe·Quatro"
  },
  Voice_5468_AwakerVoiceContent = {
    Text = "Se eu soubesse antes que aquelas pessoas estavam atormentadas por essa maldição devoradora, eu... Não, não é tarde demais agora. Eu preciso erradicá-la e eliminar todo sofrimento, mesmo que me custe a vida mais uma vez."
  },
  Voice_5468_AwakerVoiceTitle = {
    Text = "Bate-papo · Sobre Dissolução"
  },
  Voice_5469_AwakerVoiceContent = {
    Text = "Não desanime. O mar abraça a todos."
  },
  Voice_5469_AwakerVoiceTitle = {
    Text = "Investigação Interrompida"
  },
  Voice_5470_AwakerVoiceContent = {
    Text = "Com um corpo tão frágil, é demais esperar que você se torne meu companheiro. Vamos lá, vamos levá-lo ao clube esportivo da academia para ampliar seus horizontes e passar por um treinamento rigoroso!"
  },
  Voice_5470_AwakerVoiceTitle = {
    Text = "Conversa·Sobre Guardião do Segredo"
  },
  Voice_5471_AwakerVoiceContent = {
    Text = "Aquela pobre alma que emprestou meu poder tem sido atormentada pela Dissolução... Que tipo de olhar é esse? Não pense nem por um segundo! Eu não vou te dizer onde ela está!"
  },
  Voice_5471_AwakerVoiceTitle = {
    Text = "Bate-papo · Sobre Dissolução"
  },
  Voice_5472_AwakerVoiceContent = {
    Text = "Enquanto você tiver sorte o suficiente, pode se tornar invencível."
  },
  Voice_5472_AwakerVoiceTitle = {
    Text = "Investigação Bem-sucedida"
  },
  Voice_5473_AwakerVoiceContent = {
    Text = "Será muito severo?"
  },
  Voice_5473_AwakerVoiceTitle = {
    Text = "Carta de Habilidade·Quatro"
  },
  Voice_5474_AwakerVoiceContent = {
    Text = "Oh querido, a maioria das pessoas aqui ainda são crianças. Aquele cavalheiro já tem cabelo branco, e o jovem de rosto sério está sem um braço. Nenhum deles é uma escolha ideal... Isso é um verdadeiro dilema."
  },
  Voice_5474_AwakerVoiceTitle = {
    Text = "Chat·Sobre a Universidade Mythag"
  },
  Voice_5475_AwakerVoiceContent = {
    Text = "Será muito severo?"
  },
  Voice_5475_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_5476_AwakerVoiceContent = {
    Text = "Runa desenhada meticulosamente, estátuas esculpidas devotadamente, poções tabus refinadas repetidamente... nenhuma pode ser poupada."
  },
  Voice_5476_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_5476_UnlockDesc = {
    Text = "Nível de iluminação atingiu 2 para desbloquear"
  },
  Voice_5477_AwakerVoiceContent = {
    Text = "O trono deve ser construído com pedra verde antiga de Aequor, e o altar deve ser lambuzado com sangue sacrificial... Não deveria começar a se preparar?"
  },
  Voice_5477_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexão"
  },
  Voice_5477_UnlockDesc = {
    Text = "Nível de iluminação atingiu 3 para desbloquear"
  },
  Voice_5478_AwakerVoiceContent = {
    Text = "Invocar todos; eles devem tremer e se ajoelhar em antecipação à Sua chegada."
  },
  Voice_5478_AwakerVoiceTitle = {
    Text = "Iluminar: Insight"
  },
  Voice_5478_UnlockDesc = {
    Text = "Nível de iluminação atingiu 7 para desbloquear"
  },
  Voice_5479_AwakerVoiceContent = {
    Text = "Vou me dirigir às ruínas de Aequor, banhando-me nas águas onde Ele nasceu..."
  },
  Voice_5479_AwakerVoiceTitle = {
    Text = "Iluminar·Construção"
  },
  Voice_5479_UnlockDesc = {
    Text = "Nível de iluminação atingiu 11 para desbloquear"
  },
  Voice_5480_AwakerVoiceContent = {
    Text = "Bem-vindo à cerimônia de nascimento Dele, para testemunhar Sua chegada... O que? Você diz que Sua morte também é um destino? ... Não, isso é impossível... Já paguei um preço tão alto..."
  },
  Voice_5480_AwakerVoiceTitle = {
    Text = "Iluminar·Florescer"
  },
  Voice_5480_UnlockDesc = {
    Text = "Nível de iluminação atingiu 15 para desbloquear"
  },
  Voice_5481_AwakerVoiceContent = {
    Text = "Siga os mandamentos divinos."
  },
  Voice_5481_AwakerVoiceTitle = {
    Text = "Carta de Habilidade·Quatro"
  },
  Voice_5482_AwakerVoiceContent = {
    Text = "Seu lado será o lugar onde Desmaio e eu pertencemos?"
  },
  Voice_5482_AwakerVoiceTitle = {
    Text = "Iluminar·Construção"
  },
  Voice_5482_UnlockDesc = {
    Text = "Nível de iluminação atingiu 11 para desbloquear"
  },
  Voice_5483_AwakerVoiceContent = {
    Text = "Hmm, naquela época, eu perdi minha voz. Sua graça a trouxe de volta."
  },
  Voice_5483_AwakerVoiceTitle = {
    Text = "Iluminar: Insight"
  },
  Voice_5483_UnlockDesc = {
    Text = "Nível de iluminação atingiu 7 para desbloquear"
  },
  Voice_5484_AwakerVoiceContent = {
    Text = "Siga os mandamentos divinos."
  },
  Voice_5484_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_5485_AwakerVoiceContent = {
    Text = "O vasto cosmos, o profundo espaço sem limites e a jornada sem fim uma vez me deixaram perdido..."
  },
  Voice_5485_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_5485_UnlockDesc = {
    Text = "Nível de iluminação atingiu 2 para desbloquear"
  },
  Voice_5486_AwakerVoiceContent = {
    Text = "Métodos de atalho podem lhe dar um impulso, mas não negligencie o treinamento de suas habilidades."
  },
  Voice_5486_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · I"
  },
  Voice_5487_AwakerVoiceContent = {
    Text = "Então esse método se aplica a mim também..."
  },
  Voice_5487_AwakerVoiceTitle = {
    Text = "Atualizar·II"
  },
  Voice_5488_AwakerVoiceContent = {
    Text = "Uma sensação maravilhosa."
  },
  Voice_5488_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · Três"
  },
  Voice_5492_AwakerVoiceContent = {
    Text = "A chegada dele não traria um fim ao sofrimento causado por esta morte negra?"
  },
  Voice_5492_AwakerVoiceTitle = {
    Text = "Bate-papo · Sobre Dissolução"
  },
  Voice_5493_AwakerVoiceContent = {
    Text = "Bom dia, meu senhor. Se você está saindo para conduzir uma investigação, por favor, permita-me acompanhá-lo como seu guardião."
  },
  Voice_5493_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Um"
  },
  Voice_5493_UnlockDesc = {
    Text = "Nível de afinidade atingido 2 desbloqueado"
  },
  Voice_5494_AwakerVoiceContent = {
    Text = "O que fazer? Se você está entediado, apenas escreva este relatório de missão."
  },
  Voice_5494_AwakerVoiceTitle = {
    Text = "Conversa·Toque"
  },
  Voice_5495_AwakerVoiceContent = {
    Text = "Está finalmente começando? Meus pequenos animais de estimação estão famintos há tanto, tanto tempo..."
  },
  Voice_5495_AwakerVoiceTitle = {
    Text = "Início da Investigação"
  },
  Voice_5496_AwakerVoiceContent = {
    Text = "O poder da linhagem está em ebulição."
  },
  Voice_5496_AwakerVoiceTitle = {
    Text = "Início da Investigação"
  },
  Voice_5497_AwakerVoiceContent = {
    Text = "...Espere um minuto, eu já vi isso antes. Eles me deram água com essa gosma preta. Pode estar relacionado ao meu ganho do poder da Chama Verde? Eu suponho que seja uma bênção disfarçada."
  },
  Voice_5497_AwakerVoiceTitle = {
    Text = "Bate-papo · Sobre Dissolução"
  },
  Voice_5498_AwakerVoiceContent = {
    Text = "Ramona Dexter, pode me chamar de Ramona. Estou ansiosa para trabalhar com você, Guardião."
  },
  Voice_5498_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_5499_AwakerVoiceContent = {Text = "Sim."},
  Voice_5499_AwakerVoiceTitle = {Text = "Ataque·II"},
  Voice_5500_AwakerVoiceContent = {
    Text = "Comando recebido."
  },
  Voice_5500_AwakerVoiceTitle = {Text = "Ataque·Um"},
  Voice_5501_AwakerVoiceContent = {
    Text = "Hmph, desrespeitosos, deixe-me me divertir um pouco com vocês."
  },
  Voice_5501_AwakerVoiceTitle = {
    Text = "Início da Investigação"
  },
  Voice_5502_AwakerVoiceContent = {
    Text = "Desgostos? Um cano que seca na hora certa, um trem perdido, chuva ao usar sapatos novos. Basicamente, toda má sorte é irritante."
  },
  Voice_5502_AwakerVoiceTitle = {
    Text = "Conversa·Coisas odiadas"
  },
  Voice_5503_AwakerVoiceContent = {
    Text = "Chave, chave ajustável, chave de boca, chave de fenda plana, chave de fenda Phillips, parafuso rebaixado, parafuso pan head... Se puder consertar coisas quebradas, eu gosto."
  },
  Voice_5503_AwakerVoiceTitle = {
    Text = "Conversa·Coisas favoritas"
  },
  Voice_5504_AwakerVoiceContent = {
    Text = "Oh não~ Você me pegou~\nEstá tudo bem, os Despertadores têm um poder espiritual tão abundante. Eu preciso roubar pelo menos 365 vezes antes que eles se tornem marionetes sem mente~ Não consegue? Tudo bem, serei mais cuidadoso na próxima vez! Apenas um pouquinho de \"medo\" durante o corte, certo?"
  },
  Voice_5504_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Quatro"
  },
  Voice_5504_UnlockDesc = {
    Text = "Nível de afinidade atingido 8 desbloqueado"
  },
  Voice_5505_AwakerVoiceContent = {
    Text = "Ei, você já conhece os segredos da magia de Casiah, certo? Hmm, para garantir que você não revele nada, você terá que me seguir para onde eu for na turnê~ Haha, você acha que estou coletando suas emoções? De fato, nada escapa de você!"
  },
  Voice_5505_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Cinco"
  },
  Voice_5505_UnlockDesc = {
    Text = "Nível de afinidade atingido 10 desbloqueado"
  },
  Voice_5506_AwakerVoiceContent = {
    Text = "Você, seja o assistente mágico de Casiah! Não tenha medo~ Apenas entre na minha caixa mágica por um momento.\n\nVocê está se escondendo bem? Estou prestes a inserir a espada~ Oh, não há armadilhas lá dentro~"
  },
  Voice_5506_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Um"
  },
  Voice_5506_UnlockDesc = {
    Text = "Nível de afinidade atingido 2 desbloqueado"
  },
  Voice_5507_AwakerVoiceContent = {
    Text = "Aqui, coloque este chapéu de copa! Depois, me conte o presente que você mais deseja. Entendi, eu vejo! Agora, coloque a mão no chapéu—"
  },
  Voice_5507_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Dois"
  },
  Voice_5507_UnlockDesc = {
    Text = "Nível de afinidade atingido 4 desbloqueado"
  },
  Voice_5508_AwakerVoiceContent = {
    Text = "Um pouco preocupante. Aqueles crianças vêm a cada show, e meu estoque está acabando... Hmm, um mágico não pode fazer os mesmos truques para o mesmo público. Criar nova mágica? Desculpe, não tenho esse talento; só sou bom em imitações."
  },
  Voice_5508_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Três"
  },
  Voice_5508_UnlockDesc = {
    Text = "Nível de afinidade atingido 6 desbloqueado"
  },
  Voice_5509_AwakerVoiceContent = {
    Text = "Esta academia está em estado de deterioração; apenas o lounge do diretor é um pouco apresentável. O que você acha?"
  },
  Voice_5509_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_5509_UnlockDesc = {
    Text = "Nível de iluminação atingiu 2 para desbloquear"
  },
  Voice_5510_AwakerVoiceContent = {
    Text = "Aqueles arrogantes e desprezíveis tolos todos se tornarão espíritos vingativos sob meu comando."
  },
  Voice_5510_AwakerVoiceTitle = {
    Text = "Atualizar·II"
  },
  Voice_5511_AwakerVoiceContent = {
    Text = "A lâmina da vingança se torna cada vez mais afiada."
  },
  Voice_5511_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · Três"
  },
  Voice_5512_AwakerVoiceContent = {
    Text = "Meu salão não é tão inocente quanto um baile. Você está pronto?"
  },
  Voice_5512_AwakerVoiceTitle = {
    Text = "Iluminar·Construção"
  },
  Voice_5512_UnlockDesc = {
    Text = "Nível de iluminação atingiu 11 para desbloquear"
  },
  Voice_5513_AwakerVoiceContent = {
    Text = "Meu salão é o solo, o jardim, onde a beleza intoxicante e o poder florescerão..."
  },
  Voice_5513_AwakerVoiceTitle = {
    Text = "Iluminar·Florescer"
  },
  Voice_5513_UnlockDesc = {
    Text = "Nível de iluminação atingiu 15 para desbloquear"
  },
  Voice_5514_AwakerVoiceContent = {
    Text = "Almofadas de seda, chá preto, macarons... Eu também preciso de rosas frescas com orvalho da manhã para adornar minha sala de recepção."
  },
  Voice_5514_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexão"
  },
  Voice_5514_UnlockDesc = {
    Text = "Nível de iluminação atingiu 3 para desbloquear"
  },
  Voice_5515_AwakerVoiceContent = {
    Text = "Não podemos fazer uma exceção e permitir que os convidados do lado de fora entrem na academia?"
  },
  Voice_5515_AwakerVoiceTitle = {
    Text = "Iluminar: Insight"
  },
  Voice_5515_UnlockDesc = {
    Text = "Nível de iluminação atingiu 7 para desbloquear"
  },
  Voice_5516_AwakerVoiceContent = {
    Text = "Erro de tempo de execução, erro, erro, erro..."
  },
  Voice_5516_AwakerVoiceTitle = {
    Text = "Investigação Interrompida"
  },
  Voice_5517_AwakerVoiceContent = {
    Text = "Ah! Que horas são?! Desculpe, Mestre... Karen não deveria estar relaxando! Mas estou tão exausta..."
  },
  Voice_5517_AwakerVoiceTitle = {
    Text = "Conversa·Toque"
  },
  Voice_5518_AwakerVoiceContent = {
    Text = "É minha única opção esperar pela morte? Alguém pode me ajudar? Posso resistir ao controle deles? Eu costumava me fazer essas perguntas todos os dias, mas a resposta sempre estava na minha mente—eu apenas não me atrevia a enfrentá-la... Se você não tivesse aparecido, eu não sei se teria coragem de reagir.\nO-obrigado—não me entenda mal, isto não é uma declaração ou algo assim!"
  },
  Voice_5518_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Cinco"
  },
  Voice_5518_UnlockDesc = {
    Text = "Nível de afinidade atingido 10 desbloqueado"
  },
  Voice_5519_AwakerVoiceContent = {
    Text = "Eu vivo em seus sonhos falsos, privado do meu direito de ser uma pessoa comum por uma profecia ridícula, sem nem mesmo a liberdade de escolher... Eu faria qualquer coisa para escapar desta vida."
  },
  Voice_5519_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Quatro"
  },
  Voice_5519_UnlockDesc = {
    Text = "Nível de afinidade atingido 8 desbloqueado"
  },
  Voice_5520_AwakerVoiceContent = {
    Text = "\"Lírios d'água pendurados suspiram ao redor,\nEla se agita ocasionalmente entre os álamos adormecidos;\nUm pássaro se mexe, tremendo em seu ninho,\nUma canção misteriosa desce das estrelas douradas.\"\nAh, você ouviu isso? Desculpe, é um dos meus favoritos... Você gostaria de ler comigo?"
  },
  Voice_5520_AwakerVoiceTitle = {
    Text = "Conversa Ociosa: Sobre Leitura"
  },
  Voice_5521_AwakerVoiceContent = {
    Text = "Não entre em uma sala de dama sem autorização, nem faça comentários sobre seu comportamento. Saia agora, eu preciso descansar."
  },
  Voice_5521_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Dois"
  },
  Voice_5521_UnlockDesc = {
    Text = "Nível de afinidade atingido 4 desbloqueado"
  },
  Voice_5522_AwakerVoiceContent = {
    Text = "É melhor você não se achar demais comigo. Conheça seu lugar e abra os olhos para ver quem é o verdadeiro mestre."
  },
  Voice_5522_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Um"
  },
  Voice_5522_UnlockDesc = {
    Text = "Nível de afinidade atingido 2 desbloqueado"
  },
  Voice_5523_AwakerVoiceContent = {
    Text = "Oh, preciso exibir os itens?"
  },
  Voice_5523_AwakerVoiceTitle = {
    Text = "Início da Investigação"
  },
  Voice_5524_AwakerVoiceContent = {
    Text = "Muito bem. É hora de celebrar a vitória com um barril de rum!"
  },
  Voice_5524_AwakerVoiceTitle = {
    Text = "Investigação Bem-sucedida"
  },
  Voice_5525_AwakerVoiceContent = {
    Text = "Desaparecer."
  },
  Voice_5525_AwakerVoiceTitle = {Text = "Ataque·II"},
  Voice_5526_AwakerVoiceContent = {
    Text = "Deixe isso comigo!"
  },
  Voice_5526_AwakerVoiceTitle = {
    Text = "Carta de Habilidade·Quatro"
  },
  Voice_5527_AwakerVoiceContent = {
    Text = "A sensação de ser esmagado sob meus pés deve ser absolutamente maravilhosa~"
  },
  Voice_5527_AwakerVoiceTitle = {
    Text = "Investigação Bem-sucedida"
  },
  Voice_5528_AwakerVoiceContent = {
    Text = "Aguente firme!"
  },
  Voice_5528_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_5529_AwakerVoiceContent = {
    Text = "Curioso sobre o que está sob o curativo? Eu lhe mostrarei em um ambiente mais apropriado, então não seja tão impaciente."
  },
  Voice_5529_AwakerVoiceTitle = {
    Text = "Conversa·Toque"
  },
  Voice_5530_AwakerVoiceContent = {
    Text = "Já acabou? ... Minha empolgação estava apenas começando a crescer."
  },
  Voice_5530_AwakerVoiceTitle = {
    Text = "Investigação Bem-sucedida"
  },
  Voice_5531_AwakerVoiceContent = {
    Text = "Ei, pare de brincar comigo. Verdadeiros guerreiros nunca dependem de ajudas externas."
  },
  Voice_5531_AwakerVoiceTitle = {
    Text = "Iluminar·Visão Remota"
  },
  Voice_5531_UnlockDesc = {
    Text = "Nível de iluminação atingiu 1 para desbloquear"
  },
  Voice_5532_AwakerVoiceContent = {
    Text = "Aigis se tornou mais forte... Usarei esses olhos para paralisar o inimigo!"
  },
  Voice_5532_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · Três"
  },
  Voice_5533_AwakerVoiceContent = {
    Text = "A Universidade Mythag não é diferente do exército. Cada um de nós está na linha de frente, polindo nossas armas e se preparando para a batalha."
  },
  Voice_5533_AwakerVoiceTitle = {
    Text = "Chat·Sobre a Universidade Mythag"
  },
  Voice_5534_AwakerVoiceContent = {Text = "Perfeito!"},
  Voice_5534_AwakerVoiceTitle = {
    Text = "Habilidade·Um"
  },
  Voice_5535_AwakerVoiceContent = {Text = "Perfeito!"},
  Voice_5535_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_5536_AwakerVoiceContent = {
    Text = "Eu posso ser acorrentado, puxado pelo cabelo e ajoelhado na sua frente como escravo. Tudo bem com isso – desde que eu possa matar alguém, o escultor, a senhora astmática... qualquer pessoa, prometo rasgar suas gargantas e beber seu sangue"
  },
  Voice_5536_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Quatro"
  },
  Voice_5536_UnlockDesc = {
    Text = "Nível de afinidade atingido 8 desbloqueado"
  },
  Voice_5537_AwakerVoiceContent = {
    Text = "Da dissolução fluem não apenas lodo negro, mas também uma inspiração sem fim. Sinceramente, não me importaria com um pouco mais"
  },
  Voice_5537_AwakerVoiceTitle = {
    Text = "Bate-papo · Sobre Dissolução"
  },
  Voice_5538_AwakerVoiceContent = {
    Text = "Assustado? Hahaha, isso mesmo! Que se dane tudo. Eu só quero saborear seu medo."
  },
  Voice_5538_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Um"
  },
  Voice_5538_UnlockDesc = {
    Text = "Nível de afinidade atingido 2 desbloqueado"
  },
  Voice_5539_AwakerVoiceContent = {
    Text = "Interessante, seu sangue tem gosto... doce, como hidromel."
  },
  Voice_5539_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Dois"
  },
  Voice_5539_UnlockDesc = {
    Text = "Nível de afinidade atingido 4 desbloqueado"
  },
  Voice_5540_AwakerVoiceContent = {
    Text = "Naquela época, dezenas de milhares aclamavam meu nome. O mar chamado \"Uvhash\" afogou tudo, celebrando minha quebra do pescoço de um fraco careca. Foi incrível. Como meu camarada, você deve entender."
  },
  Voice_5540_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Três"
  },
  Voice_5540_UnlockDesc = {
    Text = "Nível de afinidade atingido 6 desbloqueado"
  },
  Voice_5541_AwakerVoiceContent = {
    Text = "Espere, espere!"
  },
  Voice_5541_AwakerVoiceTitle = {Text = "Acertar·1"},
  Voice_5542_AwakerVoiceContent = {Text = "Não!"},
  Voice_5542_AwakerVoiceTitle = {
    Text = "Acertar · II"
  },
  Voice_5543_AwakerVoiceContent = {Text = "Ai!"},
  Voice_5543_AwakerVoiceTitle = {
    Text = "Acertar·III"
  },
  Voice_5544_AwakerVoiceContent = {Text = "(Gemido)"},
  Voice_5544_AwakerVoiceTitle = {
    Text = "Golpe·Quatro"
  },
  Voice_5545_AwakerVoiceContent = {
    Text = "Buscando \"Dissolução\" no amplo Arquivo... Não necessário? Você deseja saber a minha posição sobre a Dissolução? Entendido. Buscando por \"armas de Dissolução\" no domínio privado do Despertar... Resultado: \"0\"."
  },
  Voice_5545_AwakerVoiceTitle = {
    Text = "Bate-papo · Sobre Dissolução"
  },
  Voice_5546_AwakerVoiceContent = {
    Text = "Objetos falsos, frágeis como poeira, podem ser soprados por uma mera brisa..."
  },
  Voice_5546_AwakerVoiceTitle = {
    Text = "Conversas Ociosas·Sobre Murphy"
  },
  Voice_5546_UnlockDesc = {
    Text = "Desbloqueado após obter Despertador \"Murphy\""
  },
  Voice_5547_AwakerVoiceContent = {
    Text = "Um pouco barulhentos, eles são estudantes?\nEles me lembram de albatrozes. Você conhece essas aves? Energia infinita, jornadas que parecem intermináveis..."
  },
  Voice_5547_AwakerVoiceTitle = {
    Text = "Conversa·Coisas odiadas"
  },
  Voice_5548_AwakerVoiceContent = {Text = "Ha"},
  Voice_5548_AwakerVoiceTitle = {
    Text = "Defesa · I"
  },
  Voice_5549_AwakerVoiceContent = {Text = "Hmph"},
  Voice_5549_AwakerVoiceTitle = {Text = "Defesa·II"},
  Voice_5550_AwakerVoiceContent = {
    Text = "Ramona é a única interessante aqui, talentosa em esgrima. Os outros são todos rígidos... Você é um deles? Você realmente acha que escrever relatórios de missão é divertido?"
  },
  Voice_5550_AwakerVoiceTitle = {
    Text = "Chat·Sobre a Universidade Mythag"
  },
  Voice_5551_AwakerVoiceContent = {
    Text = "Não vale a pena mencionar."
  },
  Voice_5551_AwakerVoiceTitle = {
    Text = "Investigação Bem-sucedida"
  },
  Voice_5552_AwakerVoiceContent = {
    Text = "As mães não são todas iguais. Algumas são boas, e outras são más.\nA Mestra é uma boa mãe."
  },
  Voice_5552_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Quatro"
  },
  Voice_5552_UnlockDesc = {
    Text = "Nível de afinidade atingido 8 desbloqueado"
  },
  Voice_5553_AwakerVoiceContent = {
    Text = "Sinto muito por não ter conseguido protegê-lo..."
  },
  Voice_5553_AwakerVoiceTitle = {
    Text = "Investigação Interrompida"
  },
  Voice_5554_AwakerVoiceContent = {
    Text = "Você reservou o local? Precisa ser um jardim maior que 150 metros quadrados!"
  },
  Voice_5554_AwakerVoiceTitle = {
    Text = "Iluminar·Visão Remota"
  },
  Voice_5554_UnlockDesc = {
    Text = "Nível de iluminação atingiu 1 para desbloquear"
  },
  Voice_5555_AwakerVoiceContent = {
    Text = "O sangue dos moribundos é um líquido escorregadio. Com apenas um leve corte no pescoço, o sangue flui entre os dentes, transformando-se em correntes quentes que lentamente preenchem meu ventre... Heh, delicioso."
  },
  Voice_5555_AwakerVoiceTitle = {
    Text = "Fala Ociosa · Sobre Sangue"
  },
  Voice_5556_AwakerVoiceContent = {Text = "Ah"},
  Voice_5556_AwakerVoiceTitle = {
    Text = "Habilidade Especial · Um"
  },
  Voice_5557_AwakerVoiceContent = {Text = "Oi!"},
  Voice_5557_AwakerVoiceTitle = {
    Text = "Habilidade Especial · Um"
  },
  Voice_5558_AwakerVoiceContent = {Text = "Ei"},
  Voice_5558_AwakerVoiceTitle = {
    Text = "Habilidade Especial · Um"
  },
  Voice_5559_AwakerVoiceContent = {
    Text = "Obrigado pela sua bondade em me oferecer abrigo. Espero que não traga um destino trágico a você..."
  },
  Voice_5559_AwakerVoiceTitle = {
    Text = "Conversa·Sobre Guardião do Segredo"
  },
  Voice_5560_AwakerVoiceContent = {
    Text = "Eu venho de um planeta alienígena distante, um lugar de tempestades de neve implacáveis e frio extremo. Mas está tudo bem; em minha mansão, mais de mil servos oferecem calor reconfortante através de seu contato."
  },
  Voice_5560_AwakerVoiceTitle = {
    Text = "Conversas Ociosas·Sobre o Passado"
  },
  Voice_5561_AwakerVoiceContent = {
    Text = "Não posso cair aqui antes do seu retorno."
  },
  Voice_5561_AwakerVoiceTitle = {
    Text = "Exaltar · Dois"
  },
  Voice_5562_AwakerVoiceContent = {
    Text = "Não posso cair aqui antes do seu retorno."
  },
  Voice_5562_AwakerVoiceTitle = {
    Text = "Fúria Explosiva"
  },
  Voice_5563_AwakerVoiceContent = {
    Text = "Oh, como pode haver um convidado tão arrogante no mundo, querendo \"a arma mais poderosa do mundo\"? Eu disse a ele que precisaria de uma cabeça ensopada em ódio para trocá-la, e ele saiu emburrado..."
  },
  Voice_5563_AwakerVoiceTitle = {
    Text = "Bate-papo · Sobre Golias"
  },
  Voice_5563_UnlockDesc = {
    Text = "Após obter o despertador \"Golias\", desbloqueado"
  },
  Voice_5564_AwakerVoiceContent = {
    Text = "Seu olhar confiante, como se você estivesse sempre pronto para \"salvar o mundo\", faz minhas articulações coçarem só de olhar para isso."
  },
  Voice_5564_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Um"
  },
  Voice_5564_UnlockDesc = {
    Text = "Nível de afinidade atingido 2 desbloqueado"
  },
  Voice_5565_AwakerVoiceContent = {
    Text = "Justo antes de a proibição de pesquisas ser imposta, eu estava prestes a permitir que a aniquilação engolisse este chamado santuário da Dissolução... Que pena."
  },
  Voice_5565_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Dois"
  },
  Voice_5565_UnlockDesc = {
    Text = "Nível de afinidade atingido 4 desbloqueado"
  },
  Voice_5566_AwakerVoiceContent = {
    Text = "Sim, tenho incontáveis corpos e escape da dissolução. Mas busquei a verdade, e não me arrependo"
  },
  Voice_5566_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Três"
  },
  Voice_5566_UnlockDesc = {
    Text = "Nível de afinidade atingido 6 desbloqueado"
  },
  Voice_5567_AwakerVoiceContent = {
    Text = "A verdade do mundo, seu começo e seu fim—tudo sem sentido. Se você deseja trilhar o caminho para a verdade, não me importo em ser seu guia... assim como antes."
  },
  Voice_5567_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Quatro"
  },
  Voice_5567_UnlockDesc = {
    Text = "Nível de afinidade atingido 8 desbloqueado"
  },
  Voice_5568_AwakerVoiceContent = {
    Text = "Você pode ser capaz de me parar, mas o fim é inevitável... Eu salvarei esta escola — e você — por último. Juntos, nos banharemos no crepúsculo do tempo no alto da torre, testemunhando a queda da civilização... O que você acha? Desta forma, nosso vínculo não terá sido em vão, certo?"
  },
  Voice_5568_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Cinco"
  },
  Voice_5568_UnlockDesc = {
    Text = "Nível de afinidade atingido 10 desbloqueado"
  },
  Voice_5569_AwakerVoiceContent = {Text = "Certo."},
  Voice_5569_AwakerVoiceTitle = {Text = "Ataque·Um"},
  Voice_5570_AwakerVoiceContent = {
    Text = "Desaparecer."
  },
  Voice_5570_AwakerVoiceTitle = {Text = "Ataque·II"},
  Voice_5571_AwakerVoiceContent = {
    Text = "Que minhas orações sejam o sino da manhã que desperta a pátria..."
  },
  Voice_5571_AwakerVoiceTitle = {
    Text = "Investigação Bem-sucedida"
  },
  Voice_5572_AwakerVoiceContent = {
    Text = "Eu nunca pensei que alguém além de Tinta me aceitaria. Estou feliz por ter te conhecido, Guardião. Farei o meu melhor para aprender a controlar meu poder, para que quando eu te abrace, eu não drene sua força vital... Um abraço, certo? A forma humana de expressar gratidão?"
  },
  Voice_5572_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Cinco"
  },
  Voice_5572_UnlockDesc = {
    Text = "Nível de afinidade atingido 10 desbloqueado"
  },
  Voice_5573_AwakerVoiceContent = {
    Text = "Se eu ficar aqui, não preciso pagar nada? Eu posso ajudar você a ganhar status aqui. Basta ameaçar drenar a vida deles—é simples, como o que eu fiz por Tinta... Ah! Não conte a ninguém sobre isso!"
  },
  Voice_5573_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Quatro"
  },
  Voice_5573_UnlockDesc = {
    Text = "Nível de afinidade atingido 8 desbloqueado"
  },
  Voice_5574_AwakerVoiceContent = {
    Text = "Desculpe, eu não sou como os outros... Eu sou imperfeito."
  },
  Voice_5574_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Um"
  },
  Voice_5574_UnlockDesc = {
    Text = "Nível de afinidade atingido 2 desbloqueado"
  },
  Voice_5575_AwakerVoiceContent = {
    Text = "Uma criada habilidosa pode aprimorar muito o salão, mas uma criada azul-esverdeada... deixe-me reconsiderar..."
  },
  Voice_5575_AwakerVoiceTitle = {
    Text = "Chat·Sobre Karen"
  },
  Voice_5575_UnlockDesc = {
    Text = "Após obter o despertador \"Karen\", desbloqueado"
  },
  Voice_5576_AwakerVoiceContent = {
    Text = "A Tinta é minha irmã gêmea. Ao contrário de mim, ela sempre brilha intensamente...\nSem meu arrasto, ela teria um futuro mais brilhante, sua canção ecoando por toda a galáxia..."
  },
  Voice_5576_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Três"
  },
  Voice_5576_UnlockDesc = {
    Text = "Nível de afinidade atingido 6 desbloqueado"
  },
  Voice_5577_AwakerVoiceContent = {
    Text = "O berço é apertado, sem espaço para esticar meu corpo... Mas Tinta disse que, para a segurança de todos, eu deveria permanecer no berço... Já que esse é o desejo dela, eu obedecerei."
  },
  Voice_5577_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Dois"
  },
  Voice_5577_UnlockDesc = {
    Text = "Nível de afinidade atingido 4 desbloqueado"
  },
  Voice_5578_AwakerVoiceContent = {
    Text = "Frequentemente sinto como se existisse na lacuna entre a vida e a morte. Onde quer que eu esteja, a melancolia se espalha como uma maré, e tragédias se desenrolam uma após a outra. Mesmo assim, você ainda gostaria que eu escrevesse um poema para você? Hmm... talvez você mereça o mais doce..."
  },
  Voice_5578_AwakerVoiceTitle = {
    Text = "Iluminar·Florescer"
  },
  Voice_5578_UnlockDesc = {
    Text = "Nível de iluminação atingiu 15 para desbloquear"
  },
  Voice_5579_AwakerVoiceContent = {
    Text = "\"As rosas ainda não floresceram, mas a aurora está se aproximando.\""
  },
  Voice_5579_AwakerVoiceTitle = {
    Text = "Iluminar·Construção"
  },
  Voice_5579_UnlockDesc = {
    Text = "Nível de iluminação atingiu 11 para desbloquear"
  },
  Voice_5580_AwakerVoiceContent = {
    Text = "O que você anseia? É a beleza das palavras elegantes, a fama amplamente difundida, ou a sinceridade genuína por trás dessas palavras?"
  },
  Voice_5580_AwakerVoiceTitle = {
    Text = "Iluminar: Insight"
  },
  Voice_5580_UnlockDesc = {
    Text = "Nível de iluminação atingiu 7 para desbloquear"
  },
  Voice_5581_AwakerVoiceContent = {
    Text = "Com tinta invisível, esboce os botões deformados... Este galho de rosa fantasmagórico e etéreo pode realmente inspirar uma inspiração poética..."
  },
  Voice_5581_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexão"
  },
  Voice_5581_UnlockDesc = {
    Text = "Nível de iluminação atingiu 3 para desbloquear"
  },
  Voice_55825_AwakerVoiceContent = {
    Text = "Ouça meu Senhor."
  },
  Voice_55825_AwakerVoiceTitle = {
    Text = "Despertar · II"
  },
  Voice_55826_AwakerVoiceContent = {
    Text = "Sacrifique! Reformule o Reino de Deus—"
  },
  Voice_55826_AwakerVoiceTitle = {
    Text = "Despertar III"
  },
  Voice_5582_AwakerVoiceContent = {
    Text = "Se você insistir, eu voltarei para a luz do sol... a mesma luz do sol do dia em que deixei Cité..."
  },
  Voice_5582_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_5582_UnlockDesc = {
    Text = "Nível de iluminação atingiu 2 para desbloquear"
  },
  Voice_5583_AwakerVoiceContent = {
    Text = "Hehe, você quer ver um universo em destruição? Eh, é tarde demais para recuar agora!"
  },
  Voice_5583_AwakerVoiceTitle = {
    Text = "Iluminar·Florescer"
  },
  Voice_5583_UnlockDesc = {
    Text = "Nível de iluminação atingiu 15 para desbloquear"
  },
  Voice_5584_AwakerVoiceContent = {
    Text = "Beba, o doce sabor da morte."
  },
  Voice_5584_AwakerVoiceTitle = {
    Text = "Fúria Explosiva"
  },
  Voice_5585_AwakerVoiceContent = {
    Text = "Beba, o doce sabor da morte."
  },
  Voice_5585_AwakerVoiceTitle = {
    Text = "Exaltar · Dois"
  },
  Voice_5586_AwakerVoiceContent = {
    Text = "Isso é suficiente!"
  },
  Voice_5586_AwakerVoiceTitle = {
    Text = "Habilidade·Um"
  },
  Voice_5587_AwakerVoiceContent = {Text = "Não..."},
  Voice_5587_AwakerVoiceTitle = {
    Text = "Acertar · II"
  },
  Voice_5588_AwakerVoiceContent = {
    Text = "Eis a majestade de Yu."
  },
  Voice_5588_AwakerVoiceTitle = {
    Text = "Despertar do Conhecimento Espiritual"
  },
  Voice_5589_AwakerVoiceContent = {
    Text = "O ar no campus às 4 da manhã é refrescante. Estou feliz que você esteja disposto a se exercitar comigo. Devo dizer, esculpir é um bom treino."
  },
  Voice_5589_AwakerVoiceTitle = {
    Text = "Conversa Informal·Sobre a Manhã"
  },
  Voice_5590_AwakerVoiceContent = {
    Text = "Este poder se sente muito bem para usar."
  },
  Voice_5590_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_5590_UnlockDesc = {
    Text = "Nível de iluminação atingiu 2 para desbloquear"
  },
  Voice_5591_AwakerVoiceContent = {
    Text = "Eu odeio pessoas que não pagam pelo que compram. Se você gerencia uma loja o suficiente, encontrará esse tipo de problema. Não tenho escolha a não ser lidar com isso eu mesmo e recuperar a conta~"
  },
  Voice_5591_AwakerVoiceTitle = {
    Text = "Conversa·Coisas odiadas"
  },
  Voice_5592_AwakerVoiceContent = {
    Text = "Tortura lentamente."
  },
  Voice_5592_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_5593_AwakerVoiceContent = {
    Text = "Tortura lentamente."
  },
  Voice_5593_AwakerVoiceTitle = {
    Text = "Carta de Habilidade·Quatro"
  },
  Voice_5594_AwakerVoiceContent = {Text = "Carregar."},
  Voice_5594_AwakerVoiceTitle = {
    Text = "Habilidade·Um"
  },
  Voice_5595_AwakerVoiceContent = {Text = "Iniciar."},
  Voice_5595_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_5596_AwakerVoiceContent = {
    Text = "Deixe este lugar se tornar um mar de empolgação para todos!"
  },
  Voice_5596_AwakerVoiceTitle = {
    Text = "Fúria Explosiva"
  },
  Voice_5597_AwakerVoiceContent = {
    Text = "O que? Você espera que eu te agradeça?"
  },
  Voice_5597_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · I"
  },
  Voice_5598_AwakerVoiceContent = {
    Text = "Como um tributo, isso está longe de ser adequado... mas à luz de sua sinceridade, eu o aceitarei relutantemente."
  },
  Voice_5598_AwakerVoiceTitle = {
    Text = "Atualizar·II"
  },
  Voice_5599_AwakerVoiceContent = {
    Text = "Você realmente achou que isso me faria ouvir você?"
  },
  Voice_5599_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · Três"
  },
  Voice_5600_AwakerVoiceContent = {Text = "Hah!"},
  Voice_5600_AwakerVoiceTitle = {Text = "Ataque·Um"},
  Voice_5601_AwakerVoiceContent = {Text = "Vá!"},
  Voice_5601_AwakerVoiceTitle = {Text = "Ataque·Um"},
  Voice_5602_AwakerVoiceContent = {
    Text = "Monstros ingratos, assassinos e matadores—eles têm algum valor que você reconhece? Monstro."
  },
  Voice_5602_AwakerVoiceTitle = {
    Text = "Iluminar·Construção"
  },
  Voice_5602_UnlockDesc = {
    Text = "Nível de iluminação atingiu 11 para desbloquear"
  },
  Voice_5603_AwakerVoiceContent = {
    Text = "Não importa quantas almofadas você empilhe, um trono de lápis-lazúli não pode se comparar a uma cama de penas. Nesse aspecto, há algo louvável em seu lugar."
  },
  Voice_5603_AwakerVoiceTitle = {
    Text = "Chat·Sobre a Universidade Mythag"
  },
  Voice_5604_AwakerVoiceContent = {
    Text = "Uma punição leve."
  },
  Voice_5604_AwakerVoiceTitle = {
    Text = "Habilidade·Um"
  },
  Voice_5605_AwakerVoiceContent = {
    Text = "Eu odeio a solidão, odeio me preocupar com os sentimentos de alguém em uma escuridão sem fim... Então, por favor, não me abandone, tá?"
  },
  Voice_5605_AwakerVoiceTitle = {
    Text = "Conversa·Coisas odiadas"
  },
  Voice_5606_AwakerVoiceContent = {
    Text = "Se eu fosse você, trancaria todos os Despertadores em gaiolas! Uma vez que cães loucos se libertem, eles sempre mordem seus donos primeiro."
  },
  Voice_5606_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Três"
  },
  Voice_5606_UnlockDesc = {
    Text = "Nível de afinidade atingido 6 desbloqueado"
  },
  Voice_5607_AwakerVoiceContent = {
    Text = "Eu cheguei uma hora atrasado para essa reunião—culpe aqueles bonzinhos que aboliram a escravidão! Agora não há ninguém para pentear meu cabelo para mim!"
  },
  Voice_5607_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Dois"
  },
  Voice_5607_UnlockDesc = {
    Text = "Nível de afinidade atingido 4 desbloqueado"
  },
  Voice_5608_AwakerVoiceContent = {
    Text = "Inacreditável, minha casa pereceu assim... Aquela era a grande Roma! Você deve ter ouvido falar dela!"
  },
  Voice_5608_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Um"
  },
  Voice_5608_UnlockDesc = {
    Text = "Nível de afinidade atingido 2 desbloqueado"
  },
  Voice_5609_AwakerVoiceContent = {
    Text = "Vamos, vamos começar com uma vitória!"
  },
  Voice_5609_AwakerVoiceTitle = {
    Text = "Início da Investigação"
  },
  Voice_5610_AwakerVoiceContent = {
    Text = "Esta é a bênção do meu senhor."
  },
  Voice_5610_AwakerVoiceTitle = {
    Text = "Despertar do Conhecimento Espiritual"
  },
  Voice_5611_AwakerVoiceContent = {
    Text = "Guarde sua pena para si mesmo. Eu não gosto e não preciso da simpatia de ninguém. Se você continuar me olhando assim, pode ser que eu não consiga resistir a atormentá-lo... Você não quer que as coisas saiam do controle, quer? Então seja um bom menino/menina, ouça e obedientemente torne-se meu gladiador."
  },
  Voice_5611_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Cinco"
  },
  Voice_5611_UnlockDesc = {
    Text = "Nível de afinidade atingido 10 desbloqueado"
  },
  Voice_5612_AwakerVoiceContent = {
    Text = "Não *silencie* pergunte novamente. Fui descuidado, deixei o gladiador escapar e toda a minha família foi morta! Assim como o Império Romano agora, reduzido a cinzas!"
  },
  Voice_5612_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Quatro"
  },
  Voice_5612_UnlockDesc = {
    Text = "Nível de afinidade atingido 8 desbloqueado"
  },
  Voice_5613_AwakerVoiceContent = {
    Text = "Comparado aos outros, Nínfea é apenas uma pessoa comum, sem conquistas ou valor.\nO que me despertou... pode ser alguns pequenos e humildes desejos."
  },
  Voice_5613_AwakerVoiceTitle = {
    Text = "Chat·Sobre a Universidade Mythag"
  },
  Voice_5614_AwakerVoiceContent = {
    Text = "Hoje, quebrei as regras da escola novamente ao chegar cinco minutos atrasado para a aula... Portanto, solicito sinceramente a punição mais severa, preferencialmente realizada pelo guardião."
  },
  Voice_5614_AwakerVoiceTitle = {
    Text = "Chat·Sobre a Universidade Mythag"
  },
  Voice_5615_AwakerVoiceContent = {
    Text = "As ferramentas também precisam de manutenção. Um conjunto prático de ferramentas é a alma de um mecânico."
  },
  Voice_5615_AwakerVoiceTitle = {
    Text = "Iluminar·Visão Remota"
  },
  Voice_5615_UnlockDesc = {
    Text = "Nível de iluminação atingiu 1 para desbloquear"
  },
  Voice_5616_AwakerVoiceContent = {
    Text = "(Resistência desdenhosa)"
  },
  Voice_5616_AwakerVoiceTitle = {
    Text = "Acertar · II"
  },
  Voice_5617_AwakerVoiceContent = {
    Text = "Se acontecer de novo, vou solicitar uma suspensão disciplinar para você."
  },
  Voice_5617_AwakerVoiceTitle = {
    Text = "Investigação Interrompida"
  },
  Voice_5618_AwakerVoiceContent = {
    Text = "Além de lutar, eu tenho outros trabalhos a fazer. Mesmo na Era Arqueana, eu não fiquei ocioso... Ei, você realmente acha que eu sou apenas um brutamontes que só sabe lutar, não é?"
  },
  Voice_5618_AwakerVoiceTitle = {
    Text = "Conversa Informal: Sobre Trabalho"
  },
  Voice_5619_AwakerVoiceContent = {
    Text = "Quando as pessoas se aproximam de mim, sempre lembram suas memórias mais tristes e não conseguem evitar derramar lágrimas. Alguém como eu ainda pode crescer?"
  },
  Voice_5619_AwakerVoiceTitle = {
    Text = "Iluminar·Visão Remota"
  },
  Voice_5619_UnlockDesc = {
    Text = "Nível de iluminação atingiu 1 para desbloquear"
  },
  Voice_5620_AwakerVoiceTitle = {
    Text = "Golpe·Quatro"
  },
  Voice_5621_AwakerVoiceContent = {
    Text = "Está correto?"
  },
  Voice_5621_AwakerVoiceTitle = {Text = "Defesa·II"},
  Voice_5622_AwakerVoiceContent = {
    Text = "Este lugar é muito melhor do que a prisão podre e fedorenta de New Gate! Seja deitando no sofá ou espremido em um canto, tudo é bastante confortável, não é?"
  },
  Voice_5622_AwakerVoiceTitle = {
    Text = "Chat·Sobre a Universidade Mythag"
  },
  Voice_5623_AwakerVoiceContent = {Text = "Brown...!"},
  Voice_5623_AwakerVoiceTitle = {Text = "Acertar·1"},
  Voice_5624_AwakerVoiceContent = {
    Text = "Shell, para onde foi"
  },
  Voice_5624_AwakerVoiceTitle = {
    Text = "Carta de Habilidade·Quatro"
  },
  Voice_5625_AwakerVoiceContent = {Text = "Astuto!"},
  Voice_5625_AwakerVoiceTitle = {
    Text = "Acertar · II"
  },
  Voice_5626_AwakerVoiceContent = {
    Text = "Para onde foi a concha espiral?!"
  },
  Voice_5626_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_5627_AwakerVoiceContent = {
    Text = "A fluente Via Láctea..."
  },
  Voice_5627_AwakerVoiceTitle = {
    Text = "Despertar do Conhecimento Espiritual"
  },
  Voice_5628_AwakerVoiceContent = {
    Text = "Aurita não gosta que os amigos partam de repente... Mas, se eles voltarem, Aurita os perdoará!"
  },
  Voice_5628_AwakerVoiceTitle = {
    Text = "Conversa·Coisas odiadas"
  },
  Voice_5629_AwakerVoiceContent = {
    Text = "Uma mulher que navega sozinha pelo mar é uma deusa ou uma louca. Confundir Miryam com uma deusa foi um grave erro."
  },
  Voice_5629_AwakerVoiceTitle = {
    Text = "Chat·Sobre Miryam"
  },
  Voice_5629_UnlockDesc = {
    Text = "Após obter o despertador \"Miryam\", desbloqueado"
  },
  Voice_5630_AwakerVoiceContent = {
    Text = "...Tá bom!"
  },
  Voice_5630_AwakerVoiceTitle = {
    Text = "Habilidade Especial · Um"
  },
  Voice_56313_AwakerVoiceContent = {
    Text = "Eu observei secretamente a mágica da Senhorita Casiah. Sua apresentação trouxe alegria ao público, mas eu sempre trago tristeza... Você acha que lágrimas e sorrisos são igualmente preciosos? Talvez..."
  },
  Voice_56313_AwakerVoiceTitle = {
    Text = "Bate-papo · Sobre Casiah"
  },
  Voice_56313_UnlockDesc = {
    Text = "Desbloqueia ao obter o despertador \"Casiah\""
  },
  Voice_56314_AwakerVoiceContent = {
    Text = "Poesia, chamas e tristeza são semelhantes; eles te consomem sem aviso... Quando você percebe, já está imerso no mundo da poesia..."
  },
  Voice_56314_AwakerVoiceTitle = {
    Text = "Conversa·Coisas favoritas"
  },
  Voice_56315_AwakerVoiceContent = {
    Text = "Deixe os poemas do passado despertarem o jardim oculto em seu coração."
  },
  Voice_56315_AwakerVoiceTitle = {
    Text = "Superexaltação"
  },
  Voice_56316_AwakerVoiceContent = {
    Text = "Poesia e flores são provavelmente a mesma coisa, não são? Ambas são efêmeras e eternas. Neste mundo sem limites, capturam os momentos mais inesquecíveis em um pequeno espaço... Eu acho que todos já ficaram em silêncio por um poema, assim como param para admirar a floração de uma flor."
  },
  Voice_56316_AwakerVoiceTitle = {
    Text = "Conversas Ociosas: Sobre Poesia"
  },
  Voice_56317_AwakerVoiceContent = {
    Text = "Eu quase esqueci... Que tipo de flores florescem na Cité nesta temporada?"
  },
  Voice_56317_AwakerVoiceTitle = {
    Text = "Conversas Ociosas: Sobre Cité"
  },
  Voice_56318_AwakerVoiceContent = {
    Text = "Sua presença reacendeu a tinta na minha caneta, permitindo que fluísse mais uma vez como um suave riacho. Continuarei a escrever poesia para sua história."
  },
  Voice_56318_AwakerVoiceTitle = {
    Text = "Conversas Ociosas: Sobre o Guardião 1"
  },
  Voice_56319_AwakerVoiceContent = {
    Text = "A beleza das flores em flor é igualada à tristeza de seu murchar. Não importa quantas vezes eu sinta pena, não posso deixar de parar e lamentar por elas. Se eu as ignorasse por medo da dor, quão tristes estariam essas flores..."
  },
  Voice_56319_AwakerVoiceTitle = {
    Text = "Conversa Ociosa: Sobre o Sofrimento"
  },
  Voice_5631_AwakerVoiceContent = {
    Text = "Para pesquisar a estrutura interna deste corpo enquanto Erica está \"dormindo\", Winkle solicitou que eu descansasse em seu escritório à noite.\nDevo mencionar que Erica retém uma parte de sua consciência enquanto está adormecida?"
  },
  Voice_5631_AwakerVoiceTitle = {
    Text = "Bate-Papo·Sobre Búzio"
  },
  Voice_5631_UnlockDesc = {
    Text = "Após obter o despertador \"Búzio\", desbloqueado"
  },
  Voice_56320_AwakerVoiceContent = {
    Text = "A Senhora Vermelha é realmente bonita. Sua força e confiança, seu sorriso gracioso frente ao destino, e sua força vital vibrante, mas resoluta, tudo isso me enche de inveja"
  },
  Voice_56320_AwakerVoiceTitle = {
    Text = "Conversa Informal·Sobre Sorel"
  },
  Voice_56320_UnlockDesc = {
    Text = "Desbloqueado após obter Despertar\"Sorel\""
  },
  Voice_56321_AwakerVoiceContent = {
    Text = "Eu escrevi um novo poema ontem, mas não mostrei a ninguém. Não é muito bom, mas... Guardião, você estaria disposto a dar uma olhada nele?"
  },
  Voice_56321_AwakerVoiceTitle = {
    Text = "Conversa Ociosa: Sobre o Guardião 2"
  },
  Voice_56322_AwakerVoiceContent = {
    Text = "O Clube de Poesia dos Estudantes quer que eu seja seu conselheiro... Não posso concordar. Não quero abafar seu entusiasmo, mas apenas traria decepção e desencorajamento."
  },
  Voice_56322_AwakerVoiceTitle = {
    Text = "Chat·Sobre a Universidade Mythag"
  },
  Voice_56323_AwakerVoiceContent = {
    Text = "Não há nada para odiar neste mundo. Os anos dourados merecem louvor, enquanto o declínio da velhice merece pena; o esplendor da juventude é invejável, enquanto os restos desgastados evocam reflexão."
  },
  Voice_56323_AwakerVoiceTitle = {
    Text = "Conversa·Coisas odiadas"
  },
  Voice_56324_AwakerVoiceContent = {
    Text = "Toda vez que vejo a Senhorita Nínfea, penso naquela pintura de lírios d'água. Ela carrega a tranquila amargura e o perfume dos lírios d'água... Pergunto-me como é o mundo dela?"
  },
  Voice_56324_AwakerVoiceTitle = {
    Text = "Conversa Ociosa: Sobre Nínfea"
  },
  Voice_56324_UnlockDesc = {
    Text = "Desbloqueia ao obter o despertador \"Nínfea\""
  },
  Voice_56325_AwakerVoiceContent = {
    Text = "Eu sempre senti a presença de \"fantasmas\" ao meu redor, como se alguma possessão inexplicável ou feitiço estivesse drenando minha esperança no mundo. Mas se for um fantasma, como você explica o leite e a água desaparecendo no ar...?"
  },
  Voice_56325_AwakerVoiceTitle = {
    Text = "Conversa Casual · Sobre Fantasmas"
  },
  Voice_56326_AwakerVoiceContent = {
    Text = "Meu corpo não foi afetado pela Dissolução; aqueles líquidos negros são apenas tinta. Mas honestamente, mesmo sem a Dissolução, tudo eventualmente se transforma em Ilusão, não é?"
  },
  Voice_56326_AwakerVoiceTitle = {
    Text = "Bate-papo · Sobre Dissolução"
  },
  Voice_56327_AwakerVoiceContent = {
    Text = "Na lápide da Chave do Túmulo, vi o nome do Guardião... As memórias da vida eram dolorosas, mas nunca tive a intenção de esquecê-las. Para o Guardião, aquelas memórias perdidas devem ser igualmente preciosas, certo?"
  },
  Voice_56327_AwakerVoiceTitle = {
    Text = "Conversas Ociosas: Sobre Memória"
  },
  Voice_56328_AwakerVoiceContent = {
    Text = "Se a poesia existe para louvar a beleza, então sua existência é como poesia em si. Quando ela começa a cantar, eu de repente entendo o que os antigos descreviam como a voz de um rouxinol..."
  },
  Voice_56328_AwakerVoiceTitle = {
    Text = "Chit-chat·Sobre a Tinta"
  },
  Voice_56328_UnlockDesc = {
    Text = "Após obter o despertador \"Tinta\", desbloqueado"
  },
  Voice_56329_AwakerVoiceContent = {
    Text = "A bela dançarina... Suas chamas verde-esmeralda são irresistíveis, mesmo que queimem uma pessoa até as cinzas..."
  },
  Voice_56329_AwakerVoiceTitle = {
    Text = "Conversa Informal: Sobre Liz"
  },
  Voice_56329_UnlockDesc = {
    Text = "Desbloqueado após adquirir o Despertar \"Liz\""
  },
  Voice_5632_AwakerVoiceContent = {
    Text = "Substitua a absorção da essência primal desta maneira?"
  },
  Voice_5632_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · I"
  },
  Voice_5633_AwakerVoiceContent = {
    Text = "Delicioso, absolutamente delicioso."
  },
  Voice_5633_AwakerVoiceTitle = {
    Text = "Atualizar·II"
  },
  Voice_5634_AwakerVoiceContent = {
    Text = "Convidado, que tipo de recompensa você gostaria?"
  },
  Voice_5634_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · Três"
  },
  Voice_5635_AwakerVoiceContent = {
    Text = "Apresse-se e termine. Não demore nas ruas."
  },
  Voice_5635_AwakerVoiceTitle = {
    Text = "Início da Investigação"
  },
  Voice_5636_AwakerVoiceContent = {
    Text = "Sacrifício Iminente"
  },
  Voice_5636_AwakerVoiceTitle = {
    Text = "Carta de Habilidade·Quatro"
  },
  Voice_5637_AwakerVoiceContent = {
    Text = "(Um gemido abafado de resistência)"
  },
  Voice_5637_AwakerVoiceTitle = {
    Text = "Golpe·Quatro"
  },
  Voice_56386_AwakerVoiceContent = {
    Text = "Entrada atual completa. Emitindo corrente."
  },
  Voice_56386_AwakerVoiceTitle = {
    Text = "Superexaltação"
  },
  Voice_56387_AwakerVoiceContent = {
    Text = "Não subestime o melhor ladrão de rua!"
  },
  Voice_56387_AwakerVoiceTitle = {
    Text = "Superexaltação"
  },
  Voice_56388_AwakerVoiceContent = {
    Text = "Aqui vem a homenagem de abertura!"
  },
  Voice_56388_AwakerVoiceTitle = {
    Text = "Superexaltação"
  },
  Voice_56389_AwakerVoiceContent = {
    Text = "A Miragem Milenar aparece aqui!"
  },
  Voice_56389_AwakerVoiceTitle = {
    Text = "Superexaltação"
  },
  Voice_5638_AwakerVoiceContent = {
    Text = "Chegando mais perto..."
  },
  Voice_5638_AwakerVoiceTitle = {
    Text = "Iluminar·Visão Remota"
  },
  Voice_5638_UnlockDesc = {
    Text = "Nível de iluminação atingiu 1 para desbloquear"
  },
  Voice_56390_AwakerVoiceContent = {
    Text = "Afunde e queime! Dança para a destruição!"
  },
  Voice_56390_AwakerVoiceTitle = {
    Text = "Superexaltação"
  },
  Voice_56391_AwakerVoiceContent = {
    Text = "Esta é a cidade onde inúmeras almas perdidas vagam, incapazes de encontrar o caminho de casa."
  },
  Voice_56391_AwakerVoiceTitle = {
    Text = "Superexaltação"
  },
  Voice_56392_AwakerVoiceContent = {
    Text = "Deixe-me dar-lhe minha energia de transferência restante...!"
  },
  Voice_56392_AwakerVoiceTitle = {
    Text = "Superexaltação"
  },
  Voice_56393_AwakerVoiceContent = {
    Text = "Não subestime o melhor ladrão de rua!"
  },
  Voice_56393_AwakerVoiceTitle = {
    Text = "Sobre-Exaltação Aliemus Explosão·II"
  },
  Voice_5639_AwakerVoiceContent = {
    Text = "É um inimigo? Por favor, me dê o comando de ataque.\nA gosma negra é um inimigo... Lily também é uma inimiga?"
  },
  Voice_5639_AwakerVoiceTitle = {
    Text = "Bate-papo · Sobre Dissolução"
  },
  Voice_5640_AwakerVoiceContent = {
    Text = "Erica, o Autômato, Torso nº EA307881, Motor nº MF311028. Delighted em estar à sua disposição."
  },
  Voice_5640_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_5641_AwakerVoiceContent = {
    Text = "Lutem com todas as suas forças até que o inimigo esteja completamente derrotado!"
  },
  Voice_5641_AwakerVoiceTitle = {
    Text = "Início da Investigação"
  },
  Voice_5642_AwakerVoiceContent = {
    Text = "Olá, eu sou... Você pode me dizer meu nome?"
  },
  Voice_5642_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_5643_AwakerVoiceContent = {
    Text = "Após chegar à escola, passei a compreender a doença chamada Dissolução que havia me infectado. Meus pais sempre me afastaram do oceano enquanto eu estava vivo, e agora parece que essa infecção pode de fato estar ligada à minha proximidade com o mar..."
  },
  Voice_5643_AwakerVoiceTitle = {
    Text = "Bate-papo · Sobre Dissolução"
  },
  Voice_5644_AwakerVoiceContent = {
    Text = "Certo, eu não vou \"decepcioná-lo.\""
  },
  Voice_5644_AwakerVoiceTitle = {
    Text = "Início da Investigação"
  },
  Voice_5645_AwakerVoiceContent = {
    Text = "Esse hálito escaldante—"
  },
  Voice_5645_AwakerVoiceTitle = {
    Text = "Exaltar · Dois"
  },
  Voice_5646_AwakerVoiceContent = {Text = "Vá."},
  Voice_5646_AwakerVoiceTitle = {Text = "Ataque·Um"},
  Voice_5647_AwakerVoiceContent = {Text = "Gire."},
  Voice_5647_AwakerVoiceTitle = {Text = "Ataque·II"},
  Voice_5648_AwakerVoiceContent = {Text = "Oi!"},
  Voice_5648_AwakerVoiceTitle = {Text = "Ataque·Um"},
  Voice_5650_AwakerVoiceContent = {
    Text = "O dia finalmente chegou..."
  },
  Voice_5650_AwakerVoiceTitle = {
    Text = "Investigação Interrompida"
  },
  Voice_5651_AwakerVoiceContent = {Text = "Ha!"},
  Voice_5651_AwakerVoiceTitle = {Text = "Ataque·Um"},
  Voice_5652_AwakerVoiceContent = {
    Text = "Ainda não terminei... Que tal você se levantar para que eu possa te matar de novo?"
  },
  Voice_5652_AwakerVoiceTitle = {
    Text = "Investigação Bem-sucedida"
  },
  Voice_5654_AwakerVoiceContent = {
    Text = "Guardião, eu preciso falar com você. Antes de alcançarmos a vitória final, algumas pessoas não deveriam ser tão extravagantes. Lembre-se, eu não estou lutando pelas vidas luxuosas de tais pessoas."
  },
  Voice_5654_AwakerVoiceTitle = {
    Text = "Conversa Informal·Sobre Sorel"
  },
  Voice_5654_UnlockDesc = {
    Text = "Desbloqueado após obter Despertar\"Sorel\""
  },
  Voice_5655_AwakerVoiceContent = {
    Text = "Se eu for levado como prisioneiro de guerra, que destino cruel me aguarda?"
  },
  Voice_5655_AwakerVoiceTitle = {
    Text = "Investigação Interrompida"
  },
  Voice_5656_AwakerVoiceContent = {Text = "Veja isso!"},
  Voice_5656_AwakerVoiceTitle = {
    Text = "Defesa · I"
  },
  Voice_5657_AwakerVoiceContent = {Text = "Hmph!"},
  Voice_5657_AwakerVoiceTitle = {
    Text = "Defesa · I"
  },
  Voice_5658_AwakerVoiceContent = {
    Text = "Ufa—tô com sono. Antes de descansarmos, você preparou algum lanche para relaxar?"
  },
  Voice_5658_AwakerVoiceTitle = {
    Text = "Investigação Bem-sucedida"
  },
  Voice_5659_AwakerVoiceContent = {
    Text = "Mãe, você gostaria de tocá-los? Dizem que são muito macios."
  },
  Voice_5659_AwakerVoiceTitle = {
    Text = "Iluminar: Insight"
  },
  Voice_5659_UnlockDesc = {
    Text = "Nível de iluminação atingiu 7 para desbloquear"
  },
  Voice_5660_AwakerVoiceContent = {
    Text = "Hmm hmm hmm, la la la~ Limpando, limpando, eu amo limpar, me sinto ótimo~"
  },
  Voice_5660_AwakerVoiceTitle = {
    Text = "Conversa Informal: Sobre Trabalho"
  },
  Voice_5661_AwakerVoiceContent = {
    Text = "(Gemendo de dor)"
  },
  Voice_5661_AwakerVoiceTitle = {
    Text = "Golpe·Quatro"
  },
  Voice_5662_AwakerVoiceContent = {
    Text = "Hmm... Não é ruim."
  },
  Voice_5662_AwakerVoiceTitle = {Text = "Acertar·1"},
  Voice_5663_AwakerVoiceContent = {
    Text = "(Gemendo de dor)"
  },
  Voice_5663_AwakerVoiceTitle = {
    Text = "Acertar · II"
  },
  Voice_5664_AwakerVoiceContent = {
    Text = "(Gemendo de dor)"
  },
  Voice_5664_AwakerVoiceTitle = {
    Text = "Acertar·III"
  },
  Voice_5665_AwakerVoiceContent = {
    Text = "Raiva Ardente!"
  },
  Voice_5665_AwakerVoiceTitle = {
    Text = "Habilidade Especial · Um"
  },
  Voice_5666_AwakerVoiceContent = {
    Text = "Vi muitos enlouquecerem pela Dissolução. Honestamente, já estou louco o suficiente. A Dissolução não me afetará."
  },
  Voice_5666_AwakerVoiceTitle = {
    Text = "Bate-papo · Sobre Dissolução"
  },
  Voice_5667_AwakerVoiceContent = {
    Text = "Heh~ Hahaha!"
  },
  Voice_5667_AwakerVoiceTitle = {
    Text = "Despertar do Conhecimento Espiritual"
  },
  Voice_5668_AwakerVoiceContent = {
    Text = "Boas ferramentas são metade do sucesso!"
  },
  Voice_5668_AwakerVoiceTitle = {
    Text = "Atualizar·II"
  },
  Voice_5669_AwakerVoiceContent = {
    Text = "Sente-se como se estivesse voltando à vida."
  },
  Voice_5669_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · Três"
  },
  Voice_5670_AwakerVoiceContent = {Text = "Nada mal."},
  Voice_5670_AwakerVoiceTitle = {
    Text = "Atualizar·II"
  },
  Voice_5671_AwakerVoiceContent = {
    Text = "Agora posso balançar com mais força."
  },
  Voice_5671_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · I"
  },
  Voice_5672_AwakerVoiceContent = {
    Text = "Equilibrando a presença, mantendo o progresso da pesquisa e completando as tarefas de ensino. Parece que o experimento de compressão de tempo reverso precisa ser priorizado."
  },
  Voice_5672_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexão"
  },
  Voice_5672_UnlockDesc = {
    Text = "Nível de iluminação atingiu 3 para desbloquear"
  },
  Voice_5673_AwakerVoiceContent = {
    Text = "Um passo mais perto da aventura oficial."
  },
  Voice_5673_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · I"
  },
  Voice_5674_AwakerVoiceContent = {
    Text = "Não deixe ninguém perto da água, ou a chama do seu amor pode ser extinguida!"
  },
  Voice_5674_AwakerVoiceTitle = {
    Text = "Conversa·Coisas odiadas"
  },
  Voice_5675_AwakerVoiceContent = {
    Text = "Lute até o Fim!"
  },
  Voice_5675_AwakerVoiceTitle = {
    Text = "Despertar do Conhecimento Espiritual"
  },
  Voice_5676_AwakerVoiceContent = {
    Text = "Você realmente tem uma coragem notável. Olhe para esses tentáculos—você não tem medo de ser consumido pela loucura?"
  },
  Voice_5676_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Dois"
  },
  Voice_5676_UnlockDesc = {
    Text = "Nível de afinidade atingido 4 desbloqueado"
  },
  Voice_5677_AwakerVoiceContent = {Text = "Ai!"},
  Voice_5677_AwakerVoiceTitle = {Text = "Acertar·1"},
  Voice_5678_AwakerVoiceContent = {Text = "Ai..."},
  Voice_5678_AwakerVoiceTitle = {
    Text = "Acertar·III"
  },
  Voice_5679_AwakerVoiceContent = {
    Text = "Por favor, pare!"
  },
  Voice_5679_AwakerVoiceTitle = {
    Text = "Acertar · II"
  },
  Voice_5680_AwakerVoiceContent = {
    Text = "Você gostaria de tocá-lo? Meu coração bate por causa da sua presença."
  },
  Voice_5680_AwakerVoiceTitle = {
    Text = "Iluminar·Visão Remota"
  },
  Voice_5680_UnlockDesc = {
    Text = "Nível de iluminação atingiu 1 para desbloquear"
  },
  Voice_5681_AwakerVoiceContent = {
    Text = "Eles estão cantando felizes. Obrigado, Mestre."
  },
  Voice_5681_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexão"
  },
  Voice_5681_UnlockDesc = {
    Text = "Nível de iluminação atingiu 3 para desbloquear"
  },
  Voice_5682_AwakerVoiceContent = {
    Text = "Algo está despertando no meu peito... quente e gentil. Lily, as lágrimas de Lily estão quase...\nMãe, vamos celebrar juntos."
  },
  Voice_5682_AwakerVoiceTitle = {
    Text = "Iluminar·Florescer"
  },
  Voice_5682_UnlockDesc = {
    Text = "Nível de iluminação atingiu 15 para desbloquear"
  },
  Voice_5683_AwakerVoiceContent = {
    Text = "Estar com minha mãe me enche de uma sensação de felicidade."
  },
  Voice_5683_AwakerVoiceTitle = {
    Text = "Iluminar·Construção"
  },
  Voice_5683_UnlockDesc = {
    Text = "Nível de iluminação atingiu 11 para desbloquear"
  },
  Voice_5684_AwakerVoiceContent = {
    Text = "Estou cheio... Meu estômago está cheio.\nLily vai ficar mais forte após o ritual?"
  },
  Voice_5684_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_5684_UnlockDesc = {
    Text = "Nível de iluminação atingiu 2 para desbloquear"
  },
  Voice_5685_AwakerVoiceContent = {
    Text = "Eu amo o mar. É irônico? Porque tudo que possuía agora está submerso em Aequor..."
  },
  Voice_5685_AwakerVoiceTitle = {
    Text = "Conversa·Coisas favoritas"
  },
  Voice_5686_AwakerVoiceContent = {Text = "Cuidado!"},
  Voice_5686_AwakerVoiceTitle = {
    Text = "Defesa · I"
  },
  Voice_5687_AwakerVoiceContent = {
    Text = "Coisas que eu odeio...? Nenhuma. Você odiaria uma gota de poeira ou uma folha?"
  },
  Voice_5687_AwakerVoiceTitle = {
    Text = "Conversa·Coisas odiadas"
  },
  Voice_5688_AwakerVoiceContent = {
    Text = "Eu recusei os convites para o baile da criada várias vezes. Ela parecia um pouco desanimada... Mas comparado a se divertir, a segurança do mestre é muito mais importante!"
  },
  Voice_5688_AwakerVoiceTitle = {
    Text = "Chat·Sobre Karen"
  },
  Voice_5688_UnlockDesc = {
    Text = "Após obter o despertador \"Karen\", desbloqueado"
  },
  Voice_5689_AwakerVoiceContent = {
    Text = "O senhor é a razão da existência de um cavaleiro, então sinta-se à vontade para me dar ordens!"
  },
  Voice_5689_AwakerVoiceTitle = {
    Text = "Conversa·Sobre Guardião do Segredo"
  },
  Voice_5690_AwakerVoiceContent = {
    Text = "...Podemos precisar de uma chave de torque para isso... Hmm, desculpe, você acabou de me chamar?"
  },
  Voice_5690_AwakerVoiceTitle = {
    Text = "Conversa·Toque"
  },
  Voice_5691_AwakerVoiceTitle = {
    Text = "Golpe·Quatro"
  },
  Voice_5692_AwakerVoiceContent = {
    Text = "Como você se atreve!"
  },
  Voice_5692_AwakerVoiceTitle = {Text = "Acertar·1"},
  Voice_5693_AwakerVoiceContent = {
    Text = "(Hum elegante)"
  },
  Voice_5693_AwakerVoiceTitle = {
    Text = "Acertar · II"
  },
  Voice_5694_AwakerVoiceContent = {
    Text = "(Um gemido abafado de resistência)"
  },
  Voice_5694_AwakerVoiceTitle = {
    Text = "Acertar·III"
  },
  Voice_5695_AwakerVoiceContent = {
    Text = "Isso é suficiente."
  },
  Voice_5695_AwakerVoiceTitle = {
    Text = "Defesa · I"
  },
  Voice_5696_AwakerVoiceContent = {
    Text = "Seja gentil."
  },
  Voice_5696_AwakerVoiceTitle = {Text = "Defesa·II"},
  Voice_5697_AwakerVoiceContent = {
    Text = "Certamente, ainda é difícil focar o espírito..."
  },
  Voice_5697_AwakerVoiceTitle = {
    Text = "Investigação Interrompida"
  },
  Voice_5698_AwakerVoiceContent = {
    Text = "Ela costuma ficar perto de mim à noite. Será simplesmente porque minha cabeça é conspícua demais?"
  },
  Voice_5698_AwakerVoiceTitle = {
    Text = "Bate-Papo·Sobre Búzio"
  },
  Voice_5698_UnlockDesc = {
    Text = "Após obter o despertador \"Búzio\", desbloqueado"
  },
  Voice_5699_AwakerVoiceContent = {
    Text = "Eu sempre esperei pela chegada da destruição, nunca considerando \"resistência\"... Você ajudará minha alma superficial a cruzar o abismo? Mesmo em um mundo onde sobrevivi por pouco, você ainda me concede salvação..."
  },
  Voice_5699_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Cinco"
  },
  Voice_5699_UnlockDesc = {
    Text = "Nível de afinidade atingido 10 desbloqueado"
  },
  Voice_5700_AwakerVoiceContent = {
    Text = "Como eu estou Despertado como seu apóstolo, não busco nada além de sua paz e alegria, esse é meu desejo... Ugh... Ah... De fato, sobrevivência, sobrevivência, sobrevivência, viver"
  },
  Voice_5700_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Quatro"
  },
  Voice_5700_UnlockDesc = {
    Text = "Nível de afinidade atingido 8 desbloqueado"
  },
  Voice_5701_AwakerVoiceContent = {
    Text = "Por que não se perder no meu amor? Você não me despertou pela calorosa abraçada?"
  },
  Voice_5701_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Um"
  },
  Voice_5701_UnlockDesc = {
    Text = "Nível de afinidade atingido 2 desbloqueado"
  },
  Voice_5702_AwakerVoiceContent = {
    Text = "Você não deseja evitar envolvimentos com mulheres de origens desconhecidas? Muito bem, muito bem. O rei deposto de Nineveh, o povo de Shinar que aspira alcançar os céus, a garota cuja vontade foi tirada sob a árvore sagrada do Eufrates... De onde você gostaria de começar?"
  },
  Voice_5702_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Três"
  },
  Voice_5702_UnlockDesc = {
    Text = "Nível de afinidade atingido 6 desbloqueado"
  },
  Voice_5703_AwakerVoiceContent = {
    Text = "Por que você sempre me evita? Está com vergonha? Que fofo, essa relutância em enfrentar seus desejos"
  },
  Voice_5703_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Dois"
  },
  Voice_5703_UnlockDesc = {
    Text = "Nível de afinidade atingido 4 desbloqueado"
  },
  Voice_5704_AwakerVoiceContent = {
    Text = "Este lugar é terrível, absolutamente terrível! Como ousam me fazer compartilhar uma mesa para o chá da tarde! ...Os biscoitos caseiros são bem bons, no entanto. Envie alguns para meu quarto após o jantar."
  },
  Voice_5704_AwakerVoiceTitle = {
    Text = "Chat·Sobre a Universidade Mythag"
  },
  Voice_5705_AwakerVoiceContent = {Text = "E aí!"},
  Voice_5705_AwakerVoiceTitle = {Text = "Ataque·Um"},
  Voice_5706_AwakerVoiceContent = {Text = "Veja isso!"},
  Voice_5706_AwakerVoiceTitle = {Text = "Ataque·II"},
  Voice_5707_AwakerVoiceContent = {
    Text = "Dissolução... Há registros na academia da minha casa, mas Karen odeia ler e esqueceu tudo!"
  },
  Voice_5707_AwakerVoiceTitle = {
    Text = "Bate-papo · Sobre Dissolução"
  },
  Voice_5708_AwakerVoiceContent = {
    Text = "Você deseja que eu zarpe mais uma vez? Se você puder ignorar meus fracassos passados, vou tentar."
  },
  Voice_5708_AwakerVoiceTitle = {
    Text = "Iluminar·Visão Remota"
  },
  Voice_5708_UnlockDesc = {
    Text = "Nível de iluminação atingiu 1 para desbloquear"
  },
  Voice_5709_AwakerVoiceContent = {
    Text = "Desgostos? Muitos—chefes que fazem os trabalhadores ficarem até tarde, freiras autossuficientes, estômagos roncando, pão preto com pedaços de vidro..."
  },
  Voice_5709_AwakerVoiceTitle = {
    Text = "Conversa·Coisas odiadas"
  },
  Voice_5710_AwakerVoiceContent = {
    Text = "Tudo é culpa da Aigis... Tudo é minha culpa..."
  },
  Voice_5710_AwakerVoiceTitle = {
    Text = "Investigação Interrompida"
  },
  Voice_5711_AwakerVoiceContent = {
    Text = "Vamos acabar com isso!"
  },
  Voice_5711_AwakerVoiceTitle = {Text = "Ataque·Um"},
  Voice_5712_AwakerVoiceContent = {
    Text = "Graças à bondade da Srta. Hannah, eu participei do ensaio do coro. Hinos são bastante diferentes das canções de marinheiro. Durante meu tempo protegendo o navio, nunca ouvi melodias tão distintas..."
  },
  Voice_5712_AwakerVoiceTitle = {
    Text = "Chat·Sobre a Universidade Mythag"
  },
  Voice_5713_AwakerVoiceContent = {
    Text = "Que tal esse movimento!"
  },
  Voice_5713_AwakerVoiceTitle = {
    Text = "Habilidade·Um"
  },
  Voice_5714_AwakerVoiceContent = {
    Text = "Que tal esse movimento!"
  },
  Voice_5714_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_5715_AwakerVoiceContent = {
    Text = "Tão assustador~"
  },
  Voice_5715_AwakerVoiceTitle = {
    Text = "Defesa · I"
  },
  Voice_5716_AwakerVoiceContent = {Text = "Ugh"},
  Voice_5716_AwakerVoiceTitle = {
    Text = "Defesa · I"
  },
  Voice_5717_AwakerVoiceContent = {
    Text = "Olá, meu novo mestre! O menu de hoje inclui pudim de lesma, ensopado de sapo e vinho de chama verde. Sinta-se à vontade para escolher."
  },
  Voice_5717_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_5718_AwakerVoiceContent = {
    Text = "Isso é a forma de retornar ao Gênesis...? Não, é um pouco diferente do que eu imaginei. Mas se eu pudesse me tornar assim, seria ótimo."
  },
  Voice_5718_AwakerVoiceTitle = {
    Text = "Bate-papo · Sobre a Linha de Sangue Aequor"
  },
  Voice_5718_UnlockDesc = {
    Text = "Desbloqueado após obter qualquer um dos Despertadores: \"Tulu\", \"Murphy\", \"Miryam\" ou \"Golias\"."
  },
  Voice_5719_AwakerVoiceContent = {
    Text = "Esperando o momento certo."
  },
  Voice_5719_AwakerVoiceTitle = {
    Text = "Habilidade·Um"
  },
  Voice_5720_AwakerVoiceContent = {Text = "Veja isso!"},
  Voice_5720_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_5721_AwakerVoiceContent = {
    Text = "Cordeiros, a misericórdia de Deus vos redimirá."
  },
  Voice_5721_AwakerVoiceTitle = {
    Text = "Exaltar · Dois"
  },
  Voice_5722_AwakerVoiceContent = {
    Text = "Cordeiros, a misericórdia de Deus vos redimirá."
  },
  Voice_5722_AwakerVoiceTitle = {
    Text = "Fúria Explosiva"
  },
  Voice_5723_AwakerVoiceContent = {Text = "Morra!"},
  Voice_5723_AwakerVoiceTitle = {Text = "Ataque·Um"},
  Voice_5724_AwakerVoiceContent = {Text = "Ha!"},
  Voice_5724_AwakerVoiceTitle = {Text = "Ataque·Um"},
  Voice_5725_AwakerVoiceContent = {Text = "Hmph!"},
  Voice_5725_AwakerVoiceTitle = {Text = "Ataque·Um"},
  Voice_5726_AwakerVoiceContent = {Text = "Ha!"},
  Voice_5726_AwakerVoiceTitle = {Text = "Ataque·Um"},
  Voice_5727_AwakerVoiceContent = {
    Text = "Ela também é uma alma lamentável, destinada a ser devastada pelo destino. Pois quando Ele realmente descer, será o momento em que eu lhe entregarei a morte."
  },
  Voice_5727_AwakerVoiceTitle = {
    Text = "Chat·Sobre Miryam"
  },
  Voice_5727_UnlockDesc = {
    Text = "Após obter o despertador \"Miryam\", desbloqueado"
  },
  Voice_5728_AwakerVoiceContent = {
    Text = "Seja manchado de sangue!"
  },
  Voice_5728_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_5729_AwakerVoiceContent = {
    Text = "Vingança...!"
  },
  Voice_5729_AwakerVoiceTitle = {
    Text = "Carta de Habilidade·Quatro"
  },
  Voice_5730_AwakerVoiceContent = {Text = "Dói..."},
  Voice_5730_AwakerVoiceTitle = {Text = "Acertar·1"},
  Voice_5731_AwakerVoiceContent = {
    Text = "(Gemido abafado de dor)"
  },
  Voice_5731_AwakerVoiceTitle = {
    Text = "Acertar·III"
  },
  Voice_5732_AwakerVoiceContent = {
    Text = "(Gemido abafado de dor)"
  },
  Voice_5732_AwakerVoiceTitle = {
    Text = "Acertar · II"
  },
  Voice_5733_AwakerVoiceContent = {Text = "Ai..."},
  Voice_5733_AwakerVoiceTitle = {
    Text = "Golpe·Quatro"
  },
  Voice_5734_AwakerVoiceContent = {
    Text = "Você gostaria de afundar junto comigo?"
  },
  Voice_5734_AwakerVoiceTitle = {
    Text = "Conversa·Toque"
  },
  Voice_5735_AwakerVoiceContent = {
    Text = "Vá embora!"
  },
  Voice_5735_AwakerVoiceTitle = {Text = "Acertar·1"},
  Voice_5736_AwakerVoiceContent = {
    Text = "Coisas que eu odeio... uma mesa desorganizada, um guarda-roupa bagunçado, peitoris empoeirados — sim, estou descrevendo seu quarto. Até as 7 da manhã de amanhã, quero que ele seja restaurado ao que era antes de você se mudar."
  },
  Voice_5736_AwakerVoiceTitle = {
    Text = "Conversa·Coisas odiadas"
  },
  Voice_5737_AwakerVoiceContent = {
    Text = "(Zumbido de interesse)"
  },
  Voice_5737_AwakerVoiceTitle = {
    Text = "Acertar·III"
  },
  Voice_5738_AwakerVoiceContent = {
    Text = "Interessante!"
  },
  Voice_5738_AwakerVoiceTitle = {
    Text = "Acertar · II"
  },
  Voice_5739_AwakerVoiceContent = {
    Text = "(Zombando desdenhosamente)"
  },
  Voice_5739_AwakerVoiceTitle = {
    Text = "Golpe·Quatro"
  },
  Voice_5740_AwakerVoiceContent = {
    Text = "Se necessário, posso deixar o berço..."
  },
  Voice_5740_AwakerVoiceTitle = {
    Text = "Investigação Interrompida"
  },
  Voice_5741_AwakerVoiceContent = {
    Text = "Você quer?"
  },
  Voice_5741_AwakerVoiceTitle = {Text = "Ataque·II"},
  Voice_5742_AwakerVoiceContent = {Text = "Cuidado~!"},
  Voice_5742_AwakerVoiceTitle = {Text = "Ataque·Um"},
  Voice_5743_AwakerVoiceContent = {
    Text = "Duplo, duplo, duplo!"
  },
  Voice_5743_AwakerVoiceTitle = {
    Text = "Carta de Habilidade·Quatro"
  },
  Voice_5744_AwakerVoiceContent = {
    Text = "Isso me lembra do primeiro par de sapatos de dança vermelhos que recebi quando tinha oito anos. Eu realmente os amo. Obrigado, Guardião."
  },
  Voice_5744_AwakerVoiceTitle = {
    Text = "Iluminar·Visão Remota"
  },
  Voice_5744_UnlockDesc = {
    Text = "Nível de iluminação atingiu 1 para desbloquear"
  },
  Voice_5745_AwakerVoiceContent = {
    Text = "Amigo... Mestre? Ou Mãe?"
  },
  Voice_5745_AwakerVoiceTitle = {
    Text = "Chat·Sobre a Universidade Mythag"
  },
  Voice_5746_AwakerVoiceContent = {
    Text = "Minha proteção também pode falhar às vezes..."
  },
  Voice_5746_AwakerVoiceTitle = {
    Text = "Investigação Interrompida"
  },
  Voice_5747_AwakerVoiceContent = {Text = "(Gemido)"},
  Voice_5747_AwakerVoiceTitle = {
    Text = "Acertar · II"
  },
  Voice_5748_AwakerVoiceContent = {Text = "(Gemido)"},
  Voice_5748_AwakerVoiceTitle = {Text = "Acertar·1"},
  Voice_5749_AwakerVoiceContent = {Text = "(Gemido)"},
  Voice_5749_AwakerVoiceTitle = {
    Text = "Golpe·Quatro"
  },
  Voice_5750_AwakerVoiceContent = {
    Text = "Gostos? Alguém uma vez me perguntou isso nos campos de batalha do Peloponeso... É tarde demais. Eu já abandonei tais preferências pessoais."
  },
  Voice_5750_AwakerVoiceTitle = {
    Text = "Conversa·Coisas favoritas"
  },
  Voice_5751_AwakerVoiceContent = {
    Text = "Shh... por favor, não deixe que \"eles\" descubram que estou ficando mais forte."
  },
  Voice_5751_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · I"
  },
  Voice_5752_AwakerVoiceContent = {
    Text = "\"Eles\" disseram... Muito apreciado."
  },
  Voice_5752_AwakerVoiceTitle = {
    Text = "Atualizar·II"
  },
  Voice_5753_AwakerVoiceContent = {
    Text = "Uh... O que é isso?"
  },
  Voice_5753_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · Três"
  },
  Voice_5754_AwakerVoiceContent = {
    Text = "Isso só me levará mais perto do Abismo."
  },
  Voice_5754_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_5754_UnlockDesc = {
    Text = "Nível de iluminação atingiu 2 para desbloquear"
  },
  Voice_5755_AwakerVoiceContent = {
    Text = "Você é meu amado servo. Eu sei que você chama isso de amigo, parceiro, camarada... O que quer que te faça feliz."
  },
  Voice_5755_AwakerVoiceTitle = {
    Text = "Conversa·Sobre Guardião do Segredo"
  },
  Voice_5756_AwakerVoiceContent = {
    Text = "Eu obtive a resposta... Mesmo que não fosse o que eu esperava, eu ainda obtive a resposta."
  },
  Voice_5756_AwakerVoiceTitle = {
    Text = "Iluminar·Construção"
  },
  Voice_5756_UnlockDesc = {
    Text = "Nível de iluminação atingiu 11 para desbloquear"
  },
  Voice_5757_AwakerVoiceContent = {
    Text = "É \"medo\"? Ou \"tristeza\"? Sua expressão de desânimo é realmente cativante."
  },
  Voice_5757_AwakerVoiceTitle = {
    Text = "Iluminar: Insight"
  },
  Voice_5757_UnlockDesc = {
    Text = "Nível de iluminação atingiu 7 para desbloquear"
  },
  Voice_5758_AwakerVoiceContent = {
    Text = "O cheiro de morte e aniquilação, tão vívido."
  },
  Voice_5758_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexão"
  },
  Voice_5758_UnlockDesc = {
    Text = "Nível de iluminação atingiu 3 para desbloquear"
  },
  Voice_5759_AwakerVoiceContent = {
    Text = "A Vida aqui? Muito, muito boa. Enquanto eu compartilhar algum conhecimento de ciência mecânica e pesquisa espiritual com a Sra. Boneca, ela me deixa manter as luzes acesas."
  },
  Voice_5759_AwakerVoiceTitle = {
    Text = "Chat·Sobre a Universidade Mythag"
  },
  Voice_5760_AwakerVoiceContent = {
    Text = "Espero que Jenkin e Brown estejam aproveitando seu tempo na academia. Comparado à liberdade dela, os abotoaduras do Pai são insignificantes. Estou certo de que ele tem uma caixa inteira de sobras."
  },
  Voice_5760_AwakerVoiceTitle = {
    Text = "Fofocas · Sobre Jenki"
  },
  Voice_5760_UnlockDesc = {
    Text = "Desbloqueado após adquirir o Despertar \"Jenkin\""
  },
  Voice_5761_AwakerVoiceContent = {
    Text = "Não pode sair..."
  },
  Voice_5761_AwakerVoiceTitle = {
    Text = "Carta de Habilidade·Quatro"
  },
  Voice_5762_AwakerVoiceContent = {
    Text = "Tendo transcendido raças inferiores, não temo tal influência. Mesmo que o corpo hostil se quebre, a nobre linhagem não perecerá."
  },
  Voice_5762_AwakerVoiceTitle = {
    Text = "Bate-papo · Sobre Dissolução"
  },
  Voice_5763_AwakerVoiceContent = {
    Text = "Eu detesto pessoas com sorrisos falsos! Você não pode roubar emoções delas!"
  },
  Voice_5763_AwakerVoiceTitle = {
    Text = "Conversa·Coisas odiadas"
  },
  Voice_5764_AwakerVoiceContent = {
    Text = "Hmm? Por que todos estão em silêncio? Karen odeia o silêncio. Deixa eu te contar uma história. Era uma vez uma montanha..."
  },
  Voice_5764_AwakerVoiceTitle = {
    Text = "Conversa·Coisas odiadas"
  },
  Voice_5765_AwakerVoiceContent = {
    Text = "Lily vai agarrar o futuro... Tokuli—Li!"
  },
  Voice_5765_AwakerVoiceTitle = {
    Text = "Fúria Explosiva"
  },
  Voice_5766_AwakerVoiceContent = {
    Text = "Lily vai agarrar o futuro... Tokuli—Li!"
  },
  Voice_5766_AwakerVoiceTitle = {
    Text = "Fúria Explosiva"
  },
  Voice_5767_AwakerVoiceContent = {
    Text = "Se você busca perceber Sua presença, eu temporariamente perdoarei sua indelicadeza."
  },
  Voice_5767_AwakerVoiceTitle = {
    Text = "Conversa·Toque"
  },
  Voice_5768_AwakerVoiceContent = {
    Text = "Eu não quero fazer isso..."
  },
  Voice_5768_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_5769_AwakerVoiceContent = {Text = "Afaste-se!"},
  Voice_5769_AwakerVoiceTitle = {
    Text = "Habilidade·Um"
  },
  Voice_5770_AwakerVoiceContent = {
    Text = "Gradualmente, gradualmente se sincronizando com o seu ritmo de comando!"
  },
  Voice_5770_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · Três"
  },
  Voice_5771_AwakerVoiceContent = {
    Text = "Estão mais próximos de se tornarem um cavaleiro completo!"
  },
  Voice_5771_AwakerVoiceTitle = {
    Text = "Atualizar·II"
  },
  Voice_5772_AwakerVoiceContent = {
    Text = "Obrigado pela sua promoção, é uma honra"
  },
  Voice_5772_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · I"
  },
  Voice_5773_AwakerVoiceContent = {
    Text = "O banho é um ótimo lugar para passar o tempo. A comida é deliciosa e eles oferecem serviços de relaxamento muscular. Tentado? Construa um na escola agora mesmo!"
  },
  Voice_5773_AwakerVoiceTitle = {
    Text = "Conversa·Coisas favoritas"
  },
  Voice_5774_AwakerVoiceContent = {
    Text = "Não, não vá embora!"
  },
  Voice_5774_AwakerVoiceTitle = {
