  Voice_57841_AwakerVoiceTitle = {
    Text = "Superexaltação"
  },
  Voice_57842_AwakerVoiceContent = {
    Text = "O deus do labirinto subterrâneo pronuncia julgamento sobre todos vocês!"
  },
  Voice_57842_AwakerVoiceTitle = {
    Text = "Sobre-Exaltação Aliemus Explosão·II"
  },
  Voice_57843_AwakerVoiceContent = {
    Text = "Pássaro voando no céu azul, por favor, ouça minha oração."
  },
  Voice_57843_AwakerVoiceTitle = {
    Text = "Sobre-Exaltação Aliemus Explosão·II"
  },
  Voice_57844_AwakerVoiceContent = {
    Text = "Pássaro voando no céu azul, por favor, ouça minha oração."
  },
  Voice_57844_AwakerVoiceTitle = {
    Text = "Superexaltação"
  },
  Voice_57845_AwakerVoiceContent = {
    Text = "Não se mova! Não se mova! Não se mova!"
  },
  Voice_57845_AwakerVoiceTitle = {
    Text = "Sobre-Exaltação Aliemus Explosão·II"
  },
  Voice_57846_AwakerVoiceContent = {
    Text = "Treme sob o Helot... Pereça sob o Helot!"
