  },
  Voice_5784_AwakerVoiceContent = {Text = "Hehe..."},
  Voice_5784_AwakerVoiceTitle = {Text = "Ataque·II"},
  Voice_57850_AwakerVoiceContent = {
    Text = "Eis! Este é o poder no qual os Perishites confiam!"
  },
  Voice_57850_AwakerVoiceTitle = {
    Text = "Sobre-Exaltação Aliemus Explosão·II"
  },
  Voice_57851_AwakerVoiceContent = {
    Text = "Eis! Este é o poder no qual os Perishites confiam!"
  },
  Voice_57851_AwakerVoiceTitle = {
    Text = "Superexaltação"
  },
  Voice_5785_AwakerVoiceContent = {
    Text = "Muito fraco."
  },
  Voice_5785_AwakerVoiceTitle = {
    Text = "Defesa · I"
  },
  Voice_5786_AwakerVoiceContent = {Text = "Ha!"},
  Voice_5786_AwakerVoiceTitle = {
    Text = "Defesa · I"
  },
  Voice_5787_AwakerVoiceContent = {
    Text = "Hmm... O mestre parece chateado? Deixe a Karen animá-lo com uma cara engraçada, hehe!\nVocê está se sentindo melhor agora?"
  },
  Voice_5787_AwakerVoiceTitle = {
    Text = "Conversa·Sobre Guardião do Segredo"
  },
  Voice_5788_AwakerVoiceContent = {
    Text = "Revele a essência do mundo com a inteligência humana...!"
  },
  Voice_5788_AwakerVoiceTitle = {
    Text = "Exaltar · Dois"
  },
  Voice_5789_AwakerVoiceContent = {
    Text = "Encontrei algumas pessoas inquietantes no corredor. Você pode precisar cooperar com elas devido às circunstâncias, mas permaneça vigilante. O coração humano é mais cruel do que a guerra, e as piores traições muitas vezes vêm de dentro."
  },
  Voice_5789_AwakerVoiceTitle = {
    Text = "Conversas Ociosas·Sobre @2"
  },
  Voice_5789_UnlockDesc = {
    Text = "Desbloqueado após obter Despertador \"Hilota\" ou \"Lily\""
  },
  Voice_5790_AwakerVoiceContent = {
    Text = "Sua tarefa está feita, certo? Você pode vir comigo para a cidade de Londinium... Eh? Seu dever de matemática ainda não está feito?!\nAh... desculpe, não esperava que ninguém não entendesse cálculo... Deixe-me ajudar."
  },
  Voice_5790_AwakerVoiceTitle = {
    Text = "Conversa Casual: Sobre Aprender"
  },
  Voice_5791_AwakerVoiceContent = {
    Text = "Eu juro a você, aquele comerciante definitivamente apareceu no salão de Fontainebleau... Eu vejo, ela tem estado assim desde então. Eu me pergunto quantos segredos podemos negociar com ela?"
  },
  Voice_5791_AwakerVoiceTitle = {
    Text = "Conversa Casual · Sobre Narciso"
  },
  Voice_5791_UnlockDesc = {
    Text = "Desbloqueado após adquirir o Despertar \"Narciso\""
  },
  Voice_5792_AwakerVoiceContent = {
    Text = "(Exclamação)"
  },
  Voice_5792_AwakerVoiceTitle = {Text = "Acertar·1"},
  Voice_5793_AwakerVoiceContent = {
    Text = "Não quebre isso."
  },
  Voice_5793_AwakerVoiceTitle = {Text = "Defesa·II"},
  Voice_5794_AwakerVoiceContent = {
    Text = "Aurita ama brincar com todos! Você vai se juntar? Esse é Jelly, aquele é Hela, e lá está Jelly... huh?"
  },
  Voice_5794_AwakerVoiceTitle = {
    Text = "Conversa·Coisas favoritas"
  },
  Voice_5795_AwakerVoiceContent = {
    Text = "Desgraça, deixe este movimento te purificar!"
  },
  Voice_5795_AwakerVoiceTitle = {
    Text = "Exaltar · Dois"
  },
  Voice_5796_AwakerVoiceContent = {
    Text = "A loja de Daffodil está agora aberta. Crianças que não estão preparadas, por favor, não entrem casualmente."
  },
  Voice_5796_AwakerVoiceTitle = {
    Text = "Iluminar·Visão Remota"
  },
  Voice_5796_UnlockDesc = {
    Text = "Nível de iluminação atingiu 1 para desbloquear"
  },
  Voice_5797_AwakerVoiceContent = {
    Text = "Por favor, não toque no meu pescoço... Só porque você não pode vê-lo, não significa que não exista."
  },
  Voice_5797_AwakerVoiceTitle = {
    Text = "Conversa·Toque"
  },
  Voice_5798_AwakerVoiceContent = {
    Text = "Eu admiro aqueles com convicções, sejam eles animais, Despertadores ou humanos. Se forem lutadores habilidosos, melhor ainda."
  },
  Voice_5798_AwakerVoiceTitle = {
    Text = "Conversa·Coisas favoritas"
  },
  Voice_5799_AwakerVoiceContent = {Text = "Vá."},
  Voice_5799_AwakerVoiceTitle = {Text = "Ataque·Um"},
  Voice_5800_AwakerVoiceContent = {
    Text = "Não se preocupe!"
  },
  Voice_5800_AwakerVoiceTitle = {Text = "Defesa·II"},
  Voice_5801_AwakerVoiceContent = {
    Text = "Ramona odeia perder... Desculpe, quero dizer, não gosto de despedidas; é muito triste."
  },
  Voice_5801_AwakerVoiceTitle = {
    Text = "Conversa·Coisas odiadas"
  },
  Voice_5802_AwakerVoiceContent = {
    Text = "Não sou bom em lidar com clérigos. Eles são chatos e rígidos, e deram seus cintos ao seu amado \"Deus\". Que pena, o Senhor Salvador cheira tão bem..."
  },
  Voice_5802_AwakerVoiceTitle = {
    Text = "Conversa Casual · Sobre Salvador"
  },
  Voice_5802_UnlockDesc = {
    Text = "Desbloqueado após adquirir o Despertar \"Salvador\""
  },
  Voice_5803_AwakerVoiceContent = {
    Text = "O entusiasmo da batalha supera tudo, incluindo a vitória ou a derrota"
  },
  Voice_5803_AwakerVoiceTitle = {
    Text = "Investigação Interrompida"
  },
  Voice_5804_AwakerVoiceContent = {
    Text = "Quem não ama uma cama macia e um quarto sem correntes de ar...?"
  },
  Voice_5804_AwakerVoiceTitle = {
    Text = "Conversa·Coisas favoritas"
  },
  Voice_5805_AwakerVoiceContent = {
    Text = "...Não me faça recordar... os dias aprisionada em Elworth..."
  },
  Voice_5805_AwakerVoiceTitle = {
    Text = "Conversa·Coisas odiadas"
  },
  Voice_5806_AwakerVoiceContent = {
    Text = "Queime tudo!"
  },
  Voice_5806_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_5807_AwakerVoiceContent = {
    Text = "Queime tudo!"
  },
  Voice_5807_AwakerVoiceTitle = {
    Text = "Habilidade·Um"
  },
  Voice_5808_AwakerVoiceContent = {
    Text = "Eu segui o cheiro de sangue até este lugar. Posso perguntar... você oferece pacotes de sangue fresco aqui?"
  },
  Voice_5808_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_5809_AwakerVoiceContent = {
    Text = "Hmm... Agrippa tem muitos companheiros, mas todos parecem ter medo dela. Poderia ser que ela rouba a comida deles?"
  },
  Voice_5809_AwakerVoiceTitle = {
    Text = "Fala Ociosa · Sobre Agrippa"
  },
  Voice_5809_UnlockDesc = {
    Text = "Após obter o despertador \"Agrippa\", desbloqueado"
  },
  Voice_5810_AwakerVoiceContent = {
    Text = "Minha vida gira em torno da dança. Aprender outros conhecimentos é difícil para meu crescimento. Mas todos são gentis; eles não vão me denunciar por vaidade ou dinheiro—eu posso sentir isso."
  },
  Voice_5810_AwakerVoiceTitle = {
    Text = "Chat·Sobre a Universidade Mythag"
  },
  Voice_5811_AwakerVoiceContent = {
    Text = "Covarde! Você possui um poder imenso semelhante ao meu, mas se contém. Como isso é diferente de usar um colar voluntariamente?"
  },
  Voice_5811_AwakerVoiceTitle = {
    Text = "Fala Ociosa · Sobre Lily"
  },
  Voice_5811_UnlockDesc = {
    Text = "Desbloqueado após adquirir o Despertar \"Lily\""
  },
  Voice_5812_AwakerVoiceContent = {
    Text = "Não é suficiente... ainda não há poder suficiente..."
  },
  Voice_5812_AwakerVoiceTitle = {
    Text = "Investigação Interrompida"
  },
  Voice_5813_AwakerVoiceContent = {Text = "Volte."},
  Voice_5813_AwakerVoiceTitle = {
    Text = "Defesa · I"
  },
  Voice_5814_AwakerVoiceContent = {Text = "Ah!"},
  Voice_5814_AwakerVoiceTitle = {Text = "Defesa·II"},
  Voice_5815_AwakerVoiceContent = {
    Text = "Cartolas, chapéus de feltro, chapéus caçador, boinas... Devo dizer, é bastante engraçado como vocês, senhores da alta sociedade, vão a grandes esforços para esconder sua calvície."
  },
  Voice_5815_AwakerVoiceTitle = {
    Text = "Conversas Ociosas · Sobre Etiqueta"
  },
  Voice_5816_AwakerVoiceContent = {
    Text = "Eu admiro profundamente aquela pessoa, o deus do mar tão puro e elegante quanto um lírio... Você diz que nem ela pôde controlar seu destino e, por fim, afundou no mar? É realmente difícil de imaginar..."
  },
  Voice_5816_AwakerVoiceTitle = {
    Text = "Bate-papo · Sobre Celeste"
  },
  Voice_5816_UnlockDesc = {
    Text = "Após obter o despertador \"celeste\", desbloqueado"
  },
  Voice_5817_AwakerVoiceContent = {
    Text = "Não há nada no mundo que um gigante não possa superar!"
  },
  Voice_5817_AwakerVoiceTitle = {
    Text = "Fúria Explosiva"
  },
  Voice_5818_AwakerVoiceContent = {
    Text = "Não há nada no mundo que um gigante não possa superar!"
  },
  Voice_5818_AwakerVoiceTitle = {
    Text = "Exaltar · Dois"
  },
  Voice_5819_AwakerVoiceContent = {
    Text = "Droga, droga...! O Poder só me mantém preso neste corpo..."
  },
  Voice_5819_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_5819_UnlockDesc = {
    Text = "Nível de iluminação atingiu 2 para desbloquear"
  },
  Voice_5820_AwakerVoiceContent = {
    Text = "Desejo ficar em um lugar que esteja sempre iluminado... Sim, os polos. Neste planeta, somente os polos."
  },
  Voice_5820_AwakerVoiceTitle = {
    Text = "Iluminar·Construção"
  },
  Voice_5820_UnlockDesc = {
    Text = "Nível de iluminação atingiu 11 para desbloquear"
  },
  Voice_5821_AwakerVoiceContent = {
    Text = "Eu... eu não posso suportar grandes responsabilidades. Posso apenas perseguir a luz. Então, por favor, não pare de brilhar..."
  },
  Voice_5821_AwakerVoiceTitle = {
    Text = "Iluminar·Florescer"
  },
  Voice_5821_UnlockDesc = {
    Text = "Nível de iluminação atingiu 15 para desbloquear"
  },
  Voice_5822_AwakerVoiceContent = {
    Text = "Se eu pudesse migrar, eu gostaria de me tornar uma estrela..."
  },
  Voice_5822_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexão"
  },
  Voice_5822_UnlockDesc = {
    Text = "Nível de iluminação atingiu 3 para desbloquear"
  },
  Voice_5823_AwakerVoiceContent = {
    Text = "Não importa como eu calcule, a fórmula para a transferência de consciência continua insolúvel..."
  },
  Voice_5823_AwakerVoiceTitle = {
    Text = "Iluminar: Insight"
  },
  Voice_5823_UnlockDesc = {
    Text = "Nível de iluminação atingiu 7 para desbloquear"
  },
  Voice_5824_AwakerVoiceContent = {
    Text = "Bem-vindo! Vamos nos divertir juntos!"
  },
  Voice_5824_AwakerVoiceTitle = {
    Text = "Fúria Explosiva"
  },
  Voice_5825_AwakerVoiceContent = {
    Text = "Aproveite sua refeição, senhor!"
  },
  Voice_5825_AwakerVoiceTitle = {
    Text = "Exaltar · Dois"
  },
  Voice_5826_AwakerVoiceContent = {
    Text = "Huff—É Aurita! Um, dois, três... Uau! Bem-vindo, bem-vindo! Um novo parceiro se juntou! Huh? Eu sou o novo parceiro? Bem, você poderia dizer isso!"
  },
  Voice_5826_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_5827_AwakerVoiceContent = {
    Text = "Você chama este brinquedo de uma pistola? Apenas covardes se escondem nas sombras para emboscar seus inimigos."
  },
  Voice_5827_AwakerVoiceTitle = {
    Text = "Conversa·Coisas odiadas"
  },
  Voice_5828_AwakerVoiceContent = {
    Text = "É sem sentido. Fazer isso é completamente inútil."
  },
  Voice_5828_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · I"
  },
  Voice_5829_AwakerVoiceContent = {
    Text = "Você não sabe absolutamente nada."
  },
  Voice_5829_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · Três"
  },
  Voice_5830_AwakerVoiceContent = {
    Text = "Ainda contando comigo para ser a reserva do \"Salvador\"?"
  },
  Voice_5830_AwakerVoiceTitle = {
    Text = "Atualizar·II"
  },
  Voice_5831_AwakerVoiceContent = {
    Text = "Desculpe, você viu meu parafuso? É estranho, mas sempre que aquela criança com as orelhas de rato está por perto, eu pareço esquecer onde coloquei as coisas..."
  },
  Voice_5831_AwakerVoiceTitle = {
    Text = "Fofocas · Sobre Jenki"
  },
  Voice_5831_UnlockDesc = {
    Text = "Desbloqueado após adquirir o Despertar \"Jenkin\""
  },
  Voice_5832_AwakerVoiceContent = {
    Text = "Eu não vou esquecer tudo que você sacrificou para o meu reencontro com meu mestre..."
  },
  Voice_5832_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · Três"
  },
  Voice_5833_AwakerVoiceContent = {
    Text = "Uma Canção Magistral!"
  },
  Voice_5833_AwakerVoiceTitle = {
    Text = "Despertar do Conhecimento Espiritual"
  },
  Voice_5834_AwakerVoiceContent = {
    Text = "Você reconheceu meu desejo?"
  },
  Voice_5834_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · I"
  },
  Voice_5835_AwakerVoiceContent = {
    Text = "Espero que seu comando não decepcione."
  },
  Voice_5835_AwakerVoiceTitle = {
    Text = "Início da Investigação"
  },
  Voice_5836_AwakerVoiceContent = {
    Text = "É este corpo ou minha consciência que melhorou? Um tópico intrigante."
  },
  Voice_5836_AwakerVoiceTitle = {
    Text = "Iluminar·Visão Remota"
  },
  Voice_5836_UnlockDesc = {
    Text = "Nível de iluminação atingiu 1 para desbloquear"
  },
  Voice_5837_AwakerVoiceContent = {Text = "Afaste-se."},
  Voice_5837_AwakerVoiceTitle = {Text = "Defesa·II"},
  Voice_5838_AwakerVoiceContent = {Text = "Afaste-se."},
  Voice_5838_AwakerVoiceTitle = {
    Text = "Defesa · I"
  },
  Voice_5839_AwakerVoiceContent = {
    Text = "Minhas veias fervem com a vontade de sobreviver, gritando e me empurrando para derramar sangue em cada centímetro deste planeta... Ah, eu falei demais; por favor, me perdoe. Eu sou Táias. Você me convocou? Você está pronta para se fundir comigo?"
  },
  Voice_5839_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_5840_AwakerVoiceContent = {
    Text = "Se ao menos Aigis pudesse suportar esse líquido negro por todos... Afinal, Aigis nunca existiu, o que pode ser algo bom para este mundo, certo?"
  },
  Voice_5840_AwakerVoiceTitle = {
    Text = "Bate-papo · Sobre Dissolução"
  },
  Voice_5841_AwakerVoiceContent = {
    Text = "Hobbies incluem a Hipótese de Riemann—essa é a frase de efeito do pavão, não minha. Pessoalmente, estou mais interessado em padrões de massa atômica."
  },
  Voice_5841_AwakerVoiceTitle = {
    Text = "Conversa·Coisas favoritas"
  },
  Voice_5842_AwakerVoiceContent = {
    Text = "O sabor de estar exilado e à deriva no mar... Uma vez é suficiente."
  },
  Voice_5842_AwakerVoiceTitle = {
    Text = "Investigação Interrompida"
  },
  Voice_5844_AwakerVoiceContent = {
    Text = "Observe de perto!"
  },
  Voice_5844_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_5845_AwakerVoiceContent = {
    Text = "Observe de perto!"
  },
  Voice_5845_AwakerVoiceTitle = {
    Text = "Carta de Habilidade·Quatro"
  },
  Voice_5846_AwakerVoiceContent = {
    Text = "Enquanto você puder defender essa justiça, sempre carregarei o dever da lâmina."
  },
  Voice_5846_AwakerVoiceTitle = {
    Text = "Conversa·Sobre Guardião do Segredo"
  },
  Voice_5847_AwakerVoiceContent = {
    Text = "Você sabia sobre a lenda do \"Pintor\" aqui? Das grafites expressionistas, sinto um toque familiar..."
  },
  Voice_5847_AwakerVoiceTitle = {
    Text = "Chat·Sobre a Universidade Mythag"
  },
  Voice_5848_AwakerVoiceContent = {
    Text = "Tão doloroso, ainda assim tão emocionante—"
  },
  Voice_5848_AwakerVoiceTitle = {
    Text = "Despertar do Conhecimento Espiritual"
  },
  Voice_5849_AwakerVoiceContent = {
    Text = "Sinta minha ira!"
  },
  Voice_5849_AwakerVoiceTitle = {
    Text = "Despertar do Conhecimento Espiritual"
  },
  Voice_5850_AwakerVoiceContent = {
    Text = "Deixe esta vitória ser registrada em poesia."
  },
  Voice_5850_AwakerVoiceTitle = {
    Text = "Investigação Bem-sucedida"
  },
  Voice_5851_AwakerVoiceContent = {Text = "Cresça—"},
  Voice_5851_AwakerVoiceTitle = {
    Text = "Despertar do Conhecimento Espiritual"
  },
  Voice_5852_AwakerVoiceContent = {Text = "Veja isso!"},
  Voice_5852_AwakerVoiceTitle = {
    Text = "Defesa · I"
  },
  Voice_5853_AwakerVoiceContent = {Text = "Oi!"},
  Voice_5853_AwakerVoiceTitle = {Text = "Defesa·II"},
  Voice_5854_AwakerVoiceContent = {
    Text = "Talvez quando eu crescer, eu consiga me controlar e não drenar a Vida dos outros... Um pouquinho é suficiente para eu sobreviver."
  },
  Voice_5854_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexão"
  },
  Voice_5854_UnlockDesc = {
    Text = "Nível de iluminação atingiu 3 para desbloquear"
  },
  Voice_5855_AwakerVoiceContent = {
    Text = "Parece que estou mais pesado. O berço ainda suporta meu peso?"
  },
  Voice_5855_AwakerVoiceTitle = {
    Text = "Iluminar: Insight"
  },
  Voice_5855_UnlockDesc = {
    Text = "Nível de iluminação atingiu 7 para desbloquear"
  },
  Voice_5856_AwakerVoiceContent = {
    Text = "O poder está prestes a transbordar, e minhas costas estão coçando. Estou crescendo?"
  },
  Voice_5856_AwakerVoiceTitle = {
    Text = "Iluminar·Construção"
  },
  Voice_5856_UnlockDesc = {
    Text = "Nível de iluminação atingiu 11 para desbloquear"
  },
  Voice_5857_AwakerVoiceContent = {
    Text = "Embora eu ainda pareça uma criança, agora eu... tenho o poder de proteger você."
  },
  Voice_5857_AwakerVoiceTitle = {
    Text = "Iluminar·Florescer"
  },
  Voice_5857_UnlockDesc = {
    Text = "Nível de iluminação atingiu 15 para desbloquear"
  },
  Voice_5858_AwakerVoiceContent = {
    Text = "Farei o meu melhor para crescer."
  },
  Voice_5858_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_5858_UnlockDesc = {
    Text = "Nível de iluminação atingiu 2 para desbloquear"
  },
  Voice_5859_AwakerVoiceContent = {
    Text = "Você ingrato, por que você é tão persistente em me acordar?"
  },
  Voice_5859_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_5860_AwakerVoiceContent = {
    Text = "Eu me tornarei a Mãe dos Deuses!"
  },
  Voice_5860_AwakerVoiceTitle = {
    Text = "Despertar do Conhecimento Espiritual"
  },
  Voice_5861_AwakerVoiceContent = {
    Text = "Quantas vezes fui convocado... Humano, é melhor você ter \"comida\" suficiente preparada, ou não posso garantir nada."
  },
  Voice_5861_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_5862_AwakerVoiceContent = {
    Text = "Além da Porta!"
  },
  Voice_5862_AwakerVoiceTitle = {
    Text = "Despertar do Conhecimento Espiritual"
  },
  Voice_5863_AwakerVoiceContent = {Text = "Tolo."},
  Voice_5863_AwakerVoiceTitle = {Text = "Ataque·Um"},
  Voice_5864_AwakerVoiceContent = {Text = "Haha"},
  Voice_5864_AwakerVoiceTitle = {Text = "Ataque·Um"},
  Voice_5865_AwakerVoiceContent = {
    Text = "Hmph, não é ruim. Vou colocar tudo em nosso próximo duelo."
  },
  Voice_5865_AwakerVoiceTitle = {
    Text = "Investigação Interrompida"
  },
  Voice_5866_AwakerVoiceContent = {
    Text = "Você, insolente!"
  },
  Voice_5866_AwakerVoiceTitle = {Text = "Ataque·II"},
  Voice_5867_AwakerVoiceContent = {
    Text = "Às vezes, a beleza da arte reside em sua aniquilação. Mas seu fracasso... claramente não se encaixa nessa categoria."
  },
  Voice_5867_AwakerVoiceTitle = {
    Text = "Investigação Interrompida"
  },
  Voice_5868_AwakerVoiceContent = {
    Text = "Você é meu ouvinte mais importante. Sempre que precisar, estou pronto para cantar e te dar tudo."
  },
  Voice_5868_AwakerVoiceTitle = {
    Text = "Conversa·Sobre Guardião do Segredo"
  },
  Voice_5869_AwakerVoiceContent = {
    Text = "Coisas favoritas? Algas, cardumes de peixes, colunatas, labirintos... Claro que eu já vi! Estão todos no livro do Tio Ornn!"
  },
  Voice_5869_AwakerVoiceTitle = {
    Text = "Conversa·Coisas favoritas"
  },
  Voice_5870_AwakerVoiceContent = {
    Text = "É preparação para uma missão de investigação? Eu entendo."
  },
  Voice_5870_AwakerVoiceTitle = {
    Text = "Iluminar·Visão Remota"
  },
  Voice_5870_UnlockDesc = {
    Text = "Nível de iluminação atingiu 1 para desbloquear"
  },
  Voice_5871_AwakerVoiceContent = {
    Text = "Meu nome é Celeste. Enquanto você ainda precisar de mim, estarei aqui."
  },
  Voice_5871_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_5872_AwakerVoiceContent = {
    Text = "Aprenda a sua lição!"
  },
  Voice_5872_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_5873_AwakerVoiceContent = {
    Text = "Mostre algum respeito, júnior. No exército, a senioridade é respeitada, e as ordens devem ser seguidas sem exceções. Tal comportamento inadequado será punido."
  },
  Voice_5873_AwakerVoiceTitle = {
    Text = "Conversa·Toque"
  },
  Voice_5874_AwakerVoiceContent = {
    Text = "Estaria disposto a fornecer serviço pós-venda para aqueles \"brinquedinhos\", mas a questão é, você se atreve a aceitar meu serviço?"
  },
  Voice_5874_AwakerVoiceTitle = {
    Text = "Conversa Casual · Sobre Invenções"
  },
  Voice_5875_AwakerVoiceContent = {
    Text = "Você é o mestre aqui, mas também um convidado em meu salão. Vou preparar a melhor hospitalidade para sua visita—você prefere uma saia escarlate ou uma camisolinha rosa-branca?"
  },
  Voice_5875_AwakerVoiceTitle = {
    Text = "Conversa·Sobre Guardião do Segredo"
  },
  Voice_5876_AwakerVoiceContent = {
    Text = "Desculpe, a luz do sol aqui está um pouco ofuscante... Um rato de uma caverna escura não consegue se adaptar rapidamente."
  },
  Voice_5876_AwakerVoiceTitle = {
    Text = "Início da Investigação"
  },
  Voice_5877_AwakerVoiceContent = {
    Text = "Capaz de corroer tudo, apagando tudo... Era uma arma e tanto. Se eu soubesse na época... Heh."
  },
  Voice_5877_AwakerVoiceTitle = {
    Text = "Bate-papo · Sobre Dissolução"
  },
  Voice_5878_AwakerVoiceContent = {
    Text = "Rumores dizem que corpos se contorcendo nas chamas parecem estar dançando."
  },
  Voice_5878_AwakerVoiceTitle = {
    Text = "Chitchat·Sobre o Fogo"
  },
  Voice_5880_AwakerVoiceContent = {
    Text = "Não saia à noite. Mesmo com uma luz de 2000 lúmens, não é completamente seguro... Uma vez que você entra na escuridão, o mal que espreita além da sua visão vai te perseguir, devorar você, perseguir você, devorar você... até que nada reste."
  },
  Voice_5880_AwakerVoiceTitle = {
    Text = "Conversas Ociosas · Sobre a Noite"
  },
  Voice_5881_AwakerVoiceContent = {Text = "Grite."},
  Voice_5881_AwakerVoiceTitle = {
    Text = "Habilidade·Um"
  },
  Voice_5882_AwakerVoiceContent = {Text = "Recebido."},
  Voice_5882_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_5883_AwakerVoiceContent = {
    Text = "É o anseio pela vida que leva o cisne a lutar por seu retorno ao céu distante."
  },
  Voice_5883_AwakerVoiceTitle = {
    Text = "Iluminar: Insight"
  },
  Voice_5883_UnlockDesc = {
    Text = "Nível de iluminação atingiu 7 para desbloquear"
  },
  Voice_5884_AwakerVoiceContent = {
    Text = "Está começando a mudar!"
  },
  Voice_5884_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_5885_AwakerVoiceContent = {Text = "Ajuda!"},
  Voice_5885_AwakerVoiceTitle = {Text = "Acertar·1"},
  Voice_5886_AwakerVoiceContent = {
    Text = "(Exclamação)"
  },
  Voice_5886_AwakerVoiceTitle = {
    Text = "Acertar · II"
  },
  Voice_5887_AwakerVoiceContent = {Text = "(Gemido)"},
  Voice_5887_AwakerVoiceTitle = {
    Text = "Acertar·III"
  },
  Voice_5888_AwakerVoiceContent = {Text = "Ah!"},
  Voice_5888_AwakerVoiceTitle = {
    Text = "Golpe·Quatro"
  },
  Voice_5889_AwakerVoiceContent = {
    Text = "Ah, o Marrom fugiu! Eu... eu provavelmente deveria recuar um pouco...\nEu queria ser amiga dela, mas acabei me tornando seu pesadelo... Ela provavelmente não quer me ver de qualquer jeito..."
  },
  Voice_5889_AwakerVoiceTitle = {
    Text = "Fofocas · Sobre Jenki"
  },
  Voice_5889_UnlockDesc = {
    Text = "Desbloqueado após adquirir o Despertar \"Jenkin\""
  },
  Voice_5890_AwakerVoiceContent = {
    Text = "Capela? Obrigado, mas eu não sou tão ultrapassado. Contanto que eu mantenha os ensinamentos do Deus da Bondade em meu coração e siga Sua vontade, minha alma nunca se desviará de Sua glória."
  },
  Voice_5890_AwakerVoiceTitle = {
    Text = "Papo reto·Sobre a Capela"
  },
  Voice_5891_AwakerVoiceContent = {
    Text = "Meu nome é Ogier. De acordo com nosso contrato, prometo minha lealdade de cavaleiro a você, proteger seu bem-estar e eliminar seus inimigos. Este juramento faço, nunca esquecerei."
  },
  Voice_5891_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_5892_AwakerVoiceContent = {
    Text = "Aquela mulher emaciada com pupilas duplas cheira exatamente como um inseto espartano."
  },
  Voice_5892_AwakerVoiceTitle = {
    Text = "Fala Ociosa · Sobre Agrippa"
  },
  Voice_5892_UnlockDesc = {
    Text = "Após obter o despertador \"Agrippa\", desbloqueado"
  },
  Voice_5893_AwakerVoiceContent = {
    Text = "Gostos? Claro, boa sorte. Eu sempre procuro um bom presságio antes de sair todos os dias."
  },
  Voice_5893_AwakerVoiceTitle = {
    Text = "Conversa·Coisas favoritas"
  },
  Voice_5894_AwakerVoiceContent = {
    Text = "P-Por favor, não diga à senhorita Hannah que estou escondido aqui. Ainda não estou pronto..."
  },
  Voice_5894_AwakerVoiceTitle = {
    Text = "Conversas Ociosas: Sobre Hannah"
  },
  Voice_5895_AwakerVoiceContent = {
    Text = "Que tal isso?"
  },
  Voice_5895_AwakerVoiceTitle = {Text = "Ataque·Um"},
  Voice_5896_AwakerVoiceContent = {
    Text = "Você é meu estimado convidado. Lembre-se, você é o único que pode acumular contas. Afinal, faz anos desde que vi um crânio tão perfeito..."
  },
  Voice_5896_AwakerVoiceTitle = {
    Text = "Conversa·Sobre Guardião do Segredo"
  },
  Voice_5897_AwakerVoiceContent = {Text = "Ai!"},
  Voice_5897_AwakerVoiceTitle = {
    Text = "Acertar·III"
  },
  Voice_5898_AwakerVoiceContent = {
    Text = "(Exclamação)"
  },
  Voice_5898_AwakerVoiceTitle = {Text = "Acertar·1"},
  Voice_5899_AwakerVoiceContent = {Text = "Ai!"},
  Voice_5899_AwakerVoiceTitle = {
    Text = "Golpe·Quatro"
  },
  Voice_5900_AwakerVoiceContent = {
    Text = "Gostos... Um rei não deveria mostrar tais preferências, mas se eu pudesse escapar dos incômodos memoriais e orações, certamente desfrutaria de algum lazer em um sofá macio."
  },
  Voice_5900_AwakerVoiceTitle = {
    Text = "Conversa·Coisas favoritas"
  },
  Voice_5901_AwakerVoiceContent = {
    Text = "Eu tomarei seu desrespeito como um pedido por descanso eterno."
  },
  Voice_5901_AwakerVoiceTitle = {
    Text = "Conversa·Toque"
  },
  Voice_5902_AwakerVoiceContent = {
    Text = "Odeia? Eu odeio um destino inescapável e uma tragédia inevitável."
  },
  Voice_5902_AwakerVoiceTitle = {
    Text = "Conversa·Coisas odiadas"
  },
  Voice_5903_AwakerVoiceContent = {Text = "Hmph!"},
  Voice_5903_AwakerVoiceTitle = {Text = "Defesa·II"},
  Voice_5904_AwakerVoiceContent = {
    Text = "(Zunido abafado)"
  },
  Voice_5904_AwakerVoiceTitle = {
    Text = "Acertar·III"
  },
  Voice_5905_AwakerVoiceContent = {
    Text = "Não chegue mais perto!"
  },
  Voice_5905_AwakerVoiceTitle = {
    Text = "Defesa · I"
  },
  Voice_5906_AwakerVoiceContent = {
    Text = "Oh, curioso sobre meu segredo? Este nome, este corpo, este rosto, esta voz—todos vêm da mulher que possuía uma cabeça de San Pedro. Ela fez um acordo comigo... Após sua morte, eu me tornei ela. Quanto ao paradeiro dela... bem, essa é minha coleção mais requintada, você sabe?"
  },
  Voice_5906_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Três"
  },
  Voice_5906_UnlockDesc = {
    Text = "Nível de afinidade atingido 6 desbloqueado"
  },
  Voice_5907_AwakerVoiceContent = {
    Text = "Você é um convidado adorável; até eu estou cativado pela sua cabeça única... Se algum dia você considerar se separar dela, não deixe de visitar minha pequena loja. Haha... só uma piada."
  },
  Voice_5907_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Dois"
  },
  Voice_5907_UnlockDesc = {
    Text = "Nível de afinidade atingido 4 desbloqueado"
  },
  Voice_5908_AwakerVoiceContent = {
    Text = "Curioso sobre minha verdadeira identidade? Ainda é cedo para isso. Apenas acredite nisso: crianças perdidas podem encontrar seu caminho na minha loja. Talvez isso inclua você também?"
  },
  Voice_5908_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Um"
  },
  Voice_5908_UnlockDesc = {
    Text = "Nível de afinidade atingido 2 desbloqueado"
  },
  Voice_5909_AwakerVoiceContent = {
    Text = "Ninguém será prejudicado."
  },
  Voice_5909_AwakerVoiceTitle = {
    Text = "Fúria Explosiva"
  },
  Voice_5910_AwakerVoiceContent = {
    Text = "Ainda não acabou!"
  },
  Voice_5910_AwakerVoiceTitle = {Text = "Acertar·1"},
  Voice_5911_AwakerVoiceContent = {
    Text = "Vendo o quanto você está trabalhando duro, eu quase me sinto culpado por coletar minha recompensa tão cedo. Então, vou deixar sua cabeça ficar onde está por enquanto.\nMas não se esqueça, já está reservada como minha propriedade pessoal, tá bom?"
  },
  Voice_5911_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Cinco"
  },
  Voice_5911_UnlockDesc = {
    Text = "Nível de afinidade atingido 10 desbloqueado"
  },
  Voice_5912_AwakerVoiceContent = {
    Text = "Eu não fui sempre assim; ela me deu uma nova vida. Nesse sentido, você também me deu uma segunda vida, então eu valorizarei sua cabeça também."
  },
  Voice_5912_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Quatro"
  },
  Voice_5912_UnlockDesc = {
    Text = "Nível de afinidade atingido 8 desbloqueado"
  },
  Voice_5913_AwakerVoiceContent = {
    Text = "Escape completamente da escuridão."
  },
  Voice_5913_AwakerVoiceTitle = {
    Text = "Despertar do Conhecimento Espiritual"
  },
  Voice_5914_AwakerVoiceContent = {
    Text = "Então aventurar-se é tão perigoso..."
  },
  Voice_5914_AwakerVoiceTitle = {
    Text = "Investigação Interrompida"
  },
  Voice_5915_AwakerVoiceContent = {
    Text = "Por que aquela garota boba foge no momento em que me vê? Da próxima vez, vou pisar no fio dela e ver aonde ela pode ir."
  },
  Voice_5915_AwakerVoiceTitle = {
    Text = "Bate-papo · Sobre Aigis"
  },
  Voice_5915_UnlockDesc = {
    Text = "Após obter o despertador \"Aigis\", desbloqueado"
  },
  Voice_5916_AwakerVoiceContent = {Text = "Ugh!"},
  Voice_5916_AwakerVoiceTitle = {Text = "Ataque·Um"},
  Voice_5917_AwakerVoiceContent = {
    Text = "Hmph~ Hahaha!"
  },
  Voice_5917_AwakerVoiceTitle = {
    Text = "Carta de Habilidade·Quatro"
  },
  Voice_5918_AwakerVoiceContent = {Text = "Hahaha!"},
  Voice_5918_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_5919_AwakerVoiceContent = {
    Text = "Aquele garoto é astuto; a sobrevivência nas ruas exige esse tipo de esperteza. Se eu ainda estivesse investigando, eu certamente me tornaria amiga dela."
  },
  Voice_5919_AwakerVoiceTitle = {
    Text = "Fofocas · Sobre Jenki"
  },
  Voice_5919_UnlockDesc = {
    Text = "Desbloqueado após adquirir o Despertar \"Jenkin\""
  },
  Voice_5920_AwakerVoiceContent = {
    Text = "O Santo Pai não pode salvar todos. Ele pode ajudar uma alma infeliz, mas não pode puxar todos para fora da lama... Estou ansioso pela queda dele, o colapso de sua fé."
  },
  Voice_5920_AwakerVoiceTitle = {
    Text = "Conversa Casual · Sobre Salvador"
  },
  Voice_5920_UnlockDesc = {
    Text = "Desbloqueado após adquirir o Despertar \"Salvador\""
  },
  Voice_5921_AwakerVoiceContent = {
    Text = "Você pode encontrar tudo nos esgotos de Londinium: salmão, sabão, uísque meio bebido... \nO que? Você pergunta por que sei disso? Uma vez arrastei o corpo do meu irmão por cinco milhas disso..."
  },
  Voice_5921_AwakerVoiceTitle = {
    Text = "Conversa Informal · Sobre os Esgotos"
  },
  Voice_5922_AwakerVoiceContent = {
    Text = "Ajoelhe-se diante de mim!"
  },
  Voice_5922_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_5923_AwakerVoiceContent = {
    Text = "Ajoelhe-se diante de mim."
  },
  Voice_5923_AwakerVoiceTitle = {
    Text = "Carta de Habilidade·Quatro"
  },
  Voice_5924_AwakerVoiceContent = {
    Text = "Depois de vislumbrar o mundo real além do campo de batalha, eu uma vez questionei o valor dos \"heróis\". Mas felizmente, conheci você — honesto, corajoso e puro. Sob sua liderança, lutarei incansavelmente pela paz e estabilidade. Desta vez, certamente completarei minha redenção."
  },
  Voice_5924_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Cinco"
  },
  Voice_5924_UnlockDesc = {
    Text = "Nível de afinidade atingido 10 desbloqueado"
  },
  Voice_5925_AwakerVoiceContent = {
    Text = "Ih! Oh não..."
  },
  Voice_5925_AwakerVoiceTitle = {
    Text = "Acertar·III"
  },
  Voice_5926_AwakerVoiceContent = {
    Text = "Imundo, sujo, caótico—este é o nosso Poder."
  },
  Voice_5926_AwakerVoiceTitle = {
    Text = "Despertar do Conhecimento Espiritual"
  },
  Voice_5927_AwakerVoiceContent = {
    Text = "Eu odeio seu ato pretensioso. Pensou que estou louco, patético, certo? Para mim, você é como Ícaro, ofuscado pelo sol. Vocês são os verdadeiramente patéticos."
  },
  Voice_5927_AwakerVoiceTitle = {
    Text = "Conversa·Coisas odiadas"
  },
  Voice_5928_AwakerVoiceContent = {
    Text = "Deixe-me tomar a dianteira!"
  },
  Voice_5928_AwakerVoiceTitle = {
    Text = "Início da Investigação"
  },
  Voice_5929_AwakerVoiceContent = {
    Text = "Aqueles caras parecem estranhos. Eles não podem ser formas de vida naturalmente nascidas neste planeta."
  },
  Voice_5929_AwakerVoiceTitle = {
    Text = "Chit-chat: Sobre os Viajeros Estelares"
  },
  Voice_5929_UnlockDesc = {
    Text = "Desbloqueado após obter qualquer um dos Despertadores \"Búzio\", \"Tinta\", \"Desmaio\" ou \"Wanda\"."
  },
  Voice_5931_AwakerVoiceContent = {Text = "(Gemido)"},
  Voice_5931_AwakerVoiceTitle = {
    Text = "Acertar·III"
  },
  Voice_5932_AwakerVoiceContent = {
    Text = "Desaparecer!"
  },
  Voice_5932_AwakerVoiceTitle = {
    Text = "Habilidade Especial · Um"
  },
  Voice_5933_AwakerVoiceContent = {
    Text = "Por favor, não..."
  },
  Voice_5933_AwakerVoiceTitle = {Text = "Acertar·1"},
  Voice_5934_AwakerVoiceContent = {
    Text = "Ser um monstro está bem. Tudo que eu sempre quis foi o poder para a vingança."
  },
  Voice_5934_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexão"
  },
  Voice_5934_UnlockDesc = {
    Text = "Nível de iluminação atingiu 3 para desbloquear"
  },
  Voice_5935_AwakerVoiceContent = {
    Text = "Além de eliminar seu oponente, você tem outros desejos? Em troca, eu atenderei seu desejo... dentro da minha capacidade, é claro."
  },
  Voice_5935_AwakerVoiceTitle = {
    Text = "Iluminar: Insight"
  },
  Voice_5935_UnlockDesc = {
    Text = "Nível de iluminação atingiu 7 para desbloquear"
  },
  Voice_5936_AwakerVoiceContent = {Text = "(Gemido)"},
  Voice_5936_AwakerVoiceTitle = {
    Text = "Golpe·Quatro"
  },
  Voice_5937_AwakerVoiceContent = {
    Text = "Um companheiro? ... Vou considerar isso. Não morra antes de eu tomar minha decisão."
  },
  Voice_5937_AwakerVoiceTitle = {
    Text = "Iluminar·Florescer"
  },
  Voice_5937_UnlockDesc = {
    Text = "Nível de iluminação atingiu 15 para desbloquear"
  },
  Voice_5938_AwakerVoiceContent = {
    Text = "Desde que foi documentado claramente pela primeira vez, o Fenômeno D afetou a vida de mais de um milhão de pessoas. Nossas ações são cruciais para a sobrevivência de toda a população humana."
  },
  Voice_5938_AwakerVoiceTitle = {
    Text = "Bate-papo · Sobre Dissolução"
  },
  Voice_5939_AwakerVoiceContent = {
    Text = "A todo vapor!"
  },
  Voice_5939_AwakerVoiceTitle = {Text = "Ataque·Um"},
  Voice_5940_AwakerVoiceContent = {
    Text = "Cuidado com a Fúria do Mar"
  },
  Voice_5940_AwakerVoiceTitle = {
    Text = "Habilidade·Um"
  },
  Voice_5941_AwakerVoiceContent = {
    Text = "Cuidado com a Fúria do Mar"
  },
  Voice_5941_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_5942_AwakerVoiceContent = {Text = "Oi!"},
  Voice_5942_AwakerVoiceTitle = {Text = "Ataque·Um"},
  Voice_5943_AwakerVoiceContent = {
    Text = "Eu sou Sua princesa e Sua mãe. Quanto a você, é apenas uma formiga insignificante diante Dele."
  },
  Voice_5943_AwakerVoiceTitle = {
    Text = "Conversa·Sobre Guardião do Segredo"
  },
  Voice_5944_AwakerVoiceContent = {
    Text = "Tudo está bem, vamos erguer as velas triunfantes."
  },
  Voice_5944_AwakerVoiceTitle = {
    Text = "Investigação Bem-sucedida"
  },
  Voice_5945_AwakerVoiceContent = {
    Text = "Fique longe de mim! Você deseja se tornar o brinquedo da princesa ou um sacrifício para o nascimento divino?"
  },
  Voice_5945_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Um"
  },
  Voice_5945_UnlockDesc = {
    Text = "Nível de afinidade atingido 2 desbloqueado"
  },
  Voice_59463_AwakerVoiceContent = {
    Text = "Uma vitória fácil, uma vitória total!"
  },
  Voice_59463_AwakerVoiceTitle = {
    Text = "Sobre-Exaltação Aliemus Explosão·II"
  },
  Voice_59464_AwakerVoiceContent = {
    Text = "Uma vitória fácil, uma vitória total!"
  },
  Voice_59464_AwakerVoiceTitle = {
    Text = "Superexaltação"
  },
  Voice_5946_AwakerVoiceContent = {
    Text = "Eu permito que você se torne uma testemunha, para testemunhar o momento radiante que desafia a ética."
  },
  Voice_5946_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Três"
  },
  Voice_5946_UnlockDesc = {
    Text = "Nível de afinidade atingido 6 desbloqueado"
  },
  Voice_5947_AwakerVoiceContent = {
    Text = "Oco? Os ocos são frequentemente criados durante a telecinesia. Os ocos criados por Casiah se conectam a outra dimensão, como aqueles em Dissolução?"
  },
  Voice_5947_AwakerVoiceTitle = {
    Text = "Bate-papo · Sobre Dissolução"
  },
  Voice_5948_AwakerVoiceContent = {
    Text = "Guardião, pelo poder da Deusa Mãe, eu reservei um lugar para você ao lado do Trono Aequor. Você testemunhará a era do renascimento após a Destruição. Regozije-se, pois esta é a promessa da Deusa Mãe!"
  },
  Voice_5948_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Cinco"
  },
  Voice_5948_UnlockDesc = {
    Text = "Nível de afinidade atingido 10 desbloqueado"
  },
  Voice_5949_AwakerVoiceContent = {
    Text = "Em reconhecimento ao seu comportamento respeitoso, eu concederei uma resposta a você. No começo, realmente houve luta. Mas agora eu entendo: minha vida de luxo origina-se Dele. A morte não é o fim; Ele me renascerá, concedendo vida eterna através deste ciclo distorcido..."
  },
  Voice_5949_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Quatro"
  },
  Voice_5949_UnlockDesc = {
    Text = "Nível de afinidade atingido 8 desbloqueado"
  },
  Voice_5950_AwakerVoiceContent = {
    Text = "O desejo daquela mulher é risível. Nada pode sobreviver à aniquilação, nem mesmo um \"deus\"."
  },
  Voice_5950_AwakerVoiceTitle = {
    Text = "Conversa: Sobre Táias"
  },
  Voice_5950_UnlockDesc = {
    Text = "Após obter o despertador \"Táias\", desbloqueado"
  },
  Voice_5951_AwakerVoiceContent = {
    Text = "Sou um praticante do Espiritismo, não um ser onipotente, e assim estou sujeito a erros. As ações daquela mulher, que arrastaram todos para a ruína, foram meus erros involuntários... Portanto, preciso da sua ajuda. Para garantir que você possa responder ao meu chamado a qualquer momento, você está autorizado a colocar uma cama no meu quarto."
  },
  Voice_5951_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Cinco"
  },
  Voice_5951_UnlockDesc = {
    Text = "Nível de afinidade atingido 10 desbloqueado"
  },
  Voice_5952_AwakerVoiceContent = {
    Text = "Você carrega o peso de enfrentar os Clades, um fardo pesado para alguém da sua idade... Se você tivesse sabido desde o início que não poderia mudar o futuro, ainda assim teria cumprido sua missão fielmente? Não se apresse em responder; reflita sobre isso enquanto eu descanso. Estou curioso sobre sua resposta."
  },
  Voice_5952_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Quatro"
  },
  Voice_5952_UnlockDesc = {
    Text = "Nível de afinidade atingido 8 desbloqueado"
  },
  Voice_5953_AwakerVoiceContent = {
    Text = "Já faz algum tempo desde que eu acordei, você não tem nada a me perguntar? As revelações de Deus, a profecia absolutamente verdadeira, até mesmo o tesouro da terra submersa—você não está curioso? \nHm... estranho."
  },
  Voice_5953_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Três"
  },
  Voice_5953_UnlockDesc = {
    Text = "Nível de afinidade atingido 6 desbloqueado"
  },
  Voice_5954_AwakerVoiceContent = {
    Text = "Eu nunca pedi adoração de ninguém. A tolice dos outros apenas me exaure ainda mais... Acalme-se, é hora de descansar."
  },
  Voice_5954_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Dois"
  },
  Voice_5954_UnlockDesc = {
    Text = "Nível de afinidade atingido 4 desbloqueado"
  },
  Voice_5955_AwakerVoiceContent = {
    Text = "Não vejo nenhuma das qualidades dos meus subordinados em você... Talvez isso seja melhor. O pensamento daquela mulher me exaure."
  },
  Voice_5955_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Um"
  },
  Voice_5955_UnlockDesc = {
    Text = "Nível de afinidade atingido 2 desbloqueado"
  },
  Voice_5956_AwakerVoiceContent = {
    Text = "Deus trata todos igualmente."
  },
  Voice_5956_AwakerVoiceTitle = {
    Text = "Despertar do Conhecimento Espiritual"
  },
  Voice_5957_AwakerVoiceContent = {
    Text = "Eu sei, você é um público especial. Não posso simplesmente te transportar para outra dimensão; isso causaria grandes problemas. Ei, você já fez isso com mais alguém? Não pergunte, é meu segredo!"
  },
  Voice_5957_AwakerVoiceTitle = {
    Text = "Conversa·Sobre Guardião do Segredo"
  },
  Voice_5958_AwakerVoiceContent = {
    Text = "Eek, você está interessado nesta aparência? Parece que sempre há um compromisso. Isso deve ser uma das minhas sorte, a sorte do Ryker!"
  },
  Voice_5958_AwakerVoiceTitle = {
    Text = "Conversa·Toque"
  },
  Voice_5959_AwakerVoiceContent = {
    Text = "Mythag é o lugar onde tenho mais memórias, e também... meu lar mais acolhedor."
  },
  Voice_5959_AwakerVoiceTitle = {
    Text = "Chat·Sobre a Universidade Mythag"
  },
  Voice_5960_AwakerVoiceContent = {
    Text = "Deixe isso comigo."
  },
  Voice_5960_AwakerVoiceTitle = {Text = "Defesa·II"},
  Voice_5961_AwakerVoiceContent = {
    Text = "Quão ingênuo!"
  },
  Voice_5961_AwakerVoiceTitle = {
    Text = "Defesa · I"
  },
  Voice_5962_AwakerVoiceContent = {
    Text = "Hino de Aequor!"
  },
  Voice_5962_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_5963_AwakerVoiceContent = {
    Text = "Aquilo que me foi concedido—"
  },
  Voice_5963_AwakerVoiceTitle = {
    Text = "Habilidade·um·Mar Calmo"
  },
  Voice_5964_AwakerVoiceContent = {
    Text = "Se você estiver disposto a reconhecer que eu ainda sou \"Ramona\", continue a me chamar assim."
  },
  Voice_5964_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_5965_AwakerVoiceContent = {
    Text = "O quê? Você também quer explorar minha raiva?"
  },
  Voice_5965_AwakerVoiceTitle = {
    Text = "Iluminar·Visão Remota"
  },
  Voice_5965_UnlockDesc = {
    Text = "Nível de iluminação atingiu 1 para desbloquear"
  },
  Voice_5966_AwakerVoiceContent = {
    Text = "A verdade... é revelada aqui."
  },
  Voice_5966_AwakerVoiceTitle = {
    Text = "Despertar do Conhecimento Espiritual"
  },
  Voice_5967_AwakerVoiceContent = {
    Text = "De acordo com as regras da rua, a comida deve ser comida imediatamente."
  },
  Voice_5967_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · I"
  },
  Voice_5968_AwakerVoiceContent = {
    Text = "Sente-se cheio."
  },
  Voice_5968_AwakerVoiceTitle = {
    Text = "Atualizar·II"
  },
  Voice_5969_AwakerVoiceContent = {
    Text = "Hmm... Está coçando. Marrom, coce minhas costas para mim."
  },
  Voice_5969_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · Três"
  },
  Voice_5970_AwakerVoiceContent = {
    Text = "Novas peças mecânicas ajudarão muito meu sistema a operar — isso não conta como gostar de algo? Desculpe, temo que não entenda sua pergunta. Preferências não têm significado para bonecas mecânicas."
  },
  Voice_5970_AwakerVoiceTitle = {
    Text = "Conversa·Coisas favoritas"
  },
  Voice_5971_AwakerVoiceContent = {
    Text = "Observe isto."
  },
  Voice_5971_AwakerVoiceTitle = {
    Text = "Habilidade·Um"
  },
  Voice_5972_AwakerVoiceContent = {Text = "Veja isso!"},
  Voice_5972_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_5974_AwakerVoiceContent = {Text = "Pense bem."},
  Voice_5974_AwakerVoiceTitle = {
    Text = "Defesa · I"
  },
  Voice_5975_AwakerVoiceContent = {
    Text = "Mantenha a calma e pense."
  },
  Voice_5975_AwakerVoiceTitle = {Text = "Defesa·II"},
  Voice_5976_AwakerVoiceContent = {
    Text = "A Senhorita Búzio, assim como eu, não é deste planeta... Não há nada que me prenda à minha casa além da Tinta. Eu me pergunto como a Senhorita Búzio se sente em relação à sua terra natal?"
  },
  Voice_5976_AwakerVoiceTitle = {
    Text = "Bate-Papo·Sobre Búzio"
  },
  Voice_5976_UnlockDesc = {
    Text = "Após obter o despertador \"Búzio\", desbloqueado"
  },
  Voice_5977_AwakerVoiceContent = {
    Text = "Não se aproxime de mim por trás, a menos que queira ter o pescoço quebrado."
  },
  Voice_5977_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Um"
  },
  Voice_5977_UnlockDesc = {
    Text = "Nível de afinidade atingido 2 desbloqueado"
  },
  Voice_5978_AwakerVoiceContent = {
    Text = "Hah—Como você pode permitir que gatos abandonados andem pelo campus?! E se aquela criatura mal-educada arranhar alguém?!"
  },
  Voice_5978_AwakerVoiceTitle = {
    Text = "Conversa·Coisas odiadas"
  },
  Voice_5979_AwakerVoiceContent = {
    Text = "Meu olhar te faz sentir desconfortável? Bom, essa é a ferocidade que me manteve vivo no purgatório."
  },
  Voice_5979_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Três"
  },
  Voice_5979_UnlockDesc = {
    Text = "Nível de afinidade atingido 6 desbloqueado"
  },
  Voice_5980_AwakerVoiceContent = {
    Text = "P poupe-me com o discurso pomposo. O que você quer de mim? Deve haver uma razão para manter minha sanidade intacta."
  },
  Voice_5980_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Dois"
  },
  Voice_5980_UnlockDesc = {
    Text = "Nível de afinidade atingido 4 desbloqueado"
  },
  Voice_5981_AwakerVoiceContent = {
    Text = "Minha vingança sempre foi direcionada aos espartanos, mas agora, até mesmo aquela cidade-estado não existe mais... Tudo bem, tornar-me sua lâmina não é impossível. Aceito você como meu parceiro, mas se você ousar me trair, eu arrancarei seu coração."
  },
  Voice_5981_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Cinco"
  },
  Voice_5981_UnlockDesc = {
    Text = "Nível de afinidade atingido 10 desbloqueado"
  },
  Voice_5982_AwakerVoiceContent = {
    Text = "Minhas mãos estão manchadas de sangue. Meus parentes fracos não entendem minha vingança; eles sussurram sobre minha crueldade, minha ingratidão e minha traição... A vingança sempre foi por mim mesmo, e ninguém mais."
  },
  Voice_5982_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Quatro"
  },
  Voice_5982_UnlockDesc = {
    Text = "Nível de afinidade atingido 8 desbloqueado"
  },
  Voice_5983_AwakerVoiceContent = {
    Text = "É hora de usar mais aço."
  },
  Voice_5983_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_5984_AwakerVoiceContent = {
    Text = "É hora de usar mais aço."
  },
  Voice_5984_AwakerVoiceTitle = {
    Text = "Habilidade·Um"
  },
  Voice_5985_AwakerVoiceContent = {Text = "Morra."},
  Voice_5985_AwakerVoiceTitle = {Text = "Ataque·Um"},
  Voice_5986_AwakerVoiceContent = {
    Text = "Estou... apenas me chame de Búzio, é assim que todos me chamam. Sim, me chame assim, como eles fazem."
  },
  Voice_5986_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_5987_AwakerVoiceContent = {
    Text = "Este corpo será o escudo do meu senhor!"
  },
  Voice_5987_AwakerVoiceTitle = {
    Text = "Exaltar · Dois"
  },
  Voice_5988_AwakerVoiceContent = {
    Text = "Este corpo será o escudo do meu senhor!"
  },
  Voice_5988_AwakerVoiceTitle = {
    Text = "Fúria Explosiva"
  },
  Voice_5989_AwakerVoiceContent = {
    Text = "\"O Quebra-Nozes\" deveria ser um conto de fadas romântico para meninas, mas aqueles indivíduos repulsivos apenas veem os membros graciosos em movimento e desejos vulgares... Decepcionante."
  },
  Voice_5989_AwakerVoiceTitle = {
    Text = "Conversa·Coisas odiadas"
  },
  Voice_5990_AwakerVoiceContent = {
    Text = "Deve... eliminar...!"
  },
  Voice_5990_AwakerVoiceTitle = {
    Text = "Habilidade·Um"
  },
  Voice_5991_AwakerVoiceContent = {
    Text = "Pandia... Ela chama isso de treinamento? Haha... Permita-me rir por um momento. Os humanos ainda são muito covardes; tudo o que fazem parece brincadeira de criança."
  },
  Voice_5991_AwakerVoiceTitle = {
    Text = "Chat·Sobre Pandia"
  },
  Voice_5991_UnlockDesc = {
    Text = "Desbloqueado após obter Despertador \"Pandia\""
  },
  Voice_5992_AwakerVoiceContent = {
    Text = "Não chegue mais perto!"
  },
  Voice_5992_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_5993_AwakerVoiceContent = {
    Text = "Preciso me apresentar novamente? Você realmente é uma mão cheia. Eu sou Jenkin, e este garoto é Marrom. \"Sinhazinha!\"\nNão se esqueça! Se você errar nossos nomes, eu vou bater na sua *censurado* com minha lanterna! \"Sinhazinha?!\""
  },
  Voice_5993_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_5994_AwakerVoiceContent = {
    Text = "Salte, salte!"
  },
  Voice_5994_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_5995_AwakerVoiceContent = {
    Text = "Salte, salte!"
  },
  Voice_5995_AwakerVoiceTitle = {
    Text = "Carta de Habilidade·Quatro"
  },
  Voice_5996_AwakerVoiceContent = {
    Text = "Aqui vem a homenagem de abertura!"
  },
  Voice_5996_AwakerVoiceTitle = {
    Text = "Exaltar · Dois"
  },
  Voice_5997_AwakerVoiceContent = {Text = "Hmph."},
  Voice_5997_AwakerVoiceTitle = {Text = "Acertar·1"},
  Voice_5998_AwakerVoiceContent = {
    Text = "Apenas um pouco de pedra, duas cinzelas e três íris voltadas para o sol... posso criar qualquer coisa para você."
  },
  Voice_5998_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexão"
  },
  Voice_5998_UnlockDesc = {
    Text = "Nível de iluminação atingiu 3 para desbloquear"
  },
  Voice_5999_AwakerVoiceContent = {Text = "(Gemido)"},
  Voice_5999_AwakerVoiceTitle = {
    Text = "Acertar·III"
  },
  Voice_6000_AwakerVoiceContent = {
    Text = "É só isso?"
  },
  Voice_6000_AwakerVoiceTitle = {
    Text = "Acertar · II"
  },
  Voice_6001_AwakerVoiceContent = {Text = "Bom."},
  Voice_6001_AwakerVoiceTitle = {
    Text = "Golpe·Quatro"
  },
  Voice_6002_AwakerVoiceContent = {
    Text = "Essa luta sem sentido..."
  },
  Voice_6002_AwakerVoiceTitle = {
    Text = "Acertar · II"
  },
  Voice_6003_AwakerVoiceContent = {Text = "(Gemido)"},
  Voice_6003_AwakerVoiceTitle = {
    Text = "Acertar·III"
  },
  Voice_6004_AwakerVoiceContent = {
    Text = "Depois da morte de Tibério, o povo de Roma finalmente cumpriu seu desejo de longa data — jogá-lo no rio Tibre para alimentar os peixes. Claro, eles pagaram um pequeno preço por isso: serem jogados na arena por Calígula para meu divertimento."
  },
  Voice_6004_AwakerVoiceTitle = {
    Text = "Conversa·Coisas favoritas"
  },
  Voice_6005_AwakerVoiceContent = {Text = "(Gemido)"},
  Voice_6005_AwakerVoiceTitle = {Text = "Acertar·1"},
  Voice_6006_AwakerVoiceContent = {
    Text = "Eu sinto que a garota pequena possui poderes semelhantes aos meus. Ela ainda não compreendeu totalmente a extensão de sua força. Por sua causa, eu irei treiná-la adequadamente."
  },
  Voice_6006_AwakerVoiceTitle = {
    Text = "Fala Ociosa · Sobre Lily"
  },
  Voice_6006_UnlockDesc = {
    Text = "Desbloqueado após adquirir o Despertar \"Lily\""
  },
  Voice_6007_AwakerVoiceContent = {
    Text = "Droga, você ainda me menospreza?!"
  },
  Voice_6007_AwakerVoiceTitle = {
    Text = "Investigação Interrompida"
  },
  Voice_6008_AwakerVoiceContent = {
    Text = "Prova de Existência"
  },
  Voice_6008_AwakerVoiceTitle = {
    Text = "Habilidade·Um"
  },
  Voice_6009_AwakerVoiceContent = {
    Text = "Prova de Existência"
  },
  Voice_6009_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_6010_AwakerVoiceContent = {
    Text = "Eu acredito que tudo acontece por uma razão, mas... a violência sem sentido, os preconceitos que fazem irmãos se voltarem uns contra os outros, realmente me entristecem. Se há algo que eu detesto, provavelmente é isso."
  },
  Voice_6010_AwakerVoiceTitle = {
    Text = "Conversa·Coisas odiadas"
  },
  Voice_6011_AwakerVoiceContent = {
    Text = "Eu realmente não quero usar esse poder."
  },
  Voice_6011_AwakerVoiceTitle = {
    Text = "Despertar do Conhecimento Espiritual"
  },
  Voice_6012_AwakerVoiceContent = {
    Text = "Não abaixe a guarda."
  },
  Voice_6012_AwakerVoiceTitle = {
    Text = "Defesa · I"
  },
  Voice_6013_AwakerVoiceContent = {Text = "Hmph"},
  Voice_6013_AwakerVoiceTitle = {Text = "Defesa·II"},
  Voice_6014_AwakerVoiceContent = {Text = "Pare!"},
  Voice_6014_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_6015_AwakerVoiceContent = {Text = "Pare!"},
  Voice_6015_AwakerVoiceTitle = {
    Text = "Habilidade·Um"
  },
  Voice_6016_AwakerVoiceContent = {
    Text = "Casiah é incrível! Ela consegue fazer um coelho aparecer em um piscar de olhos!"
  },
  Voice_6016_AwakerVoiceTitle = {
    Text = "Bate-papo · Sobre Casiah"
  },
  Voice_6016_UnlockDesc = {
    Text = "Desbloqueia ao obter o despertador \"Casiah\""
  },
  Voice_6017_AwakerVoiceContent = {
    Text = "Magie, prête !"
  },
  Voice_6017_AwakerVoiceTitle = {
    Text = "Despertar do Conhecimento Espiritual"
  },
  Voice_6018_AwakerVoiceContent = {
    Text = "Dissolução... Devo admitir, há coisas neste mundo que estão além do controle do poder."
  },
  Voice_6018_AwakerVoiceTitle = {
    Text = "Bate-papo · Sobre Dissolução"
  },
  Voice_6019_AwakerVoiceContent = {Text = "Ah—"},
  Voice_6019_AwakerVoiceTitle = {
    Text = "Início da Investigação"
  },
  Voice_6020_AwakerVoiceContent = {
    Text = "Dança em meio às chamas esmeralda."
  },
  Voice_6020_AwakerVoiceTitle = {
    Text = "Início da Investigação"
  },
  Voice_6021_AwakerVoiceContent = {
    Text = "Não se preocupe; cicatrizes são um distintivo de honra para um guerreiro."
  },
  Voice_6021_AwakerVoiceTitle = {
    Text = "Investigação Interrompida"
  },
  Voice_6022_AwakerVoiceContent = {
    Text = "Trema diante desses músculos... sempre prontos para cortar sua cabeça."
  },
  Voice_6022_AwakerVoiceTitle = {
    Text = "Conversa·Toque"
  },
  Voice_6024_AwakerVoiceContent = {
    Text = "Hora da refeição? Ou hora da atividade?"
  },
  Voice_6024_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_6024_UnlockDesc = {
    Text = "Nível de iluminação atingiu 2 para desbloquear"
  },
  Voice_6025_AwakerVoiceContent = {
    Text = "Hmm! Dessa forma, os companheiros de Aurita não desaparecerão!"
  },
  Voice_6025_AwakerVoiceTitle = {
    Text = "Iluminar·Florescer"
  },
  Voice_6025_UnlockDesc = {
    Text = "Nível de iluminação atingiu 15 para desbloquear"
  },
  Voice_6026_AwakerVoiceContent = {
    Text = "A professora Sylvia disse que devemos agradecer quando recebemos algo... Obrigado, obrigado, obrigado!"
  },
  Voice_6026_AwakerVoiceTitle = {
    Text = "Iluminar·Construção"
  },
  Voice_6026_UnlockDesc = {
    Text = "Nível de iluminação atingiu 11 para desbloquear"
  },
  Voice_6027_AwakerVoiceContent = {
    Text = "É a vez de Aurita ser o fantasma desta vez! Você só tem 5 segundos para se esconder! 5, 4—"
  },
  Voice_6027_AwakerVoiceTitle = {
    Text = "Iluminar: Insight"
  },
  Voice_6027_UnlockDesc = {
    Text = "Nível de iluminação atingiu 7 para desbloquear"
  },
  Voice_6028_AwakerVoiceContent = {
    Text = "Todos desapareceram depois de começar o esconde-esconde. Desta vez, Aurita está determinada a encontrar todos!"
  },
  Voice_6028_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexão"
  },
  Voice_6028_UnlockDesc = {
    Text = "Nível de iluminação atingiu 3 para desbloquear"
  },
  Voice_6029_AwakerVoiceContent = {
    Text = "Porque encontraram meus ossos debaixo d'água, acham que eu gosto de água e quero construir uma piscina do lado de fora dos meus aposentos? \nHaha... Façam como desejarem. Não me importunem mais com essas trivialidades."
  },
  Voice_6029_AwakerVoiceTitle = {
    Text = "Conversa·Coisas odiadas"
  },
  Voice_6030_AwakerVoiceContent = {
    Text = "Uma pequena gota no oceano, uma crente imortal, mas superficial, Miryam... te saúda."
  },
  Voice_6030_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_6031_AwakerVoiceContent = {
    Text = "É minha vez de agir."
  },
  Voice_6031_AwakerVoiceTitle = {Text = "Ataque·Um"},
  Voice_6032_AwakerVoiceContent = {Text = "Ho!"},
  Voice_6032_AwakerVoiceTitle = {Text = "Ataque·Um"},
  Voice_6033_AwakerVoiceContent = {
    Text = "Absolutamente incrível... Seu comentário casual resolveu um problema criativo que me atormentava há meses."
  },
  Voice_6033_AwakerVoiceTitle = {
    Text = "Iluminar·Visão Remota"
  },
  Voice_6033_UnlockDesc = {
    Text = "Nível de iluminação atingiu 1 para desbloquear"
  },
  Voice_6034_AwakerVoiceContent = {
    Text = "Comparado com aquelas damas nobres na festa do vinho, o temperamento de Murphy é absolutamente adorável."
  },
  Voice_6034_AwakerVoiceTitle = {
    Text = "Conversas Ociosas·Sobre Murphy"
  },
  Voice_6034_UnlockDesc = {
    Text = "Desbloqueado após obter Despertador \"Murphy\""
  },
  Voice_6035_AwakerVoiceContent = {
    Text = "Mestre da Cura Mental? Aqueles garotos estão me elogiando demais. Eu simplesmente faço o meu melhor para ouvir e ajudar a liberar sua ansiedade interna - assim como sempre fiz."
  },
  Voice_6035_AwakerVoiceTitle = {
    Text = "Chat·Sobre a Universidade Mythag"
  },
  Voice_6036_AwakerVoiceContent = {
    Text = "Não me subestime!"
  },
  Voice_6036_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_6037_AwakerVoiceContent = {
    Text = "Não me subestime!"
  },
  Voice_6037_AwakerVoiceTitle = {
    Text = "Habilidade·Um"
  },
  Voice_6038_AwakerVoiceContent = {
    Text = "Sentindo sede? Água potável é um luxo raro na prisão."
  },
  Voice_6038_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_6038_UnlockDesc = {
    Text = "Nível de iluminação atingiu 2 para desbloquear"
  },
  Voice_6039_AwakerVoiceContent = {
    Text = "Bons filhos, filhos obedientes~ Vocês não devem desistir pela metade~"
  },
  Voice_6039_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexão"
  },
  Voice_6039_UnlockDesc = {
    Text = "Nível de iluminação atingiu 3 para desbloquear"
  },
  Voice_6040_AwakerVoiceContent = {
    Text = "Você deve ter caído na minha doce armadilha, certo?"
  },
  Voice_6040_AwakerVoiceTitle = {
    Text = "Iluminar: Insight"
  },
  Voice_6040_UnlockDesc = {
    Text = "Nível de iluminação atingiu 7 para desbloquear"
  },
  Voice_6041_AwakerVoiceContent = {
    Text = "Continue, só mais um pouco~ Você está quase no pico do êxtase~"
  },
  Voice_6041_AwakerVoiceTitle = {
    Text = "Iluminar·Construção"
  },
  Voice_6041_UnlockDesc = {
    Text = "Nível de iluminação atingiu 11 para desbloquear"
  },
  Voice_6042_AwakerVoiceContent = {
    Text = "Entrei na escola aos 14 anos. Se eu tivesse me formado sem problemas, você estaria me chamando de \"Diretor\" agora."
  },
  Voice_6042_AwakerVoiceTitle = {
    Text = "Chat·Sobre a Universidade Mythag"
  },
  Voice_6043_AwakerVoiceContent = {
    Text = "Seu cérebro frágil parece incapaz de reter lições."
  },
  Voice_6043_AwakerVoiceTitle = {
    Text = "Conversa·Toque"
  },
  Voice_6044_AwakerVoiceContent = {
    Text = "Você pergunta qual é o meu desejo? Viagens seguras e paz—não conta?\nQuanto a outros desejos, não pensei muito sobre eles... Mas vou considerar cuidadosamente e te direi depois."
  },
  Voice_6044_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Três"
  },
  Voice_6044_UnlockDesc = {
    Text = "Nível de afinidade atingido 6 desbloqueado"
  },
  Voice_6045_AwakerVoiceContent = {
    Text = "\"O que busco são os mistérios do universo. Quero entender qual Poder está me controlando.\" Embora eu não esteja satisfeito com a trama deste romance e ache sua ciência fictícia risivelmente ingênua, após lê-lo, você deve me entender... Espere, você já leu este livro?"
  },
  Voice_6045_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Quatro"
  },
  Voice_6045_UnlockDesc = {
    Text = "Nível de afinidade atingido 8 desbloqueado"
  },
  Voice_6046_AwakerVoiceContent = {
    Text = "Missão e destino são semelhantes. Não podem ser facilmente abandonados, nem é necessário fazê-lo."
  },
  Voice_6046_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Um"
  },
  Voice_6046_UnlockDesc = {
    Text = "Nível de afinidade atingido 2 desbloqueado"
  },
  Voice_6047_AwakerVoiceContent = {
    Text = "Eu pareço sempre ocupado? Sim, assistentes podem ocasionalmente ajudar, mas em algumas pesquisas, sou insubstituível. Quer ajudar? Então confira de vez em quando para ver se ainda estou vivo."
  },
  Voice_6047_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Dois"
  },
  Voice_6047_UnlockDesc = {
    Text = "Nível de afinidade atingido 4 desbloqueado"
  },
  Voice_6048_AwakerVoiceContent = {
    Text = "Você acha que estou bravo? Você sabe quantos músculos são necessários para sorrir? Uma vez, expliquei isso na aula, que claramente escapou do seu cérebro liso. A resposta é pelo menos dezessete, e não tenho motivo para ficar bravo com você."
  },
  Voice_6048_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Três"
  },
  Voice_6048_UnlockDesc = {
    Text = "Nível de afinidade atingido 6 desbloqueado"
  },
  Voice_6049_AwakerVoiceContent = {
    Text = "A Senhorita Ramona disse: \"Não preciso acomodar todos. Você entende o que isso significa? ...Significa que não preciso mais de sua proteção?\""
  },
  Voice_6049_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Quatro"
  },
  Voice_6049_UnlockDesc = {
    Text = "Nível de afinidade atingido 8 desbloqueado"
  },
  Voice_6050_AwakerVoiceContent = {
    Text = "Treze relatórios requerem aprovação urgente, seis comunicadores danificados estão esperando para serem reparados, e eu também preciso monitorar os resultados de cinco diferentes experimentos de extração de Prata... Então, em vez de desperdiçar meu tempo limitado me incomodando, por que não tenta exercitar sua fraca matéria cinzenta?"
  },
  Voice_6050_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Um"
  },
  Voice_6050_UnlockDesc = {
    Text = "Nível de afinidade atingido 2 desbloqueado"
  },
  Voice_6051_AwakerVoiceContent = {
    Text = "Espero que da próxima vez, minha terra natal responda ao meu chamado."
  },
  Voice_6051_AwakerVoiceTitle = {
    Text = "Investigação Bem-sucedida"
  },
  Voice_6052_AwakerVoiceContent = {
    Text = "Tranca liberada."
  },
  Voice_6052_AwakerVoiceTitle = {
    Text = "Despertar do Conhecimento Espiritual"
  },
  Voice_6054_AwakerVoiceContent = {
    Text = "Estou tão feliz... Você é tão tendencioso e me favorece tanto."
  },
  Voice_6054_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_6054_UnlockDesc = {
    Text = "Nível de iluminação atingiu 2 para desbloquear"
  },
  Voice_6055_AwakerVoiceContent = {
    Text = "Outros podem ficar chateados se acharem que você está mostrando favoritismo."
  },
  Voice_6055_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexão"
  },
  Voice_6055_UnlockDesc = {
    Text = "Nível de iluminação atingiu 3 para desbloquear"
  },
  Voice_6056_AwakerVoiceContent = {
    Text = "Você também anseia por mim?"
  },
  Voice_6056_AwakerVoiceTitle = {
    Text = "Iluminar: Insight"
  },
  Voice_6056_UnlockDesc = {
    Text = "Nível de iluminação atingiu 7 para desbloquear"
  },
  Voice_6057_AwakerVoiceContent = {
    Text = "Finalmente, acabou. Não mais ver aqueles negros, viscosos..."
  },
  Voice_6057_AwakerVoiceTitle = {
    Text = "Investigação Bem-sucedida"
  },
  Voice_6058_AwakerVoiceContent = {
    Text = "Por tudo que você me deu, seu amor já se tornou um com o meu..."
  },
  Voice_6058_AwakerVoiceTitle = {
    Text = "Iluminar·Florescer"
  },
  Voice_6058_UnlockDesc = {
    Text = "Nível de iluminação atingiu 15 para desbloquear"
  },
  Voice_6059_AwakerVoiceContent = {Text = "Oi!"},
  Voice_6059_AwakerVoiceTitle = {Text = "Defesa·II"},
  Voice_6060_AwakerVoiceContent = {
    Text = "Então perigoso."
  },
  Voice_6060_AwakerVoiceTitle = {
    Text = "Defesa · I"
  },
  Voice_6061_AwakerVoiceContent = {
    Text = "Você trabalhou tanto; é hora de aproveitar os frutos do seu trabalho, certo? Venha mais perto, eu não vou desapontá-lo~"
  },
  Voice_6061_AwakerVoiceTitle = {
    Text = "Iluminar·Florescer"
  },
  Voice_6061_UnlockDesc = {
    Text = "Nível de iluminação atingiu 15 para desbloquear"
  },
  Voice_6062_AwakerVoiceContent = {
    Text = "Eu... eu entendo sua intenção. Embora eu ainda seja desajeitada, Aigis lutará por você com todas as suas forças!"
  },
  Voice_6062_AwakerVoiceTitle = {
    Text = "Iluminar·Florescer"
  },
  Voice_6062_UnlockDesc = {
    Text = "Nível de iluminação atingiu 15 para desbloquear"
  },
  Voice_6063_AwakerVoiceContent = {
    Text = "Seu olhar está me queimando... A Aigis te causou algum problema?"
  },
  Voice_6063_AwakerVoiceTitle = {
    Text = "Iluminar·Construção"
  },
  Voice_6063_UnlockDesc = {
    Text = "Nível de iluminação atingiu 11 para desbloquear"
  },
  Voice_6064_AwakerVoiceContent = {
    Text = "Aigis está muito ansiosa... insegura se pode atender às suas expectativas..."
  },
  Voice_6064_AwakerVoiceTitle = {
    Text = "Iluminar: Insight"
  },
  Voice_6064_UnlockDesc = {
    Text = "Nível de iluminação atingiu 7 para desbloquear"
  },
  Voice_6065_AwakerVoiceContent = {
    Text = "Seu olhar sobre mim deixa Aigis inquieta... Você não tem medo da maldição?"
  },
  Voice_6065_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexão"
  },
  Voice_6065_UnlockDesc = {
    Text = "Nível de iluminação atingiu 3 para desbloquear"
  },
  Voice_6066_AwakerVoiceContent = {
    Text = "P-por favor, não olhe nos meus olhos... Aigis tem medo de te machucar... Afinal, sou como um monstro..."
  },
  Voice_6066_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_6066_UnlockDesc = {
    Text = "Nível de iluminação atingiu 2 para desbloquear"
  },
  Voice_6067_AwakerVoiceContent = {
    Text = "O sentido de olfato da besta é apenas sorte, certo? Não entenda errado, ok?"
  },
  Voice_6067_AwakerVoiceTitle = {
    Text = "Iluminar·Visão Remota"
  },
  Voice_6067_UnlockDesc = {
    Text = "Nível de iluminação atingiu 1 para desbloquear"
  },
  Voice_6068_AwakerVoiceContent = {
    Text = "Não posso parar ainda..."
  },
  Voice_6068_AwakerVoiceTitle = {
    Text = "Investigação Interrompida"
  },
  Voice_6069_AwakerVoiceContent = {
    Text = "Poder, incessante!"
  },
  Voice_6069_AwakerVoiceTitle = {
    Text = "Carta de Habilidade·Quatro"
  },
  Voice_6070_AwakerVoiceContent = {
    Text = "Poder, sempre fluindo."
  },
  Voice_6070_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_6071_AwakerVoiceContent = {
    Text = "Você gosta do mar? Eu amo o mar, não importa o que aconteça. Ainda me lembro daquele dia, muitos anos atrás, quando o mar gentilmente trouxe a tão esperada morte para o infeliz eu."
  },
  Voice_6071_AwakerVoiceTitle = {
    Text = "Conversa·Coisas favoritas"
  },
  Voice_6073_AwakerVoiceContent = {
    Text = "Por algum motivo, um senso sem precedentes de prazer surgiu..."
  },
  Voice_6073_AwakerVoiceTitle = {
    Text = "Investigação Interrompida"
  },
  Voice_6074_AwakerVoiceContent = {
    Text = "Essa correnteza vai despedaçar os inimigos."
  },
  Voice_6074_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_6075_AwakerVoiceContent = {
    Text = "Essa correnteza vai despedaçar os inimigos."
  },
  Voice_6075_AwakerVoiceTitle = {
    Text = "Carta de Habilidade·Quatro"
  },
  Voice_6076_AwakerVoiceContent = {
    Text = "Estive esperando alguém para me ensinar o verdadeiro amor, dor e desejo. Você pode cumprir meu desejo? Você pode me redimir desta prisão escura?"
  },
  Voice_6076_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Cinco"
  },
  Voice_6076_UnlockDesc = {
    Text = "Nível de afinidade atingido 10 desbloqueado"
  },
  Voice_6077_AwakerVoiceContent = {
    Text = "Você quer saber a verdade? Eu odeio a prisão, odeio a escuridão, e a odeio tanto que poderia morrer. Quero ser notado e quero ser aceso..."
  },
  Voice_6077_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Quatro"
  },
  Voice_6077_UnlockDesc = {
    Text = "Nível de afinidade atingido 8 desbloqueado"
  },
  Voice_6078_AwakerVoiceContent = {
    Text = "Tudo é para o bem-estar eterno do futuro."
  },
  Voice_6078_AwakerVoiceTitle = {
    Text = "Início da Investigação"
  },
  Voice_6079_AwakerVoiceContent = {
    Text = "Quer me desfrutar? Então torne-se meu escravo. Eu te farei derreter de calor~"
  },
  Voice_6079_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Um"
  },
  Voice_6079_UnlockDesc = {
    Text = "Nível de afinidade atingido 2 desbloqueado"
  },
  Voice_6080_AwakerVoiceContent = {
    Text = "Considere isso uma humilde oferta de seu servo."
  },
  Voice_6080_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · I"
  },
  Voice_6081_AwakerVoiceContent = {
    Text = "Estou tão entediado, tão entediado. Comparado àqueles grandes prisioneiros tremendo, isso é como brincar de casinha. Por que você não me faz companhia~"
  },
  Voice_6081_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Três"
  },
  Voice_6081_UnlockDesc = {
    Text = "Nível de afinidade atingido 6 desbloqueado"
  },
  Voice_6082_AwakerVoiceContent = {
    Text = "Eu desejo mais escravos, para ouvir seus gemidos e súplicas—\nTraga-me mais escravos~ Por favor~"
  },
  Voice_6082_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Dois"
  },
  Voice_6082_UnlockDesc = {
    Text = "Nível de afinidade atingido 4 desbloqueado"
  },
  Voice_6083_AwakerVoiceContent = {
    Text = "Desculpe, me perdi nas memórias novamente. Por favor, não fique triste. É sua vez de narrar sua história. Você gostaria de escrever um poema? Suas aventuras, suas experiências, suas alegrias, suas tristezas, fluirão como um rio flutuante da sua mente para suas pontas dos dedos?"
  },
  Voice_6083_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Quatro"
  },
  Voice_6083_UnlockDesc = {
    Text = "Nível de afinidade atingido 8 desbloqueado"
  },
  Voice_6084_AwakerVoiceContent = {
    Text = "Eu era apenas uma marca de água fugaz em pergaminho, mas nosso encontro me fez persistir. Talvez isso seja um milagre. Vou valorizar esse milagre e compor poemas atemporais para você."
  },
  Voice_6084_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Cinco"
  },
  Voice_6084_UnlockDesc = {
    Text = "Nível de afinidade atingido 10 desbloqueado"
  },
  Voice_6085_AwakerVoiceContent = {
    Text = "Alguém uma vez me disse que a poesia é escrita para ser apreciada... Posso ouvir seus pensamentos sobre isso?"
  },
  Voice_6085_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Um"
  },
  Voice_6085_UnlockDesc = {
    Text = "Nível de afinidade atingido 2 desbloqueado"
  },
  Voice_6086_AwakerVoiceContent = {
    Text = "Você já passou por isso? Enfrentando as ofensas dos outros com um coração perdoador, apenas para não alcançar o resultado desejado. Você entrega uma rosa, mas suas mãos ficam sem o aroma duradouro, apenas com as marcas sangrentas de espinhos afiados."
  },
  Voice_6086_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Dois"
  },
  Voice_6086_UnlockDesc = {
    Text = "Nível de afinidade atingido 4 desbloqueado"
  },
  Voice_6087_AwakerVoiceTitle = {
    Text = "Acertar·III"
  },
  Voice_6088_AwakerVoiceContent = {
    Text = "Minha caneta e tinta..."
  },
  Voice_6088_AwakerVoiceTitle = {Text = "Acertar·1"},
  Voice_6089_AwakerVoiceContent = {
    Text = "(Exclamação)"
  },
  Voice_6089_AwakerVoiceTitle = {
    Text = "Acertar·III"
  },
  Voice_6090_AwakerVoiceContent = {Text = "Errado..."},
  Voice_6090_AwakerVoiceTitle = {
    Text = "Acertar · II"
  },
  Voice_6091_AwakerVoiceContent = {
    Text = "(Exclamação)"
  },
  Voice_6091_AwakerVoiceTitle = {
    Text = "Golpe·Quatro"
  },
  Voice_6092_AwakerVoiceContent = {
    Text = "Esta é uma bênção do Grande!"
  },
  Voice_6092_AwakerVoiceTitle = {
    Text = "Fúria Explosiva"
  },
  Voice_6093_AwakerVoiceContent = {
    Text = "Bênção do Grande Pálido"
  },
  Voice_6093_AwakerVoiceTitle = {
    Text = "Exaltar · Dois"
  },
  Voice_6094_AwakerVoiceContent = {
    Text = "Eu não tenho tempo para descansar. O Fenômeno D destruiu dois dos meus corpos. Antes que o fim me alcance, há muito que preciso entender... Ajude-me, começando com a preparação dos materiais para o experimento. Confio que você não vai errar o equilíbrio."
  },
  Voice_6094_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Cinco"
  },
  Voice_6094_UnlockDesc = {
    Text = "Nível de afinidade atingido 10 desbloqueado"
  },
  Voice_6095_AwakerVoiceContent = {
    Text = "Eu amo o vitral em Fontainebleau. Ele projeta diferentes tons nos rostos das pessoas: púrpura desesperadora, azul lisonjeiro e, claro, meu favorito—vermelho ambicioso..."
  },
  Voice_6095_AwakerVoiceTitle = {
    Text = "Conversa·Coisas favoritas"
  },
  Voice_6096_AwakerVoiceContent = {
    Text = "Aqui, frequentemente sinto a presença do meu Senhor, mas talvez eu ainda não esteja pronto para encará-Lo... De qualquer forma, obrigado por me oferecer abrigo."
  },
  Voice_6096_AwakerVoiceTitle = {
    Text = "Chat·Sobre a Universidade Mythag"
  },
  Voice_6097_AwakerVoiceContent = {
    Text = "A traição transforma as pessoas em monstros, não importa de que lado estejam. É por isso que eu detesto traidores."
  },
  Voice_6097_AwakerVoiceTitle = {
    Text = "Conversa·Coisas odiadas"
  },
  Voice_60985_AwakerVoiceContent = {
    Text = "Hameln, à sua disposição."
  },
  Voice_60985_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_60986_AwakerVoiceContent = {
    Text = "Eu uma vez conheci alguém com uma compreensão quase instintiva da música. Os concertos e sinfonias criados por essa pessoa foram inesquecíveis.\nUm verdadeiro gênio."
  },
  Voice_60986_AwakerVoiceTitle = {
    Text = "Conversa Casual: Sobre Velhos Conhecidos"
  },
  Voice_60987_AwakerVoiceContent = {
    Text = "Eu não gosto de passar tempo em estratégia. Comparado à música, a arte da estratégia tem pouco valor. No entanto, como uma ferramenta para derrubar obstáculos, é necessária. Para alcançar o auge da música, não me importo em usá-la."
  },
  Voice_60987_AwakerVoiceTitle = {
    Text = "Conversa Casual: Sobre Estratégia"
  },
  Voice_60988_AwakerVoiceContent = {Text = "Rude."},
  Voice_60988_AwakerVoiceTitle = {
    Text = "Golpe·Quatro"
  },
  Voice_60989_AwakerVoiceContent = {
    Text = "Aqui está de novo. Que melodia é essa? Desde a última vez que a ouvi, ela ficou na minha mente, recusando-se a partir ou descansar."
  },
  Voice_60989_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_60989_UnlockDesc = {
    Text = "Nível de iluminação atingiu 2 para desbloquear"
  },
  Voice_6098_AwakerVoiceContent = {
    Text = "(Exclamação)"
  },
  Voice_6098_AwakerVoiceTitle = {Text = "Acertar·1"},
  Voice_60990_AwakerVoiceContent = {
    Text = "Em termos de técnica, planejamento estratégico e condução musical não são diferentes. A humanidade, a emoção, o desejo... eles são tão claros e dóceis quanto notas em uma pauta, expostas diante dos meus olhos, dançando ao longo do caminho do bastão. Entender música é entender tudo."
  },
  Voice_60990_AwakerVoiceTitle = {
    Text = "Conversa Casual: Sobre Comunidade"
  },
  Voice_60991_AwakerVoiceContent = {
    Text = "Quase lá, só mais um pouco. Eu preciso terminar isso; eu preciso ouvir!"
  },
  Voice_60991_AwakerVoiceTitle = {
    Text = "Iluminar·Construção"
  },
  Voice_60991_UnlockDesc = {
    Text = "Nível de iluminação atingiu 11 para desbloquear"
  },
  Voice_60992_AwakerVoiceContent = {Text = "Hmm."},
  Voice_60992_AwakerVoiceTitle = {Text = "Acertar·1"},
  Voice_60993_AwakerVoiceContent = {Text = "Rude."},
  Voice_60993_AwakerVoiceTitle = {
    Text = "Acertar · II"
  },
  Voice_60994_AwakerVoiceContent = {Text = "Hmm."},
  Voice_60994_AwakerVoiceTitle = {
    Text = "Acertar·III"
  },
  Voice_60995_AwakerVoiceContent = {
    Text = "A música transcende a linguagem, a escrita e tudo. Se isso não é perfeição, não sei o que é."
  },
  Voice_60995_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Um"
  },
  Voice_60995_UnlockDesc = {
    Text = "Nível de afinidade atingido 2 desbloqueado"
  },
  Voice_60996_AwakerVoiceContent = {
    Text = "Preste atenção no ritmo."
  },
  Voice_60996_AwakerVoiceTitle = {
    Text = "Habilidade·Um"
  },
  Voice_60997_AwakerVoiceContent = {
    Text = "Sintonia completa."
  },
  Voice_60997_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · I"
  },
  Voice_60998_AwakerVoiceContent = {
    Text = "Fico feliz que você entenda a importância do treinamento."
  },
  Voice_60998_AwakerVoiceTitle = {
    Text = "Atualizar·II"
  },
  Voice_60999_AwakerVoiceContent = {
    Text = "Eu entregarei uma performance perfeita."
  },
  Voice_60999_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · Três"
  },
  Voice_6099_AwakerVoiceContent = {
    Text = "Invejoso? Essas escamas duras são prova de uma linhagem nobre."
  },
  Voice_6099_AwakerVoiceTitle = {
    Text = "Conversa·Toque"
  },
  Voice_61000_AwakerVoiceContent = {
    Text = "Eu fui uma vez elogiado, mas... isso não era verdade talento.\nMinhas obras eram meras imitações de meus predecessores."
  },
  Voice_61000_AwakerVoiceTitle = {
    Text = "Conversa Casual: Sobre o Trabalho"
  },
  Voice_61001_AwakerVoiceContent = {
    Text = "Madeiras e cordas... entrelaçando-se para cima e para baixo, o motivo reaparece... Agora me lembro, é o réquiem que compus para o gênio prematuramente falecido, a estrela caída."
  },
  Voice_61001_AwakerVoiceTitle = {
    Text = "Iluminar: Insight"
  },
  Voice_61001_UnlockDesc = {
    Text = "Nível de iluminação atingiu 7 para desbloquear"
  },
  Voice_61002_AwakerVoiceContent = {
    Text = "Hmm? Você tem uma nova peça para me mostrar?"
  },
  Voice_61002_AwakerVoiceTitle = {
    Text = "Conversa·Toque"
  },
  Voice_61003_AwakerVoiceContent = {
    Text = "Esta melodia é dedicada às almas dos que partiram."
  },
  Voice_61003_AwakerVoiceTitle = {
    Text = "Despertar do Conhecimento Espiritual"
  },
  Voice_61004_AwakerVoiceContent = {
    Text = "A dançarina verde possuía uma elegância digna de ser a líder de uma trupe de corte.\nSe tivesse a oportunidade, realmente espero que pudéssemos colaborar."
  },
  Voice_61004_AwakerVoiceTitle = {
    Text = "Conversa Informal: Sobre Liz"
  },
  Voice_61004_UnlockDesc = {
    Text = "Desbloqueado após adquirir o Despertar \"Liz\""
  },
  Voice_61005_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_61006_AwakerVoiceContent = {
    Text = "Há um concertino na orquestra, mas um concertino sozinho não pode formar uma orquestra completa. Minha orquestra não tem lugar para aqueles que apenas buscam se exibir."
  },
  Voice_61006_AwakerVoiceTitle = {
    Text = "Conversa·Coisas odiadas"
  },
  Voice_61007_AwakerVoiceContent = {
    Text = "Eu acho que ouvi uma melodia. Alguém está ensaiando nas proximidades?"
  },
  Voice_61007_AwakerVoiceTitle = {
    Text = "Iluminar·Visão Remota"
  },
  Voice_61007_UnlockDesc = {
    Text = "Nível de iluminação atingiu 1 para desbloquear"
  },
  Voice_61008_AwakerVoiceTitle = {Text = "Defesa·II"},
  Voice_61009_AwakerVoiceTitle = {
    Text = "Defesa · I"
  },
  Voice_6100_AwakerVoiceContent = {
    Text = "Prepare-se para encontrar seu destino!"
  },
  Voice_6100_AwakerVoiceTitle = {
    Text = "Habilidade·Um"
  },
  Voice_61010_AwakerVoiceContent = {
    Text = "Sim, sim, é isso — a missa final, um réquiem pela própria música!"
  },
  Voice_61010_AwakerVoiceTitle = {
    Text = "Iluminar·Florescer"
  },
  Voice_61010_UnlockDesc = {
    Text = "Nível de iluminação atingiu 15 para desbloquear"
  },
  Voice_61011_AwakerVoiceContent = {
    Text = "Ah, Guardião, você chegou na hora certa. Diga-me, o que você acha desse movimento?"
  },
  Voice_61011_AwakerVoiceTitle = {
    Text = "Conversa·Sobre Guardião do Segredo"
  },
  Voice_61012_AwakerVoiceContent = {
    Text = "Cordas, comecem."
  },
  Voice_61012_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_61013_AwakerVoiceTitle = {
    Text = "Carta de Habilidade·Quatro"
  },
  Voice_61014_AwakerVoiceContent = {
    Text = "Ficou claro, aquela melodia sinuosa, como o lamento de uma alma... Tenho certeza de que a ouvi em algum lugar antes."
  },
  Voice_61014_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexão"
  },
  Voice_61014_UnlockDesc = {
    Text = "Nível de iluminação atingiu 3 para desbloquear"
  },
  Voice_61015_AwakerVoiceContent = {
    Text = "A racionalidade e a ordem abriram caminho. Eu subi e abri os portões do salão. Além deles, nada permaneceu — a verdadeira música eterna transcende a razão."
  },
  Voice_61015_AwakerVoiceTitle = {
    Text = "Conversa Casual: Sobre Razão e Ordem"
  },
  Voice_61016_AwakerVoiceContent = {
    Text = "Observe minhas mãos, um, dois, três."
  },
  Voice_61016_AwakerVoiceTitle = {
    Text = "Início da Investigação"
  },
  Voice_61017_AwakerVoiceContent = {
    Text = "Eu ouvi a apresentação da sua chamada orquestra, cheia de erros. Mas não se preocupe, eu tenho um plano detalhado para apresentar um show perfeito antes do Festival da Prata Congelada."
  },
  Voice_61017_AwakerVoiceTitle = {
    Text = "Conversa·Sobre Missaga"
  },
  Voice_61018_AwakerVoiceContent = {
    Text = "Nunca poderei esquecer a primeira vez que ouvi a música profundamente em minha consciência. Nasquelas notas e acordes, o mundo real desapareceu; apenas a música pura e sublime permaneceu."
  },
  Voice_61018_AwakerVoiceTitle = {
    Text = "Conversa·Coisas favoritas"
  },
  Voice_61019_AwakerVoiceContent = {
    Text = "É uma pena. Parece que mais ensaios são necessários."
  },
  Voice_61019_AwakerVoiceTitle = {
    Text = "Investigação Interrompida"
  },
  Voice_6101_AwakerVoiceContent = {
    Text = "Isso é uma ordem."
  },
  Voice_6101_AwakerVoiceTitle = {Text = "Ataque·II"},
  Voice_61020_AwakerVoiceContent = {
    Text = "Normalmente, não faço tais convites, mas... você gostaria de tentar? Segure a batuta e dê nova vida à música?"
  },
  Voice_61020_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Cinco"
  },
  Voice_61020_UnlockDesc = {
    Text = "Nível de afinidade atingido 10 desbloqueado"
  },
  Voice_61021_AwakerVoiceContent = {
    Text = "Eu prefiro me expressar através da música ao invés de palavras. Mas comunicar-me com você é como conduzir uma orquestra que foi ensaiada inúmeras vezes—suave, e frequentemente agradavelmente surpreendente.\nVocê ocupa um lugar especial tanto para a música quanto para mim."
  },
  Voice_61021_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Quatro"
  },
  Voice_61021_UnlockDesc = {
    Text = "Nível de afinidade atingido 8 desbloqueado"
  },
  Voice_61022_AwakerVoiceContent = {
    Text = "Em uma sinfonia, a coordenação entre os instrumentos é crucial; como cada seção entra e sai traz uma experiência diferente para a música.\nO que quero dizer é que, se comandar Despertadores é uma performance, você está se saindo bem."
  },
  Voice_61022_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Três"
  },
  Voice_61022_UnlockDesc = {
    Text = "Nível de afinidade atingido 6 desbloqueado"
  },
  Voice_61023_AwakerVoiceContent = {
    Text = "Você gosta desta peça? Ela apresenta completamente o tema em apenas quatro compasses, com os instrumentos de sopro empurrando a melodia para cima até o tema ser alcançado. Tal design influenciou incontáveis sucessores... Desculpe, estou falando demais?"
  },
  Voice_61023_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Dois"
  },
  Voice_61023_UnlockDesc = {
    Text = "Nível de afinidade atingido 4 desbloqueado"
  },
  Voice_61024_AwakerVoiceContent = {
    Text = "Desempenho Perfeito."
  },
  Voice_61024_AwakerVoiceTitle = {
    Text = "Investigação Bem-sucedida"
  },
  Voice_61025_AwakerVoiceTitle = {Text = "Ataque·Um"},
  Voice_61026_AwakerVoiceTitle = {Text = "Ataque·II"},
  Voice_61027_AwakerVoiceContent = {
    Text = "Cada um de nós esconde uma melodia em nossos corações, aprisionada pela razão e pelo corpo, apenas para ser plenamente expressa na loucura."
  },
  Voice_61027_AwakerVoiceTitle = {
    Text = "Bate-papo · Sobre Dissolução"
  },
  Voice_61028_AwakerVoiceContent = {
    Text = "Apenas a música merece louvor."
  },
  Voice_61028_AwakerVoiceTitle = {
    Text = "Fúria Explosiva"
  },
  Voice_61029_AwakerVoiceContent = {
    Text = "Apenas a música merece louvor."
  },
  Voice_61029_AwakerVoiceTitle = {
    Text = "Exaltar · Dois"
  },
  Voice_6102_AwakerVoiceContent = {Text = "Vá."},
  Voice_6102_AwakerVoiceTitle = {Text = "Ataque·Um"},
  Voice_61030_AwakerVoiceContent = {
    Text = "Ouça, este é o último réquiem!"
  },
  Voice_61030_AwakerVoiceTitle = {
    Text = "Superexaltação"
  },
  Voice_6103_AwakerVoiceContent = {
    Text = "Implore por misericórdia!"
  },
  Voice_6103_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_61049_AwakerVoiceContent = {
    Text = "Ouça, este é o último réquiem!"
  },
  Voice_61049_AwakerVoiceTitle = {
    Text = "Sobre-Exaltação Aliemus Explosão·II"
  },
  Voice_6104_AwakerVoiceContent = {Text = "(Gemido)"},
  Voice_6104_AwakerVoiceTitle = {
    Text = "Acertar·III"
  },
  Voice_6105_AwakerVoiceContent = {
    Text = "Você também deseja ser consumido pelas chamas verdes?"
  },
  Voice_6105_AwakerVoiceTitle = {
    Text = "Conversa·Toque"
  },
  Voice_6107_AwakerVoiceContent = {
    Text = "Ousa perder o foco?"
  },
  Voice_6107_AwakerVoiceTitle = {Text = "Ataque·Um"},
  Voice_6108_AwakerVoiceContent = {
    Text = "Concentre-se!"
  },
  Voice_6108_AwakerVoiceTitle = {Text = "Ataque·II"},
  Voice_6109_AwakerVoiceContent = {
    Text = "Como pode haver alunos tão adoráveis na universidade~ Eu apenas perguntei a ele, \"Você gostaria de ser meu servo?\" e ele ficou ruborizado, gaguejando algo sobre como \"já sou um cavaleiro do Guardião\"...\nClaramente, não há conflito algum~"
  },
  Voice_6109_AwakerVoiceTitle = {
    Text = "Conversa Casual · Sobre Ogier"
  },
  Voice_6109_UnlockDesc = {
    Text = "Desbloqueia ao obter o despertador \"Ogier\""
  },
  Voice_6110_AwakerVoiceContent = {
    Text = "Não pense nem em se aproximar da princesa."
  },
  Voice_6110_AwakerVoiceTitle = {
    Text = "Habilidade·Um·Onda de Ira"
  },
  Voice_6111_AwakerVoiceContent = {
    Text = "Aceite seu destino."
  },
  Voice_6111_AwakerVoiceTitle = {
    Text = "Habilidade·um·Onda"
  },
  Voice_6112_AwakerVoiceContent = {
    Text = "Os portões da minha terra natal estão se afastando... Não... Novamente não..."
  },
  Voice_6112_AwakerVoiceTitle = {
    Text = "Investigação Interrompida"
  },
  Voice_6113_AwakerVoiceContent = {
    Text = "Saia do caminho!"
  },
  Voice_6113_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_6114_AwakerVoiceContent = {
    Text = "Saia do caminho!"
  },
  Voice_6114_AwakerVoiceTitle = {
    Text = "Carta de Habilidade·Quatro"
  },
  Voice_6115_AwakerVoiceContent = {
    Text = "Pague o preço por suas ações."
  },
  Voice_6115_AwakerVoiceTitle = {
    Text = "Início da Investigação"
  },
  Voice_6116_AwakerVoiceContent = {
    Text = "Você quer morrer?"
  },
  Voice_6116_AwakerVoiceTitle = {
    Text = "Conversa·Toque"
  },
  Voice_6117_AwakerVoiceContent = {
    Text = "Eu acho que fui afligido pela Dissolução novamente... Meu coração está se dissolvendo! Apenas alguns aspirinas, um chicote e um pouco de dor devem resolver o truque para me curar..."
  },
  Voice_6117_AwakerVoiceTitle = {
    Text = "Bate-papo · Sobre Dissolução"
  },
  Voice_6118_AwakerVoiceContent = {
    Text = "Até você não consegue curar essa doença fantasmagórica? Então por que perseguir a Dissolução, arriscando sua vida?"
  },
  Voice_6118_AwakerVoiceTitle = {
    Text = "Bate-papo · Sobre Dissolução"
  },
  Voice_6119_AwakerVoiceContent = {
    Text = "Sou o último guerreiro romano—Uvhash!"
  },
  Voice_6119_AwakerVoiceTitle = {
    Text = "Fúria Explosiva"
  },
  Voice_6120_AwakerVoiceContent = {Text = "(Gemido)"},
  Voice_6120_AwakerVoiceTitle = {
    Text = "Acertar·III"
  },
  Voice_6121_AwakerVoiceContent = {
    Text = "Sou o último guerreiro romano—Uvhash!"
  },
  Voice_6121_AwakerVoiceTitle = {
    Text = "Exaltar · Dois"
  },
  Voice_6122_AwakerVoiceContent = {
    Text = "Dissolução...? Claro, eu sei. Isso apenas significa que o vínculo mestre-servo foi quebrado, certo? O que há de tão difícil nisso?"
  },
  Voice_6122_AwakerVoiceTitle = {
    Text = "Bate-papo · Sobre Dissolução"
  },
  Voice_6123_AwakerVoiceContent = {
    Text = "Eu fui convocado; a fronteira entre deuses e tolos se tornou turva."
  },
  Voice_6123_AwakerVoiceTitle = {
    Text = "Iluminar·Visão Remota"
  },
  Voice_6123_UnlockDesc = {
    Text = "Nível de iluminação atingiu 1 para desbloquear"
  },
  Voice_6124_AwakerVoiceContent = {
    Text = "Hmm... A pressão está bem equilibrada, e a técnica de massagem é bastante boa~"
  },
  Voice_6124_AwakerVoiceTitle = {
    Text = "Conversa·Toque"
  },
  Voice_6125_AwakerVoiceContent = {
    Text = "A decoração aqui não está muito desatualizada? É assustador, como se fosse assombrado."
  },
  Voice_6125_AwakerVoiceTitle = {
    Text = "Chat·Sobre a Universidade Mythag"
  },
  Voice_6126_AwakerVoiceContent = {
    Text = "Aqui estão plantas exuberantes, ar tranquilo e um remédio para a doença da minha irmã. Para nós duas, é o lar novo mais maravilhoso."
  },
  Voice_6126_AwakerVoiceTitle = {
    Text = "Chat·Sobre a Universidade Mythag"
  },
  Voice_6127_AwakerVoiceContent = {
    Text = "Nunca esperei encontrar aqui... Me pergunto como minha irmã tem estado desde então. Não importa como eu pergunte, ela só diz que está bem... Desculpe, e obrigado por nos reunir."
  },
  Voice_6127_AwakerVoiceTitle = {
    Text = "Bate-papo · Sobre Desmaio"
  },
  Voice_6127_UnlockDesc = {
    Text = "Após obter o despertador \"Desmaio\", desbloqueado"
  },
  Voice_6128_AwakerVoiceContent = {
    Text = "Uma oferenda ao meu Senhor."
  },
  Voice_6128_AwakerVoiceTitle = {
    Text = "Habilidade·Um"
  },
  Voice_6129_AwakerVoiceContent = {
    Text = "Uma oferenda ao meu Senhor."
  },
  Voice_6129_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_6130_AwakerVoiceContent = {
    Text = "Calma, calma, calma..."
  },
  Voice_6130_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_6131_AwakerVoiceContent = {
    Text = "Há muitos \"eu\" dentro. Felizes, tristes, irritados... Eles amam bolo esponjoso, odeiam os dias chuvosos de Londinium. Todos se chamam \"24\" e todos adoram você."
  },
  Voice_6131_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Cinco"
  },
  Voice_6131_UnlockDesc = {
    Text = "Nível de afinidade atingido 10 desbloqueado"
  },
  Voice_6132_AwakerVoiceContent = {
    Text = "Eu costumava trabalhar até meia-noite todos os dias—fazia fiação, lavagem, limpeza, cuidar de crianças, até garimpar... Fazia qualquer coisa para ganhar dinheiro. Naquela época, viver era apenas sobreviver.\nAgora, temos comida fresca, camas quentes e Mestres gentis como você... É além dos meus sonhos mais loucos."
  },
  Voice_6132_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Quatro"
  },
  Voice_6132_UnlockDesc = {
    Text = "Nível de afinidade atingido 8 desbloqueado"
  },
  Voice_6133_AwakerVoiceContent = {
    Text = "Não importa o que aconteça, compartilhemos um bife e uma cama, e nunca lhe causaremos problemas."
  },
  Voice_6133_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Três"
  },
  Voice_6133_UnlockDesc = {
    Text = "Nível de afinidade atingido 6 desbloqueado"
  },
  Voice_6134_AwakerVoiceContent = {
    Text = "Heh, aquela mulher está tão assustada com a minha saída que não se atreve a dormir à noite. Relaxe, eu não mataria você — não enquanto você me der presentes.\nQuem sou eu? Claro, eu sou o \"24\", hahaha!"
  },
  Voice_6134_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Dois"
  },
  Voice_6134_UnlockDesc = {
    Text = "Nível de afinidade atingido 4 desbloqueado"
  },
  Voice_6135_AwakerVoiceContent = {
    Text = "Eu me sinto fantástico agora. O quê? Você diz que minha mente foi dominada por algo mais? N-não pode ser... uh..."
  },
  Voice_6135_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Um"
  },
  Voice_6135_UnlockDesc = {
    Text = "Nível de afinidade atingido 2 desbloqueado"
  },
  Voice_6136_AwakerVoiceContent = {
    Text = "Como assunto, você é bastante perceptivo. Antes do meu próximo longo sono, eu irei abrilhantar este momento com minha presença."
  },
  Voice_6136_AwakerVoiceTitle = {
    Text = "Conversa·Sobre Guardião do Segredo"
  },
  Voice_6137_AwakerVoiceContent = {
    Text = "Hmm, o mar está bastante quente esta noite..."
  },
  Voice_6137_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · Três"
  },
  Voice_6138_AwakerVoiceContent = {
    Text = "O pássaro branco circulando no sonho chegou."
  },
  Voice_6138_AwakerVoiceTitle = {
    Text = "Atualizar·II"
  },
  Voice_6139_AwakerVoiceContent = {
    Text = "Como você deseja, minha presença se tornou mais tangível."
  },
  Voice_6139_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · I"
  },
  Voice_6140_AwakerVoiceContent = {
    Text = "Tão satisfatório, tão satisfatório!"
  },
  Voice_6140_AwakerVoiceTitle = {
    Text = "Habilidade·Um"
  },
  Voice_6141_AwakerVoiceContent = {Text = "Doce!"},
  Voice_6141_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_6142_AwakerVoiceContent = {
    Text = "Deixe isso comigo!"
  },
  Voice_6142_AwakerVoiceTitle = {
    Text = "Habilidade·Um"
  },
  Voice_6143_AwakerVoiceContent = {
    Text = "Deixe isso comigo!"
  },
  Voice_6143_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_6144_AwakerVoiceContent = {
    Text = "Bem-vindo à — nossa festa!"
  },
  Voice_6144_AwakerVoiceTitle = {
    Text = "Exaltar · Mania"
  },
  Voice_6145_AwakerVoiceContent = {
    Text = "Esta garota indubitavelmente carrega a linhagem de Yu... Não, Yu não é velho o suficiente para ter descendentes. No entanto, seu poder é de fato semelhante ao de Yu."
  },
  Voice_6145_AwakerVoiceTitle = {
    Text = "Conversa Ociosa · Sobre a Linhagem Divina"
  },
  Voice_6145_UnlockDesc = {
    Text = "Desbloqueado após adquirir o Despertar \"Aigis\" ou \"Murphy\""
  },
  Voice_6146_AwakerVoiceContent = {
    Text = "A bondade do mestre, Karen não ousa esquecer nem por um momento!"
  },
  Voice_6146_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · I"
  },
  Voice_6147_AwakerVoiceContent = {
    Text = "—Tão doce e deliciosa!"
  },
  Voice_6147_AwakerVoiceTitle = {
    Text = "Atualizar·II"
  },
  Voice_6148_AwakerVoiceContent = {
    Text = "Karen está de dieta e não pode comer muito~"
  },
  Voice_6148_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · Três"
  },
  Voice_6149_AwakerVoiceContent = {
    Text = "Esses caras não são dignos de serem meus oponentes."
  },
  Voice_6149_AwakerVoiceTitle = {
    Text = "Investigação Bem-sucedida"
  },
  Voice_6150_AwakerVoiceContent = {
    Text = "Explicar arte é tão ridículo quanto explicar ações ferroviárias—por favor, não torne a vida mais difícil para os pobres artistas."
  },
  Voice_6150_AwakerVoiceTitle = {
    Text = "Conversa·Sobre Guardião do Segredo"
  },
  Voice_6151_AwakerVoiceContent = {
    Text = "Aigis... Fiz algo errado?"
  },
  Voice_6151_AwakerVoiceTitle = {
    Text = "Conversa·Toque"
  },
  Voice_6152_AwakerVoiceContent = {
    Text = "Suas orações foram ouvidas."
  },
  Voice_6152_AwakerVoiceTitle = {
    Text = "Exaltar · Dois"
  },
  Voice_6153_AwakerVoiceContent = {
    Text = "Suas orações foram ouvidas."
  },
  Voice_6153_AwakerVoiceTitle = {
    Text = "Fúria Explosiva"
  },
  Voice_6154_AwakerVoiceContent = {
    Text = "Hmph, desrespeitoso."
  },
  Voice_6154_AwakerVoiceTitle = {
    Text = "Início da Investigação"
  },
  Voice_6155_AwakerVoiceContent = {
    Text = "Ah, foi o Mestre que passou agora? Não, tanto faz. Da última vez que o cumprimentei, ele não me reconheceu... Eu esperei por ele na prisão, esperando que ele me levasse, mas ele nunca veio, nem mesmo durante o motim."
  },
  Voice_6155_AwakerVoiceTitle = {
    Text = "Bate-papo · Sobre \"N\""
  },
  Voice_6155_UnlockDesc = {
    Text = "Desbloqueado após completar o Capítulo 7 da \"Operação de Investigação\""
  },
  Voice_6156_AwakerVoiceContent = {
    Text = "Responder ao Despertar da humanidade e formar alianças é cumprir meu dever inacabado - se você conseguir se tornar forte o suficiente para me desafiar, isso seria o ideal."
  },
  Voice_6156_AwakerVoiceTitle = {
    Text = "Conversa·Sobre Guardião do Segredo"
  },
  Voice_6157_AwakerVoiceContent = {
    Text = "Irmã, Marrom, a covarde do orfanato, estou contente por tê-las apenas como amigas. Uh... bem, eu suponho que você também conta. Marrom, compartilhe um pedaço de doce com o Guardião.  \n\"Cheep?!\""
  },
  Voice_6157_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Cinco"
  },
  Voice_6157_UnlockDesc = {
    Text = "Nível de afinidade atingido 10 desbloqueado"
  },
  Voice_6158_AwakerVoiceContent = {
    Text = "A Favela Leste não é lugar para crianças. Foremen astutos encontrariam maneiras de descontar o pagamento dos meninos que entregam jornais e criticariam os entregadores de leite por sua velocidade... ridiculamente exigentes! Para sobreviver nas ruas, você só pode contar consigo mesmo. Ninguém mais pode ser confiável."
  },
  Voice_6158_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Quatro"
  },
  Voice_6158_UnlockDesc = {
    Text = "Nível de afinidade atingido 8 desbloqueado"
  },
  Voice_6159_AwakerVoiceContent = {
    Text = "Meus \"hábitos ruins\" não podem ser mudados da noite para o dia, você entende, certo? Dormir sob pontes e em bueiros, sobrevivendo com lixo—apenas permanecer vivo já era difícil o suficiente... Você não pode esperar que eu comece a arrumar minha cama imediatamente! Vai levar pelo menos meio mês para me acostumar!"
  },
  Voice_6159_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Três"
  },
  Voice_6159_UnlockDesc = {
    Text = "Nível de afinidade atingido 6 desbloqueado"
  },
  Voice_6160_AwakerVoiceContent = {
    Text = "Não é bom se perder no espaço. Desde que você me tirou de lá, sinta-se à vontade para perguntar qualquer coisa, mas não posso garantir que eu conseguirei ajudar.\nConsiderando minha idade, você não iria incomodar uma criança, iria?~"
  },
  Voice_6160_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Dois"
  },
  Voice_6160_UnlockDesc = {
    Text = "Nível de afinidade atingido 4 desbloqueado"
  },
  Voice_6161_AwakerVoiceContent = {
    Text = "Ei, Westsider! Você viu o Marrom? Esse glutão deve ter farejado algo de novo."
  },
  Voice_6161_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Um"
  },
  Voice_6161_UnlockDesc = {
    Text = "Nível de afinidade atingido 2 desbloqueado"
  },
  Voice_6162_AwakerVoiceContent = {
    Text = "\"Aqueles com força não devem usar seu poder para oprimir os outros, pois todos vocês compartilham meu sangue.\" — Eu me lembro dos ensinamentos do Deus da Compaixão e usarei essa força para proteger os que estão ao meu redor."
  },
  Voice_6162_AwakerVoiceTitle = {
    Text = "Iluminar·Visão Remota"
  },
  Voice_6162_UnlockDesc = {
    Text = "Nível de iluminação atingiu 1 para desbloquear"
  },
  Voice_6163_AwakerVoiceContent = {
    Text = "Curioso sobre o que vi no início do universo? Posso lhe contar, não havia nada lá."
  },
  Voice_6163_AwakerVoiceTitle = {
    Text = "Iluminar·Florescer"
  },
  Voice_6163_UnlockDesc = {
    Text = "Nível de iluminação atingiu 15 para desbloquear"
  },
  Voice_6164_AwakerVoiceContent = {
    Text = "Está mais claro agora."
  },
  Voice_6164_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · Três"
  },
  Voice_6165_AwakerVoiceContent = {
    Text = "A lâmpada eterna..."
  },
  Voice_6165_AwakerVoiceTitle = {
    Text = "Atualizar·II"
  },
  Voice_6166_AwakerVoiceContent = {
    Text = "A conexão com a terra natal se fortaleceu."
  },
  Voice_6166_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · I"
  },
  Voice_6167_AwakerVoiceContent = {
    Text = "Se eu puder libertar o mundo de seu sofrimento, ficarei contente."
  },
  Voice_6167_AwakerVoiceTitle = {
    Text = "Atualizar·II"
  },
  Voice_6168_AwakerVoiceContent = {
    Text = "Me dê mais comandos, Mensageiro Pálido. Que sua chama ilumine meu caminho."
  },
  Voice_6168_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · Três"
  },
  Voice_6169_AwakerVoiceContent = {
    Text = "(Exclamação)"
  },
  Voice_6169_AwakerVoiceTitle = {
    Text = "Golpe·Quatro"
  },
  Voice_6170_AwakerVoiceContent = {
    Text = "A forja de uma pessoa envolve não apenas o corpo, mas também o coração."
  },
  Voice_6170_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · I"
  },
  Voice_6171_AwakerVoiceContent = {Text = "(Gemido)"},
  Voice_6171_AwakerVoiceTitle = {
    Text = "Acertar · II"
  },
  Voice_6172_AwakerVoiceContent = {Text = "Ai!"},
  Voice_6172_AwakerVoiceTitle = {
    Text = "Acertar·III"
  },
  Voice_6173_AwakerVoiceContent = {Text = "(Gemido)"},
  Voice_6173_AwakerVoiceTitle = {Text = "Acertar·1"},
  Voice_6174_AwakerVoiceContent = {
    Text = "Hmm! Sua temperatura está um pouco alta para coral. Mas... é quente e intensa. Eu gosto."
  },
  Voice_6174_AwakerVoiceTitle = {
    Text = "Conversa·Toque"
  },
  Voice_6175_AwakerVoiceContent = {
    Text = "Ah... Você precisa de algo? Se possível, vamos conversar nos bastidores..."
  },
  Voice_6175_AwakerVoiceTitle = {
    Text = "Conversa·Toque"
  },
  Voice_6176_AwakerVoiceContent = {
    Text = "Murchando antes de florescer, como um lótus encharcado... Buscando paz nas frias e turbulentas marés, tímido demais para buscar minha própria felicidade... Esse sou eu, o Guardião."
  },
  Voice_6176_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Quatro"
  },
  Voice_6176_UnlockDesc = {
    Text = "Nível de afinidade atingido 8 desbloqueado"
  },
  Voice_6177_AwakerVoiceContent = {
    Text = "Uma vez eu lidei com este dilema: A dor é mais longa que a própria vida? Se sim, um sono pacífico é mais feliz que uma vigília atormentada? Depois de acordar, eu também fiquei preso, até que você me trouxe este refúgio seguro..."
  },
  Voice_6177_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Cinco"
  },
  Voice_6177_UnlockDesc = {
    Text = "Nível de afinidade atingido 10 desbloqueado"
  },
  Voice_6178_AwakerVoiceContent = {
    Text = "Durante meu tempo no sanatório, tentei fazer amigos, mas as pessoas eram relutantes em se aproximar de mim... É por causa deste \"veneno\" que corrói os ossos? De qualquer forma, tenha cuidado ao se aproximar de mim."
  },
  Voice_6178_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Um"
  },
  Voice_6178_UnlockDesc = {
    Text = "Nível de afinidade atingido 2 desbloqueado"
  },
  Voice_6179_AwakerVoiceContent = {
    Text = "O som do sino levado pelo vento noturno traz paz. Você gostaria de sentar na cadeira de pedra e ouvir por um momento? Eu prepararei um assento para você com um lenço."
  },
  Voice_6179_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Dois"
  },
  Voice_6179_UnlockDesc = {
    Text = "Nível de afinidade atingido 4 desbloqueado"
  },
  Voice_6180_AwakerVoiceContent = {
    Text = "Você já ouviu falar de \"sepultamento no mar\"? Na cidade onde eu vivia antes, havia um costume de submergir o falecido no mar, fazendo do oceano o último lugar de descanso de todos. Quanto a mim, voltei para o abraço do mar cedo..."
  },
  Voice_6180_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Três"
  },
  Voice_6180_UnlockDesc = {
    Text = "Nível de afinidade atingido 6 desbloqueado"
  },
  Voice_6181_AwakerVoiceContent = {Text = "Hmph!"},
  Voice_6181_AwakerVoiceTitle = {
    Text = "Acertar · II"
  },
  Voice_6182_AwakerVoiceContent = {Text = "Ah!"},
  Voice_6182_AwakerVoiceTitle = {
    Text = "Acertar·III"
  },
  Voice_6183_AwakerVoiceContent = {Text = "Ah!"},
  Voice_6183_AwakerVoiceTitle = {Text = "Acertar·1"},
  Voice_6184_AwakerVoiceContent = {Text = "Ah!"},
  Voice_6184_AwakerVoiceTitle = {
    Text = "Golpe·Quatro"
  },
  Voice_6185_AwakerVoiceContent = {
    Text = "O registro de combate foi arquivado. Obrigado pelo seu trabalho duro, Guardião."
  },
  Voice_6185_AwakerVoiceTitle = {
    Text = "Investigação Bem-sucedida"
  },
  Voice_6186_AwakerVoiceContent = {
    Text = "(Gemido de dor)"
  },
  Voice_6186_AwakerVoiceTitle = {
    Text = "Golpe·Quatro"
  },
  Voice_6187_AwakerVoiceContent = {
    Text = "(Gemido de dor)"
  },
  Voice_6187_AwakerVoiceTitle = {
    Text = "Acertar·III"
  },
  Voice_6188_AwakerVoiceContent = {
    Text = "(Gemido de dor)"
  },
  Voice_6188_AwakerVoiceTitle = {
    Text = "Acertar · II"
  },
  Voice_6189_AwakerVoiceContent = {
    Text = "Você pode continuar."
  },
  Voice_6189_AwakerVoiceTitle = {Text = "Acertar·1"},
  Voice_6190_AwakerVoiceContent = {
    Text = "Os visitantes do salão recebem a mais fina hospitalidade... Como ingresso, os convidados prepararam segredos dignos deste grandioso banquete?"
  },
  Voice_6190_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_6191_AwakerVoiceContent = {
    Text = "Eu amo coisas novas. Ao longo de meus milênios de viagens, testemunhei muitas inovações e invenções fascinantes, como formas poéticas e cenas cinematográficas. Os humanos são verdadeiramente criaturas intrigantes."
  },
  Voice_6191_AwakerVoiceTitle = {
    Text = "Conversa·Coisas favoritas"
  },
  Voice_6192_AwakerVoiceContent = {
    Text = "Hmm, Lily a reconhece. Quando sua mãe não está por perto, Lily fica em sua casa."
  },
  Voice_6192_AwakerVoiceTitle = {
    Text = "Conversa Casual · Sobre Narciso"
  },
  Voice_6192_UnlockDesc = {
    Text = "Desbloqueado após adquirir o Despertar \"Narciso\""
  },
  Voice_6195_AwakerVoiceContent = {
    Text = "Você é quem está perturbando meu longo sono?"
  },
  Voice_6195_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_6196_AwakerVoiceContent = {
    Text = "Deuses? Apenas tolos confiariam suas vidas a seres tão intangíveis. Em vez de depender de supostos deuses, pense mais em como se tornar mais forte."
  },
  Voice_6196_AwakerVoiceTitle = {
    Text = "Conversa·Coisas odiadas"
  },
  Voice_6197_AwakerVoiceContent = {
    Text = "Que mestre dos gladiadores, apenas um inseto sem valor."
  },
  Voice_6197_AwakerVoiceTitle = {
    Text = "Fala Ociosa · Sobre Agrippa"
  },
  Voice_6197_UnlockDesc = {
    Text = "Após obter o despertador \"Agrippa\", desbloqueado"
  },
  Voice_6198_AwakerVoiceContent = {
    Text = "Após a vitória, por favor, me permita levar os materiais necessários para a reprodução."
  },
  Voice_6198_AwakerVoiceTitle = {
    Text = "Início da Investigação"
  },
  Voice_6199_AwakerVoiceContent = {
    Text = "Grande amigo! Parceiro! Hoo-hoo, vamos ser melhores amigos para sempre com Aurita!"
  },
  Voice_6199_AwakerVoiceTitle = {
    Text = "Conversa·Sobre Guardião do Segredo"
  },
  Voice_6200_AwakerVoiceContent = {
    Text = "Estou emocionado agora... Se você não quer morrer, é melhor manter distância de mim."
  },
  Voice_6200_AwakerVoiceTitle = {
    Text = "Atualizar·II"
  },
  Voice_6201_AwakerVoiceContent = {
    Text = "Está mesmo certo que aquela pessoa trate os outros assim? A Sra. Sarah disse que crianças não deveriam fazer birra..."
  },
  Voice_6201_AwakerVoiceTitle = {
    Text = "Conversas Ociosas·Sobre Murphy"
  },
  Voice_6201_UnlockDesc = {
    Text = "Desbloqueado após obter Despertador \"Murphy\""
  },
  Voice_6202_AwakerVoiceContent = {
    Text = "A glória da vitória pertence a você"
  },
  Voice_6202_AwakerVoiceTitle = {
    Text = "Investigação Bem-sucedida"
  },
  Voice_6203_AwakerVoiceContent = {
    Text = "Não posso comer mais, estou cheio~"
  },
  Voice_6203_AwakerVoiceTitle = {
    Text = "Atualizar·II"
  },
  Voice_6204_AwakerVoiceContent = {
    Text = "O vazio interior foi preenchido~"
  },
  Voice_6204_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · Três"
  },
  Voice_6205_AwakerVoiceContent = {
    Text = "Um pouco mais quente~"
  },
  Voice_6205_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · I"
  },
  Voice_6206_AwakerVoiceContent = {
    Text = "Eu conheço aquela garota. Ela às vezes fica longe, assistindo à performance. É melhor que ela não se aproxime, caso contrário, esses pequenos espectadores ficarão \"mental e fisicamente exaustos\"!"
  },
  Voice_6206_AwakerVoiceTitle = {
    Text = "Bate-papo · Sobre Desmaio"
  },
  Voice_6206_UnlockDesc = {
    Text = "Após obter o despertador \"Desmaio\", desbloqueado"
  },
  Voice_6207_AwakerVoiceContent = {
    Text = "A Tinta disse: \"Recompense a bondade.\" Então, desde que esteja dentro da minha capacidade de ajudar, eu estenderei a mão..."
  },
  Voice_6207_AwakerVoiceTitle = {
    Text = "Conversa·Sobre Guardião do Segredo"
  },
  Voice_6208_AwakerVoiceContent = {
    Text = "Olá, Guardião. Como posso ajudá-lo?"
  },
  Voice_6208_AwakerVoiceTitle = {
    Text = "Conversa·Toque"
  },
  Voice_6209_AwakerVoiceContent = {
    Text = "Um dia, eu retornarei ao campo de batalha como o líder na vanguarda."
  },
  Voice_6209_AwakerVoiceTitle = {
    Text = "Iluminar: Insight"
  },
  Voice_6209_UnlockDesc = {
    Text = "Nível de iluminação atingiu 7 para desbloquear"
  },
  Voice_6210_AwakerVoiceContent = {
    Text = "Você pode acreditar? Eu sinto meu osso da perna quebrada se curando."
  },
  Voice_6210_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexão"
  },
  Voice_6210_UnlockDesc = {
    Text = "Nível de iluminação atingiu 3 para desbloquear"
  },
  Voice_6211_AwakerVoiceContent = {
    Text = "Agradeço sinceramente pela sua confiança em me treinar até este nível. Você deve ser alguém que busca a justiça, então continuarei a trazer glória para nosso exército aqui."
  },
  Voice_6211_AwakerVoiceTitle = {
    Text = "Iluminar·Florescer"
  },
  Voice_6211_UnlockDesc = {
    Text = "Nível de iluminação atingiu 15 para desbloquear"
  },
  Voice_6212_AwakerVoiceContent = {
    Text = "O dia da jornada está se aproximando e meu sangue ferve de paixão."
  },
  Voice_6212_AwakerVoiceTitle = {
    Text = "Iluminar·Construção"
  },
  Voice_6212_UnlockDesc = {
    Text = "Nível de iluminação atingiu 11 para desbloquear"
  },
  Voice_6213_AwakerVoiceContent = {
    Text = "A honra de ser um guerreiro está sendo restaurada."
  },
  Voice_6213_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_6213_UnlockDesc = {
    Text = "Nível de iluminação atingiu 2 para desbloquear"
  },
  Voice_6214_AwakerVoiceContent = {Text = "(Gemido)"},
  Voice_6214_AwakerVoiceTitle = {
    Text = "Golpe·Quatro"
  },
  Voice_6215_AwakerVoiceContent = {Text = "Ai!"},
  Voice_6215_AwakerVoiceTitle = {Text = "Acertar·1"},
  Voice_6216_AwakerVoiceContent = {Text = "(Gemido)"},
  Voice_6216_AwakerVoiceTitle = {
    Text = "Acertar·III"
  },
  Voice_6217_AwakerVoiceContent = {
    Text = "Trapaceiro!"
  },
  Voice_6217_AwakerVoiceTitle = {
    Text = "Acertar · II"
  },
  Voice_6218_AwakerVoiceContent = {
    Text = "Oops, desculpe! Vou fazer acontecer da próxima vez!"
  },
  Voice_6218_AwakerVoiceTitle = {
    Text = "Investigação Interrompida"
  },
  Voice_6219_AwakerVoiceContent = {
    Text = "Ouço alguém chamando meu nome, Agrippa, Agrippa, Agrippina..."
  },
  Voice_6219_AwakerVoiceTitle = {
    Text = "Iluminar·Construção"
  },
  Voice_6219_UnlockDesc = {
    Text = "Nível de iluminação atingiu 11 para desbloquear"
  },
  Voice_6220_AwakerVoiceContent = {
    Text = "Eu vi... Ele subindo da escuridão do poço, incontáveis olhos aparecendo em seu ovo de carne. Eles estavam me encarando, me chamando... Deus do Labirinto."
  },
  Voice_6220_AwakerVoiceTitle = {
    Text = "Iluminar·Florescer"
  },
  Voice_6220_UnlockDesc = {
    Text = "Nível de iluminação atingiu 15 para desbloquear"
  },
  Voice_6221_AwakerVoiceContent = {
    Text = "Eu tenho um impulso muito forte de assistir a um duelo... Seria ainda melhor se ocorresse em um labirinto."
  },
  Voice_6221_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexão"
  },
  Voice_6221_UnlockDesc = {
    Text = "Nível de iluminação atingiu 3 para desbloquear"
  },
  Voice_6222_AwakerVoiceContent = {
    Text = "Contrato... Sim, quero assinar um contrato com você, um contrato mestre-servo eterno..."
  },
  Voice_6222_AwakerVoiceTitle = {
    Text = "Iluminar: Insight"
  },
  Voice_6222_UnlockDesc = {
    Text = "Nível de iluminação atingiu 7 para desbloquear"
  },
  Voice_6223_AwakerVoiceContent = {
    Text = "Hmph... Não é ruim. Me dê mais. Preciso alimentar esses filhotes de aranha."
  },
  Voice_6223_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_6223_UnlockDesc = {
    Text = "Nível de iluminação atingiu 2 para desbloquear"
  },
  Voice_6224_AwakerVoiceContent = {
    Text = "Que sujeira, que abominação! Ah—pare! Por favor! Não me faça ver isso, e não mencione isso perto de mim..."
  },
  Voice_6224_AwakerVoiceTitle = {
    Text = "Bate-papo · Sobre Dissolução"
  },
  Voice_6225_AwakerVoiceContent = {
    Text = "Meu passado era rotineiro e calmo, como os mares próximos ao equador, nada digno de nota."
  },
  Voice_6225_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Dois"
  },
  Voice_6225_UnlockDesc = {
    Text = "Nível de afinidade atingido 4 desbloqueado"
  },
  Voice_6226_AwakerVoiceContent = {
    Text = "Hmm...? Mãe, um abraço... Mm, tão quente..."
  },
  Voice_6226_AwakerVoiceTitle = {
    Text = "Conversa·Toque"
  },
  Voice_6227_AwakerVoiceContent = {
    Text = "Poeira Estelar..."
  },
  Voice_6227_AwakerVoiceTitle = {
    Text = "Habilidade·Um"
  },
  Voice_6228_AwakerVoiceContent = {
    Text = "Oh não, você está perdido?"
  },
  Voice_6228_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_6229_AwakerVoiceContent = {Text = "Inútil."},
  Voice_6229_AwakerVoiceTitle = {Text = "Acertar·1"},
  Voice_6230_AwakerVoiceContent = {
    Text = "Sempre que me lembro daqueles traidores de joelhos e chorando por misericórdia, sinto uma onda de satisfação, e as chamas em meu coração parecem se acalmar."
  },
  Voice_6230_AwakerVoiceTitle = {
    Text = "Conversa·Coisas favoritas"
  },
  Voice_6231_AwakerVoiceContent = {
    Text = "O mestre do navio me tirou de casa e me confiou a missão da primeira viagem do navio. Desde então, o significado da minha vida está além do meu controle. Alguém me disse que, pelo menos nesta segunda vida como um Despertador, eu deveria viver pelos meus próprios desejos... Você vai me ajudar? Ajude-me a ser egoísta, ajude-me a encontrar meu desejo."
  },
  Voice_6231_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Cinco"
  },
  Voice_6231_UnlockDesc = {
    Text = "Nível de afinidade atingido 10 desbloqueado"
  },
  Voice_6232_AwakerVoiceContent = {
    Text = "Agrippa. Não tenho nada a dizer a você— a menos que você se atreva a se oferecer como meu gladiador."
  },
  Voice_6232_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_6233_AwakerVoiceContent = {
    Text = "Tawil... muito mais perigosa do que imaginávamos. Se eu não estiver por perto, você deve ter cuidado extremo com ela."
  },
  Voice_6233_AwakerVoiceTitle = {
    Text = "Conversas Ociosas·Sobre Tawil"
  },
  Voice_6235_AwakerVoiceContent = {
    Text = "Com este raciocínio... interprete o mundo!"
  },
  Voice_6235_AwakerVoiceTitle = {
    Text = "Fúria Explosiva"
  },
  Voice_6236_AwakerVoiceContent = {
    Text = "Com este raciocínio... interprete o mundo!"
  },
  Voice_6236_AwakerVoiceTitle = {
    Text = "Exaltar · Dois"
  },
  Voice_6237_AwakerVoiceContent = {
    Text = "Brilhe intensamente!"
  },
  Voice_6237_AwakerVoiceTitle = {
    Text = "Despertar do Conhecimento Espiritual"
  },
  Voice_6238_AwakerVoiceContent = {
    Text = "Para o melhor da minha capacidade."
  },
  Voice_6238_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_6239_AwakerVoiceContent = {
    Text = "Para o melhor da minha capacidade."
  },
  Voice_6239_AwakerVoiceTitle = {
    Text = "Carta de Habilidade·Quatro"
  },
  Voice_6240_AwakerVoiceContent = {
    Text = "Deixe apodrecer."
  },
  Voice_6240_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_6241_AwakerVoiceContent = {
    Text = "Deixe apodrecer."
  },
  Voice_6241_AwakerVoiceTitle = {
    Text = "Habilidade·Um"
  },
  Voice_6242_AwakerVoiceContent = {
    Text = "Sorrisos e etiqueta servem como uma camada de armadura, ajudando-me a manter distância dos outros e evitar perturbações tediosas. Quanto ao meu verdadeiro eu... não me importo em mostrá-lo a você."
  },
  Voice_6242_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Quatro"
  },
  Voice_6242_UnlockDesc = {
    Text = "Nível de afinidade atingido 8 desbloqueado"
  },
  Voice_6243_AwakerVoiceContent = {
    Text = "Pensamentos se acumulam como calcário branco e são lavados em belos corais. Eles se fundem comigo, pulsando com meu batimento cardíaco... Você vai ouvir?"
  },
  Voice_6243_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Cinco"
  },
  Voice_6243_UnlockDesc = {
    Text = "Nível de afinidade atingido 10 desbloqueado"
  },
  Voice_6244_AwakerVoiceContent = {
    Text = "A Inspiração é como bolhas subindo no mar: um toque suave e elas desaparecem. Você é o mesmo?"
  },
  Voice_6244_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Dois"
  },
  Voice_6244_UnlockDesc = {
    Text = "Nível de afinidade atingido 4 desbloqueado"
  },
  Voice_6245_AwakerVoiceContent = {
    Text = "A guerra, o saque e a fama são todos desejos humanos. A humilde escultora não tem interesse no que os humanos perseguem; ela apenas deseja ser escrava da beleza."
  },
  Voice_6245_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Três"
  },
  Voice_6245_UnlockDesc = {
    Text = "Nível de afinidade atingido 6 desbloqueado"
  },
  Voice_6246_AwakerVoiceContent = {
    Text = "Uma vida maravilhosa está na indulgência. Às vezes, você não deve ser tão duro consigo mesmo."
  },
  Voice_6246_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Um"
  },
  Voice_6246_UnlockDesc = {
    Text = "Nível de afinidade atingido 2 desbloqueado"
  },
  Voice_6247_AwakerVoiceContent = {
    Text = "Apenas ferimentos leves..."
  },
  Voice_6247_AwakerVoiceTitle = {Text = "Acertar·1"},
  Voice_6249_AwakerVoiceContent = {Text = "(Gemido)"},
  Voice_6249_AwakerVoiceTitle = {
    Text = "Acertar·III"
  },
  Voice_6250_AwakerVoiceContent = {Text = "Droga!"},
  Voice_6250_AwakerVoiceTitle = {
    Text = "Acertar · II"
  },
  Voice_6251_AwakerVoiceContent = {Text = "(Gemido)"},
  Voice_6251_AwakerVoiceTitle = {
    Text = "Golpe·Quatro"
  },
  Voice_6252_AwakerVoiceContent = {
    Text = "O Fenômeno d traz caos e desastres. Talvez meu país tenha afundado no Aequor por causa disso..."
  },
  Voice_6252_AwakerVoiceTitle = {
    Text = "Bate-papo · Sobre Dissolução"
  },
  Voice_6253_AwakerVoiceContent = {Text = "Hah!"},
  Voice_6253_AwakerVoiceTitle = {Text = "Ataque·Um"},
  Voice_6254_AwakerVoiceContent = {Text = "Ah~!"},
  Voice_6254_AwakerVoiceTitle = {
    Text = "Habilidade Especial · Um"
  },
  Voice_6255_AwakerVoiceContent = {
    Text = "Majestade do Gigante"
  },
  Voice_6255_AwakerVoiceTitle = {
    Text = "Habilidade Especial · Um"
  },
  Voice_6256_AwakerVoiceContent = {
    Text = "Experimente isso!"
  },
  Voice_6256_AwakerVoiceTitle = {Text = "Ataque·Um"},
  Voice_6257_AwakerVoiceContent = {
    Text = "Sacrifício Iminente"
  },
  Voice_6257_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_6258_AwakerVoiceContent = {
    Text = "Nada mal, esta é a glória do guerreiro."
  },
  Voice_6258_AwakerVoiceTitle = {
    Text = "Investigação Bem-sucedida"
  },
  Voice_6259_AwakerVoiceContent = {
    Text = "Você! Como pôde deixar aquela mulher aqui? Crie uma área restrita para mim! Não a deixe chegar a 50 passos de mim!"
  },
  Voice_6259_AwakerVoiceTitle = {
    Text = "Chat·Sobre Miryam"
  },
  Voice_6259_UnlockDesc = {
    Text = "Após obter o despertador \"Miryam\", desbloqueado"
  },
  Voice_6260_AwakerVoiceContent = {
    Text = "Por que eu quero me tornar mais forte? Na minha tribo, os fracos têm suas roupas arrancadas, suas cabeças raspadas e são submetidos às humilhações mais sujas imagináveis - o custo da fraqueza não é algo que todos conseguem suportar."
  },
  Voice_6260_AwakerVoiceTitle = {
    Text = "Iluminar·Construção"
  },
  Voice_6260_UnlockDesc = {
    Text = "Nível de iluminação atingiu 11 para desbloquear"
  },
  Voice_6261_AwakerVoiceContent = {
    Text = "Deusa da fortuna, concede-me a tua bênção!"
  },
  Voice_6261_AwakerVoiceTitle = {
    Text = "Despertar do Conhecimento Espiritual"
  },
  Voice_6262_AwakerVoiceContent = {
    Text = "Como era de se esperar... A força humana tem seus limites...?"
  },
  Voice_6262_AwakerVoiceTitle = {
    Text = "Investigação Interrompida"
  },
  Voice_6263_AwakerVoiceContent = {
    Text = "Os músculos e ossos relaxaram ligeiramente."
  },
  Voice_6263_AwakerVoiceTitle = {
    Text = "Iluminar·Visão Remota"
  },
  Voice_6263_UnlockDesc = {
    Text = "Nível de iluminação atingiu 1 para desbloquear"
  },
  Voice_6264_AwakerVoiceContent = {
    Text = "É a manifestação do seu desejo, aprofundar meu afeto?"
  },
  Voice_6264_AwakerVoiceTitle = {
    Text = "Iluminar·Construção"
  },
  Voice_6264_UnlockDesc = {
    Text = "Nível de iluminação atingiu 11 para desbloquear"
  },
  Voice_6265_AwakerVoiceContent = {
    Text = "Liberte-se!"
  },
  Voice_6265_AwakerVoiceTitle = {
    Text = "Despertar do Conhecimento Espiritual"
  },
  Voice_6266_AwakerVoiceContent = {
    Text = "(Exclamação)"
  },
  Voice_6266_AwakerVoiceTitle = {
    Text = "Acertar·III"
  },
  Voice_6267_AwakerVoiceContent = {Text = "(Gemido)"},
  Voice_6267_AwakerVoiceTitle = {
    Text = "Acertar · II"
  },
  Voice_6268_AwakerVoiceContent = {
    Text = "(Exclamação)"
  },
  Voice_6268_AwakerVoiceTitle = {Text = "Acertar·1"},
  Voice_6269_AwakerVoiceContent = {
    Text = "Ah, imperdoável..."
  },
  Voice_6269_AwakerVoiceTitle = {
    Text = "Investigação Interrompida"
  },
  Voice_6270_AwakerVoiceTitle = {
    Text = "Golpe·Quatro"
  },
  Voice_6271_AwakerVoiceContent = {
    Text = "Ponto Imprudente!"
  },
  Voice_6271_AwakerVoiceTitle = {Text = "Ataque·Um"},
  Voice_6272_AwakerVoiceContent = {Text = "Biu—"},
  Voice_6272_AwakerVoiceTitle = {Text = "Ataque·II"},
  Voice_6273_AwakerVoiceContent = {
    Text = "Continue assim! Suas notas finais são promissoras."
  },
  Voice_6273_AwakerVoiceTitle = {
    Text = "Investigação Bem-sucedida"
  },
  Voice_6274_AwakerVoiceContent = {
    Text = "Eu ouvi que um ladrão dos subúrbios apareceu, trazendo consigo um rato gordo? Hehehe... Veja como eu eliminarei essa ameaça para o meu mestre!"
  },
  Voice_6274_AwakerVoiceTitle = {
    Text = "Fofocas · Sobre Jenki"
  },
  Voice_6274_UnlockDesc = {
    Text = "Desbloqueado após adquirir o Despertar \"Jenkin\""
  },
  Voice_6275_AwakerVoiceContent = {
    Text = "Vamos lá, respire fundo—"
  },
  Voice_6275_AwakerVoiceTitle = {
    Text = "Despertar do Conhecimento Espiritual"
  },
  Voice_6276_AwakerVoiceContent = {
    Text = "Interessante, seu crescimento em batalha supera muito minhas expectativas. Dado tempo, você pode se tornar o próximo... Estranho... Através do tempo, ainda encontro esperança em um ser fraco como você."
  },
  Voice_6276_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Quatro"
  },
  Voice_6276_UnlockDesc = {
    Text = "Nível de afinidade atingido 8 desbloqueado"
  },
  Voice_6277_AwakerVoiceContent = {
    Text = "Talvez agora seja a hora de dizer isso. Ouça com atenção.\nLotan, a Besta Estelar, oficialmente te desafia... Mas não se preocupe, eu garantirei sua segurança até que você alcance seu auge. Não deixarei meu oponente escolhido encontrar o mesmo destino novamente."
  },
  Voice_6277_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Cinco"
  },
  Voice_6277_UnlockDesc = {
    Text = "Nível de afinidade atingido 10 desbloqueado"
  },
  Voice_6278_AwakerVoiceContent = {
    Text = "Hmph... Não consigo entender por que Ramona aprovaria você como parceira. Admito, você exala um cheiro de força, mas ainda está longe de ser meu rival."
  },
  Voice_6278_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Dois"
  },
  Voice_6278_UnlockDesc = {
    Text = "Nível de afinidade atingido 4 desbloqueado"
  },
  Voice_6279_AwakerVoiceContent = {
    Text = "Sim, olhe para mim com reverência. Eu sou a Relíquia mais antiga do Planeta, merecendo respeito dos insignificantes—eu guardei este Planeta por eras. Pedir uma batalha emocionante como recompensa não é demais, certo?"
  },
  Voice_6279_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Três"
  },
  Voice_6279_UnlockDesc = {
    Text = "Nível de afinidade atingido 6 desbloqueado"
  },
  Voice_6280_AwakerVoiceContent = {
    Text = "Hah, eu não tenho energia para brincar de casinha com crianças. Se você souber o que é bom para você, apenas encontre um canto e fique quieto."
  },
  Voice_6280_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Um"
  },
  Voice_6280_UnlockDesc = {
    Text = "Nível de afinidade atingido 2 desbloqueado"
  },
  Voice_6281_AwakerVoiceContent = {
    Text = "Almas sem proteção, concederei a vocês a paz final"
  },
  Voice_6281_AwakerVoiceTitle = {
    Text = "Início da Investigação"
  },
  Voice_6282_AwakerVoiceContent = {Text = "Alerta."},
  Voice_6282_AwakerVoiceTitle = {
    Text = "Defesa · I"
  },
  Voice_6283_AwakerVoiceContent = {Text = "Alerta."},
  Voice_6283_AwakerVoiceTitle = {Text = "Defesa·II"},
  Voice_6284_AwakerVoiceContent = {
    Text = "Algo está gemendo... na minha mente."
  },
  Voice_6284_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_6284_UnlockDesc = {
    Text = "Nível de iluminação atingiu 2 para desbloquear"
  },
  Voice_6285_AwakerVoiceContent = {
    Text = "Sente como se um véu de névoa branca estivesse obscurecendo meus pensamentos."
  },
  Voice_6285_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexão"
  },
  Voice_6285_UnlockDesc = {
    Text = "Nível de iluminação atingiu 3 para desbloquear"
  },
  Voice_6286_AwakerVoiceContent = {
    Text = "O som ficou mais alto, e a névoa branca engrossou."
  },
  Voice_6286_AwakerVoiceTitle = {
    Text = "Iluminar: Insight"
  },
  Voice_6286_UnlockDesc = {
    Text = "Nível de iluminação atingiu 7 para desbloquear"
  },
  Voice_6287_AwakerVoiceContent = {
    Text = "Isso é o som dos ponteiros do relógio se movendo?"
  },
  Voice_6287_AwakerVoiceTitle = {
    Text = "Iluminar·Construção"
  },
  Voice_6287_UnlockDesc = {
    Text = "Nível de iluminação atingiu 11 para desbloquear"
  },
  Voice_6288_AwakerVoiceContent = {
    Text = "Quando o sino tocar, ainda estarei aqui?"
  },
  Voice_6288_AwakerVoiceTitle = {
    Text = "Iluminar·Florescer"
  },
  Voice_6288_UnlockDesc = {
    Text = "Nível de iluminação atingiu 15 para desbloquear"
  },
  Voice_6289_AwakerVoiceContent = {
    Text = "Truque tão desajeitado... Hmph, you tolo ingênuo. Como você poderia pensar que poderia me prender tão facilmente?"
  },
  Voice_6289_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_6290_AwakerVoiceContent = {
    Text = "Com licença... Você viu minha irmã, Jenkin? Ela é uma garota que carrega um rato e pode ser bastante feroz... Eu não poderia confundi-la."
  },
  Voice_6290_AwakerVoiceTitle = {
    Text = "Fofocas · Sobre Jenki"
  },
  Voice_6290_UnlockDesc = {
    Text = "Desbloqueado após limpar \"Operação de Investigação\" Capítulo 2"
  },
  Voice_6292_AwakerVoiceContent = {
    Text = "Obrigado pela sua bondade."
  },
  Voice_6292_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · I"
  },
  Voice_6293_AwakerVoiceContent = {Text = "Pronto."},
  Voice_6293_AwakerVoiceTitle = {
    Text = "Habilidade·Um"
  },
  Voice_6294_AwakerVoiceContent = {
    Text = "Por favor, aguarde com expectativa."
  },
  Voice_6294_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · Três"
  },
  Voice_6295_AwakerVoiceContent = {
    Text = "Cantando para você."
  },
  Voice_6295_AwakerVoiceTitle = {
    Text = "Atualizar·II"
  },
  Voice_6296_AwakerVoiceContent = {
    Text = "Novo Guardião? Dê tudo de si e me mostre se você é digno de ser meu oponente."
  },
  Voice_6296_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_6297_AwakerVoiceContent = {
    Text = "Embora eu seja pacifista, \"eles\" claramente pensam de outra forma..."
  },
  Voice_6297_AwakerVoiceTitle = {
    Text = "Início da Investigação"
  },
  Voice_6298_AwakerVoiceContent = {Text = "Ha!"},
  Voice_6298_AwakerVoiceTitle = {Text = "Ataque·Um"},
  Voice_6299_AwakerVoiceContent = {Text = "Afaste-se!"},
  Voice_6299_AwakerVoiceTitle = {Text = "Ataque·Um"},
  Voice_6300_AwakerVoiceContent = {
    Text = "Como você se atreve a me humilhar assim..."
  },
  Voice_6300_AwakerVoiceTitle = {
    Text = "Investigação Interrompida"
  },
  Voice_6301_AwakerVoiceContent = {
    Text = "Você está pronto? O show de mágica de Casiah está prestes a começar! Não olhe para longe, não perca os destaques. É hora do show!"
  },
  Voice_6301_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_6302_AwakerVoiceTitle = {
    Text = "Defesa · I"
  },
  Voice_6303_AwakerVoiceContent = {Text = "Ha!"},
  Voice_6303_AwakerVoiceTitle = {Text = "Defesa·II"},
  Voice_6304_AwakerVoiceContent = {
    Text = "Peguei sua agenda com Sylvia, é muito rigorosa para um novato. Entendo que estão fazendo a coisa certa, mas sobrecarregar os novatos pode causar problemas desnecessários para a equipe.\nVocê diz que não é novato? Não, posso ver em seus olhos, você ainda não passou por muita coisa."
  },
  Voice_6304_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Quatro"
  },
  Voice_6304_UnlockDesc = {
    Text = "Nível de afinidade atingido 8 desbloqueado"
  },
  Voice_6305_AwakerVoiceContent = {
    Text = "Eu desprezo minhas próprias falhas... Ah! Não há necessidade de me confortar! Essas experiências passadas se tornaram a força motriz por trás do meu crescimento. Eu já não me tornei seu apoio?"
  },
  Voice_6305_AwakerVoiceTitle = {
    Text = "Conversa·Coisas odiadas"
  },
  Voice_6306_AwakerVoiceContent = {
    Text = "Simplesmente não consigo me dar bem com aquele homem. A vida não se resume a pecado e punição, certo? Não é mais importante aproveitar o momento?"
  },
  Voice_6306_AwakerVoiceTitle = {
    Text = "Conversa Casual · Sobre Salvador"
  },
  Voice_6306_UnlockDesc = {
    Text = "Desbloqueado após adquirir o Despertar \"Salvador\""
  },
  Voice_6307_AwakerVoiceContent = {
    Text = "O tempo está se esgotando, vamos nos mover."
  },
  Voice_6307_AwakerVoiceTitle = {
    Text = "Início da Investigação"
  },
  Voice_6308_AwakerVoiceContent = {
    Text = "Eu odeio velas que se apagam facilmente, pão preto e fios soltos em saias... Sem motivo, apenas odeio. Não é natural?"
  },
  Voice_6308_AwakerVoiceTitle = {
    Text = "Conversa·Coisas odiadas"
  },
  Voice_6309_AwakerVoiceContent = {
    Text = "Desde que você me coroou como a Donzela Sagrada, você deve se submeter!"
  },
  Voice_6309_AwakerVoiceTitle = {
    Text = "Fúria Explosiva"
  },
  Voice_6310_AwakerVoiceContent = {
    Text = "Desde que você me coroou como a Donzela Sagrada, você deve se submeter!"
  },
  Voice_6310_AwakerVoiceTitle = {
    Text = "Exaltar · Dois"
  },
  Voice_6311_AwakerVoiceContent = {Text = "Cante."},
  Voice_6311_AwakerVoiceTitle = {Text = "Ataque·Um"},
  Voice_6312_AwakerVoiceContent = {
    Text = "\"O Guarda-Roupa da Dama\" e \"O Guia da Mulher Trabalhadora\" são leituras excelentes... Mesmo que você não possa comprá-los, simplesmente admirar os belos vestidos é bastante agradável."
  },
  Voice_6312_AwakerVoiceTitle = {
    Text = "Conversa·Coisas favoritas"
  },
  Voice_6313_AwakerVoiceContent = {
    Text = "É estranho. Eu geralmente tenho dificuldade em lembrar das coisas, mas memorize você em apenas alguns dias... O quê? Já se passaram três meses? Desculpe, esqueci de novo."
  },
  Voice_6313_AwakerVoiceTitle = {
    Text = "Conversa·Sobre Guardião do Segredo"
  },
  Voice_6314_AwakerVoiceContent = {
    Text = "Saboreie isso."
  },
  Voice_6314_AwakerVoiceTitle = {Text = "Ataque·II"},
  Voice_6316_AwakerVoiceContent = {
    Text = "Continue melhorando sua compostura."
  },
  Voice_6316_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · I"
  },
  Voice_6317_AwakerVoiceContent = {
    Text = "Pratique o Giro do Chicote mais vinte vezes."
  },
  Voice_6317_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · Três"
  },
  Voice_6318_AwakerVoiceContent = {
    Text = "Meus movimentos são precisos o suficiente?"
  },
  Voice_6318_AwakerVoiceTitle = {
    Text = "Atualizar·II"
  },
  Voice_6319_AwakerVoiceContent = {
    Text = "Por favor, siga em frente!"
  },
  Voice_6319_AwakerVoiceTitle = {Text = "Ataque·II"},
  Voice_6320_AwakerVoiceContent = {
    Text = "Acelera, leve Brown e vá!"
  },
  Voice_6320_AwakerVoiceTitle = {
    Text = "Investigação Interrompida"
  },
  Voice_6321_AwakerVoiceContent = {
    Text = "Ajoelhe-se diante do trono."
  },
  Voice_6321_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_6322_AwakerVoiceContent = {
    Text = "Ajoelhe-se diante do trono."
  },
  Voice_6322_AwakerVoiceTitle = {
    Text = "Carta de Habilidade·Quatro"
  },
  Voice_6323_AwakerVoiceContent = {
    Text = "As várias expressões dos humanos diante do desejo nunca deixam de me surpreender. Infelizmente, os humanos ainda são muito frágeis, muito insignificantes... Isso só me faz sentir como se um gato estivesse arranhando meu coração."
  },
  Voice_6323_AwakerVoiceTitle = {
    Text = "Conversa·Coisas odiadas"
  },
  Voice_6324_AwakerVoiceContent = {
    Text = "Das memórias dela, vi muitos eventos passados relacionados à \"Dissolução\"... Mas toda vez que queria te contar, minha consciência se desconectava. Temo que isso também seja obra dela."
  },
  Voice_6324_AwakerVoiceTitle = {
    Text = "Bate-papo · Sobre Dissolução"
  },
  Voice_6325_AwakerVoiceContent = {
    Text = "Não seria bom simplesmente se desvanecer no esquecimento?"
  },
  Voice_6325_AwakerVoiceTitle = {
    Text = "Investigação Interrompida"
  },
  Voice_6326_AwakerVoiceContent = {
    Text = "Um servo qualificado deve ser frágil e vazio de cabeça — eu gosto de cordeiros obedientes."
  },
  Voice_6326_AwakerVoiceTitle = {
    Text = "Conversa·Coisas favoritas"
  },
  Voice_6327_AwakerVoiceContent = {
    Text = "Nossa reunião deve ser uma promessa dos deuses para aqueles que sofrem — você é a chama pálida que dissipa a calamidade, e eu serei seu braço, ao seu lado."
  },
  Voice_6327_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_6328_AwakerVoiceContent = {
    Text = "Isso é suficiente!"
  },
  Voice_6328_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_6329_AwakerVoiceContent = {
    Text = "Você já tentou injetar D-Slime diretamente em seu corpo? A gosma negra se enrola ao redor do seu coração como uma víbora, e então... boom! Seu corpo explode em uma piscina morna de gosma. Degradante, mas eficaz."
  },
  Voice_6329_AwakerVoiceTitle = {
    Text = "Bate-papo · Sobre Dissolução"
  },
  Voice_6330_AwakerVoiceContent = {
    Text = "Hmph, um refúgio para os fracos se aglomerarem."
  },
  Voice_6330_AwakerVoiceTitle = {
    Text = "Chat·Sobre a Universidade Mythag"
  },
  Voice_6331_AwakerVoiceContent = {
    Text = "De vez em quando, a garota na motocicleta me ajuda a manter meu membro protético. No entanto, recentemente, a frequência das verificações de manutenção não tem sido um pouco alta demais?"
  },
  Voice_6331_AwakerVoiceTitle = {
    Text = "Bate-Papo·Sobre Náutilo"
  },
  Voice_6331_UnlockDesc = {
    Text = "Após obter o despertador \"Náutilo\", desbloqueado"
  },
  Voice_6332_AwakerVoiceContent = {
    Text = "Nosso relacionamento? Você realmente precisa perguntar? É exatamente o que você está imaginando!"
  },
  Voice_6332_AwakerVoiceTitle = {
    Text = "Conversa·Sobre Guardião do Segredo"
  },
  Voice_6333_AwakerVoiceContent = {
    Text = "Não é meu gênero preferido, mas se você insiste."
  },
  Voice_6333_AwakerVoiceTitle = {
    Text = "Início da Investigação"
  },
  Voice_6334_AwakerVoiceContent = {
    Text = "As suas olheiras estão piorando... Por que trabalhar tanto? Você deveria ser mais como eu e aprender a aproveitar seu tempo livre."
  },
  Voice_6334_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_6334_UnlockDesc = {
    Text = "Nível de iluminação atingiu 2 para desbloquear"
  },
  Voice_6335_AwakerVoiceContent = {
    Text = "Espere, sem minha permissão..."
  },
  Voice_6335_AwakerVoiceTitle = {
    Text = "Iluminar·Visão Remota"
  },
  Voice_6335_UnlockDesc = {
    Text = "Nível de iluminação atingiu 1 para desbloquear"
  },
  Voice_6336_AwakerVoiceContent = {
    Text = "Bom... Está chegando mais perto de sua forma original."
  },
  Voice_6336_AwakerVoiceTitle = {
    Text = "Iluminar·Construção"
  },
  Voice_6336_UnlockDesc = {
    Text = "Nível de iluminação atingiu 11 para desbloquear"
  },
  Voice_6337_AwakerVoiceContent = {
    Text = "Este é o poder para contra-atacar a \"Corrupção Verde\"... Você tocou em algo que não deveria. Quanto a mim, nunca vou deixar você ir novamente."
  },
  Voice_6337_AwakerVoiceTitle = {
    Text = "Iluminar·Florescer"
  },
  Voice_6337_UnlockDesc = {
    Text = "Nível de iluminação atingiu 15 para desbloquear"
  },
  Voice_6338_AwakerVoiceContent = {
    Text = "Shh... O brilho da manhã no vale—esta deve ser a sua primeira vez vendo isso, certo? Esta é sua recompensa pela lealdade."
  },
  Voice_6338_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexão"
  },
  Voice_6338_UnlockDesc = {
    Text = "Nível de iluminação atingiu 3 para desbloquear"
  },
  Voice_6339_AwakerVoiceContent = {
    Text = "Este livro, \"A Revelação @1@2,\" é concedido a você. Ajuda a iluminar a mente ou a adormecer rapidamente"
  },
  Voice_6339_AwakerVoiceTitle = {
    Text = "Iluminar: Insight"
  },
  Voice_6339_UnlockDesc = {
    Text = "Nível de iluminação atingiu 7 para desbloquear"
  },
  Voice_6340_AwakerVoiceContent = {
    Text = "O mundo mortal ainda é barulhento demais. Se você puder encontrar um canto tranquilo para mim na academia, seria perfeito... Não, eu não preciso de uma lareira. Somente através de práticas ascéticas os deuses podem ouvir minhas orações..."
  },
  Voice_6340_AwakerVoiceTitle = {
    Text = "Chat·Sobre a Universidade Mythag"
  },
  Voice_6341_AwakerVoiceContent = {
    Text = "É cera ou mel escorrendo do meu corpo? Por que você não dá uma lambida e vê por si mesmo?"
  },
  Voice_6341_AwakerVoiceTitle = {
    Text = "Iluminar·Visão Remota"
  },
  Voice_6341_UnlockDesc = {
    Text = "Nível de iluminação atingiu 1 para desbloquear"
  },
  Voice_6342_AwakerVoiceContent = {
    Text = "Olá... Prazer em conhecê-lo. Meu nome é Aigis... Por favor, apenas finja que eu não existo!"
  },
  Voice_6342_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_6343_AwakerVoiceContent = {
    Text = "Enquanto eu ainda for \"Ramona\", ainda somos parceiros, certo?"
  },
  Voice_6343_AwakerVoiceTitle = {
    Text = "Conversa·Sobre Guardião do Segredo"
  },
  Voice_6344_AwakerVoiceContent = {
    Text = "Aquela senhora com olheiras profundas uma vez me consultou sobre \"viver para sempre ao sol\"... Ela só precisava migrar entre duas dimensões. No entanto, se recusa a entrar no túnel Dimensional. Foi realmente uma dor de cabeça."
  },
  Voice_6344_AwakerVoiceTitle = {
    Text = "Bate-Papo·Sobre Búzio"
  },
  Voice_6344_UnlockDesc = {
    Text = "Após obter o despertador \"Búzio\", desbloqueado"
  },
  Voice_6345_AwakerVoiceContent = {
    Text = "Bem-vindo ao meu paraíso! Você está pronto para enfrentar a chibata?"
  },
  Voice_6345_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_6346_AwakerVoiceContent = {
    Text = "Como Ele te reconheceu, eu não te considerarei um inimigo."
  },
  Voice_6346_AwakerVoiceTitle = {
    Text = "Conversa·Sobre Guardião do Segredo"
  },
  Voice_6347_AwakerVoiceContent = {
    Text = "O que você quer dizer com \"eu fiz isso\"? Não me acuse falsamente! Quando os parafusos dela desapareceram, eu estava—Marrom, pare! ... Hehe, apenas finja que você não viu nada, tudo bem?"
  },
  Voice_6347_AwakerVoiceTitle = {
    Text = "Bate-Papo·Sobre Náutilo"
  },
  Voice_6347_UnlockDesc = {
    Text = "Após obter o despertador \"Náutilo\", desbloqueado"
  },
  Voice_6348_AwakerVoiceContent = {
    Text = "A aventura é tão emocionante quanto nas histórias! Qual era aquela história...?"
  },
  Voice_6348_AwakerVoiceTitle = {
    Text = "Investigação Bem-sucedida"
  },
  Voice_6349_AwakerVoiceContent = {
    Text = "...Hic. Ah, desculpe, acabei absorvendo energia demais de novo."
  },
  Voice_6349_AwakerVoiceTitle = {
    Text = "Investigação Bem-sucedida"
  },
  Voice_6350_AwakerVoiceContent = {
    Text = "Uma vez dentro de um corpo humano, perdi todo contato com meu clã. Fico aterrorizado que os outros não tenham escapado dos demônios e que eu possa ser o último da minha espécie... Por favor, Guardião, me salve. Deixe-me ficar ao seu lado, não me deixe na escuridão."
  },
  Voice_6350_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Cinco"
  },
  Voice_6350_UnlockDesc = {
    Text = "Nível de afinidade atingido 10 desbloqueado"
  },
  Voice_6351_AwakerVoiceContent = {
    Text = "Quando o planeta foi destruído, eu abandonei meu corpo e transfiri minha consciência para um corpo humano... Mas o demônio negro me perseguiu incansavelmente, amarrando meu espírito e impedindo minha fuga! Ele busca arrastar o mundo para um abismo de escuridão!"
  },
  Voice_6351_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Quatro"
  },
  Voice_6351_UnlockDesc = {
    Text = "Nível de afinidade atingido 8 desbloqueado"
  },
  Voice_6352_AwakerVoiceContent = {
    Text = "Por favor, Guardião... Enquanto você me deixar ficar no localizador e não sair, farei qualquer coisa, exceto entrar na escuridão e enfrentar aquela... aquela coisa negra! Eu não posso deixar o localizador. Só mais um pouco, e eu localizarei os restos do planeta natal! Apenas 1,2 bilhão de cálculos restantes!"
  },
  Voice_6352_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Três"
  },
  Voice_6352_UnlockDesc = {
    Text = "Nível de afinidade atingido 6 desbloqueado"
  },
  Voice_6353_AwakerVoiceContent = {
    Text = "Você poderia usar sua parte do suprimento para me conseguir duas sacolas de suplementos de cafeína? ... Eu não consigo dormir. Por que deveria dormir? Nunca durma! Assim que você fechar os olhos, tudo se transforma em escuridão... escuridão..."
  },
  Voice_6353_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Dois"
  },
  Voice_6353_UnlockDesc = {
    Text = "Nível de afinidade atingido 4 desbloqueado"
  },
  Voice_6354_AwakerVoiceContent = {
    Text = "Uau! Fique longe de mim! Primeiro, prove que você não é um servo das trevas! Sim, servo. Apenas tire suas roupas e me mostre que você não tem aquela nojenta gosma preta no seu corpo, e então eu saberei que você não é maligno..."
  },
  Voice_6354_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Um"
  },
  Voice_6354_UnlockDesc = {
    Text = "Nível de afinidade atingido 2 desbloqueado"
  },
  Voice_6355_AwakerVoiceContent = {
    Text = "Não pergunte, não pergunte...! Você sabe exatamente o que eu mais temo e odeio! Escuridão, escuridão sem fim!"
  },
  Voice_6355_AwakerVoiceTitle = {
    Text = "Conversa·Coisas odiadas"
  },
  Voice_6356_AwakerVoiceContent = {
    Text = "Um método para curar a Dissolução? Tal coisa não existe em lugar algum.\nVocê pergunta como eu permaneço não infectado? Hehe... desde que você \"não seja visto\", isso é tudo o que é necessário."
  },
  Voice_6356_AwakerVoiceTitle = {
    Text = "Bate-papo · Sobre Dissolução"
  },
  Voice_6357_AwakerVoiceContent = {
    Text = "Obrigado, Mestre."
  },
  Voice_6357_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · Três"
  },
  Voice_6358_AwakerVoiceContent = {
    Text = "Eles também estão felizes."
  },
  Voice_6358_AwakerVoiceTitle = {
    Text = "Atualizar·II"
  },
  Voice_6359_AwakerVoiceContent = {
    Text = "Lily cresceu."
  },
  Voice_6359_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · I"
  },
  Voice_6360_AwakerVoiceContent = {
    Text = "Esmagar isso?"
  },
  Voice_6360_AwakerVoiceTitle = {
    Text = "Início da Investigação"
  },
  Voice_6361_AwakerVoiceContent = {
    Text = "Como você poderia evocá-lo! Aquele cabeçudo inútil! Preguiçoso e sem ambição... Ele foi alguém que eu tinha grandes esperanças! Vamos! Eu não quero ver esse cara!"
  },
  Voice_6361_AwakerVoiceTitle = {
    Text = "Papo reto · Sobre Tulu"
  },
  Voice_6361_UnlockDesc = {
    Text = "Desbloqueado após obter o Despertador \"Tulu\""
  },
  Voice_6362_AwakerVoiceContent = {
    Text = "Repugnante!"
  },
  Voice_6362_AwakerVoiceTitle = {Text = "Defesa·II"},
  Voice_6363_AwakerVoiceContent = {
    Text = "Tão irritante!"
  },
  Voice_6363_AwakerVoiceTitle = {
    Text = "Defesa · I"
  },
  Voice_6364_AwakerVoiceContent = {
    Text = "Next time, let's go see the sea together. Febvre está bem, posso ser seu guia; ou em qualquer outro lugar, até os fins da terra, eu quero ir com você."
  },
  Voice_6364_AwakerVoiceTitle = {
    Text = "Iluminar·Florescer"
  },
  Voice_6364_UnlockDesc = {
    Text = "Nível de iluminação atingiu 15 para desbloquear"
  },
  Voice_6365_AwakerVoiceContent = {
    Text = "O mar possui sua própria língua.\n...Assim, posso ocasionalmente conversar com os peixinhos do lago sobre nossa terra natal. Se você estiver curioso, posso ajudar a traduzir para você."
  },
  Voice_6365_AwakerVoiceTitle = {
    Text = "Iluminar·Construção"
  },
  Voice_6365_UnlockDesc = {
    Text = "Nível de iluminação atingiu 11 para desbloquear"
  },
  Voice_6366_AwakerVoiceContent = {
    Text = "Para ser salvo por você, muitas vezes me sinto tão feliz que isso me assusta... Por favor, diga-me, isso não é um sonho, e você não vai desaparecer no mar sem deixar vestígios, certo?"
  },
  Voice_6366_AwakerVoiceTitle = {
    Text = "Iluminar: Insight"
  },
  Voice_6366_UnlockDesc = {
    Text = "Nível de iluminação atingiu 7 para desbloquear"
  },
  Voice_6367_AwakerVoiceContent = {
    Text = "Esse sentimento pode ser chamado de \"felicidade\"? Eu... nunca me atrevi a esperar por isso antes."
  },
  Voice_6367_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexão"
  },
  Voice_6367_UnlockDesc = {
    Text = "Nível de iluminação atingiu 3 para desbloquear"
  },
  Voice_6368_AwakerVoiceContent = {
    Text = "Meu corpo se sente quente, como se estivesse gentilmente envolto pelo mar. É realmente incrível."
  },
  Voice_6368_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_6368_UnlockDesc = {
    Text = "Nível de iluminação atingiu 2 para desbloquear"
  },
  Voice_6369_AwakerVoiceContent = {
    Text = "É um fragmento Dele? Impressionante, realmente possui uma aura régia."
  },
  Voice_6369_AwakerVoiceTitle = {
    Text = "Papo reto · Sobre Tulu"
  },
  Voice_6369_UnlockDesc = {
    Text = "Desbloqueado após obter o Despertador \"Tulu\""
  },
  Voice_6370_AwakerVoiceContent = {
    Text = "Não, não continue... Ele vai me encontrar, ele vai me encontrar!"
  },
  Voice_6370_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · I"
  },
  Voice_6371_AwakerVoiceContent = {
    Text = "Isto deve me manter acordado."
  },
  Voice_6371_AwakerVoiceTitle = {
    Text = "Atualizar·II"
  },
  Voice_6372_AwakerVoiceContent = {
    Text = "Acabou, acabou, acabou... Eles definitivamente descobrirão..."
  },
  Voice_6372_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · Três"
  },
  Voice_6373_AwakerVoiceContent = {
    Text = "Nós vencemos. Você está feliz? Como é sentir \"feliz\"?"
  },
  Voice_6373_AwakerVoiceTitle = {
    Text = "Investigação Bem-sucedida"
  },
  Voice_6374_AwakerVoiceContent = {
    Text = "Coisas que eu gosto? Eu gosto das canções de ninar do Tinct... Claro, seu canto também é maravilhoso!"
  },
  Voice_6374_AwakerVoiceTitle = {
    Text = "Conversa·Coisas favoritas"
  },
  Voice_6375_AwakerVoiceContent = {
    Text = "Ele é um guerreiro confiável. Eu o considerava um \"camarada\" uma vez... O que? Você acredita que minha definição de \"camarada\" está errada? Por favor, ilumine-me."
  },
  Voice_6375_AwakerVoiceTitle = {
    Text = "Bate-papo · Sobre Golias"
  },
  Voice_6375_UnlockDesc = {
    Text = "Após obter o despertador \"Golias\", desbloqueado"
  },
  Voice_6378_AwakerVoiceContent = {Text = "Meteoro..."},
  Voice_6378_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_6379_AwakerVoiceContent = {Text = "Ah—"},
  Voice_6379_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_6380_AwakerVoiceContent = {
    Text = "Um impulso contínuo de poder, preenchendo todo o corpo..."
  },
  Voice_6380_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · I"
  },
  Voice_6381_AwakerVoiceContent = {Text = "Voe!"},
  Voice_6381_AwakerVoiceTitle = {Text = "Ataque·Um"},
  Voice_6382_AwakerVoiceContent = {
    Text = "Nada mal, você é mais útil do que parece."
  },
  Voice_6382_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · Três"
  },
  Voice_6383_AwakerVoiceContent = {
    Text = "Vinte, vinte e um, vinte e quatro... Espere, que número eu estava contando? Um, dois, três..."
  },
  Voice_6383_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_6383_UnlockDesc = {
    Text = "Nível de iluminação atingiu 2 para desbloquear"
  },
  Voice_6384_AwakerVoiceContent = {
    Text = "Finalmente descobri quantos materiais tinha antes, para que eu pudesse terminar os reparos mais rápido—Espere, de onde vieram estes?"
  },
  Voice_6384_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexão"
  },
  Voice_6384_UnlockDesc = {
    Text = "Nível de iluminação atingiu 3 para desbloquear"
  },
  Voice_6385_AwakerVoiceContent = {
    Text = "Graças à sua ajuda, a eficiência dos reparos recentes melhorou. Em breve poderemos partir em uma aventura!"
  },
  Voice_6385_AwakerVoiceTitle = {
    Text = "Iluminar: Insight"
  },
  Voice_6385_UnlockDesc = {
    Text = "Nível de iluminação atingiu 7 para desbloquear"
  },
  Voice_6386_AwakerVoiceContent = {
    Text = "Acho que estou começando a lembrar das coisas... Você me passou uma chave inglesa número 7 ontem?"
  },
  Voice_6386_AwakerVoiceTitle = {
    Text = "Iluminar·Construção"
  },
  Voice_6386_UnlockDesc = {
    Text = "Nível de iluminação atingiu 11 para desbloquear"
  },
  Voice_6387_AwakerVoiceContent = {
    Text = "Repare, conserte, complete! Uma aventura desconhecida, um mundo misterioso, aqui vou eu!"
  },
  Voice_6387_AwakerVoiceTitle = {
    Text = "Iluminar·Florescer"
  },
  Voice_6387_UnlockDesc = {
    Text = "Nível de iluminação atingiu 15 para desbloquear"
  },
  Voice_6388_AwakerVoiceContent = {Text = "Boom—"},
  Voice_6388_AwakerVoiceTitle = {Text = "Ataque·II"},
  Voice_6389_AwakerVoiceContent = {
    Text = "Não engane a si mesmo. Algemas mentais ainda são algemas e não podem ser chamadas de justas."
  },
  Voice_6389_AwakerVoiceTitle = {
    Text = "Chat·Sobre a Universidade Mythag"
  },
  Voice_6390_AwakerVoiceContent = {
    Text = "Agora, a linha entre eu e o Despertador está ainda mais turva. É melhor você ficar de olho em mim."
  },
  Voice_6390_AwakerVoiceTitle = {
    Text = "Iluminar·Construção"
  },
  Voice_6390_UnlockDesc = {
    Text = "Nível de iluminação atingiu 11 para desbloquear"
  },
  Voice_6391_AwakerVoiceContent = {
    Text = "Vamos e salvar o mundo."
  },
  Voice_6391_AwakerVoiceTitle = {
    Text = "Iluminar·Florescer"
  },
  Voice_6391_UnlockDesc = {
    Text = "Nível de iluminação atingiu 15 para desbloquear"
  },
  Voice_6392_AwakerVoiceContent = {
    Text = "É tão refrescante quanto ler \"A Origem das Espécies\" de uma vez só"
  },
  Voice_6392_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexão"
  },
  Voice_6392_UnlockDesc = {
    Text = "Nível de iluminação atingiu 3 para desbloquear"
  },
  Voice_6393_AwakerVoiceContent = {
    Text = "Fiquei mais forte. Deixe-me tentar lidar com a próxima missão sozinho, tudo bem?"
  },
  Voice_6393_AwakerVoiceTitle = {
    Text = "Iluminar: Insight"
  },
  Voice_6393_UnlockDesc = {
    Text = "Nível de iluminação atingiu 7 para desbloquear"
  },
  Voice_6394_AwakerVoiceContent = {
    Text = "Além da habilidade de combate, minha memória e raciocínio lógico não melhoraram muito. Eu ainda tenho que depender dos meus próprios pensamentos."
  },
  Voice_6394_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_6394_UnlockDesc = {
    Text = "Nível de iluminação atingiu 2 para desbloquear"
  },
  Voice_6395_AwakerVoiceContent = {
    Text = "Eu quero que eles experimentem a sensação de ter suas vidas viradas de cabeça para baixo, perder tudo e ser pisoteados por todos."
  },
  Voice_6395_AwakerVoiceTitle = {
    Text = "Iluminar·Construção"
  },
  Voice_6395_UnlockDesc = {
    Text = "Nível de iluminação atingiu 11 para desbloquear"
  },
  Voice_6396_AwakerVoiceContent = {
    Text = "A humilhação que eu suportei, tudo que eu perdi... Eu os farei pagar. Eu farei todos eles pagarem."
  },
  Voice_6396_AwakerVoiceTitle = {
    Text = "Iluminar·Florescer"
  },
  Voice_6396_UnlockDesc = {
    Text = "Nível de iluminação atingiu 15 para desbloquear"
  },
  Voice_6397_AwakerVoiceContent = {
    Text = "Tal doce ódio, quando temperado com o sangue dos inimigos, é certamente o prato mais requintado do mundo."
  },
  Voice_6397_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexão"
  },
  Voice_6397_UnlockDesc = {
    Text = "Nível de iluminação atingiu 3 para desbloquear"
  },
  Voice_6398_AwakerVoiceContent = {
    Text = "Ah! Não me surpreenda por trás!"
  },
  Voice_6398_AwakerVoiceTitle = {
    Text = "Conversa·Toque"
  },
  Voice_6399_AwakerVoiceContent = {
    Text = "As chamas escaldantes queimam em meu peito... Sim, eu nunca esqueci, nem poderei esquecer."
  },
  Voice_6399_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_6399_UnlockDesc = {
    Text = "Nível de iluminação atingiu 2 para desbloquear"
  },
  Voice_6400_AwakerVoiceContent = {
    Text = "Queime, ó alma da poesia."
  },
  Voice_6400_AwakerVoiceTitle = {
    Text = "Despertar do Conhecimento Espiritual"
  },
  Voice_6401_AwakerVoiceContent = {Text = "(Hmph)"},
  Voice_6401_AwakerVoiceTitle = {Text = "Acertar·1"},
  Voice_6402_AwakerVoiceContent = {Text = "(Hmph)"},
  Voice_6402_AwakerVoiceTitle = {
    Text = "Acertar·III"
  },
  Voice_6403_AwakerVoiceContent = {Text = "(Hmph)"},
  Voice_6403_AwakerVoiceTitle = {
    Text = "Acertar · II"
  },
  Voice_6404_AwakerVoiceContent = {Text = "(Hmph)"},
  Voice_6404_AwakerVoiceTitle = {
    Text = "Golpe·Quatro"
  },
  Voice_6405_AwakerVoiceContent = {
    Text = "É tão engraçado! Assim como quando a empregada usa uma pena para fazer cócegas nas solas dos meus pés. Você *bleep* não fez isso de propósito, certo?"
  },
  Voice_6405_AwakerVoiceTitle = {
    Text = "Iluminar·Visão Remota"
  },
  Voice_6405_UnlockDesc = {
    Text = "Nível de iluminação atingiu 1 para desbloquear"
  },
  Voice_6406_AwakerVoiceContent = {
    Text = "Que você tenha doces sonhos."
  },
  Voice_6406_AwakerVoiceTitle = {
    Text = "Habilidade·Um"
  },
  Voice_6407_AwakerVoiceContent = {
    Text = "Que você tenha doces sonhos."
  },
  Voice_6407_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_6408_AwakerVoiceContent = {
    Text = "Conceda serenidade...!"
  },
  Voice_6408_AwakerVoiceTitle = {Text = "Defesa·II"},
  Voice_6409_AwakerVoiceContent = {
    Text = "Movimente-se com elegância."
  },
  Voice_6409_AwakerVoiceTitle = {
    Text = "Defesa · I"
  },
  Voice_6410_AwakerVoiceContent = {
    Text = "Você pode me ouvir? Minha voz."
  },
  Voice_6410_AwakerVoiceTitle = {
    Text = "Carta de Habilidade·Quatro"
  },
  Voice_6411_AwakerVoiceContent = {
    Text = "Você pode me ouvir? Minha voz."
  },
  Voice_6411_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_6412_AwakerVoiceContent = {
    Text = "Está chovendo. A chuva lava tudo: comida estragada, sujeira persistente e pessoas como eu... os dispensáveis."
  },
  Voice_6412_AwakerVoiceTitle = {
    Text = "Conversa·Coisas odiadas"
  },
  Voice_6413_AwakerVoiceContent = {
    Text = "A onda de vingança enfurecida nunca cessa."
  },
  Voice_6413_AwakerVoiceTitle = {
    Text = "Despertar do Conhecimento Espiritual"
  },
  Voice_6414_AwakerVoiceContent = {
    Text = "Sangue, banhe meu corpo inteiro!"
  },
  Voice_6414_AwakerVoiceTitle = {
    Text = "Despertar do Conhecimento Espiritual"
  },
  Voice_6415_AwakerVoiceContent = {Text = "Ah!"},
  Voice_6415_AwakerVoiceTitle = {Text = "Ataque·Um"},
  Voice_6416_AwakerVoiceContent = {
    Text = "Olhe para cá!"
  },
  Voice_6416_AwakerVoiceTitle = {Text = "Ataque·Um"},
  Voice_6417_AwakerVoiceContent = {
    Text = "Não tenho medo."
  },
  Voice_6417_AwakerVoiceTitle = {Text = "Defesa·II"},
  Voice_6418_AwakerVoiceContent = {Text = "Cuidado!"},
  Voice_6418_AwakerVoiceTitle = {
    Text = "Defesa · I"
  },
  Voice_6419_AwakerVoiceContent = {
    Text = "Um mundo intocado pela tristeza, imaculado pelo luto, livre da dor e não manchado pelo sofrimento sombrio—talvez uma ilusão inatingível, mas é o ideal que eu procurei durante toda a minha vida."
  },
  Voice_6419_AwakerVoiceTitle = {
    Text = "Conversa·Coisas favoritas"
  },
  Voice_6420_AwakerVoiceContent = {
    Text = "Eis a magnificência do Reino Eterno!"
  },
  Voice_6420_AwakerVoiceTitle = {
    Text = "Exaltar · Dois"
  },
  Voice_6421_AwakerVoiceContent = {
    Text = "Eis a magnificência do Reino Eterno!"
  },
  Voice_6421_AwakerVoiceTitle = {
    Text = "Fúria Explosiva"
  },
  Voice_6422_AwakerVoiceContent = {
    Text = "Oferecendo tributos obedientemente novamente? Bom garoto."
  },
  Voice_6422_AwakerVoiceTitle = {
    Text = "Iluminar·Visão Remota"
  },
  Voice_6422_UnlockDesc = {
    Text = "Nível de iluminação atingiu 1 para desbloquear"
  },
  Voice_6423_AwakerVoiceContent = {Text = "Dói?"},
  Voice_6423_AwakerVoiceTitle = {Text = "Ataque·II"},
  Voice_6424_AwakerVoiceContent = {
    Text = "Mantenha o foco."
  },
  Voice_6424_AwakerVoiceTitle = {Text = "Ataque·Um"},
  Voice_6425_AwakerVoiceContent = {
    Text = "A passagem dos milênios me tornou um pouco descuidado."
  },
  Voice_6425_AwakerVoiceTitle = {
    Text = "Investigação Interrompida"
  },
  Voice_6426_AwakerVoiceContent = {
    Text = "Aquele dia, as chamas da inveja se espalharam como um mar de rosas vermelhas em plena floração... Todos os poemas se tornaram cinzas quebradas no meio das línguas de fogo carmesim."
  },
  Voice_6426_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Três"
  },
  Voice_6426_UnlockDesc = {
    Text = "Nível de afinidade atingido 6 desbloqueado"
  },
  Voice_6427_AwakerVoiceContent = {
    Text = "Aprendi uma nova técnica!"
  },
  Voice_6427_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · I"
  },
  Voice_6428_AwakerVoiceContent = {Text = "Cuidado."},
  Voice_6428_AwakerVoiceTitle = {
    Text = "Defesa · I"
  },
  Voice_6429_AwakerVoiceContent = {
    Text = "A varinha quer dançar!"
  },
  Voice_6429_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · Três"
  },
  Voice_6430_AwakerVoiceContent = {
    Text = "Ah, esta sensação familiar de vazio!"
  },
  Voice_6430_AwakerVoiceTitle = {
    Text = "Atualizar·II"
  },
  Voice_6431_AwakerVoiceContent = {
    Text = "O movimento das articulações se tornou mais suave."
  },
  Voice_6431_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · Três"
  },
  Voice_6432_AwakerVoiceContent = {
    Text = "Aquela sombra negra ominosa se assemelha à minha espada-escudo amorfa... Ah! Fique tranquilo, meu senhor, minha espada guardiã nunca te fará mal!"
  },
  Voice_6432_AwakerVoiceTitle = {
    Text = "Bate-papo · Sobre Dissolução"
  },
  Voice_6433_AwakerVoiceContent = {Text = "Vamos."},
  Voice_6433_AwakerVoiceTitle = {
    Text = "Defesa · I"
  },
  Voice_6434_AwakerVoiceContent = {
    Text = "Mal consegui."
  },
  Voice_6434_AwakerVoiceTitle = {
    Text = "Atualizar·II"
  },
  Voice_6435_AwakerVoiceContent = {
    Text = "Farei o meu melhor."
  },
  Voice_6435_AwakerVoiceTitle = {
    Text = "Despertar do Conhecimento Espiritual"
  },
  Voice_6436_AwakerVoiceContent = {
    Text = "Jogar aqui hoje?"
  },
  Voice_6436_AwakerVoiceTitle = {
    Text = "Início da Investigação"
  },
  Voice_6437_AwakerVoiceContent = {
    Text = "O porão está cheio de água, suave e fria. Assim, meu corpo está sempre envolto em umidade... Como se eu fosse o único ser físico entre o céu e a terra. Às vezes, eu realmente desejo me dissolver na água.\nMas então eu deixaria de existir e nunca te encontraria."
  },
  Voice_6437_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Três"
  },
  Voice_6437_UnlockDesc = {
    Text = "Nível de afinidade atingido 6 desbloqueado"
  },
  Voice_6438_AwakerVoiceContent = {
    Text = "Aqui está um segredo... eu na verdade odeio sangue. Odeio sua cor, seu gosto. Mas não posso viver sem ele.\n...Eu engulo o sangue, depois vomito tudo... Eu me desprezo."
  },
  Voice_6438_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Dois"
  },
  Voice_6438_UnlockDesc = {
    Text = "Nível de afinidade atingido 4 desbloqueado"
  },
  Voice_6439_AwakerVoiceContent = {
    Text = "Hmm! Seu sangue... tem gosto de hidromel. Suponho que sou o único que conhece este segredo, certo?"
  },
  Voice_6439_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Um"
  },
  Voice_6439_UnlockDesc = {
    Text = "Nível de afinidade atingido 2 desbloqueado"
  },
  Voice_6440_AwakerVoiceContent = {
    Text = "Nas minhas fantasias, um cavaleiro valente me arrasta para fora da escuridão e então me prende com correntes. Ele pode me bater, me xingar, fazer qualquer coisa comigo— a dor é minha prova de vida.\nVocê estaria disposto a ser meu cavaleiro?"
  },
  Voice_6440_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Cinco"
  },
  Voice_6440_UnlockDesc = {
    Text = "Nível de afinidade atingido 10 desbloqueado"
  },
  Voice_6441_AwakerVoiceContent = {
    Text = "O sangue flui como um rio. Eu sou seu—nunca me senti tão intensamente."
  },
  Voice_6441_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Quatro"
  },
  Voice_6441_UnlockDesc = {
    Text = "Nível de afinidade atingido 8 desbloqueado"
  },
  Voice_6442_AwakerVoiceContent = {
    Text = "Esta é a vontade das Três Deusas da Vingança!"
  },
  Voice_6442_AwakerVoiceTitle = {
    Text = "Fúria Explosiva"
  },
  Voice_6443_AwakerVoiceContent = {
    Text = "Lâminas Puxadas"
  },
  Voice_6443_AwakerVoiceTitle = {
    Text = "Exaltar · Dois"
  },
  Voice_6444_AwakerVoiceContent = {Text = "Não pode!"},
  Voice_6444_AwakerVoiceTitle = {
    Text = "Defesa · I"
  },
  Voice_6445_AwakerVoiceContent = {
    Text = "Tão sujo! Tão sujo!"
  },
  Voice_6445_AwakerVoiceTitle = {Text = "Defesa·II"},
  Voice_6446_AwakerVoiceContent = {
    Text = "...Aigis, eu vejo!"
  },
  Voice_6446_AwakerVoiceTitle = {
    Text = "Carta de Habilidade·Quatro"
  },
  Voice_6447_AwakerVoiceContent = {
    Text = "...Aigis, eu vejo!"
  },
  Voice_6447_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_6448_AwakerVoiceContent = {
    Text = "Dicas, claro, dicas. Olhe para aqueles garçons desatentos na cafeteria da escola! Eles nem preparam as espreguiçadeiras com antecedência, mas ainda esperam pagamento extra? Sonhe acordado!"
  },
  Voice_6448_AwakerVoiceTitle = {
    Text = "Conversa·Coisas odiadas"
  },
  Voice_6449_AwakerVoiceContent = {Text = "Preto."},
  Voice_6449_AwakerVoiceTitle = {
    Text = "Carta de Habilidade·Quatro"
  },
  Voice_6450_AwakerVoiceContent = {
    Text = "Deixe-me sair!"
  },
  Voice_6450_AwakerVoiceTitle = {
    Text = "Habilidade·I·Mania"
  },
  Voice_6451_AwakerVoiceContent = {
    Text = "Não faça isso..."
  },
  Voice_6451_AwakerVoiceTitle = {
    Text = "Habilidade·Um·Depressão"
  },
  Voice_6452_AwakerVoiceContent = {
    Text = "Não há necessidade de cortesia, Mensageiro Pálido. Não deve haver barreiras entre nós, pois somos todas Relíquias de Deus, caminhando juntas por este caminho lamacento e desafiador."
  },
  Voice_6452_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Um"
  },
  Voice_6452_UnlockDesc = {
    Text = "Nível de afinidade atingido 2 desbloqueado"
  },
  Voice_6453_AwakerVoiceContent = {
    Text = "Claro, eu não os temo, aquelas pobres almas atormentadas pela Maldição do Derretimento. Sinto apenas tristeza por elas. Sei que não posso suportar seu sofrimento, mas posso dar tudo o que tenho se isso lhes trouxer algum conforto."
  },
  Voice_6453_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Três"
  },
  Voice_6453_UnlockDesc = {
    Text = "Nível de afinidade atingido 6 desbloqueado"
  },
  Voice_6454_AwakerVoiceContent = {
    Text = "Você vai rezar comigo, A Fogo Pálido? Reze por aqueles que morreram em nossa batalha hoje. Embora amaldiçoados com dissolução e loucura, eles ainda são relíquias do deus da bondade, nossos irmãos e irmãs. Que eles encontrem a paz que merecem."
  },
  Voice_6454_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Dois"
  },
  Voice_6454_UnlockDesc = {
    Text = "Nível de afinidade atingido 4 desbloqueado"
  },
  Voice_6455_AwakerVoiceContent = {
    Text = "Mesmo que a chama vermelha me deixe inquieto, eu pisaria na plataforma em chamas por você mais uma vez. Não se preocupe com isso, minha chama pálida. Meu sacrifício é insignificante comparado às bênçãos que você traz."
  },
  Voice_6455_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Cinco"
  },
  Voice_6455_UnlockDesc = {
    Text = "Nível de afinidade atingido 10 desbloqueado"
  },
  Voice_6456_AwakerVoiceContent = {
    Text = "Arrependimento? Não, claro que não. Minha morte aliviou seu sofrimento e comprou mais tempo—isso é o suficiente. Mas... você tem sido honesto comigo, então não vou esconder: a pira naquele dia deixou cicatrizes no meu coração."
  },
  Voice_6456_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Quatro"
  },
  Voice_6456_UnlockDesc = {
    Text = "Nível de afinidade atingido 8 desbloqueado"
  },
  Voice_6457_AwakerVoiceContent = {
    Text = "Você pode fazer uma promessa comigo? Hmm... Vamos prometer que, não importa o que aconteça, você sempre se lembrará de \"Ramona\", tudo bem?"
  },
  Voice_6457_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Cinco"
  },
  Voice_6457_UnlockDesc = {
    Text = "Nível de afinidade atingido 10 desbloqueado"
  },
  Voice_6458_AwakerVoiceContent = {
    Text = "Não me arrependo da escolha de me tornar o que sou; se tivesse a chance novamente, ainda assim o faria. Mas, Guardião, estou muito assustado... com medo de que \"Ramona\" não deixe nenhuma marca neste mundo."
  },
  Voice_6458_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Quatro"
  },
  Voice_6458_UnlockDesc = {
    Text = "Nível de afinidade atingido 8 desbloqueado"
  },
  Voice_6459_AwakerVoiceContent = {
    Text = "Não se preocupe, a venda dos olhos não afeta minha visão. Se alguma coisa, me ajuda a evitar ver tudo."
  },
  Voice_6459_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Um"
  },
  Voice_6459_UnlockDesc = {
    Text = "Nível de afinidade atingido 2 desbloqueado"
  },
  Voice_6460_AwakerVoiceContent = {
    Text = "Minha expressão parece familiar? Estou tentando controlá-la... Parece que a presença dela está ficando mais forte."
  },
  Voice_6460_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Três"
  },
  Voice_6460_UnlockDesc = {
    Text = "Nível de afinidade atingido 6 desbloqueado"
  },
  Voice_6461_AwakerVoiceContent = {
    Text = "Mistérios demais para resolver, pessoas demais para salvar. Não sei quanto tempo mais consigo continuar, e não posso proteger a todos... Está realmente difícil."
  },
  Voice_6461_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Dois"
  },
  Voice_6461_UnlockDesc = {
    Text = "Nível de afinidade atingido 4 desbloqueado"
  },
  Voice_6462_AwakerVoiceContent = {
    Text = "Ainda quer apostar em mim? Parece que viver como se agrada não é tão fácil. Não se preocupe, eu vou relaxar enquanto resolvo seus problemas."
  },
  Voice_6462_AwakerVoiceTitle = {
    Text = "Iluminar·Construção"
  },
  Voice_6462_UnlockDesc = {
    Text = "Nível de iluminação atingiu 11 para desbloquear"
  },
  Voice_6463_AwakerVoiceContent = {
    Text = "Neste ponto, não temos escolha a não ser mostrar nossas verdadeiras habilidades, certo? Onde está a cena do crime? Mesmo que eu precise queimar toda a minha sorte, eu definitivamente trarei o suspeito de volta antes do prazo!"
  },
  Voice_6463_AwakerVoiceTitle = {
    Text = "Iluminar·Florescer"
  },
  Voice_6463_UnlockDesc = {
    Text = "Nível de iluminação atingiu 15 para desbloquear"
  },
  Voice_6464_AwakerVoiceContent = {
    Text = "Suspiro, já pedi tantos favores a você, não posso guardar mais este segredo: Na verdade, posso ser a pessoa mais azarada deste mundo"
  },
  Voice_6464_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexão"
  },
  Voice_6464_UnlockDesc = {
    Text = "Nível de iluminação atingiu 3 para desbloquear"
  },
  Voice_6465_AwakerVoiceContent = {
    Text = "Parece que você não levou minhas palavras a sério... Não tem problema, ainda assim vou te ajudar a derrotar inimigos. Afinal, essas garras e presas foram adquiridas por acaso, certo?"
  },
  Voice_6465_AwakerVoiceTitle = {
    Text = "Iluminar: Insight"
  },
  Voice_6465_UnlockDesc = {
    Text = "Nível de iluminação atingiu 7 para desbloquear"
  },
  Voice_6466_AwakerVoiceContent = {
    Text = "Minha sorte pode não se transferir para meus companheiros. Você deve ter ouvido o ditado, certo? \"Pé de coelho não traz sorte para o coelho.\""
  },
  Voice_6466_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_6466_UnlockDesc = {
    Text = "Nível de iluminação atingiu 2 para desbloquear"
  },
  Voice_6467_AwakerVoiceContent = {
    Text = "Você deseja imprimir a marca de Yu em sua alma?"
  },
  Voice_6467_AwakerVoiceTitle = {
    Text = "Atualizar·II"
  },
  Voice_6468_AwakerVoiceContent = {
    Text = "Você deseja tanto meu poder?"
  },
  Voice_6468_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · Três"
  },
  Voice_6469_AwakerVoiceContent = {
    Text = "Não se deixe enganar pela minha aparência; eu fui uma dama... Eu sabia bordar, lia Tennyson... Ah, e eu podia cantar: Ela flui como um rio sem fim pelas minhas veias~"
  },
  Voice_6469_AwakerVoiceTitle = {
    Text = "Conversa·Coisas favoritas"
  },
  Voice_6470_AwakerVoiceContent = {
    Text = "Pikman e eu estamos trabalhando em uma instalação de arte fascinante, explorando a reconstrução do representacionismo abstrato através da desconstrução do primitivismo visual... Huh, por que a Aurita desmaiou?"
  },
  Voice_6470_AwakerVoiceTitle = {
    Text = "Bate-papo · Sobre Aurita"
  },
  Voice_6470_UnlockDesc = {
    Text = "Desbloqueia ao obter o despertador \"Aurita\""
  },
  Voice_6471_AwakerVoiceContent = {
    Text = "Você quer que eu sorria?\nLily, estou sorrindo?"
  },
  Voice_6471_AwakerVoiceTitle = {
    Text = "Fala Ociosa · Sobre Sorrisos"
  },
  Voice_6472_AwakerVoiceContent = {
    Text = "Que surpresa, ganhei uma amizade igual.\nNo entanto... eu peço para reter o direito de comandá-lo, como uma diversão entre nós. Venha ao meu quarto esta noite; ainda tenho muito a aprender sobre emoções humanas..."
  },
  Voice_6472_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Cinco"
  },
  Voice_6472_UnlockDesc = {
    Text = "Nível de afinidade atingido 10 desbloqueado"
  },
  Voice_6473_AwakerVoiceContent = {
    Text = "Você sabe o que te torna o mais fofo? É quando você diz \"não\" para mim. Seu nariz se enruga, suas sobrancelhas levantam levemente... Sim, assim como agora."
  },
  Voice_6473_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Quatro"
  },
  Voice_6473_UnlockDesc = {
    Text = "Nível de afinidade atingido 8 desbloqueado"
  },
  Voice_6474_AwakerVoiceContent = {
    Text = "Eu amo meus minions. Esses garotinhos bonitos, tremendo de Dissolução e se escondendo atrás de mim, são tão adoráveis. As lágrimas de uma beleza são sempre cativantes. E você? Tem medo de Dissolução?"
  },
  Voice_6474_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Três"
  },
  Voice_6474_UnlockDesc = {
    Text = "Nível de afinidade atingido 6 desbloqueado"
  },
  Voice_6475_AwakerVoiceContent = {
    Text = "Guardião, você tem alguém que você não gosta? Como um favor, eu posso dar uma lição a eles. Dentro de uma semana, eles serão uma pessoa mudada, obedientemente lambendo seus dedos dos pés."
  },
  Voice_6475_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Dois"
  },
  Voice_6475_UnlockDesc = {
    Text = "Nível de afinidade atingido 4 desbloqueado"
  },
  Voice_6476_AwakerVoiceContent = {
    Text = "Hmm... Embora você seja sem graça, não é completamente desagradável. A partir de amanhã, você vai me servir.\nVocê não quer...? Isto não é um pedido; é uma ordem."
  },
  Voice_6476_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Um"
  },
  Voice_6476_UnlockDesc = {
    Text = "Nível de afinidade atingido 2 desbloqueado"
  },
  Voice_6477_AwakerVoiceContent = {
    Text = "Faz muito tempo que me sinto assim. Subirei ao palco em forma perfeita e entregarei uma onda de som que se estende pelo universo só para você."
  },
  Voice_6477_AwakerVoiceTitle = {
    Text = "Iluminar·Florescer"
  },
  Voice_6477_UnlockDesc = {
    Text = "Nível de iluminação atingiu 15 para desbloquear"
  },
  Voice_6478_AwakerVoiceContent = {
    Text = "Você precisa saber, isso é sem sentido."
  },
  Voice_6478_AwakerVoiceTitle = {
    Text = "Iluminar·Visão Remota"
  },
  Voice_6478_UnlockDesc = {
    Text = "Nível de iluminação atingiu 1 para desbloquear"
  },
  Voice_6479_AwakerVoiceContent = {
    Text = "Após colher a flor da vitória, gostaria de reivindicar uma pequena recompensa..."
  },
  Voice_6479_AwakerVoiceTitle = {
    Text = "Início da Investigação"
  },
  Voice_6480_AwakerVoiceContent = {Text = "Ah!"},
  Voice_6480_AwakerVoiceTitle = {
    Text = "Acertar·Depressão·III"
  },
  Voice_6481_AwakerVoiceContent = {
    Text = "A aeronave estava apertada e claustrofóbica, como um caixão de metal flutuando no espaço. Esperei pela minha Estrela da Manhã até que você aparecesse."
  },
  Voice_6481_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexão"
  },
  Voice_6481_UnlockDesc = {
    Text = "Nível de iluminação atingiu 3 para desbloquear"
  },
  Voice_6482_AwakerVoiceContent = {
    Text = "Como isso poderia ser?!"
  },
  Voice_6482_AwakerVoiceTitle = {
    Text = "Acertar·Frenesi·I"
  },
  Voice_6483_AwakerVoiceContent = {Text = "Ugh..."},
  Voice_6483_AwakerVoiceTitle = {
    Text = "Acertar·Depressão·I"
  },
  Voice_6484_AwakerVoiceContent = {Text = "Ai..."},
  Voice_6484_AwakerVoiceTitle = {
    Text = "Acertar·Depressão·II"
  },
  Voice_6485_AwakerVoiceContent = {
    Text = "Punição Divina!"
  },
  Voice_6485_AwakerVoiceTitle = {
    Text = "Habilidade·Um"
  },
  Voice_6486_AwakerVoiceContent = {
    Text = "Punição Divina!"
  },
  Voice_6486_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_6487_AwakerVoiceContent = {Text = "Chato."},
  Voice_6487_AwakerVoiceTitle = {Text = "Defesa·II"},
  Voice_6488_AwakerVoiceContent = {
    Text = "(Exclamação)"
  },
  Voice_6488_AwakerVoiceTitle = {
    Text = "Golpe·Quatro"
  },
  Voice_6489_AwakerVoiceContent = {
    Text = "Ainda segurando firme."
  },
  Voice_6489_AwakerVoiceTitle = {Text = "Acertar·1"},
  Voice_6490_AwakerVoiceContent = {
    Text = "(Exclamação)"
  },
  Voice_6490_AwakerVoiceTitle = {
    Text = "Acertar · II"
  },
  Voice_6491_AwakerVoiceContent = {
    Text = "(Exclamação)"
  },
  Voice_6491_AwakerVoiceTitle = {
    Text = "Acertar·III"
  },
  Voice_6492_AwakerVoiceContent = {
    Text = "Que os irreverentes sejam dissolvidos na tranquilidade abrasadora."
  },
  Voice_6492_AwakerVoiceTitle = {
    Text = "Investigação Bem-sucedida"
  },
  Voice_6493_AwakerVoiceContent = {
    Text = "Cuidado! Se você atingir um espaço dimensional diferente, pode não conseguir recuperar sua mão!"
  },
  Voice_6493_AwakerVoiceTitle = {
    Text = "Conversa·Toque"
  },
  Voice_6494_AwakerVoiceContent = {
    Text = "Um bando de perdedores. Se você não quiser acabar como carne moída, é melhor se cuidar da próxima vez."
  },
  Voice_6494_AwakerVoiceTitle = {
    Text = "Investigação Interrompida"
  },
  Voice_6495_AwakerVoiceContent = {
    Text = "Oh querido, você está sendo afetuoso comigo?\nIsto é problemático. Se isso continuar, não conseguirei esperar até que o Guardião amadureça completamente..."
  },
  Voice_6495_AwakerVoiceTitle = {
    Text = "Conversa·Toque"
  },
  Voice_6496_AwakerVoiceContent = {
    Text = "Mergulhe nas profundezas do livre-arbítrio!"
  },
  Voice_6496_AwakerVoiceTitle = {
    Text = "Despertar do Conhecimento Espiritual"
  },
  Voice_6497_AwakerVoiceContent = {
    Text = "Ódio... Definitivamente são aqueles que desistem pela metade. Só de pensar neles me faz querer vomitar o jantar de ontem à noite."
  },
  Voice_6497_AwakerVoiceTitle = {
    Text = "Conversa·Coisas odiadas"
  },
  Voice_6498_AwakerVoiceContent = {
    Text = "Eis sua imagem, ó crânio infinito!"
  },
  Voice_6498_AwakerVoiceTitle = {
    Text = "Fúria Explosiva"
  },
  Voice_6499_AwakerVoiceContent = {
    Text = "Eis sua imagem, ó crânio infinito!"
  },
  Voice_6499_AwakerVoiceTitle = {
    Text = "Exaltar · Dois"
  },
  Voice_6500_AwakerVoiceContent = {Text = "Hah!"},
  Voice_6500_AwakerVoiceTitle = {Text = "Ataque·Um"},
  Voice_6501_AwakerVoiceContent = {Text = "Hah!"},
  Voice_6501_AwakerVoiceTitle = {Text = "Ataque·Um"},
  Voice_6502_AwakerVoiceContent = {
    Text = "Você confia tanto em mim?"
  },
  Voice_6502_AwakerVoiceTitle = {
    Text = "Iluminar·Visão Remota"
  },
  Voice_6502_UnlockDesc = {
    Text = "Nível de iluminação atingiu 1 para desbloquear"
  },
  Voice_6503_AwakerVoiceContent = {Text = "Volte."},
  Voice_6503_AwakerVoiceTitle = {
    Text = "Defesa · I"
  },
  Voice_6504_AwakerVoiceContent = {Text = "Bom!"},
  Voice_6504_AwakerVoiceTitle = {Text = "Defesa·II"},
  Voice_6505_AwakerVoiceContent = {
    Text = "Claro que eu sei, esse é outro aspecto de mim. Mas por que ela resiste? Não é aceitar o destino do escolhido e obter o que se pede ao alcance?"
  },
  Voice_6505_AwakerVoiceTitle = {
    Text = "Conversa Ociosa: Sobre \"Murphy\""
  },
  Voice_6505_UnlockDesc = {
    Text = "Desbloqueado após obter Despertador \"Murphy\""
  },
  Voice_6506_AwakerVoiceContent = {
    Text = "Olá, meu nome é Daffodil. Eu fiz uma troca com um convidado que pediu que eu o assistisse. Então, deixe-me ouvir o que você precisa.\nOh querido... o que você deseja vem a um alto preço, não vem?"
  },
  Voice_6506_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_6507_AwakerVoiceContent = {
    Text = "*Silêncio* O que você está fazendo! Acredite ou não, eu vou te cortar a mão!"
  },
  Voice_6507_AwakerVoiceTitle = {
    Text = "Conversa·Toque"
  },
  Voice_6508_AwakerVoiceContent = {Text = "Hahaha!"},
  Voice_6508_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_6509_AwakerVoiceContent = {Text = "Hahaha!"},
  Voice_6509_AwakerVoiceTitle = {
    Text = "Habilidade·Um"
  },
  Voice_6510_AwakerVoiceContent = {
    Text = "Espinhos da rosa furam dedos, fluindo para a poesia."
  },
  Voice_6510_AwakerVoiceTitle = {
    Text = "Fúria Explosiva"
  },
  Voice_6511_AwakerVoiceContent = {
    Text = "Curvado sob esta profunda tinta de tristeza, torne-se uma canção de luto..."
  },
  Voice_6511_AwakerVoiceTitle = {
    Text = "Exaltar · Dois"
  },
  Voice_6512_AwakerVoiceContent = {
    Text = "Observe isto...!"
  },
  Voice_6512_AwakerVoiceTitle = {Text = "Ataque·Um"},
  Voice_6513_AwakerVoiceContent = {Text = "Hmm...!"},
  Voice_6513_AwakerVoiceTitle = {Text = "Ataque·Um"},
  Voice_6514_AwakerVoiceContent = {
    Text = "Chegada de Clades!"
  },
  Voice_6514_AwakerVoiceTitle = {
    Text = "Despertar do Conhecimento Espiritual"
  },
  Voice_6515_AwakerVoiceContent = {
    Text = "Dê para mim."
  },
  Voice_6515_AwakerVoiceTitle = {Text = "Ataque·II"},
  Voice_6516_AwakerVoiceContent = {
    Text = "...Meu nome, uh, não consigo me lembrar.\nAh, certo, \"24\", é assim que me chamam... Não! Não saia! Você não pode, não agora."
  },
  Voice_6516_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_6517_AwakerVoiceContent = {
    Text = "O fluxo das marcas de tinta..."
  },
  Voice_6517_AwakerVoiceTitle = {
    Text = "Carta de Habilidade·Quatro"
  },
  Voice_6518_AwakerVoiceContent = {
    Text = "Emergindo..."
  },
  Voice_6518_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_6519_AwakerVoiceContent = {
    Text = "Eu não mereço o título de \"Voz Celestial\"... Enquanto você goste do meu canto, isso é tudo que importa."
  },
  Voice_6519_AwakerVoiceTitle = {
    Text = "Chit-Chat: Sobre Cantar"
  },
  Voice_6520_AwakerVoiceContent = {
    Text = "Roupas sujas devem ser trocadas antes do próximo salão."
  },
  Voice_6520_AwakerVoiceTitle = {
    Text = "Investigação Bem-sucedida"
  },
  Voice_6521_AwakerVoiceContent = {
    Text = "Está me alcançando, a eterna escuridão... Ninguém pode escapar."
  },
  Voice_6521_AwakerVoiceTitle = {
    Text = "Investigação Interrompida"
  },
  Voice_6522_AwakerVoiceContent = {
    Text = "Toda vez que o vejo, penso nas correntes invisíveis que você colocou sobre mim. Permitir que você viva é meu maior ato de tolerância."
  },
  Voice_6522_AwakerVoiceTitle = {
    Text = "Conversa·Sobre Guardião do Segredo"
  },
  Voice_6523_AwakerVoiceContent = {
    Text = "Não importa quantas vezes começamos de novo, eu caminharei ao seu lado."
  },
  Voice_6523_AwakerVoiceTitle = {
    Text = "Investigação Interrompida"
  },
  Voice_6524_AwakerVoiceContent = {
    Text = "Que o amor de Deus aqueça sua alma."
  },
  Voice_6524_AwakerVoiceTitle = {
    Text = "Investigação Bem-sucedida"
  },
  Voice_6525_AwakerVoiceContent = {
    Text = "Eu gosto de vagar sem destino. Pântanos, cemitérios, infirmarias, castelos abandonados... Nesses lugares, sempre encontro prazeres inesperados."
  },
  Voice_6525_AwakerVoiceTitle = {
    Text = "Conversa·Coisas favoritas"
  },
  Voice_6526_AwakerVoiceContent = {
    Text = "Sinta-se honrado, pois os portões do Reino Eterno estão aqui."
  },
  Voice_6526_AwakerVoiceTitle = {
    Text = "Início da Investigação"
  },
  Voice_6527_AwakerVoiceContent = {
    Text = "Hehe—tão cosquento! Aurita quer retribuir!"
  },
  Voice_6527_AwakerVoiceTitle = {
    Text = "Conversa·Toque"
  },
  Voice_6528_AwakerVoiceContent = {
    Text = "\"A Morte do Cisne,\" uma performance na qual o dançarino usa a linguagem corporal para transmitir o anseio e a luta da vida. Não é a mesma figura torcida nas chamas?"
  },
  Voice_6528_AwakerVoiceTitle = {
    Text = "Conversa·Coisas favoritas"
  },
  Voice_6529_AwakerVoiceContent = {
    Text = "Fatiar, fatiar, despedaçar. Assim como fizeram comigo no passado... hehe... hehehe!!"
  },
  Voice_6529_AwakerVoiceTitle = {
    Text = "Investigação Bem-sucedida"
  },
  Voice_6530_AwakerVoiceContent = {
    Text = "É melhor você não chegar muito perto da Miss Thais... Não, eu não estou com ciúmes. Estou apenas com medo de que alguém possa cair nas truques de uma mulher."
  },
  Voice_6530_AwakerVoiceTitle = {
    Text = "Conversa: Sobre Táias"
  },
  Voice_6530_UnlockDesc = {
    Text = "Após obter o despertador \"Táias\", desbloqueado"
  },
  Voice_6531_AwakerVoiceContent = {
    Text = "...Muito obrigado."
  },
  Voice_6531_AwakerVoiceTitle = {
    Text = "Iluminar·Visão Remota"
  },
  Voice_6531_UnlockDesc = {
    Text = "Nível de iluminação atingiu 1 para desbloquear"
  },
  Voice_6532_AwakerVoiceContent = {
    Text = "Muito bem... você tem um olho afiado para reconhecer pessoas."
  },
  Voice_6532_AwakerVoiceTitle = {
    Text = "Iluminar·Visão Remota"
  },
  Voice_6532_UnlockDesc = {
    Text = "Nível de iluminação atingiu 1 para desbloquear"
  },
  Voice_6533_AwakerVoiceContent = {
    Text = "A cidade natal de Karen é linda! É uma cidade de pedra em um lago.\nA cada lua cheia, dançamos silenciosamente nas chamas, adorando...\nHonestamente, quando Karen veio para a universidade pela primeira vez, ela sentia falta de casa todas as noites e chorava na cama. Mas agora, Karen tem um novo lar e uma família. Tudo está melhor!"
  },
  Voice_6533_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Cinco"
  },
  Voice_6533_UnlockDesc = {
    Text = "Nível de afinidade atingido 10 desbloqueado"
  },
  Voice_6534_AwakerVoiceContent = {
    Text = "Oh~ Ainda não está satisfeito? Venha, deixa eu te treinar rapidamente~"
  },
  Voice_6534_AwakerVoiceTitle = {
    Text = "Conversa·Toque"
  },
  Voice_6535_AwakerVoiceContent = {
    Text = "Músculos fracos, rosto haggard—apenas aqueles olhos mortos têm algum valor. Perfeito para alimentar aranhas."
  },
  Voice_6535_AwakerVoiceTitle = {
    Text = "Conversa·Sobre Guardião do Segredo"
  },
  Voice_6536_AwakerVoiceContent = {
    Text = "Obrigado... por tudo que você fez por Aigis. Aigis fará o seu melhor... para não decepcioná-lo!"
  },
  Voice_6536_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · I"
  },
  Voice_6537_AwakerVoiceContent = {
    Text = "(Grito de medo)"
  },
  Voice_6537_AwakerVoiceTitle = {
    Text = "Golpe·Quatro"
  },
  Voice_6538_AwakerVoiceContent = {Text = "Não!"},
  Voice_6538_AwakerVoiceTitle = {Text = "Acertar·1"},
  Voice_6539_AwakerVoiceContent = {
    Text = "P poupe-me..."
  },
  Voice_6539_AwakerVoiceTitle = {
    Text = "Acertar · II"
  },
  Voice_6540_AwakerVoiceContent = {
    Text = "(Grito de medo)"
  },
  Voice_6540_AwakerVoiceTitle = {
    Text = "Acertar·III"
  },
  Voice_6541_AwakerVoiceContent = {
    Text = "A esgrima da Senhorita Ramona é bastante diferente das técnicas que eu dominei. Se meu senhor permitir, gostaria de cruzar espadas com ela... Claro! É apenas para autoaperfeiçoamento!"
  },
  Voice_6541_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Dois"
  },
  Voice_6541_UnlockDesc = {
    Text = "Nível de afinidade atingido 4 desbloqueado"
  },
  Voice_6542_AwakerVoiceContent = {
    Text = "Você pergunta por que eu não brinco com as outras crianças? É difícil admitir... Na minha vida anterior, tive poucas oportunidades de brincar. Meu único companheiro foi a princesa a quem servi... Ah! Ao mencionar outro monarca na frente do meu senhor, por favor, perdoe meu deslize."
  },
  Voice_6542_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Três"
  },
  Voice_6542_UnlockDesc = {
    Text = "Nível de afinidade atingido 6 desbloqueado"
  },
  Voice_6543_AwakerVoiceContent = {
    Text = "Você é reconhecido pela Universidade Mythag como um Guardião, então vou te conceder as permissões de acesso correspondentes."
  },
  Voice_6543_AwakerVoiceTitle = {
    Text = "Conversa Ociosa · Sobre \"Protagonista\""
  },
  Voice_6544_AwakerVoiceContent = {
    Text = "Você está interessado nas \"Sete Habilidades Cavaleirescas\" que aprendi? Isso é maravilhoso! Ah... hum... por favor, perdoe minha rudeza anterior. O que eu queria dizer é que, se você gostaria de praticar arco e flecha montado, eu teria a honra de ser seu parceiro de treino!"
  },
  Voice_6544_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Quatro"
  },
  Voice_6544_UnlockDesc = {
    Text = "Nível de afinidade atingido 8 desbloqueado"
  },
  Voice_6545_AwakerVoiceContent = {
    Text = "Não sou um cavaleiro digno. Seja pela vil praga ou pelos inimigos invasores, falhei em proteger meu antigo senhor. Agora, a confiança que você deposita em alguém como eu é uma imensa honra... Juro sobre minha honra cavalheiresca e esta vida insignificante que sempre guardarei seu caminho à frente."
  },
  Voice_6545_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Cinco"
  },
  Voice_6545_UnlockDesc = {
    Text = "Nível de afinidade atingido 10 desbloqueado"
  },
  Voice_6546_AwakerVoiceContent = {
    Text = "Não faça mal."
  },
  Voice_6546_AwakerVoiceTitle = {
    Text = "Defesa · I"
  },
  Voice_6547_AwakerVoiceContent = {Text = "Vamos~"},
  Voice_6547_AwakerVoiceTitle = {
    Text = "Acertar·III"
  },
  Voice_6548_AwakerVoiceContent = {Text = "Toque!"},
  Voice_6548_AwakerVoiceTitle = {
    Text = "Carta de Habilidade·Quatro"
  },
  Voice_6549_AwakerVoiceContent = {Text = "Não mate."},
  Voice_6549_AwakerVoiceTitle = {Text = "Defesa·II"},
  Voice_6550_AwakerVoiceContent = {
    Text = "Então confortável~!"
  },
  Voice_6550_AwakerVoiceTitle = {
    Text = "Golpe·Quatro"
  },
  Voice_6551_AwakerVoiceContent = {
    Text = "Agora, somos como água e óleo que não se misturam."
  },
  Voice_6551_AwakerVoiceTitle = {
    Text = "Conversa·Sobre Guardião do Segredo"
  },
  Voice_6552_AwakerVoiceContent = {
    Text = "Eu não tenho favoritos em particular. Se eu tivesse que dizer, a sensação de sair em missões é bem agradável."
  },
  Voice_6552_AwakerVoiceTitle = {
    Text = "Conversa·Coisas favoritas"
  },
  Voice_6553_AwakerVoiceContent = {
    Text = "Por que, por que me trancar aqui? Haha... Eu não vou deixar você ter sucesso. Vou despedaçar essas amarras, esta prisão... em fragmentos!"
  },
  Voice_6553_AwakerVoiceTitle = {
    Text = "Chat·Sobre a Universidade Mythag"
  },
  Voice_6554_AwakerVoiceContent = {
    Text = "Proteja todos."
  },
  Voice_6554_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_6555_AwakerVoiceContent = {
    Text = "Vocês, não se cansam de assistir ao show de mágica? Fiquem parados, tá bom? Se vocês correrem para o palco novamente, eu vou jogá-los em outra dimensão!"
  },
  Voice_6555_AwakerVoiceTitle = {
    Text = "Conversa Ociosa: Sobre as Crianças"
  },
  Voice_6555_UnlockDesc = {
    Text = "Desbloqueado após adquirir qualquer um dos Despertar \"Aigis,\" \"Jenkin,\" \"Lily,\" \"Murphy,\" \"Karen,\" ou \"Aurita\""
  },
  Voice_6556_AwakerVoiceContent = {
    Text = "Aceito grato seu presente."
  },
  Voice_6556_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · I"
  },
  Voice_6557_AwakerVoiceContent = {
    Text = "Que tipo de presente de retorno poderia corresponder à sua dedicação?"
  },
  Voice_6557_AwakerVoiceTitle = {
    Text = "Atualizar·II"
  },
  Voice_6558_AwakerVoiceContent = {
    Text = "Que esplendor..."
  },
  Voice_6558_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · Três"
  },
  Voice_6559_AwakerVoiceContent = {
    Text = "Detectada alta corrente, iniciando manutenção... Correção, por que não há superaquecimento?"
  },
  Voice_6559_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_6559_UnlockDesc = {
    Text = "Nível de iluminação atingiu 2 para desbloquear"
  },
  Voice_6560_AwakerVoiceContent = {
    Text = "Desde o último ritual de Iluminar, tenho visto visões fragmentadas enquanto estou em Estado de dormência. Nelas, eu possuo um corpo Caro como o seu, e lágrimas caem dos meus olhos. É um sonho?"
  },
  Voice_6560_AwakerVoiceTitle = {
    Text = "Iluminar: Insight"
  },
  Voice_6560_UnlockDesc = {
    Text = "Nível de iluminação atingiu 7 para desbloquear"
  },
  Voice_6561_AwakerVoiceContent = {
    Text = "Após cada ritual, um alto nível de calor é detectado na área do peito, mas não há componentes relacionados à energia presentes. Você sabe por quê?"
  },
  Voice_6561_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexão"
  },
  Voice_6561_UnlockDesc = {
    Text = "Nível de iluminação atingiu 3 para desbloquear"
  },
  Voice_6562_AwakerVoiceContent = {
    Text = "Eu vi. Tudo deveria <Del:perecer na corrente eterna>. Desculpe, desculpe, o módulo parece—Aviso, aviso. Atividade de consciência não-Erica aumentando. Destruir, destruir, des... Olá, como posso ajudá-lo?"
  },
  Voice_6562_AwakerVoiceTitle = {
    Text = "Iluminar·Florescer"
  },
  Voice_6562_UnlockDesc = {
    Text = "Nível de iluminação atingiu 15 para desbloquear"
  },
  Voice_6563_AwakerVoiceContent = {
    Text = "Após análise cuidadosa, deduzi que o que vi em meu estado dormente não era um sonho no sentido tradicional, mas sim minha <Del:pobre Corpo Caro que deveria ser destruído> Memória. Quanto ao calor ardente semelhante a sobrecarga, pode ser a emoção conhecida como \"Descontentamento\"."
  },
  Voice_6563_AwakerVoiceTitle = {
    Text = "Iluminar·Construção"
  },
  Voice_6563_UnlockDesc = {
    Text = "Nível de iluminação atingiu 11 para desbloquear"
  },
  Voice_6564_AwakerVoiceContent = {
    Text = "Se você quer assistir à apresentação, sente-se corretamente na plateia!"
  },
  Voice_6564_AwakerVoiceTitle = {
    Text = "Iluminar·Visão Remota"
  },
  Voice_6564_UnlockDesc = {
    Text = "Nível de iluminação atingiu 1 para desbloquear"
  },
  Voice_6565_AwakerVoiceContent = {
    Text = "As chamas do ódio ardem ferozmente, nunca se extinguindo."
  },
  Voice_6565_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · I"
  },
  Voice_6567_AwakerVoiceContent = {
    Text = "A vontade com a qual me mesclei é barulhenta; quanto mais subo, mais clara a voz \"Dele\" se torna... como os gansos no Hyde Park, bastante barulhenta."
  },
  Voice_6567_AwakerVoiceTitle = {
    Text = "Iluminar·Construção"
  },
  Voice_6567_UnlockDesc = {
    Text = "Nível de iluminação atingiu 11 para desbloquear"
  },
  Voice_6568_AwakerVoiceContent = {
    Text = "Eu irei usar este poder para devorar o traidor."
  },
  Voice_6568_AwakerVoiceTitle = {
    Text = "Atualizar·II"
  },
  Voice_6569_AwakerVoiceContent = {
    Text = "...Muito obrigado."
  },
  Voice_6569_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · Três"
  },
  Voice_6570_AwakerVoiceContent = {
    Text = "Guardião? Ridículo. É hora de acordar deste sonho irrealista."
  },
  Voice_6570_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_6571_AwakerVoiceContent = {
    Text = "O sangue da vingança está fervendo..."
  },
  Voice_6571_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · I"
  },
  Voice_6572_AwakerVoiceContent = {
    Text = "Movam-se, lacaios!"
  },
  Voice_6572_AwakerVoiceTitle = {
    Text = "Despertar do Conhecimento Espiritual"
  },
  Voice_6573_AwakerVoiceContent = {
    Text = "Não se afogue!"
  },
  Voice_6573_AwakerVoiceTitle = {
    Text = "Defesa · I"
  },
  Voice_6574_AwakerVoiceContent = {Text = "Whoosh!"},
  Voice_6574_AwakerVoiceTitle = {
    Text = "Defesa · I"
  },
  Voice_6575_AwakerVoiceContent = {
    Text = "Eu joguei fora as armadilhas para ratos na porta dos fundos da cantina. Elas são muito perigosas. E se aquele desastrado do Brown pisar nelas!"
  },
  Voice_6575_AwakerVoiceTitle = {
    Text = "Chat·Sobre a Universidade Mythag"
  },
  Voice_6576_AwakerVoiceContent = {
    Text = "Isso se sente tão estranho... Estou morrendo? Não, me salve! Não!!!"
  },
  Voice_6576_AwakerVoiceTitle = {
    Text = "Iluminar·Visão Remota"
  },
  Voice_6576_UnlockDesc = {
    Text = "Nível de iluminação atingiu 1 para desbloquear"
  },
  Voice_6579_AwakerVoiceContent = {
    Text = "Eu quero uma lâmpada que nunca se apague. Ela realmente disse para trocá-la por um espécime de uma \"hidra voadora sem asas\". Onde posso encontrar uma espécie tão bizarra?"
  },
  Voice_6579_AwakerVoiceTitle = {
    Text = "Conversa Casual · Sobre Narciso"
  },
  Voice_6579_UnlockDesc = {
    Text = "Desbloqueado após adquirir o Despertar \"Narciso\""
  },
  Voice_6582_AwakerVoiceContent = {Text = "Perigo."},
  Voice_6582_AwakerVoiceTitle = {
    Text = "Acertar·III"
  },
  Voice_6583_AwakerVoiceContent = {Text = "Atenção."},
  Voice_6583_AwakerVoiceTitle = {
    Text = "Acertar · II"
  },
  Voice_6584_AwakerVoiceContent = {Text = "Golpe."},
  Voice_6584_AwakerVoiceTitle = {Text = "Acertar·1"},
  Voice_6585_AwakerVoiceContent = {
    Text = "Um tesouro que brilha como embrulhos de doces... Aigis o valorizará muito."
  },
  Voice_6585_AwakerVoiceTitle = {
    Text = "Atualizar·II"
  },
  Voice_6586_AwakerVoiceContent = {
    Text = "Dano recebido."
  },
  Voice_6586_AwakerVoiceTitle = {
    Text = "Golpe·Quatro"
  },
  Voice_6587_AwakerVoiceContent = {
    Text = "Minha loja existe em qualquer dimensão, qualquer localização no universo, e claro, pode estar aqui. Além disso, eu gosto daquelas crianças descuidadas em Mythag."
  },
  Voice_6587_AwakerVoiceTitle = {
    Text = "Chat·Sobre a Universidade Mythag"
  },
  Voice_6588_AwakerVoiceContent = {
    Text = "Ódio... Pimentões verdes têm um gosto terrível."
  },
  Voice_6588_AwakerVoiceTitle = {
    Text = "Conversa·Coisas odiadas"
  },
  Voice_6589_AwakerVoiceContent = {
    Text = "Nosso relacionamento é como o entre uma vela e um barco. Sem o barco, a vela não deveria existir; sem a vela, o barco não pode viajar longe. Não é verdade?"
  },
  Voice_6589_AwakerVoiceTitle = {
    Text = "Conversa·Sobre Guardião do Segredo"
  },
  Voice_6590_AwakerVoiceContent = {
    Text = "A dançarina devota está morta, e o blasfemo da arte também está morto, ambos pereceram em chamas cheias de cheiro de piche. A morte não é o fim, mas o começo, pois apenas os humanos morrem; a dança e a arte são eternas."
  },
  Voice_6590_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Quatro"
  },
  Voice_6590_UnlockDesc = {
    Text = "Nível de afinidade atingido 8 desbloqueado"
  },
  Voice_6591_AwakerVoiceContent = {
    Text = "Obrigado pela sua compreensão. Talvez agora seja o momento de me reconciliar com meu eu passado... Acredito que estou fazendo a coisa certa e não desonrei o legado da minha família na dança. Eu pisarei no palco que você preparou e brilharei como você deseja."
  },
  Voice_6591_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Cinco"
  },
  Voice_6591_UnlockDesc = {
    Text = "Nível de afinidade atingido 10 desbloqueado"
  },
  Voice_6592_AwakerVoiceContent = {Text = "Cuidado."},
  Voice_6592_AwakerVoiceTitle = {
    Text = "Defesa · I"
  },
  Voice_6593_AwakerVoiceContent = {
    Text = "Você quer que eu suba ao palco e brilhe?\nIsso agora é impossível. Estes olhos foram consumidos pelo ódio. Tudo que posso fazer é queimar tudo até as cinzas."
  },
  Voice_6593_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Um"
  },
  Voice_6593_UnlockDesc = {
    Text = "Nível de afinidade atingido 2 desbloqueado"
  },
  Voice_6594_AwakerVoiceContent = {
    Text = "Você entende essa sensação? Girando, girando, girando, nunca parando. Joelhos esticados ao limite, dedos dos pés sangrando, ensopando os sapatos de balé, mas nunca pausando. Tudo porque me recuso a aceitar o destino de ser um brinquedo..."
  },
  Voice_6594_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Dois"
  },
  Voice_6594_UnlockDesc = {
    Text = "Nível de afinidade atingido 4 desbloqueado"
  },
  Voice_6595_AwakerVoiceContent = {
    Text = "Eu não queimei dançarinos de corte habilidosos, graciosos mestres de balé ou nobres que apreciam a sublimidade e a beleza. Eu queimei tolos inúteis vendendo seus corpos, bajuladores desconsiderando os outros e seres imundos perdidos na luxúria... Você me entende, certo?"
  },
  Voice_6595_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Três"
  },
  Voice_6595_UnlockDesc = {
    Text = "Nível de afinidade atingido 6 desbloqueado"
  },
  Voice_6596_AwakerVoiceContent = {
    Text = "Não gosto dessas pessoas com tentáculos viscosos, e não gosto do oceano... Não me olhe assim! Eu não sou uma criança que tem medo dos pais!"
  },
  Voice_6596_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Três"
  },
  Voice_6596_UnlockDesc = {
    Text = "Nível de afinidade atingido 6 desbloqueado"
  },
  Voice_6597_AwakerVoiceContent = {
    Text = "Sua generosidade é muito apreciada..."
  },
  Voice_6597_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · Três"
  },
  Voice_6598_AwakerVoiceContent = {
    Text = "Desaparecer!"
  },
  Voice_6598_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_6599_AwakerVoiceContent = {
    Text = "Desaparecer!"
  },
  Voice_6599_AwakerVoiceTitle = {
    Text = "Habilidade·Um"
  },
  Voice_6600_AwakerVoiceContent = {
    Text = "Acelera, leve Brown e vá!"
  },
  Voice_6600_AwakerVoiceTitle = {
    Text = "Investigação Interrompida"
  },
  Voice_6601_AwakerVoiceContent = {Text = "Não..."},
  Voice_6601_AwakerVoiceTitle = {
    Text = "Defesa·Depressão"
  },
  Voice_6602_AwakerVoiceContent = {Text = "Fuja!"},
  Voice_6602_AwakerVoiceTitle = {
    Text = "Defesa·Mania"
  },
  Voice_6603_AwakerVoiceContent = {
    Text = "Quem é Leigh? Oh, a mulher que me implorou para bater nela. Haha, interessante... Este lugar não é tão chato afinal."
  },
  Voice_6603_AwakerVoiceTitle = {
    Text = "Chat·Sobre Leigh"
  },
  Voice_6603_UnlockDesc = {
    Text = "Após obter o despertador \"Leigh\", desbloqueado"
  },
  Voice_6604_AwakerVoiceContent = {
    Text = "O pôr do sol na pequena colina me lembra muitas vezes dos meus dias em Cleveland... Cleveland, não consigo acreditar que ainda me lembro desse nome, o lugar que me deu essas cicatrizes."
  },
  Voice_6604_AwakerVoiceTitle = {
    Text = "Conversa Ociosa: Sobre o Crepúsculo"
  },
  Voice_6605_AwakerVoiceContent = {
    Text = "Ah... as estrelas... caíram..."
  },
  Voice_6605_AwakerVoiceTitle = {
    Text = "Investigação Interrompida"
  },
  Voice_6606_AwakerVoiceContent = {
    Text = "Sem dúvida, humanos. Há criaturas mais imundas que os humanos?"
  },
  Voice_6606_AwakerVoiceTitle = {
    Text = "Conversa·Coisas odiadas"
  },
  Voice_6607_AwakerVoiceContent = {Text = "É agora!"},
  Voice_6607_AwakerVoiceTitle = {Text = "Ataque·Um"},
  Voice_6608_AwakerVoiceContent = {Text = "Oi!"},
  Voice_6608_AwakerVoiceTitle = {Text = "Ataque·II"},
  Voice_6609_AwakerVoiceContent = {
    Text = "Dissolução? Hmm... Sim! O sorvete derrete! Mas se compartilharmos, podemos comê-lo antes que ele se transforme completamente em creme!"
  },
  Voice_6609_AwakerVoiceTitle = {
    Text = "Bate-papo · Sobre Dissolução"
  },
  Voice_6610_AwakerVoiceContent = {
    Text = "Eu irei usar essa força para te proteger."
  },
  Voice_6610_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexão"
  },
  Voice_6610_UnlockDesc = {
    Text = "Nível de iluminação atingiu 3 para desbloquear"
  },
  Voice_6611_AwakerVoiceContent = {
    Text = "Oh querido, não há trocas em itens vendidos aqui! Você realmente precisa de um submarino para mergulhar no Aequor, certo?"
  },
  Voice_6611_AwakerVoiceTitle = {
    Text = "Bate-papo · Sobre Caecus"
  },
  Voice_6611_UnlockDesc = {
    Text = "Desbloqueia ao obter o despertador \"Caecus\""
  },
  Voice_6612_AwakerVoiceContent = {
    Text = "O melhor palco! Tanto os professores quanto os alunos da Universidade Mythag podem entender que minha apresentação é verdadeira magia! Isso deve ser o que chamam de espírito afim de mágico, certo?"
  },
  Voice_6612_AwakerVoiceTitle = {
    Text = "Chat·Sobre a Universidade Mythag"
  },
  Voice_6613_AwakerVoiceContent = {
    Text = "A ordem do universo se altera aqui; o futuro da destruição é a crença do mágico!"
  },
  Voice_6613_AwakerVoiceTitle = {
    Text = "Iluminar·Construção"
  },
  Voice_6613_UnlockDesc = {
    Text = "Nível de iluminação atingiu 11 para desbloquear"
  },
  Voice_6614_AwakerVoiceContent = {
    Text = "A Aigis pode ficar aqui um pouco mais? Eu permanecerei quieta, não farei barulho e farei o meu melhor para não perturbar você..."
  },
  Voice_6614_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Dois"
  },
  Voice_6614_UnlockDesc = {
    Text = "Nível de afinidade atingido 4 desbloqueado"
  },
  Voice_6615_AwakerVoiceContent = {
    Text = "Revele a essência do mundo com a inteligência humana...!"
  },
  Voice_6615_AwakerVoiceTitle = {
    Text = "Fúria Explosiva"
  },
  Voice_6616_AwakerVoiceContent = {
    Text = "Em meus sonhos, frequentemente ouço o som da maré, diminuindo cada vez mais. Sei que posso ficar aqui para sempre, Humano."
  },
  Voice_6616_AwakerVoiceTitle = {
    Text = "Bate-papo · Sobre Aequor"
  },
  Voice_6617_AwakerVoiceContent = {
    Text = "Mais memórias, mais emoções, mais sonhos—"
  },
  Voice_6617_AwakerVoiceTitle = {
    Text = "Iluminar: Insight"
  },
  Voice_6617_UnlockDesc = {
    Text = "Nível de iluminação atingiu 7 para desbloquear"
  },
  Voice_6618_AwakerVoiceContent = {
    Text = "Está começando a mudar!"
  },
  Voice_6618_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_6619_AwakerVoiceContent = {
    Text = "Não pisque!"
  },
  Voice_6619_AwakerVoiceTitle = {
    Text = "Habilidade·Um"
  },
  Voice_6620_AwakerVoiceContent = {
    Text = "Quando Ele nasce... eu não terei que suportar essa humilhação mais."
  },
  Voice_6620_AwakerVoiceTitle = {
    Text = "Investigação Interrompida"
  },
  Voice_6621_AwakerVoiceContent = {
    Text = "Escolhe-me, escolhe-me! Onde há festa, há Karen!"
  },
  Voice_6621_AwakerVoiceTitle = {
    Text = "Início da Investigação"
  },
  Voice_6622_AwakerVoiceContent = {
    Text = "Hmm? Está interessado em mim? Suponho... que você está pronto para pagar o preço?"
  },
  Voice_6622_AwakerVoiceTitle = {
    Text = "Conversa·Toque"
  },
  Voice_6623_AwakerVoiceContent = {
    Text = "Sem misericórdia, sem misericórdia...!"
  },
  Voice_6623_AwakerVoiceTitle = {
    Text = "Investigação Interrompida"
  },
  Voice_6624_AwakerVoiceContent = {
    Text = "Ainda cantando as cores das estrelas."
  },
  Voice_6624_AwakerVoiceTitle = {
    Text = "Fúria Explosiva"
  },
  Voice_6625_AwakerVoiceContent = {
    Text = "Cântico, cântico!"
  },
  Voice_6625_AwakerVoiceTitle = {
    Text = "Superexaltação"
  },
  Voice_6626_AwakerVoiceContent = {
    Text = "Amor, Mãe!"
  },
  Voice_6626_AwakerVoiceTitle = {
    Text = "Conversa·Coisas favoritas"
  },
  Voice_6627_AwakerVoiceContent = {Text = "Vamos."},
  Voice_6627_AwakerVoiceTitle = {
    Text = "Defesa · I"
  },
  Voice_6628_AwakerVoiceContent = {Text = "Cuidado."},
  Voice_6628_AwakerVoiceTitle = {Text = "Defesa·II"},
  Voice_6629_AwakerVoiceContent = {
    Text = "Os Despertadores podem comer por curiosidade, mas a comida não é essencial para a nossa existência. Portanto, não há necessidade de me chamar para cada chá da tarde. A ingestão de açúcar apenas acelera o desgaste das articulações deste corpo."
  },
  Voice_6629_AwakerVoiceTitle = {
    Text = "Conversa: No Chá da Tarde"
  },
  Voice_6632_AwakerVoiceContent = {
    Text = "Por favor, poupe meu mestre. Karen... faça o que quiser com a Karen!"
  },
  Voice_6632_AwakerVoiceTitle = {
    Text = "Investigação Interrompida"
  },
  Voice_6633_AwakerVoiceContent = {
    Text = "Todos esses são comestíveis para Lily?"
  },
  Voice_6633_AwakerVoiceTitle = {
    Text = "Iluminar·Visão Remota"
  },
  Voice_6633_UnlockDesc = {
    Text = "Nível de iluminação atingiu 1 para desbloquear"
  },
  Voice_6634_AwakerVoiceContent = {
    Text = "Irritante? Posso dizer isso? Aigis odeia sempre se sentir impotente... Mas se eu disser isso, Jenkin vai ficar realmente bravo..."
  },
  Voice_6634_AwakerVoiceTitle = {
    Text = "Conversa·Coisas odiadas"
  },
  Voice_6635_AwakerVoiceContent = {
    Text = "Transformar em cinzas."
  },
  Voice_6635_AwakerVoiceTitle = {
    Text = "Carta de Habilidade·Quatro"
  },
  Voice_6636_AwakerVoiceContent = {
    Text = "Transformar em cinzas."
  },
  Voice_6636_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_6637_AwakerVoiceContent = {
    Text = "Muito bem, Guardião. Então, quem você quer que eu mate desta vez?"
  },
  Voice_6637_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexão"
  },
  Voice_6637_UnlockDesc = {
    Text = "Nível de iluminação atingiu 3 para desbloquear"
  },
  Voice_6638_AwakerVoiceContent = {
    Text = "A Dissolução é a razão pela qual esta academia foi fundada e por que nos encontramos. Para salvar a centelha da humanidade da Dissolução, vamos dar o nosso melhor, parceiro."
  },
  Voice_6638_AwakerVoiceTitle = {
    Text = "Bate-papo · Sobre Dissolução"
  },
  Voice_6639_AwakerVoiceContent = {
    Text = "Eu consigo sentir a hostilidade da lady; deve ser meu amor por você que despertou sua inveja... Veja, até a boca daquela baleia de grandes asas está aberta em inveja."
  },
  Voice_6639_AwakerVoiceTitle = {
    Text = "Chat·Sobre Lotan"
  },
  Voice_6639_UnlockDesc = {
    Text = "Após obter o despertador \"Lotan\", desbloqueado"
  },
  Voice_6640_AwakerVoiceContent = {
    Text = "Mestre, Mestre! Karen viu uma incrível broche em relevo hoje na casa de Harold! Você poderia comprá-lo para Karen? É meu pedido de vida inteira!"
  },
  Voice_6640_AwakerVoiceTitle = {
    Text = "Conversa·Coisas favoritas"
  },
  Voice_6641_AwakerVoiceContent = {
    Text = "Eu irei ser sua luz guia na escuridão, mas este período não é eterno."
  },
  Voice_6641_AwakerVoiceTitle = {
    Text = "Conversa·Sobre Guardião do Segredo"
  },
  Voice_6642_AwakerVoiceContent = {
    Text = "Mãe, dói... Mãe..."
  },
  Voice_6642_AwakerVoiceTitle = {
    Text = "Investigação Interrompida"
  },
  Voice_6643_AwakerVoiceContent = {
    Text = "Desista! A vitória é praticamente minha!"
  },
  Voice_6643_AwakerVoiceTitle = {
    Text = "Exaltar · Dois"
  },
  Voice_6644_AwakerVoiceContent = {
    Text = "Desista! A vitória é praticamente minha!"
  },
  Voice_6644_AwakerVoiceTitle = {
    Text = "Fúria Explosiva"
  },
  Voice_6645_AwakerVoiceContent = {
    Text = "Dissolução... Minha capacidade cerebral é limitada; não consigo compreender doenças tão complexas... Se você precisar de alguma máquina reparada, venha me encontrar!"
  },
  Voice_6645_AwakerVoiceTitle = {
    Text = "Bate-papo · Sobre Dissolução"
  },
  Voice_6646_AwakerVoiceContent = {
    Text = "Oh não! Aurita foi encontrada! Como penalidade por perder, você pode fazer um pedido para Aurita—só por favor, não a faça ir para a aula, por favor!"
  },
  Voice_6646_AwakerVoiceTitle = {
    Text = "Chat·Sobre a Universidade Mythag"
  },
  Voice_6647_AwakerVoiceContent = {
    Text = "Limpando o caminho para Seu retorno..."
  },
  Voice_6647_AwakerVoiceTitle = {
    Text = "Início da Investigação"
  },
  Voice_6648_AwakerVoiceContent = {
    Text = "Um dia, o Tio Ornn me receberá de volta ao meu lar subaquático. Até lá, posso relutantemente ser amigo de você."
  },
  Voice_6648_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Quatro"
  },
  Voice_6648_UnlockDesc = {
    Text = "Nível de afinidade atingido 8 desbloqueado"
  },
  Voice_6649_AwakerVoiceContent = {
    Text = "\"Nossa família carrega um grande sangue; o escolhido desfrutará de paz eterna na Lemúria.\"\nNunca esperei sentir essa paz após deixar o mar e vir para a academia. Você é diferente daqueles que me intimidam, então não deixarei que outros intimidem você também."
  },
  Voice_6649_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Cinco"
  },
  Voice_6649_UnlockDesc = {
    Text = "Nível de afinidade atingido 10 desbloqueado"
  },
  Voice_6650_AwakerVoiceContent = {
    Text = "Material sob medida super resistente!"
  },
  Voice_6650_AwakerVoiceTitle = {
    Text = "Despertar do Conhecimento Espiritual"
  },
  Voice_6651_AwakerVoiceContent = {
    Text = "Estar preso nesta casca infundida com elementos humanos me deixa doente. Finalmente me livrei do passado, e agora tenho que lembrá-lo novamente..."
  },
  Voice_6651_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Um"
  },
  Voice_6651_UnlockDesc = {
    Text = "Nível de afinidade atingido 2 desbloqueado"
  },
  Voice_6652_AwakerVoiceContent = {
    Text = "Eu sei, o herdeiro do grande linhagem mais uma vez se tornou um capanga para os humanos. Mas não pense que pode me ordenar como quiser."
  },
  Voice_6652_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Dois"
  },
  Voice_6652_UnlockDesc = {
    Text = "Nível de afinidade atingido 4 desbloqueado"
  },
  Voice_6653_AwakerVoiceContent = {
    Text = "Hmph, você, frágil humano, tem algum talento em comandar, mas este corpo inferior impede meu pleno potencial."
  },
  Voice_6653_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Três"
  },
  Voice_6653_UnlockDesc = {
    Text = "Nível de afinidade atingido 6 desbloqueado"
  },
  Voice_6654_AwakerVoiceContent = {
    Text = "Meu corpo está esquentando."
  },
  Voice_6654_AwakerVoiceTitle = {
    Text = "Atualizar·II"
  },
  Voice_6655_AwakerVoiceContent = {
    Text = "Escapar... Eu preciso fugir! Preciso sair daqui!"
  },
  Voice_6655_AwakerVoiceTitle = {
    Text = "Fúria Explosiva"
  },
  Voice_6656_AwakerVoiceContent = {
    Text = "Escapar... Eu preciso fugir! Preciso sair daqui!"
  },
  Voice_6656_AwakerVoiceTitle = {
    Text = "Exaltar · Dois"
  },
  Voice_6657_AwakerVoiceContent = {
    Text = "Obrigado pelos seus esforços. Permita-me recompensá-lo de acordo."
  },
  Voice_6657_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · I"
  },
  Voice_6658_AwakerVoiceContent = {
    Text = "É suportável."
  },
  Voice_6658_AwakerVoiceTitle = {
    Text = "Acertar · II"
  },
  Voice_6659_AwakerVoiceContent = {
    Text = "(grunhido de dor)"
  },
  Voice_6659_AwakerVoiceTitle = {Text = "Acertar·1"},
  Voice_6660_AwakerVoiceContent = {
    Text = "Humano, embora você seja frágil, sua convicção me comoveu. Estou disposto a me tornar sua arma. Vamos causar algum caos juntos!"
  },
  Voice_6660_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Cinco"
  },
  Voice_6660_UnlockDesc = {
    Text = "Nível de afinidade atingido 10 desbloqueado"
  },
  Voice_6662_AwakerVoiceContent = {
    Text = "Este é meu salão."
  },
  Voice_6662_AwakerVoiceTitle = {
    Text = "Despertar do Conhecimento Espiritual"
  },
  Voice_6664_AwakerVoiceContent = {
    Text = "A Academia da Igualdade... Eu me pergunto quais sonhos tolos você abriga. Mesmo que você não tenha cometido erros, eles ainda te atropelarão. Eu conheço esse sentimento."
  },
  Voice_6664_AwakerVoiceTitle = {
    Text = "Chat·Sobre a Universidade Mythag"
  },
  Voice_6665_AwakerVoiceContent = {
    Text = "Esta é a fonte de toda impureza..."
  },
  Voice_6665_AwakerVoiceTitle = {
    Text = "Exaltar · Depressão"
  },
  Voice_6666_AwakerVoiceContent = {
    Text = "Fui punido por falhar em proteger a tripulação. Disseram que, devido à minha negligência, os membros da tripulação desaparecidos nunca se reunirão com suas famílias... Isso é o que é a Dissolução?"
  },
  Voice_6666_AwakerVoiceTitle = {
    Text = "Bate-papo · Sobre Dissolução"
  },
  Voice_6667_AwakerVoiceContent = {
    Text = "Mais perto do meu Senhor..."
  },
  Voice_6667_AwakerVoiceTitle = {
    Text = "Atualizar·II"
  },
  Voice_6668_AwakerVoiceContent = {
    Text = "Por quê? Por que você não... desperta?"
  },
  Voice_6668_AwakerVoiceTitle = {
    Text = "Investigação Interrompida"
  },
  Voice_6669_AwakerVoiceContent = {
    Text = "Eu sou Horla de Cité, nome literário... Eu fiz uma promessa de não revelar a ninguém. Minhas desculpas, mas por favor, chame-me apenas de Horla."
  },
  Voice_6669_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_6670_AwakerVoiceContent = {
    Text = "Eu me oponho a todos os atos de injustiça, sendo a traição a pior. No exército, se você não pode ou não se atreve a confiar em seus companheiros para proteger suas costas, toda a unidade desmoronará."
  },
  Voice_6670_AwakerVoiceTitle = {
    Text = "Conversa·Coisas odiadas"
  },
  Voice_6671_AwakerVoiceContent = {
    Text = "Por que você parece tão escuro, mas tão radiante? ... Não, nunca mind, apenas ignore meus devaneios."
  },
  Voice_6671_AwakerVoiceTitle = {
    Text = "Conversa·Sobre Guardião do Segredo"
  },
  Voice_6672_AwakerVoiceContent = {Text = "(Gemido)"},
  Voice_6672_AwakerVoiceTitle = {
    Text = "Golpe·Quatro"
  },
  Voice_6673_AwakerVoiceContent = {
    Text = "(Gemido abafado)"
  },
  Voice_6673_AwakerVoiceTitle = {
    Text = "Acertar·III"
  },
  Voice_6674_AwakerVoiceContent = {Text = "O que?!"},
  Voice_6674_AwakerVoiceTitle = {
    Text = "Acertar · II"
  },
  Voice_6675_AwakerVoiceContent = {
    Text = "Eu amo a vida, e eu amo a luz. Quero que Desmaio emerja de sua concha isolada e experimente o mundo com seus próprios olhos e ouvidos."
  },
  Voice_6675_AwakerVoiceTitle = {
    Text = "Conversa·Coisas favoritas"
  },
  Voice_6676_AwakerVoiceContent = {
    Text = "Você não pode me ver!"
  },
  Voice_6676_AwakerVoiceTitle = {
    Text = "Defesa · I"
  },
  Voice_6677_AwakerVoiceContent = {
    Text = "O trabalho de manutenção precisa continuar?"
  },
  Voice_6677_AwakerVoiceTitle = {
    Text = "Atualizar·II"
  },
  Voice_6678_AwakerVoiceContent = {
    Text = "A manutenção das partes foi concluída."
  },
  Voice_6678_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · I"
  },
  Voice_6679_AwakerVoiceContent = {
    Text = "As pessoas podem trair, mas as ferramentas nunca o farão. Se usadas corretamente, a dissolução também pode se tornar uma ferramenta de vingança."
  },
  Voice_6679_AwakerVoiceTitle = {
    Text = "Bate-papo · Sobre Dissolução"
  },
  Voice_6680_AwakerVoiceContent = {
    Text = "Após um milênio de espera, o momento finalmente chegou... Eu sou o verdadeiro governante dos Perishites!"
  },
  Voice_6680_AwakerVoiceTitle = {
    Text = "Iluminar·Florescer"
  },
  Voice_6680_UnlockDesc = {
    Text = "Nível de iluminação atingiu 15 para desbloquear"
  },
  Voice_6681_AwakerVoiceContent = {
    Text = "Foi aquele híbrido de Aequor que acabamos de passar? Hmm... veja aquela coluna ereta. Esta noite, eu o verei rastejar."
  },
  Voice_6681_AwakerVoiceTitle = {
    Text = "Bate-papo · Sobre Caecus"
  },
  Voice_6681_UnlockDesc = {
    Text = "Desbloqueia ao obter o despertador \"Caecus\""
  },
  Voice_6682_AwakerVoiceContent = {
    Text = "O poder está gradualmente voltando para minhas mãos... O próximo passo é apreender o poder que me pertence por direito!"
  },
  Voice_6682_AwakerVoiceTitle = {
    Text = "Iluminar: Insight"
  },
  Voice_6682_UnlockDesc = {
    Text = "Nível de iluminação atingiu 7 para desbloquear"
  },
  Voice_6683_AwakerVoiceContent = {
    Text = "Nada mal. Estamos um passo mais perto de rasgar o véu hipócrita daquela mulher."
  },
  Voice_6683_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexão"
  },
  Voice_6683_UnlockDesc = {
    Text = "Nível de iluminação atingiu 3 para desbloquear"
  },
  Voice_6684_AwakerVoiceContent = {
    Text = "Calma, calma, calma..."
  },
  Voice_6684_AwakerVoiceTitle = {
    Text = "Carta de Habilidade·Quatro"
  },
  Voice_6685_AwakerVoiceContent = {
    Text = "Não precisa se preocupar. Meu limite de dor pode estar muito além da sua imaginação."
  },
  Voice_6685_AwakerVoiceTitle = {
    Text = "Iluminar·Visão Remota"
  },
  Voice_6685_UnlockDesc = {
    Text = "Nível de iluminação atingiu 1 para desbloquear"
  },
  Voice_6686_AwakerVoiceContent = {
    Text = "Se você me perguntar, belos tolos são os melhores. Infelizmente, há muitas mentes inteligentes, mas inúteis por aqui."
  },
  Voice_6686_AwakerVoiceTitle = {
    Text = "Chat·Sobre a Universidade Mythag"
  },
  Voice_6687_AwakerVoiceContent = {
    Text = "Powered by the nuclear fusion of a red giant, supplemented by the energy from a collapsing star, you could start a perpetual motion machine and light an eternal lamp... Eh? Você diz que não há como construir uma máquina de movimento perpétuo aqui, e nenhum gigante vermelho? Hmm..."
  },
  Voice_6687_AwakerVoiceTitle = {
    Text = "Conversa·Coisas favoritas"
  },
  Voice_6688_AwakerVoiceContent = {
    Text = "O sangue do inimigo ainda não drenou completamente."
  },
  Voice_6688_AwakerVoiceTitle = {
    Text = "Investigação Bem-sucedida"
  },
  Voice_6689_AwakerVoiceContent = {
    Text = "Dê todos eles... a mim!"
  },
  Voice_6689_AwakerVoiceTitle = {
    Text = "Fúria Explosiva"
  },
  Voice_6690_AwakerVoiceContent = {
    Text = "Dê todos eles... a mim!"
  },
  Voice_6690_AwakerVoiceTitle = {
    Text = "Fúria Explosiva"
  },
  Voice_6691_AwakerVoiceContent = {
    Text = "É hora de ir para o campo de batalha."
  },
  Voice_6691_AwakerVoiceTitle = {
    Text = "Início da Investigação"
  },
  Voice_6692_AwakerVoiceContent = {Text = "É hora!"},
  Voice_6692_AwakerVoiceTitle = {
    Text = "Carta de Habilidade·Quatro"
  },
  Voice_6693_AwakerVoiceContent = {
    Text = "Quando eu durmo, sonhos transbordantes causam turbulência espiritual. Portanto, não se aproxime de mim enquanto estou dormindo, e não me acorde casualmente."
  },
  Voice_6693_AwakerVoiceTitle = {
    Text = "Conversas Ociosas: Sobre Sono"
  },
  Voice_6694_AwakerVoiceContent = {Text = "É hora!"},
  Voice_6694_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_6695_AwakerVoiceContent = {
    Text = "Embora Herbert seja uma pessoa aterrorizante, seus gatos são muito gentis... Não, para ser preciso, são dois gatos, certo?"
  },
  Voice_6695_AwakerVoiceTitle = {
    Text = "Fala Ociosa · Sobre Herbert"
  },
  Voice_6695_UnlockDesc = {
    Text = "Desbloqueado após limpar \"Operação de Investigação\" Capítulo 2"
  },
  Voice_6696_AwakerVoiceContent = {
    Text = "Aquela mulher Murphy se veste de forma muito chamativa... De jeito nenhum, Karen não pode perder para ela!\nOu talvez, apenas matá-la..."
  },
  Voice_6696_AwakerVoiceTitle = {
    Text = "Conversas Ociosas·Sobre Murphy"
  },
  Voice_6696_UnlockDesc = {
    Text = "Desbloqueado após obter Despertador \"Murphy\""
  },
  Voice_6697_AwakerVoiceContent = {Text = "Ah~"},
  Voice_6697_AwakerVoiceTitle = {Text = "Ataque·Um"},
  Voice_6698_AwakerVoiceContent = {
    Text = "Você está se sentindo confortável?"
  },
  Voice_6698_AwakerVoiceTitle = {Text = "Ataque·Um"},
  Voice_6699_AwakerVoiceContent = {
    Text = "Quando firmamos parceria com a Universidade Mythag, ficou claramente acordado que eu não seria enviado para a batalha..."
  },
  Voice_6699_AwakerVoiceTitle = {
    Text = "Iluminar·Visão Remota"
  },
  Voice_6699_UnlockDesc = {
    Text = "Nível de iluminação atingiu 1 para desbloquear"
  },
  Voice_6700_AwakerVoiceContent = {
    Text = "Não se empolgue. Às vezes, a linha entre o nobre e o vil é apenas um passo."
  },
  Voice_6700_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_6700_UnlockDesc = {
    Text = "Nível de iluminação atingiu 2 para desbloquear"
  },
  Voice_6701_AwakerVoiceContent = {
    Text = "Faros te cumprimenta. Invocar-me aqui deve significar que você está pronto para zarpar."
  },
  Voice_6701_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_6702_AwakerVoiceContent = {
    Text = "Yahoo—Estou tão cansado, posso ir brincar agora!"
  },
  Voice_6702_AwakerVoiceTitle = {
    Text = "Investigação Bem-sucedida"
  },
  Voice_6703_AwakerVoiceContent = {
    Text = "Ah... O brilho dele é tão intenso e ofuscante, impossível de ignorar. Foi um zelo tolo que obscureceu meus sentidos... Não, não posso fazer desculpas para minha estupidez."
  },
  Voice_6703_AwakerVoiceTitle = {
    Text = "Papo reto · Sobre Tulu"
  },
  Voice_6703_UnlockDesc = {
    Text = "Desbloqueado após obter o Despertador \"Tulu\""
  },
  Voice_6705_AwakerVoiceContent = {
    Text = "As estrelas no sonho, indo para onde deveriam, apontam para o reino de Deus!"
  },
  Voice_6705_AwakerVoiceTitle = {
    Text = "Fúria Explosiva"
  },
  Voice_6706_AwakerVoiceContent = {
    Text = "Você não acha fascinante empurrar tudo em direção ao seu fim e fazer as leis do mundo pararem?"
  },
  Voice_6706_AwakerVoiceTitle = {
    Text = "Conversa·Coisas favoritas"
  },
  Voice_6707_AwakerVoiceContent = {
    Text = "À sua saúde!"
  },
  Voice_6707_AwakerVoiceTitle = {Text = "Ataque·Um"},
  Voice_6708_AwakerVoiceContent = {Text = "Dorosa!"},
  Voice_6708_AwakerVoiceTitle = {Text = "Ataque·Um"},
  Voice_6709_AwakerVoiceContent = {
    Text = "Digite o comando de batalha."
  },
  Voice_6709_AwakerVoiceTitle = {
    Text = "Início da Investigação"
  },
  Voice_6710_AwakerVoiceContent = {
    Text = "Durante meus dias flutuando entre as estrelas, sonhei com este momento incontáveis vezes... Obrigado por reunir-me com Tinct."
  },
  Voice_6710_AwakerVoiceTitle = {
    Text = "Chit-chat·Sobre a Tinta"
  },
  Voice_6710_UnlockDesc = {
    Text = "Após obter o despertador \"Tinta\", desbloqueado"
  },
  Voice_6711_AwakerVoiceContent = {
    Text = "A Universidade Mythag é um ótimo lugar, especialmente com o cassino subterrâneo que abre toda semana...\nHã, você não sabia? Oops, deixei escapar..."
  },
  Voice_6711_AwakerVoiceTitle = {
    Text = "Chat·Sobre a Universidade Mythag"
  },
  Voice_6712_AwakerVoiceContent = {
    Text = "\"Resista à crise de Dissolução,\" ha, a autossatisfação humana é verdadeiramente risível."
  },
  Voice_6712_AwakerVoiceTitle = {
    Text = "Chat·Sobre a Universidade Mythag"
  },
  Voice_6713_AwakerVoiceContent = {
    Text = "Após tudo, os humanos são apenas criaturas superficiais. Algumas palavras, uma dica, e eles começam a lutar entre si... Suspiro, este nível de conflito é mal suficiente para inspirar."
  },
  Voice_6713_AwakerVoiceTitle = {
    Text = "Conversas Ociosas·Sobre Humanos"
  },
  Voice_6714_AwakerVoiceContent = {
    Text = "Talvez eu tenha sido míope ao considerá-lo um humano comum, saltando para conclusões muito cedo. Estou curioso—como um descrente como você mantém sua determinação? Esta não é uma pergunta da Mãe do Mar, mas sim uma indagação de Miryam. Você pode... responder para mim?"
  },
  Voice_6714_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Quatro"
  },
  Voice_6714_UnlockDesc = {
    Text = "Nível de afinidade atingido 8 desbloqueado"
  },
  Voice_6715_AwakerVoiceContent = {
    Text = "Você tão único, não se cansará deste mundo raso e turbulento? Eu realmente acredito que o reino eterno é onde você pertence. Você caminhará na terra dos deuses, banhar-se-á na piscina sagrada e enraizar-se-á no solo fértil... Junte-se a mim na minha jornada sagrada e transcendamos o plano mortal juntos. Então, lado a lado, estaremos ao lado do Trono, compartilhando a alegria de reconstruir o Reino Divino..."
  },
  Voice_6715_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Cinco"
  },
  Voice_6715_UnlockDesc = {
    Text = "Nível de afinidade atingido 10 desbloqueado"
  },
  Voice_6716_AwakerVoiceContent = {
    Text = "Nós somos todos meros mortais rastejando na poeira, mas o Sábio é diferente. Ele é o Emissário, uma encarnação divina. Seu aconselhamento ecoa as palavras dos deuses, guiando a civilização em direção à imortalidade... Não espero que você compreenda sua fé nele agora, mas um dia, você se ajoelhará diante de seu Trono."
  },
  Voice_6716_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Dois"
  },
  Voice_6716_UnlockDesc = {
    Text = "Nível de afinidade atingido 4 desbloqueado"
  },
  Voice_6717_AwakerVoiceContent = {
    Text = "Os Escolhidos são verdadeiramente abençoados, não acha? Eles receberam poder divino e vidas prolongadas. Quando o reino de Deus descer mais uma vez e Sua vontade for restaurada na terra, eles se tornarão crentes gloriosos. Não é uma fortuna e bênção imensas para a humanidade frágil?"
  },
  Voice_6717_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Três"
  },
  Voice_6717_UnlockDesc = {
    Text = "Nível de afinidade atingido 6 desbloqueado"
  },
  Voice_6718_AwakerVoiceContent = {
    Text = "A alegria de banhar-se na luz divina está além da compreensão de alguém como você que carece de fé... Que meu deus o perdoe, perdoe sua ignorância e insolência."
  },
  Voice_6718_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Um"
  },
  Voice_6718_UnlockDesc = {
    Text = "Nível de afinidade atingido 2 desbloqueado"
  },
  Voice_6719_AwakerVoiceContent = {
    Text = "Vamos ser rápidos, Guardião."
  },
  Voice_6719_AwakerVoiceTitle = {
    Text = "Início da Investigação"
  },
  Voice_6720_AwakerVoiceContent = {Text = "Eh-heh—"},
  Voice_6720_AwakerVoiceTitle = {
    Text = "Iluminar·Visão Remota"
  },
  Voice_6720_UnlockDesc = {
    Text = "Nível de iluminação atingiu 1 para desbloquear"
  },
  Voice_6721_AwakerVoiceContent = {
    Text = "Prepare-se para morrer, inseto espartano."
  },
  Voice_6721_AwakerVoiceTitle = {
    Text = "Início da Investigação"
  },
  Voice_6722_AwakerVoiceContent = {
    Text = "A Senhorita Doll diz que posso evitar temporariamente a Dissolução abandonando meu corpo como ela... Não consigo, não consigo, não consigo. Eu vou perder a consciência durante a cirurgia, e a escuridão vai dominar..."
  },
  Voice_6722_AwakerVoiceTitle = {
    Text = "Bate-papo · Sobre Boneca"
  },
  Voice_6722_UnlockDesc = {
    Text = "Após obter o despertador \"Boneca\", desbloqueado"
  },
  Voice_6723_AwakerVoiceContent = {
    Text = "Hmph... O que? Buscando o destino da obliteracão?"
  },
  Voice_6723_AwakerVoiceTitle = {
    Text = "Conversa·Toque"
  },
  Voice_6724_AwakerVoiceContent = {
    Text = "Ainda atormentado pela insônia, Mestre? Karen preparou o tranquilizante do Dobie para você~! Embora a dose esteja um pouco alta, um bom sono é a prioridade!"
  },
  Voice_6724_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Quatro"
  },
  Voice_6724_UnlockDesc = {
    Text = "Nível de afinidade atingido 8 desbloqueado"
  },
  Voice_6725_AwakerVoiceContent = {
    Text = "Estávamos bebendo e cantando quando de repente nos transformamos em monstros! Mas tudo bem, a pele esverdeada é bastante divertida!"
  },
  Voice_6725_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Três"
  },
  Voice_6725_UnlockDesc = {
    Text = "Nível de afinidade atingido 6 desbloqueado"
  },
  Voice_6726_AwakerVoiceContent = {
    Text = "O sonho de Karen? Hmm... Comprar um lindo colar de pérolas e usá-lo em um baile, tornando-se a estrela mais brilhante!"
  },
  Voice_6726_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Dois"
  },
  Voice_6726_UnlockDesc = {
    Text = "Nível de afinidade atingido 4 desbloqueado"
  },
  Voice_67276_AwakerVoiceContent = {
    Text = "O Ectípico do Desejo, Tifhreid, buscou seu caminho para a existência. Diante do desconhecido, ninguém pode julgar a nobreza ou a baixeza de seus métodos."
  },
  Voice_67276_AwakerVoiceTitle = {
    Text = "Chitchat · Sobre a Entidade do Desejo"
  },
  Voice_67276_UnlockDesc = {
    Text = "Após obter o despertador \"Táias\", desbloqueado"
  },
  Voice_67277_AwakerVoiceContent = {
    Text = "Passe pela Chave Prata para alcançar Seu Trono."
  },
  Voice_67277_AwakerVoiceTitle = {
    Text = "Despertar do Conhecimento Espiritual"
  },
  Voice_67278_AwakerVoiceTitle = {
    Text = "Golpe·Quatro"
  },
  Voice_67279_AwakerVoiceContent = {
    Text = "Não decepcione Seu conhecimento e memória"
  },
  Voice_67279_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · Três"
  },
  Voice_6727_AwakerVoiceContent = {
    Text = "Deslize para a esquerda, deslize para a direita, limpe a poeira e as preocupações—"
  },
  Voice_6727_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Um"
  },
  Voice_6727_UnlockDesc = {
    Text = "Nível de afinidade atingido 2 desbloqueado"
  },
  Voice_67280_AwakerVoiceContent = {
    Text = "Não estou aqui."
  },
  Voice_67280_AwakerVoiceTitle = {
    Text = "Acertar · II"
  },
  Voice_67281_AwakerVoiceContent = {
    Text = "Um fragmento do contínuo espaço-tempo infinito chega à minha consciência."
  },
  Voice_67281_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · I"
  },
  Voice_67282_AwakerVoiceContent = {
    Text = "Eu já vi a imagem completa."
  },
  Voice_67282_AwakerVoiceTitle = {
    Text = "Investigação Bem-sucedida"
  },
  Voice_67283_AwakerVoiceContent = {
    Text = "Tudo existe dentro do vazio."
  },
  Voice_67283_AwakerVoiceTitle = {
    Text = "Habilidade·Um"
  },
  Voice_67284_AwakerVoiceContent = {
    Text = "Você foi fundo, muito fundo. Em breve, você testemunhará um milagre extraordinário. Eu espero que você consiga permanecer tão são e calmo como está agora."
  },
  Voice_67284_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Quatro"
  },
  Voice_67284_UnlockDesc = {
    Text = "Nível de afinidade atingido 8 desbloqueado"
  },
  Voice_67285_AwakerVoiceContent = {
    Text = "\"Ignorância.\" Não, buscar diligentemente a essência não é ignorância; a verdadeira ignorância reside em viver em uma névoa, inconsciente do que não se sabe."
  },
  Voice_67285_AwakerVoiceTitle = {
    Text = "Conversa·Coisas odiadas"
  },
  Voice_67286_AwakerVoiceContent = {
    Text = "Eu irei mostrar a você meus sonhos. Tudo bizarro e caótico que você vê neles está mais próximo da verdadeira natureza deste mundo do que a realidade que você conhece."
  },
  Voice_67286_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Dois"
  },
  Voice_67286_UnlockDesc = {
    Text = "Nível de afinidade atingido 4 desbloqueado"
  },
  Voice_67287_AwakerVoiceContent = {
    Text = "Aqui está meu conselho: Fique calmo. Quando você se sentir cansado, pare imediatamente e conserve sua força e energia. Caso contrário, você estará para sempre perdido no reino dos sonhos."
  },
  Voice_67287_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Três"
  },
  Voice_67287_UnlockDesc = {
    Text = "Nível de afinidade atingido 6 desbloqueado"
  },
  Voice_67288_AwakerVoiceContent = {
    Text = "O universo cicla infinitamente."
  },
  Voice_67288_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_67289_AwakerVoiceContent = {
    Text = "A sincronização entre nós não deveria exigir um ajuste tão longo. No entanto, para proteger sua clareza mental das ilusões, prosseguirei gradualmente."
  },
  Voice_67289_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Um"
  },
  Voice_67289_UnlockDesc = {
    Text = "Nível de afinidade atingido 2 desbloqueado"
  },
  Voice_6728_AwakerVoiceContent = {
    Text = "Dissolução... Eu acabei trabalhando em um caso relacionado. No entanto, desaparecer parece algo natural, não é? No final, todos desaparecem."
  },
  Voice_6728_AwakerVoiceTitle = {
    Text = "Bate-papo · Sobre Dissolução"
  },
  Voice_67290_AwakerVoiceContent = {
    Text = "O Primeiro Portal. O universo infinito nasceu de um ponto."
  },
  Voice_67290_AwakerVoiceTitle = {
    Text = "Iluminar·Visão Remota"
  },
  Voice_67290_UnlockDesc = {
    Text = "Nível de iluminação atingiu 1 para desbloquear"
  },
  Voice_67291_AwakerVoiceContent = {
    Text = "O Segundo Portão. Uma linha se estende de um ponto, estendendo-se em direção a polaridades infinitas."
  },
  Voice_67291_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_67291_UnlockDesc = {
    Text = "Nível de iluminação atingiu 2 para desbloquear"
  },
  Voice_67292_AwakerVoiceContent = {
    Text = "O Quarto Portal. O arquétipo eterno solidificado em um espaço de dimensões."
  },
  Voice_67292_AwakerVoiceTitle = {
    Text = "Iluminar: Insight"
  },
  Voice_67292_UnlockDesc = {
    Text = "Nível de iluminação atingiu 7 para desbloquear"
  },
  Voice_67293_AwakerVoiceContent = {
    Text = "O Terceiro Portão. Planos são pronomes parciais e unilaterais."
  },
  Voice_67293_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexão"
  },
  Voice_67293_UnlockDesc = {
    Text = "Nível de iluminação atingiu 3 para desbloquear"
  },
  Voice_67294_AwakerVoiceContent = {
    Text = "Portal dos Extremos. O vácuo final que conecta incontáveis universos. Passe pelo Portal dos Extremos e os mistérios ultimated do mundo serão revelados a você."
  },
  Voice_67294_AwakerVoiceTitle = {
    Text = "Iluminar·Florescer"
  },
  Voice_67294_UnlockDesc = {
    Text = "Nível de iluminação atingiu 15 para desbloquear"
  },
  Voice_67295_AwakerVoiceContent = {
    Text = "O Quinto Portal. A passagem do tempo é apenas uma ilusão; nunca houve um começo, e assim, nenhum fim."
  },
  Voice_67295_AwakerVoiceTitle = {
    Text = "Iluminar·Construção"
  },
  Voice_67295_UnlockDesc = {
    Text = "Nível de iluminação atingiu 11 para desbloquear"
  },
  Voice_67296_AwakerVoiceContent = {
    Text = "Eu deveria ser apenas seu guia, conduzindo-o nesta jornada antes de descansar nas águas ilusórias. Agora você é meu Linker, e nossa conexão é tão intrincada que é difícil de romper..."
  },
  Voice_67296_AwakerVoiceTitle = {
    Text = "Conversa·Sobre Guardião do Segredo"
  },
  Voice_67297_AwakerVoiceContent = {
    Text = "Você deseja confirmar algo? Infelizmente, os sentidos e a mente deste corpo são muito restritos. Se nos encontrarmos no Abismo, posso lhe mostrar muito mais..."
  },
  Voice_67297_AwakerVoiceTitle = {
    Text = "Conversa·Toque"
  },
  Voice_67298_AwakerVoiceContent = {
    Text = "Ela é um dos meus Fragmentos, de outra Dimensão que foi eternamente aniquilada. Infelizmente, enquanto ela dominou a reversão do tempo, falhou em entender a essência de transcender o espaço-tempo, sucumbindo repetidamente à angústia. Isso é minha culpa."
  },
  Voice_67298_AwakerVoiceTitle = {
    Text = "Chitchat · Sobre Ramona, a Errante"
  },
  Voice_67298_UnlockDesc = {
    Text = "Desbloqueado após obter o Despertador \"Ramona: Antiga\""
  },
  Voice_67299_AwakerVoiceContent = {Text = "Eu sei."},
  Voice_67299_AwakerVoiceTitle = {Text = "Ataque·II"},
  Voice_6729_AwakerVoiceContent = {
    Text = "Você está preocupado com a aparência deste corpo? Não pense demais. Eu nasci com um rosto humano."
  },
  Voice_6729_AwakerVoiceTitle = {
    Text = "Conversa·Toque"
  },
  Voice_67300_AwakerVoiceContent = {Text = "Eu vejo"},
  Voice_67300_AwakerVoiceTitle = {Text = "Ataque·Um"},
  Voice_67301_AwakerVoiceContent = {
    Text = "Como é pequeno."
  },
  Voice_67301_AwakerVoiceTitle = {
    Text = "Defesa · I"
  },
  Voice_67302_AwakerVoiceContent = {
    Text = "Mantenha a compostura."
  },
  Voice_67302_AwakerVoiceTitle = {Text = "Defesa·II"},
  Voice_67303_AwakerVoiceContent = {
    Text = "Ligar diretamente com a substância irá danificar sua mente... No entanto, uma vez que você insiste, eu responderei ao seu chamado."
  },
  Voice_67303_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_67304_AwakerVoiceTitle = {
    Text = "Acertar·III"
  },
  Voice_67305_AwakerVoiceContent = {
    Text = "Aquela criança suportou demais por causa do meu Fragmento. Felizmente, sua Alma permanece tão clara quanto prata fluente..."
  },
  Voice_67305_AwakerVoiceTitle = {
    Text = "Papo reto · Sobre Ramona"
  },
  Voice_67305_UnlockDesc = {
    Text = "Desbloqueado após obter o Despertador \"Ramona\""
  },
  Voice_67306_AwakerVoiceContent = {
    Text = "Visite seu sonho e vislumbre os segredos tabus do universo."
  },
  Voice_67306_AwakerVoiceTitle = {
    Text = "Atualizar·II"
  },
  Voice_67307_AwakerVoiceContent = {Text = "Hmm."},
  Voice_67307_AwakerVoiceTitle = {Text = "Acertar·1"},
  Voice_67308_AwakerVoiceContent = {
    Text = "O Portal dos Extremos se abre para você. Abraça o mundo do silêncio mortal além."
  },
  Voice_67308_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Cinco"
  },
  Voice_67308_UnlockDesc = {
    Text = "Nível de afinidade atingido 10 desbloqueado"
  },
  Voice_67309_AwakerVoiceContent = {
    Text = "Meu propósito ao estabelecer esta escola com eles é para \"Armazenamento\". Você alcançou mais do que eu esperava."
  },
  Voice_67309_AwakerVoiceTitle = {
    Text = "Conversa·Sobre Missaga"
  },
  Voice_6730_AwakerVoiceContent = {
    Text = "A Dissolução é um presente divino. A dor que traz é apenas o suficiente para paralisar nossos nervos, permitindo-nos nos entregar de coração à comida, vinho e festividades, então seguir rumo à extinção."
  },
  Voice_6730_AwakerVoiceTitle = {
    Text = "Bate-papo · Sobre Dissolução"
  },
  Voice_67310_AwakerVoiceContent = {
    Text = "Passado, presente e futuro — todo o brilho de bilhões está ligado a isso!"
  },
  Voice_67310_AwakerVoiceTitle = {
    Text = "Sobre-Exaltação Aliemus Explosão·II"
  },
  Voice_67311_AwakerVoiceContent = {
    Text = "Passado, presente e futuro — todo o brilho de bilhões está ligado a isso!"
  },
  Voice_67311_AwakerVoiceTitle = {
    Text = "Superexaltação"
  },
  Voice_67312_AwakerVoiceContent = {
    Text = "O Portal dos Extremos se abriu. Aqui, todas as coisas se convergem em uma!"
  },
  Voice_67312_AwakerVoiceTitle = {
    Text = "Exaltar · Dois"
  },
  Voice_67313_AwakerVoiceContent = {
    Text = "O Portal dos Extremos se abriu. Aqui, todas as coisas se convergem em uma!"
  },
  Voice_67313_AwakerVoiceTitle = {
    Text = "Fúria Explosiva"
  },
  Voice_67314_AwakerVoiceContent = {
    Text = "Ouça a voz da sabedoria."
  },
  Voice_67314_AwakerVoiceTitle = {
    Text = "Habilidade Especial · Dois"
  },
  Voice_67315_AwakerVoiceContent = {
    Text = "Infinito, sem limites, interminável e ilimitado."
  },
  Voice_67315_AwakerVoiceTitle = {
    Text = "Habilidade Especial · Três"
  },
  Voice_67316_AwakerVoiceContent = {
    Text = "É a vontade Dele... Não, na verdade, é um olhar inconsciente que abrange todas as coisas dentro de Seu sopro."
  },
  Voice_67316_AwakerVoiceTitle = {
    Text = "Conversa fiada·Sobre a crise"
  },
  Voice_67317_AwakerVoiceContent = {
    Text = "Incapaz de investigar minuciosamente... traços sutis..."
  },
  Voice_67317_AwakerVoiceTitle = {
    Text = "Investigação Interrompida"
  },
  Voice_67318_AwakerVoiceContent = {
    Text = "Eu irei revelar a verdade."
  },
  Voice_67318_AwakerVoiceTitle = {
    Text = "Início da Investigação"
  },
  Voice_67319_AwakerVoiceContent = {
    Text = "\"Resposta\" Eu guardo esta Porta por amor, e é também por amor que coloco a Chave em sua mão."
  },
  Voice_67319_AwakerVoiceTitle = {
    Text = "Conversa·Coisas favoritas"
  },
  Voice_6731_AwakerVoiceContent = {
    Text = "Deve... voltar..."
  },
  Voice_6731_AwakerVoiceTitle = {
    Text = "Despertar do Conhecimento Espiritual"
  },
  Voice_6732_AwakerVoiceContent = {
    Text = "Céu e Terra, o ciclo do karma!"
  },
  Voice_6732_AwakerVoiceTitle = {
    Text = "Fúria Explosiva"
  },
  Voice_6733_AwakerVoiceContent = {
    Text = "Céu e Terra, o ciclo do karma!"
  },
  Voice_6733_AwakerVoiceTitle = {
    Text = "Fúria Explosiva"
  },
  Voice_6734_AwakerVoiceContent = {
    Text = "A lâmina ainda não perdeu a sua cor."
  },
  Voice_6734_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · Três"
  },
  Voice_6735_AwakerVoiceContent = {
    Text = "O treinamento não deve ser negligenciado."
  },
  Voice_6735_AwakerVoiceTitle = {
    Text = "Atualizar·II"
  },
  Voice_6736_AwakerVoiceContent = {
    Text = "Mais ágil agora."
  },
  Voice_6736_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · I"
  },
  Voice_6737_AwakerVoiceContent = {
    Text = "Entidades invisíveis estarão sob seu comando."
  },
  Voice_6737_AwakerVoiceTitle = {
    Text = "Iluminar: Insight"
  },
  Voice_6737_UnlockDesc = {
    Text = "Nível de iluminação atingiu 7 para desbloquear"
  },
  Voice_6738_AwakerVoiceContent = {
    Text = "Sinta essa respiração escaldante—"
  },
  Voice_6738_AwakerVoiceTitle = {
    Text = "Fúria Explosiva"
  },
  Voice_6739_AwakerVoiceContent = {
    Text = "Todos nós nos tornaremos... parte da Chama Verde..."
  },
  Voice_6739_AwakerVoiceTitle = {
    Text = "Investigação Interrompida"
  },
  Voice_6740_AwakerVoiceContent = {
    Text = "Meu escudo brilhará por você, meu senhor."
  },
  Voice_6740_AwakerVoiceTitle = {
    Text = "Iluminar·Construção"
  },
  Voice_6740_UnlockDesc = {
    Text = "Nível de iluminação atingiu 11 para desbloquear"
  },
  Voice_6741_AwakerVoiceContent = {
    Text = "Melhorado mais uma vez, profundamente apreciado!"
  },
  Voice_6741_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_6741_UnlockDesc = {
    Text = "Nível de iluminação atingiu 2 para desbloquear"
  },
  Voice_6743_AwakerVoiceContent = {Text = "Tsc"},
  Voice_6743_AwakerVoiceTitle = {
    Text = "Golpe·Quatro"
  },
  Voice_6744_AwakerVoiceContent = {
    Text = "(Resistência desdenhosa)"
  },
  Voice_6744_AwakerVoiceTitle = {
    Text = "Acertar·III"
  },
  Voice_6745_AwakerVoiceContent = {
    Text = "(Resistência desdenhosa)"
  },
  Voice_6745_AwakerVoiceTitle = {
    Text = "Acertar · II"
  },
  Voice_6746_AwakerVoiceContent = {
    Text = "(Resistência desdenhosa)"
  },
  Voice_6746_AwakerVoiceTitle = {Text = "Acertar·1"},
  Voice_6747_AwakerVoiceContent = {
    Text = "O tempo passado com todos sempre parece tão relaxante..."
  },
  Voice_6747_AwakerVoiceTitle = {
    Text = "Conversa·Coisas favoritas"
  },
  Voice_6748_AwakerVoiceContent = {
    Text = "O Hilota do Massacre, Mensageiro de Tisífones, Lâmina do Ódio... Eles me concederam esses títulos. Claro, não me importo em ser essa pessoa."
  },
  Voice_6748_AwakerVoiceTitle = {
    Text = "Papo reto · Sobre Mim"
  },
  Voice_6749_AwakerVoiceContent = {
    Text = "(Exclamação)"
  },
  Voice_6749_AwakerVoiceTitle = {Text = "Acertar·1"},
  Voice_6750_AwakerVoiceContent = {
    Text = "Tudo ou nada!"
  },
  Voice_6750_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_6751_AwakerVoiceContent = {
    Text = "(Exclamação)"
  },
  Voice_6751_AwakerVoiceTitle = {
    Text = "Acertar·III"
  },
  Voice_6752_AwakerVoiceContent = {
    Text = "(Exclamação)"
  },
  Voice_6752_AwakerVoiceTitle = {
    Text = "Acertar · II"
  },
  Voice_6753_AwakerVoiceContent = {
    Text = "Podemos ir mais longe desta vez? Vamos para a praia!"
  },
  Voice_6753_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · I"
  },
  Voice_6754_AwakerVoiceTitle = {
    Text = "Golpe·Quatro"
  },
  Voice_6755_AwakerVoiceContent = {
    Text = "Uau—obrigado, amigo~"
  },
  Voice_6755_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · Três"
  },
  Voice_6756_AwakerVoiceContent = {
    Text = "Companheiros~Mais Companheiros~"
  },
  Voice_6756_AwakerVoiceTitle = {
    Text = "Atualizar·II"
  },
  Voice_6757_AwakerVoiceContent = {
    Text = "Uvhash... ele é especial. Você acha que a prosperidade da minha família veio facilmente? Tudo graças a ele, matando como um cachorro louco na arena. Ele é nossa maior vaca leiteira."
  },
  Voice_6757_AwakerVoiceTitle = {
    Text = "Chat·Sobre Uvhash"
  },
  Voice_6757_UnlockDesc = {
    Text = "Após obter o despertador \"uvhash\", desbloqueado"
  },
  Voice_6758_AwakerVoiceContent = {Text = "Tolo!"},
  Voice_6758_AwakerVoiceTitle = {Text = "Defesa·II"},
  Voice_6759_AwakerVoiceContent = {Text = "Heh."},
  Voice_6759_AwakerVoiceTitle = {
    Text = "Defesa · I"
  },
  Voice_6760_AwakerVoiceContent = {
    Text = "Vá! Emita o comando de batalha!"
  },
  Voice_6760_AwakerVoiceTitle = {
    Text = "Início da Investigação"
  },
  Voice_6761_AwakerVoiceContent = {
    Text = "No abismo... haverá uma luz de justiça."
  },
  Voice_6761_AwakerVoiceTitle = {
    Text = "Exaltar · Dois"
  },
  Voice_6762_AwakerVoiceContent = {
    Text = "A luz da justiça está acesa aqui!"
  },
  Voice_6762_AwakerVoiceTitle = {
    Text = "Fúria Explosiva"
  },
  Voice_6763_AwakerVoiceContent = {
    Text = "As emoções humanas são tão frágeis e preciosas quanto flores..."
  },
  Voice_6763_AwakerVoiceTitle = {
    Text = "Conversas Ociosas: Sobre Colette"
  },
  Voice_6764_AwakerVoiceContent = {
    Text = "Hit, Stand, Black·Jack!"
  },
  Voice_6764_AwakerVoiceTitle = {
    Text = "Fúria Explosiva"
  },
  Voice_6765_AwakerVoiceContent = {
    Text = "Hit, Stand, Black·Jack!"
  },
  Voice_6765_AwakerVoiceTitle = {
    Text = "Exaltar · Dois"
  },
  Voice_67754_AwakerVoiceContent = {
    Text = "Não resista, não chore, não viva!"
  },
  Voice_67754_AwakerVoiceTitle = {
    Text = "Sobre-Exaltação Aliemus Explosão·II"
  },
  Voice_67756_AwakerVoiceContent = {
    Text = "Não resista, não chore, não viva!"
  },
  Voice_67756_AwakerVoiceTitle = {
    Text = "Superexaltação"
  },
  Voice_67772_AwakerVoiceContent = {
    Text = "Porta, abra!"
  },
  Voice_67772_AwakerVoiceTitle = {
    Text = "Habilidade Especial · Um"
  },
  Voice_79297_AwakerVoiceContent = {Text = "Oh."},
  Voice_79297_AwakerVoiceTitle = {Text = "Acertar·1"},
  Voice_79298_AwakerVoiceContent = {Text = "Hmm...?"},
  Voice_79298_AwakerVoiceTitle = {Text = "Acertar·1"},
  Voice_80092_AwakerVoiceContent = {
    Text = "A hidroterapia, a terapia eletroconvulsiva, a terapia de contenção, essas não são tratamentos, mas tortura. Portanto, durante meu período pro bono, tratarei os pacientes no hospital psiquiátrico à minha maneira, e no final, todos eles alcançarão a recuperação e encontrarão a verdadeira liberdade."
  },
  Voice_80092_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Três"
  },
  Voice_80092_UnlockDesc = {
    Text = "Nível de afinidade atingido 6 desbloqueado"
  },
  Voice_80093_AwakerVoiceContent = {
    Text = "Coitado de White, devido ao fato de que o asilo próximo está cheio, ele foi mantido em um chiqueiro por sua família. Eu o tratei de graça, e depois disso, ele finalmente percebeu que era uma pessoa, não um gado, e recuperou sua dignidade como humano."
  },
  Voice_80093_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Dois"
  },
  Voice_80093_UnlockDesc = {
    Text = "Nível de afinidade atingido 4 desbloqueado"
  },
  Voice_80094_AwakerVoiceContent = {
    Text = "Tecedeiras, advogados, barões... Eu nunca rejeitarei pacientes por causa de taxas; para mim, eles são meramente pacientes necessitando de cura."
  },
  Voice_80094_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Um"
  },
  Voice_80094_UnlockDesc = {
    Text = "Nível de afinidade atingido 2 desbloqueado"
  },
  Voice_80095_AwakerVoiceContent = {
    Text = "Admito que realmente subestimei você; sua existência é a dor em si. Desta vez, não há necessidade de visitas de acompanhamento, quero ficar ao seu lado e ver o resultado pessoalmente."
  },
  Voice_80095_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Cinco"
  },
  Voice_80095_UnlockDesc = {
    Text = "Nível de afinidade atingido 10 desbloqueado"
  },
  Voice_80096_AwakerVoiceContent = {
    Text = "Esses pacientes me deram belas memórias. A seguir, é a sua vez, Guardião, eu já escolhi o seu final. Essa será a consulta mais requintada da minha carreira."
  },
  Voice_80096_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Quatro"
  },
  Voice_80096_UnlockDesc = {
    Text = "Nível de afinidade atingido 8 desbloqueado"
  },
  Voice_81138_AwakerVoiceContent = {
    Text = "Recusar a ajuda do médico não traz benefícios para você. Talvez da próxima vez, precisamos tentar hipnose profunda."
  },
  Voice_81138_AwakerVoiceTitle = {
    Text = "Investigação Interrompida"
  },
  Voice_81139_AwakerVoiceContent = {
    Text = "Em uma sala escura, sozinho, junto com os incontáveis sussurros dolorosos ecoando constantemente em minha mente, essa é a melhor maneira de aproveitar o tempo."
  },
  Voice_81139_AwakerVoiceTitle = {
    Text = "Conversa·Coisas favoritas"
  },
  Voice_81140_AwakerVoiceContent = {
    Text = "Embora possa ser indelicado dizer, conversar com aquela criança só me entedia— você só pode ver uma expressão, e essa é um sorriso."
  },
  Voice_81140_AwakerVoiceTitle = {
    Text = "Bate-papo · Sobre Aurita"
  },
  Voice_81140_UnlockDesc = {
    Text = "Desbloqueia ao obter o despertador \"Aurita\""
  },
  Voice_81141_AwakerVoiceContent = {
    Text = "Perdoe-me por interromper, só senti sua baixa energia psicológica e vim conferir como você está. Agora, Guardião, você gostaria de embarcar em uma jornada mental?"
  },
  Voice_81141_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_81143_AwakerVoiceContent = {
    Text = "O médico psiquiátrico cura os pacientes perfurando seus crânios com uma técnica de trepanacão — relaxe, isso foi há muito tempo, agora temos muitas maneiras de medir e aprofundar na mente do paciente."
  },
  Voice_81143_AwakerVoiceTitle = {
    Text = "Iluminar·Visão Remota"
  },
  Voice_81143_UnlockDesc = {
    Text = "Nível de iluminação atingiu 1 para desbloquear"
  },
  Voice_81144_AwakerVoiceContent = {
    Text = "Para entender uns aos outros, só se pode abrir o coração—toque aqui, e meu coração de prata se abrirá para você."
  },
  Voice_81144_AwakerVoiceTitle = {
    Text = "Conversa·Toque"
  },
  Voice_81145_AwakerVoiceContent = {
    Text = "Se você quer ouvir meus pensamentos sobre algo, pode ficar desapontado. Ao invés de desabafar, sou melhor ouvindo."
  },
  Voice_81145_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · I"
  },
  Voice_81146_AwakerVoiceContent = {
    Text = "Ah, eu ouvi a Voz Dele, aqueles murmúrios, cada sílaba cheia de dor extrema!"
  },
  Voice_81146_AwakerVoiceTitle = {
    Text = "Atualizar·II"
  },
  Voice_81147_AwakerVoiceContent = {
    Text = "Vou lembrar a dor deste momento em meu coração, recordando e saboreando-a repetidamente..."
  },
  Voice_81147_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · Três"
  },
  Voice_81148_AwakerVoiceContent = {
    Text = "Como um fragmento daquela existência, você carrega seu sopro, aquele sopro cheio de dor, tornando qualquer memória sua incrivelmente deliciosa."
  },
  Voice_81148_AwakerVoiceTitle = {
    Text = "Conversa·Sobre Guardião do Segredo"
  },
  Voice_81149_AwakerVoiceContent = {
    Text = "Lembre-se desses medos, detalhe seus sentimentos de dor; a essência da terapia de impacto emocional é enfrentar a dor diretamente e conquistá-la. Venha, enxugue suas lágrimas e lentamente me conte aquelas memórias em detalhes..."
  },
  Voice_81149_AwakerVoiceTitle = {
    Text = "Iluminar·Construção"
  },
  Voice_81149_UnlockDesc = {
    Text = "Nível de iluminação atingiu 11 para desbloquear"
  },
  Voice_81150_AwakerVoiceContent = {
    Text = "Parabéns, você está curado—sim, alucinações e ilusões são fenômenos normais; são provas de sua recuperação."
  },
  Voice_81150_AwakerVoiceTitle = {
    Text = "Iluminar·Florescer"
  },
  Voice_81150_UnlockDesc = {
    Text = "Nível de iluminação atingiu 15 para desbloquear"
  },
  Voice_81151_AwakerVoiceContent = {
    Text = "Sua mente está seguramente cheia de imagens estranhas e bizarrias, o que é normal. Puxe-as para fora, e seu subconsciente e instintos revelarão tudo para você."
  },
  Voice_81151_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexão"
  },
  Voice_81151_UnlockDesc = {
    Text = "Nível de iluminação atingiu 3 para desbloquear"
  },
  Voice_81152_AwakerVoiceContent = {
    Text = "Em seguida, está a terapia moral de Philip Pinel. Você precisa expressar seus desejos e medos mais profundos, que é um procedimento necessário para libertar a mente e restaurar a humanidade adormecida."
  },
  Voice_81152_AwakerVoiceTitle = {
    Text = "Iluminar: Insight"
  },
  Voice_81152_UnlockDesc = {
    Text = "Nível de iluminação atingiu 7 para desbloquear"
  },
  Voice_81153_AwakerVoiceContent = {
    Text = "Guardião, você pode me ajudar com um pequeno teste? É apenas o teste de manchas de tinta de Rorschach. Ao passá-lo, poderei ver as profundezas do seu eu interior que permanecem desconhecidas para os outros, tornando-me o único Despertador a desvendar os segredos do coração do Guardião."
  },
  Voice_81153_AwakerVoiceTitle = {
    Text = "Conversa·Sobre análise psicológica"
  },
  Voice_81154_AwakerVoiceContent = {
    Text = "Primeiro, vamos ouvir uma música. Você consegue ouvir, a música suave e gentil? Agora, deixe seu corpo e mente ressoarem com a música, entrando em um estado de relaxamento espiritual..."
  },
  Voice_81154_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_81154_UnlockDesc = {
    Text = "Nível de iluminação atingiu 2 para desbloquear"
  },
  Voice_81155_AwakerVoiceContent = {
    Text = "Assistindo ao pêndulo, com seus olhos seguindo seu movimento..."
  },
  Voice_81155_AwakerVoiceTitle = {
    Text = "Despertar do Conhecimento Espiritual"
  },
  Voice_81156_AwakerVoiceContent = {
    Text = "Shh—Silencioso, então caminhe em direção ao fim que eu guio você."
  },
  Voice_81156_AwakerVoiceTitle = {
    Text = "Exaltar · Dois"
  },
  Voice_81157_AwakerVoiceContent = {
    Text = "Uma alma entorpecida não desperta meu interesse nem um pouco. Suas almas já morreram, e não importa o quanto se agite, não haverá uma ondulação."
  },
  Voice_81157_AwakerVoiceTitle = {
    Text = "Conversa·Coisas odiadas"
  },
  Voice_81158_AwakerVoiceTitle = {
    Text = "Golpe·Quatro"
  },
  Voice_81159_AwakerVoiceContent = {
    Text = "Estou ouvindo, por favor, continue."
  },
  Voice_81159_AwakerVoiceTitle = {Text = "Acertar·1"},
  Voice_81160_AwakerVoiceContent = {
    Text = "Por favor, permaneça em silêncio."
  },
  Voice_81160_AwakerVoiceTitle = {
    Text = "Acertar · II"
  },
  Voice_81161_AwakerVoiceTitle = {
    Text = "Acertar·III"
  },
  Voice_81162_AwakerVoiceContent = {
    Text = "Confie um pouco mais em mim."
  },
  Voice_81162_AwakerVoiceTitle = {Text = "Ataque·Um"},
  Voice_81163_AwakerVoiceContent = {
    Text = "Expose mais da dor!"
  },
  Voice_81163_AwakerVoiceTitle = {Text = "Ataque·II"},
  Voice_81164_AwakerVoiceContent = {
    Text = "Não precisa se esconder, não precisa ter vergonha, eu sou sua ouvinte mais confiável e única. Venha, derrame sua dor mais profunda para mim..."
  },
  Voice_81164_AwakerVoiceTitle = {
    Text = "Superexaltação"
  },
  Voice_81165_AwakerVoiceContent = {
    Text = "Aigis agora parece muito mais brilhante. Claro, se meu pequeno convidado precisar de ajuda, estou feliz em oferecê-la. Quero dizer, ajuda genuína."
  },
  Voice_81165_AwakerVoiceTitle = {
    Text = "Bate-papo · Sobre Aigis"
  },
  Voice_81165_UnlockDesc = {
    Text = "Após obter o despertador \"Aigis\", desbloqueado"
  },
  Voice_81166_AwakerVoiceContent = {
    Text = "Mostre-me seu eu mais verdadeiro."
  },
  Voice_81166_AwakerVoiceTitle = {
    Text = "Habilidade·Um"
  },
  Voice_81168_AwakerVoiceContent = {
    Text = "Eu saborearei esta doce dor."
  },
  Voice_81168_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_81169_AwakerVoiceContent = {
    Text = "Não precisa se esconder, não precisa ter vergonha, eu sou sua ouvinte mais confiável e única. Venha, derrame sua dor mais profunda para mim..."
  },
  Voice_81169_AwakerVoiceTitle = {
    Text = "Sobre-Exaltação Aliemus Explosão·II"
  },
  Voice_81170_AwakerVoiceContent = {
    Text = "A doença mental não é exclusiva desta era; transcende tempo e espaço, e a dissolução é a mesma. Ambos transcendem os limites da cognição humana, não é verdade?"
  },
  Voice_81170_AwakerVoiceTitle = {
    Text = "Conversa fiada·Sobre a crise"
  },
  Voice_81171_AwakerVoiceContent = {
    Text = "Shh—Silencioso, então caminhe em direção ao fim que eu guio você."
  },
  Voice_81171_AwakerVoiceTitle = {
    Text = "Fúria Explosiva"
  },
  Voice_81172_AwakerVoiceContent = {
    Text = "Este lugar está cheio de vestígios da história, e, de certa forma, a história representa memórias—memórias dolorosas dos que partiram."
  },
  Voice_81172_AwakerVoiceTitle = {
    Text = "Conversa·Sobre Missaga"
  },
  Voice_81173_AwakerVoiceContent = {
    Text = "Respiração profunda..."
  },
  Voice_81173_AwakerVoiceTitle = {Text = "Defesa·II"},
  Voice_81174_AwakerVoiceContent = {
    Text = "Dor, desespero, morte... essas memórias têm gosto de sobremesa após uma refeição."
  },
  Voice_81174_AwakerVoiceTitle = {
    Text = "Investigação Bem-sucedida"
  },
  Voice_81175_AwakerVoiceContent = {
    Text = "Não há necessidade de ficar tão nervoso, isto é apenas uma consulta psicológica regular."
  },
  Voice_81175_AwakerVoiceTitle = {
    Text = "Início da Investigação"
  },
  Voice_81176_AwakerVoiceContent = {
    Text = "Escute minha orientação."
  },
  Voice_81176_AwakerVoiceTitle = {
    Text = "Defesa · I"
  },
  Voice_84185_AwakerVoiceContent = {
    Text = "O ritual encontrou um imprevisto desconhecido. Peço desculpas por ter batido no seu braço com a bandeira, mas preciso mantê-lo acordado."
  },
  Voice_84185_AwakerVoiceTitle = {
    Text = "Iluminar: Insight"
  },
  Voice_84185_UnlockDesc = {
    Text = "Nível de iluminação atingiu 7 para desbloquear"
  },
  Voice_84186_AwakerVoiceContent = {
    Text = "Aqui posso ver diferentes modelos de navios e entrar em contato com equipamentos de navegação mais avançados. Eu gosto muito disso. O mais importante é que, acredito que este \"navio\" está seguindo a rota correta da história humana."
  },
  Voice_84186_AwakerVoiceTitle = {
    Text = "Conversa·Sobre Missaga"
  },
  Voice_84187_AwakerVoiceContent = {
    Text = "O ritual foi realizado com sucesso, agradeço pela sua cooperação. Na próxima vez, criarei alguns sinais com bandeiras exclusivos para nos ajudar a completar o ritual de forma mais segura e tranquila."
  },
  Voice_84187_AwakerVoiceTitle = {
    Text = "Iluminar·Florescer"
  },
  Voice_84187_UnlockDesc = {
    Text = "Nível de iluminação atingiu 15 para desbloquear"
  },
  Voice_84188_AwakerVoiceContent = {
    Text = "Não sei por que ele existe, mas uma coisa é clara: devo ter sucesso na navegação e trazer de volta com segurança todos os marinheiros e passageiros que saíram para o mar."
  },
  Voice_84188_AwakerVoiceTitle = {
    Text = "Conversa fiada·Sobre a crise"
  },
  Voice_84189_AwakerVoiceContent = {
    Text = "Por favor, fique tranquilo, usarei este poder para garantir a segurança da navegação do navio, jamais o utilizarei de forma abusiva."
  },
  Voice_84189_AwakerVoiceTitle = {
    Text = "Atualizar·II"
  },
  Voice_84190_AwakerVoiceContent = {
    Text = "Pare de resistir."
  },
  Voice_84190_AwakerVoiceTitle = {Text = "Ataque·II"},
  Voice_84191_AwakerVoiceContent = {
    Text = "Tenho apenas respeito por você e dedicarei minha vida a cumprir todas as ordens que me forem dadas."
  },
  Voice_84191_AwakerVoiceTitle = {
    Text = "Conversa·Sobre Guardião do Segredo"
  },
  Voice_84192_AwakerVoiceContent = {
    Text = "Desculpe, não entendo as pessoas, apenas entendo navios. Perdoe-me por usar essa analogia: seu casco não é de madeira nem de ferro, é de aço, forte e firme, digno de admiração."
  },
  Voice_84192_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Três"
  },
  Voice_84192_UnlockDesc = {
    Text = "Nível de afinidade atingido 6 desbloqueado"
  },
  Voice_84193_AwakerVoiceContent = {Text = "Render-se."},
  Voice_84193_AwakerVoiceTitle = {Text = "Ataque·Um"},
  Voice_84194_AwakerVoiceContent = {
    Text = "Mais do que \"gostar\", prefiro usar a palavra \"converter-se\". Quando olho diretamente para o deus indescritível, minha mente perde a razão e entra em êxtase. Sim, eu deveria temê-lo, mas não consigo me controlar."
  },
  Voice_84194_AwakerVoiceTitle = {
    Text = "Conversa·Coisas favoritas"
  },
  Voice_84195_AwakerVoiceContent = {
    Text = "Não serei derrubado pela tempestade."
  },
  Voice_84195_AwakerVoiceTitle = {Text = "Acertar·1"},
  Voice_84196_AwakerVoiceContent = {
    Text = "Se não houver ordem, o que restará deste mundo? Apenas caos e desordem."
  },
  Voice_84196_AwakerVoiceTitle = {
    Text = "Conversa·Coisas odiadas"
  },
  Voice_84197_AwakerVoiceContent = {
    Text = "Na próxima viagem, quero embarcar com uma identidade diferente da de navegador. Aquele... quero dizer, estou disposto a agir sob sua orientação. Você merece toda a minha confiança."
  },
  Voice_84197_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Cinco"
  },
  Voice_84197_UnlockDesc = {
    Text = "Nível de afinidade atingido 10 desbloqueado"
  },
  Voice_84198_AwakerVoiceContent = {
    Text = "Estou apenas cumprindo meu dever como navegador, não há necessidade de receber elogios públicos."
  },
  Voice_84198_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · I"
  },
  Voice_84199_AwakerVoiceContent = {
    Text = "O sistema do farol pode aliviar significativamente o estresse da navegação, e especialmente sua luz é muito brilhante; tenho grande prazer em zarpar junto com Falos."
  },
  Voice_84199_AwakerVoiceTitle = {
    Text = "Bate-Papo·Sobre Faróis"
  },
  Voice_84199_UnlockDesc = {
    Text = "Desbloqueado após obter o despertador \"Faróis\""
  },
  Voice_84200_AwakerVoiceContent = {
    Text = "Marinheiros, sigam a minha orientação. Chegaremos ao porto em segurança."
  },
  Voice_84200_AwakerVoiceTitle = {
    Text = "Superexaltação"
  },
  Voice_84201_AwakerVoiceContent = {
    Text = "O enlace espiritual foi bem-sucedido, consegui sentir sua consciência... Esta é a primeira vez que navego no vácuo, caso ocorra algum desvio de rota, por favor, me corrija a tempo."
  },
  Voice_84201_AwakerVoiceTitle = {
    Text = "Iluminar·Construção"
  },
  Voice_84201_UnlockDesc = {
    Text = "Nível de iluminação atingiu 11 para desbloquear"
  },
  Voice_84202_AwakerVoiceContent = {
    Text = "Observou-se nuvens cirrus e a queda contínua do mercúrio no barômetro. Todos atentos, o navio está prestes a encontrar uma tempestade."
  },
  Voice_84202_AwakerVoiceTitle = {
    Text = "Início da Investigação"
  },
  Voice_84203_AwakerVoiceContent = {
    Text = "Todo esse caos aconteceu porque eu planejei mal a rota. Estou disposto a aceitar a punição conforme as regras estabelecidas."
  },
  Voice_84203_AwakerVoiceTitle = {
    Text = "Investigação Interrompida"
  },
  Voice_84204_AwakerVoiceContent = {
    Text = "Mede o ângulo de elevação do corpo celeste."
  },
  Voice_84204_AwakerVoiceTitle = {
    Text = "Habilidade·Um"
  },
  Voice_84205_AwakerVoiceContent = {
    Text = "Essa sensação de tontura é parecida com a de enjoo no mar. Por favor, feche os olhos, segure minha mão e fique perto de mim, assim vai se sentir melhor."
  },
  Voice_84205_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexão"
  },
  Voice_84205_UnlockDesc = {
    Text = "Nível de iluminação atingiu 3 para desbloquear"
  },
  Voice_84206_AwakerVoiceContent = {
    Text = "Recolha a vela do traquete, incline para bombordo e o timoneiro ajuste o curso conforme meus cálculos."
  },
  Voice_84206_AwakerVoiceTitle = {
    Text = "Exaltar · Dois"
  },
  Voice_84207_AwakerVoiceContent = {
    Text = "Essas experiências são preciosas, e vou registrá-las detalhadamente no diário de navegação, deixando-as para os marinheiros que vierem depois."
  },
  Voice_84207_AwakerVoiceTitle = {
    Text = "Investigação Bem-sucedida"
  },
  Voice_84208_AwakerVoiceContent = {
    Text = "O ritual de aprofundar o link envolve riscos e resultados imprevisíveis, mas pode ficar tranquilo, pois estarei guiando você para que o ritual seja concluído com sucesso."
  },
  Voice_84208_AwakerVoiceTitle = {
    Text = "Iluminar·Visão Remota"
  },
  Voice_84208_UnlockDesc = {
    Text = "Nível de iluminação atingiu 1 para desbloquear"
  },
  Voice_84209_AwakerVoiceContent = {
    Text = "Ajuste novamente o centro de gravidade."
  },
  Voice_84209_AwakerVoiceTitle = {Text = "Defesa·II"},
  Voice_84210_AwakerVoiceContent = {
    Text = "Cuidado com a proteção do navio."
  },
  Voice_84210_AwakerVoiceTitle = {
    Text = "Acertar · II"
  },
  Voice_84211_AwakerVoiceContent = {
    Text = "Alguns são como navios a vapor, lentos para responder, mas capazes de operar em alta velocidade; outros são como navios a diesel, rápidos para iniciar, mas com potência limitada. E você, Guardião dos Segredos?"
  },
  Voice_84211_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Dois"
  },
  Voice_84211_UnlockDesc = {
    Text = "Nível de afinidade atingido 4 desbloqueado"
  },
  Voice_84212_AwakerVoiceContent = {
    Text = "Acredito firmemente na lei fundamental de que esforço gera recompensa, e no futuro vou me esforçar ainda mais."
  },
  Voice_84212_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · Três"
  },
  Voice_84213_AwakerVoiceContent = {
    Text = "Em várias ações de missão, você já provou seu valor. Acredito que você é um navegador tão excelente quanto eu... não, talvez você seja muito mais excelente do que eu."
  },
  Voice_84213_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Quatro"
  },
  Voice_84213_UnlockDesc = {
    Text = "Nível de afinidade atingido 8 desbloqueado"
  },
  Voice_84214_AwakerVoiceTitle = {
    Text = "Acertar·III"
  },
  Voice_84215_AwakerVoiceContent = {
    Text = "Basta você precisar, e a Kupersante sempre estará à disposição."
  },
  Voice_84215_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Um"
  },
  Voice_84215_UnlockDesc = {
    Text = "Nível de afinidade atingido 2 desbloqueado"
  },
  Voice_84216_AwakerVoiceContent = {
    Text = "Marinheiros, sigam minhas orientações. Certamente chegaremos ao porto em segurança."
  },
  Voice_84216_AwakerVoiceTitle = {
    Text = "Sobre-Exaltação Aliemus Explosão·II"
  },
  Voice_84217_AwakerVoiceTitle = {
    Text = "Golpe·Quatro"
  },
  Voice_84218_AwakerVoiceContent = {
    Text = "Navegador Kupersante chegou para o relatório! A bandeira está preparada, o estado pessoal está bom, aguardando o Guardião do Segredo emitir o comando de partida."
  },
  Voice_84218_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_84219_AwakerVoiceContent = {
    Text = "Certamente guiarei o navio para o rumo correto."
  },
  Voice_84219_AwakerVoiceTitle = {
    Text = "Despertar do Conhecimento Espiritual"
  },
  Voice_84220_AwakerVoiceContent = {
    Text = "O chapéu está torto? Desculpe, não entendi muito bem a sua intenção com isso. Por favor, me dê instruções claras."
  },
  Voice_84220_AwakerVoiceTitle = {
    Text = "Conversa·Toque"
  },
  Voice_84221_AwakerVoiceContent = {
    Text = "A bandeira é a linguagem do navegador, e também a sua epígrafe. Quando o navio afundar, os resgatadores interpretarão a minha última mensagem a partir dos destroços da bandeira."
  },
  Voice_84221_AwakerVoiceTitle = {
    Text = "Conversa·Sobre bandeiras"
  },
  Voice_84222_AwakerVoiceContent = {
    Text = "Perceber o ponto de equilíbrio do navio."
  },
  Voice_84222_AwakerVoiceTitle = {
    Text = "Defesa · I"
  },
  Voice_84223_AwakerVoiceContent = {
    Text = "Recolha a vela do traquete, incline para bombordo e o timoneiro ajuste o curso conforme meus cálculos."
  },
  Voice_84223_AwakerVoiceTitle = {
    Text = "Fúria Explosiva"
  },
  Voice_84224_AwakerVoiceContent = {
    Text = "A bandeira E transmite a ordem."
  },
  Voice_84224_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_84225_AwakerVoiceContent = {
    Text = "Em momentos necessários, um navegador que tenha estudado a cooperação na casa de máquinas também pode atuar como timoneiro, mas para garantir a segurança do navio, ainda espero poder confiar esta tarefa a alguém especialista nisso."
  },
  Voice_84225_AwakerVoiceTitle = {
    Text = "Bate-papo · Sobre Celeste"
  },
  Voice_84225_UnlockDesc = {
    Text = "Após obter o despertador \"celeste\", desbloqueado"
  },
  Voice_84226_AwakerVoiceContent = {
    Text = "A sensação de ausência de gravidade surge, seguida por uma vibração tão intensa quanto a de um navio em forte balanço. Siga meus movimentos e perceba o centro de gravidade do seu corpo para manter o equilíbrio."
  },
  Voice_84226_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_84226_UnlockDesc = {
    Text = "Nível de iluminação atingiu 2 para desbloquear"
  },
  Voice_84406_AwakerVoiceContent = {
    Text = "Iniciar a correção do mapa marinho."
  },
  Voice_84406_AwakerVoiceTitle = {
    Text = "Habilidade Especial · Um"
  },
  Voice_84407_AwakerVoiceTitle = {
    Text = "Habilidade Especial · Três"
  },
  Voice_84408_AwakerVoiceContent = {
    Text = "A Bandeira C está respondendo à ordem."
  },
  Voice_84408_AwakerVoiceTitle = {
    Text = "Habilidade Especial · Dois"
  },
  Voice_84409_AwakerVoiceTitle = {
    Text = "Habilidade Especial · Três"
  },
  Voice_90333_AwakerVoiceContent = {
    Text = "Não vai me ultrapassar."
  },
  Voice_90333_AwakerVoiceTitle = {Text = "Defesa·II"},
  Voice_90334_AwakerVoiceContent = {
    Text = "Como amigos devem se relacionar? Castor gosta de me mandar fazer muitas coisas, mesmo ele sendo totalmente capaz de fazê-las sozinho. E eu também quero fazer essas coisas para ele, é uma forma de interação entre nós. Se quiser, também farei algo para você."
  },
  Voice_90334_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Três"
  },
  Voice_90334_UnlockDesc = {
    Text = "Nível de afinidade atingido 6 desbloqueado"
  },
  Voice_90335_AwakerVoiceContent = {
    Text = "Com este corpo imortal, resistirei a todas as desgraças!"
  },
  Voice_90335_AwakerVoiceTitle = {
    Text = "Sobre-Exaltação Aliemus Explosão·II"
  },
  Voice_90336_AwakerVoiceContent = {
    Text = "Mesmo antes de ler aquele livro, não é que não tivéssemos curiosidade sobre o mundo exterior, sobre a ilha solitária no lago e as paisagens além do muro vermelho escuro. Mas, quando Pólux foi torturado, eu nunca cheguei a pensar em resistir. Comparado a Pólux, sou realmente muito fraco e desajeitado."
  },
  Voice_90336_AwakerVoiceTitle = {
    Text = "Iluminar: Insight"
  },
  Voice_90336_UnlockDesc = {
    Text = "Nível de iluminação atingiu 7 para desbloquear"
  },
  Voice_90337_AwakerVoiceContent = {
    Text = "Pareço um idiota? Desculpe, por favor, perdoe minha ignorância. Além do conhecimento sobre os deuses ensinado pela igreja da luz do templo, sei muito pouco sobre qualquer outra coisa. Vou estudar mais rapidamente. O que você gosta, o que odeia, me conte tudo, e eu certamente vou lembrar com cuidado."
  },
  Voice_90337_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Quatro"
  },
  Voice_90337_UnlockDesc = {
    Text = "Nível de afinidade atingido 8 desbloqueado"
  },
  Voice_90338_AwakerVoiceContent = {
    Text = "Testemunhe, esta vontade de buscar a liberdade."
  },
  Voice_90338_AwakerVoiceTitle = {
    Text = "Início da Investigação"
  },
  Voice_90339_AwakerVoiceContent = {
    Text = "Uma loja que satisfaz qualquer desejo, com produtos de todos os tipos... é algo que inspira respeito e distância. Não, não estou duvidando do poder daquela senhora, mas \"para ter algo, é preciso pagar o preço correspondente\". Esse é um princípio que Castor e eu já experimentamos muitas vezes."
  },
  Voice_90339_AwakerVoiceTitle = {
    Text = "Conversa Casual · Sobre Narciso"
  },
  Voice_90339_UnlockDesc = {
    Text = "Desbloqueado após adquirir o Despertar \"Narciso\""
  },
  Voice_90340_AwakerVoiceContent = {
    Text = "Essas asas amaldiçoadas também podem voar nas alturas?"
  },
  Voice_90340_AwakerVoiceTitle = {
    Text = "Atualizar·II"
  },
  Voice_90341_AwakerVoiceContent = {
    Text = "Vocês não podem me destruir!"
  },
  Voice_90341_AwakerVoiceTitle = {
    Text = "Fúria Explosiva"
  },
  Voice_90342_AwakerVoiceContent = {
    Text = "Você quer tocar nessas penas? Fique à vontade, preciso abrir as asas um pouco mais?"
  },
  Voice_90342_AwakerVoiceTitle = {
    Text = "Conversa·Toque"
  },
  Voice_90343_AwakerVoiceContent = {
    Text = "Quando recebo ajuda, frequentemente me pergunto: será que há algum preço oculto por trás desses cuidados especiais, desses valiosos livros e belos cristais de meteorito que você me presenteou? Desculpe-me, não deveria duvidar de você assim."
  },
  Voice_90343_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Um"
  },
  Voice_90343_UnlockDesc = {
    Text = "Nível de afinidade atingido 2 desbloqueado"
  },
  Voice_90344_AwakerVoiceContent = {
    Text = "O pássaro finalmente voará nas alturas."
  },
  Voice_90344_AwakerVoiceTitle = {
    Text = "Despertar do Conhecimento Espiritual"
  },
  Voice_90345_AwakerVoiceContent = {
    Text = "Mestre em culinária... O conhecimento para preparar comida também é realmente necessário. Embora eu não seja exigente quanto a comer, Pólux é muito difícil de contentar. Parece que eu deveria arranjar um tempo para pedir orientação séria... Não ir? Por quê? Mas a comida daquele senhor parece tão deliciosa?"
  },
  Voice_90345_AwakerVoiceTitle = {
    Text = "Conversa·Sobre Dulesain"
  },
  Voice_90345_UnlockDesc = {
    Text = "Desperte o corpo \"Dulesain\" para desbloquear"
  },
  Voice_90346_AwakerVoiceContent = {
    Text = "Pensando agora, as criadas durante a inspeção dos lampiões na verdade não eram tão diferentes de mim e Pólux. Todos vivíamos sob o peso de nossas próprias correntes, e elas sempre aceitaram isso com obediência e paciência. Porém, aquela criada verde parecia um pouco diferente; ela era muito energética e parecia naturalmente apaixonada por aquilo que fazia. Talvez ela já possuísse a mais valiosa liberdade."
  },
  Voice_90346_AwakerVoiceTitle = {
    Text = "Chat·Sobre Karen"
  },
  Voice_90346_UnlockDesc = {
    Text = "Após obter o despertador \"Karen\", desbloqueado"
  },
  Voice_90347_AwakerVoiceContent = {
    Text = "Vocês não podem me destruir!"
  },
  Voice_90347_AwakerVoiceTitle = {
    Text = "Exaltar · Dois"
  },
  Voice_90348_AwakerVoiceContent = {
    Text = "Ainda não conseguiu... voar para fora..."
  },
  Voice_90348_AwakerVoiceTitle = {
    Text = "Investigação Interrompida"
  },
  Voice_90349_AwakerVoiceContent = {
    Text = "Vento, espalhe-se!"
  },
  Voice_90349_AwakerVoiceTitle = {
    Text = "Habilidade Especial · Dois"
  },
  Voice_90350_AwakerVoiceTitle = {
    Text = "Acertar·III"
  },
  Voice_90351_AwakerVoiceContent = {
    Text = "Saudações, é um prazer conhecê-lo, sou Castor... Há algo mais que eu deva dizer? Desculpe, não sou muito bom com palavras. Se houver algo que precise que eu saiba, me avise a qualquer momento."
  },
  Voice_90351_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_90352_AwakerVoiceContent = {
    Text = "Nada demais…"
  },
  Voice_90352_AwakerVoiceTitle = {Text = "Acertar·1"},
  Voice_90353_AwakerVoiceContent = {Text = "Caia!"},
  Voice_90353_AwakerVoiceTitle = {Text = "Ataque·II"},
  Voice_90354_AwakerVoiceContent = {
    Text = "Tenho muitas coisas que nunca vi, muitas coisas que nunca fiz, e agora a água verde-escura e desoladora dos lagos e os densos nevoais que perduravam já não nos aprisionarão mais. Oceano, grandes cidades, campos e pastagens — todos os lugares mencionados naquele manuscrito, quero vê-los com meus próprios olhos, ao lado de Pólux e de você."
  },
  Voice_90354_AwakerVoiceTitle = {
    Text = "Iluminar·Construção"
  },
  Voice_90354_UnlockDesc = {
    Text = "Nível de iluminação atingiu 11 para desbloquear"
  },
  Voice_90355_AwakerVoiceContent = {
    Text = "Quando você ouvir o farfalhar das folhas nas árvores, saberá que já estou ao seu lado."
  },
  Voice_90355_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Cinco"
  },
  Voice_90355_UnlockDesc = {
    Text = "Nível de afinidade atingido 10 desbloqueado"
  },
  Voice_90356_AwakerVoiceContent = {
    Text = "Essas penas escuras tornaram-se ainda mais profundas."
  },
  Voice_90356_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · I"
  },
  Voice_90357_AwakerVoiceContent = {
    Text = "Na verdade, o que mais invejo é exatamente o modo como você e seus companheiros se relacionam, sem suspeitas e com plena confiança mútua. A sensação de ser esquecido, traído... é algo extremamente doloroso."
  },
  Voice_90357_AwakerVoiceTitle = {
    Text = "Conversa·Coisas odiadas"
  },
  Voice_90358_AwakerVoiceContent = {
    Text = "Aquela grande ladrão me disse que poderia me ensinar as técnicas mais poderosas de sobrevivência nas ruas, bastando pagar quinhentos leos... Eu fui enganado? Não, acredito que é um conhecimento muito valioso para aprender, exatamente o que eu e Pólux precisamos... É questão de dinheiro? Entendo, então vou procurá-la e negociar, oferecendo quatrocentos e cinquenta leos, o que acha?"
  },
  Voice_90358_AwakerVoiceTitle = {
    Text = "Fofocas · Sobre Jenki"
  },
  Voice_90358_UnlockDesc = {
    Text = "Desbloqueado após adquirir o Despertar \"Jenkin\""
  },
  Voice_90359_AwakerVoiceContent = {
    Text = "Ainda consigo suportar..."
  },
  Voice_90359_AwakerVoiceTitle = {
    Text = "Acertar · II"
  },
  Voice_90360_AwakerVoiceContent = {
    Text = "Quando era pequeno, o controle e a supervisão das lanternas ainda não eram tão rígidos. Às vezes, tudo o que Pollux precisava fazer era dizer algo que nem sabíamos o quê, e milagrosamente conseguia um punhado de doces. A sensação de saborear aqueles doces... era exatamente como agora."
  },
  Voice_90360_AwakerVoiceTitle = {
    Text = "Iluminar·Visão Remota"
  },
  Voice_90360_UnlockDesc = {
    Text = "Nível de iluminação atingiu 1 para desbloquear"
  },
  Voice_90361_AwakerVoiceContent = {
    Text = "Com este corpo imortal, resistirei a todas as desgraças!"
  },
  Voice_90361_AwakerVoiceTitle = {
    Text = "Superexaltação"
  },
  Voice_90362_AwakerVoiceContent = {
    Text = "Você poderia me ensinar um pouco sobre o conhecimento de troca entre pessoas? Como negociar itens com os outros, como gerenciar a moeda obtida — é realmente um assunto profundo. Ganhar liberdade é apenas o começo; para viver de forma independente, há muito o que eu e Pólux precisamos aprender. Peço desculpas antecipadas por qualquer incômodo futuro."
  },
  Voice_90362_AwakerVoiceTitle = {
    Text = "Conversa·Sobre Guardião do Segredo"
  },
  Voice_90363_AwakerVoiceContent = {
    Text = "Espalhe-se com o vento e desapareça!"
  },
  Voice_90363_AwakerVoiceTitle = {
    Text = "Habilidade Especial · Um"
  },
  Voice_90364_AwakerVoiceContent = {
    Text = "Vento, sopre-o em direção à Boca da Morte!"
  },
  Voice_90364_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_90365_AwakerVoiceContent = {
    Text = "Pólux, ele... apesar de ter sido influenciado por muitas ideias negativas do Senhor da Lanterna, no fundo ele não é mau. Ele apenas desejava desesperadamente o reconhecimento do Senhor da Lanterna e dos seguidores, a ponto de se importar excessivamente com as necessidades deles. Em vez de dizer que ele é muito egoísta, seria mais preciso dizer que ele sempre teve medo de perder aquele \"ego\"."
  },
  Voice_90365_AwakerVoiceTitle = {
    Text = "Conversa · Sobre Pólux"
  },
  Voice_90365_UnlockDesc = {
    Text = "Desbloqueado após adquirir o Despertar \"Polux\""
  },
  Voice_90366_AwakerVoiceContent = {
    Text = "Desculpe, não foi intencional eu me distrair... Você perguntou o que é esta pena? É... a coisa mais importante para ele, e também a coisa mais importante para mim. É linda, não é?"
  },
  Voice_90366_AwakerVoiceTitle = {
    Text = "Conversa·Coisas favoritas"
  },
  Voice_90367_AwakerVoiceContent = {
    Text = "Naquela época, todos os dias tínhamos que estudar teologia sob a orientação de Albino ou dos Guardadores da Luz, e naquela época meu maior desejo era que, um dia, os textos sagrados fossem reescritos, tornando-se mais curtos e em menor quantidade. Assim, eu não teria que decorá-los até ficar tonto e ser criticado pelos severos Guardadores da Luz."
  },
  Voice_90367_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_90367_UnlockDesc = {
    Text = "Nível de iluminação atingiu 2 para desbloquear"
  },
  Voice_90368_AwakerVoiceContent = {
    Text = "Obrigado por me conceder a chave que me dá acesso à liberdade."
  },
  Voice_90368_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · Três"
  },
  Voice_90369_AwakerVoiceContent = {
    Text = "Estas asas finalmente cresceram até atingir sua forma mais plena, tão fortes e poderosas. Agora posso levar você e Pólux ao mesmo tempo; quando quiser voar para o céu, basta me chamar em voz alta."
  },
  Voice_90369_AwakerVoiceTitle = {
    Text = "Iluminar·Florescer"
  },
  Voice_90369_UnlockDesc = {
    Text = "Nível de iluminação atingiu 15 para desbloquear"
  },
  Voice_90370_AwakerVoiceContent = {
    Text = "Esconda-se atrás das asas!"
  },
  Voice_90370_AwakerVoiceTitle = {
    Text = "Habilidade·Um"
  },
  Voice_90371_AwakerVoiceContent = {
    Text = "Finalmente... vi o vasto céu estrelado mencionado naquele livro."
  },
  Voice_90371_AwakerVoiceTitle = {
    Text = "Investigação Bem-sucedida"
  },
  Voice_90372_AwakerVoiceContent = {
    Text = "Antes, a Mestra... Juliette também frequentemente tinha momentos calorosos conosco. Ela nunca se poupava em mostrar aquele sorriso gentil a todos, fazendo-nos temer desapontar suas expectativas. Basta ela sorrir e acariciar sua cabeça, que qualquer palavra de recusa se torna impossível de ser dita. Hmm, agora não é mais assim. Você pode acariciar minha cabeça à vontade."
  },
  Voice_90372_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexão"
  },
  Voice_90372_UnlockDesc = {
    Text = "Nível de iluminação atingiu 3 para desbloquear"
  },
  Voice_90373_AwakerVoiceContent = {
    Text = "Eu fui imerso por muito, muito tempo naquela gosma negra, por tanto tempo que cheguei a esquecer o que era o tempo, por tanto tempo... que até mesmo Pólux me esqueceu. O que ela traz não é dor física, mas um medo profundo da alma, de ver-se desaparecer diante dos próprios olhos."
  },
  Voice_90373_AwakerVoiceTitle = {
    Text = "Conversa fiada·Sobre a crise"
  },
  Voice_90374_AwakerVoiceContent = {
    Text = "Desde crianças, não nos era permitido ter muita interação com outras pessoas. A palavra \"amigo\" só foi conhecida muito tempo depois. Pollux e eu não tínhamos ninguém além um do outro — irmãos, amigos, prisioneiros na mesma cela. Agora, chegou a hora de fazer alguns novos amigos."
  },
  Voice_90374_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Dois"
  },
  Voice_90374_UnlockDesc = {
    Text = "Nível de afinidade atingido 4 desbloqueado"
  },
  Voice_90375_AwakerVoiceContent = {Text = "Afaste-se!"},
  Voice_90375_AwakerVoiceTitle = {
    Text = "Defesa · I"
  },
  Voice_90376_AwakerVoiceContent = {
    Text = "Uma escola onde todos podem se comunicar livremente e fazer amigos como quiserem? Você diz que aqui não se estuda teologia e ainda se pode escolher entre vários cursos... e até faltar às aulas? Hmm, realmente um lugar maravilhoso."
  },
  Voice_90376_AwakerVoiceTitle = {
    Text = "Conversa·Sobre Missaga"
  },
  Voice_90377_AwakerVoiceTitle = {
    Text = "Golpe·Quatro"
  },
  Voice_90378_AwakerVoiceContent = {
    Text = "Saia do caminho!"
  },
  Voice_90378_AwakerVoiceTitle = {Text = "Ataque·Um"},
  Voice_95050_AwakerVoiceContent = {
    Text = "O ímpio... certamente será punido..."
  },
  Voice_95050_AwakerVoiceTitle = {
    Text = "Investigação Interrompida"
  },
  Voice_95051_AwakerVoiceContent = {
    Text = "Meu coração brilha com luz!"
  },
  Voice_95051_AwakerVoiceTitle = {
    Text = "Exaltar · Dois"
  },
  Voice_95052_AwakerVoiceContent = {Text = "Impureza."},
  Voice_95052_AwakerVoiceTitle = {
    Text = "Defesa · I"
  },
  Voice_95053_AwakerVoiceContent = {
    Text = "Uma fiel excessivamente fanática, que talvez aos olhos do mundo seja apenas uma louca irracional. Embora ela tenha se desviado do caminho, a determinação de dedicar tudo aos deuses é algo que a maioria dos homens comuns não consegue alcançar. Quanto a ela... sinto apenas uma tristeza de quem reconhece um semelhante."
  },
  Voice_95053_AwakerVoiceTitle = {
    Text = "Conversa fiada: Sobre Miryam"
  },
  Voice_95053_UnlockDesc = {
    Text = "Após obter o despertador \"Miryam\", desbloqueado"
  },
  Voice_95054_AwakerVoiceContent = {
    Text = "Eu trarei a liderança e o julgamento, e o resplandor da noite branca dissipará os vossos pecados!"
  },
  Voice_95054_AwakerVoiceTitle = {
    Text = "Início da Investigação"
  },
  Voice_95055_AwakerVoiceContent = {
    Text = "Há... Já se passou tanto tempo, e ele ainda não mudou nada. Talvez eu, quando criança, nunca imaginasse que um dia eu o machucaria e lhe deveria tanto, a ponto de me sentir indigno, mesmo que esse destino trágico não estivesse sob o controle de nenhum de nós. Passamos por tantas separações, mas, já que voltei, a partir de agora, nada mais poderá nos separar, nem mesmo a morte."
  },
  Voice_95055_AwakerVoiceTitle = {
    Text = "Conversa: Sobre Castor"
  },
  Voice_95055_UnlockDesc = {
    Text = "Desbloqueado após obter o Despertar \"Castor\""
  },
  Voice_95056_AwakerVoiceContent = {
    Text = "Antes, eu odiava muitas coisas. Servos descorteses, subordinados que não respeitavam a hierarquia, hereges que desrespeitavam os deuses... Mas agora, apenas a lanterna! Liriet e seu culto trouxeram a mim e meu irmão uma dor irreparável. Juro pelo nome do Filho Santo, eu não permitirei que essa dor volte a acontecer a outras pessoas!"
  },
  Voice_95056_AwakerVoiceTitle = {
    Text = "Conversa·Coisas odiadas"
  },
  Voice_95057_AwakerVoiceContent = {
    Text = "Seguirei o caminho da luz até o fim dos meus dias."
  },
  Voice_95057_AwakerVoiceTitle = {
    Text = "Despertar do Conhecimento Espiritual"
  },
  Voice_95058_AwakerVoiceContent = {
    Text = "A luz do Portador da Luz finalmente dissipará a longa noite!"
  },
  Voice_95058_AwakerVoiceTitle = {
    Text = "Sobre-Exaltação Aliemus Explosão·II"
  },
  Voice_95059_AwakerVoiceContent = {
    Text = "Você sempre foi tão generoso e gentil; vou compreender profundamente o calor desta luz."
  },
  Voice_95059_AwakerVoiceTitle = {
    Text = "Atualizar·II"
  },
  Voice_95060_AwakerVoiceContent = {
    Text = "Apostolo do Portador da Luz, nascido da Noite Branca, dispersador das trevas, Sagrado Coração e Filho Sagrado, eu, Pólux, venho em resposta ao seu chamado, oferecendo-lhe meu poder das trevas e minha alma luminosa."
  },
  Voice_95060_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_95061_AwakerVoiceTitle = {
    Text = "Golpe·Quatro"
  },
  Voice_95062_AwakerVoiceContent = {
    Text = "Lave seus pecados!"
  },
  Voice_95062_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_95063_AwakerVoiceContent = {
    Text = "Antes, todos me disseram que essa cor negra, semelhante a um abismo, era minha fé e a bênção que eu traria aos fiéis. Hoje, essa escuridão já me corroeu por completo, tornando-se parte de mim... mas o coração pulsante dentro deste corpo pecaminoso será sempre um lugar que ela não poderá atingir. Fique tranquilo, com certeza usarei a habilidade concedida por essa escuridão para trazer a verdadeira felicidade ao mundo!"
  },
  Voice_95063_AwakerVoiceTitle = {
    Text = "Conversa fiada·Sobre a crise"
  },
  Voice_95064_AwakerVoiceContent = {
    Text = "Vou espalhar sua grande fama; todas as coisas impuras e sujas serão purificadas pela luz."
  },
  Voice_95064_AwakerVoiceTitle = {
    Text = "Investigação Bem-sucedida"
  },
  Voice_95065_AwakerVoiceContent = {
    Text = "Os pecados do passado já foram cometidos, e não se deve mais fugir deles. Ainda preciso corrigir os erros da Lanterna e guiar de volta ao caminho reto aqueles que se perderam. Deixe-me carregar sobre mim os meus pecados. Então, responderei a esta luz, responderei ao seu chamado, e seguirei pelo verdadeiro caminho que pertence ao Filho Santo."
  },
  Voice_95065_AwakerVoiceTitle = {
    Text = "Iluminar·Construção"
  },
  Voice_95065_UnlockDesc = {
    Text = "Nível de iluminação atingiu 11 para desbloquear"
  },
  Voice_95066_AwakerVoiceContent = {
    Text = "Que coração compassivo o seu, por me perdoar mesmo sendo alguém repleto de pecados. Posso sentir, em sua alma, uma luz tão pura, mais brilhante até do que a chama de uma tocha. Talvez você possa guiar o meu coração perdido…"
  },
  Voice_95066_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Um"
  },
  Voice_95066_UnlockDesc = {
    Text = "Nível de afinidade atingido 2 desbloqueado"
  },
  Voice_95067_AwakerVoiceContent = {
    Text = "Essas trevas, as trevas espalhadas pelo feitiço de Yliette, sempre cobriram minha mente... Mas agora, nelas surgiu uma luz! Esse pequeno ponto de luz, será que quer me dizer algo?"
  },
  Voice_95067_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_95067_UnlockDesc = {
    Text = "Nível de iluminação atingiu 2 para desbloquear"
  },
  Voice_95068_AwakerVoiceContent = {
    Text = "Dizem que ela já foi uma santa também, mas esses modos grosseiros, essas ações e palavras arrogantes... O quê? Ela nem sabe recitar uma única passagem de oração? Com uma atitude tão irreverente, é quase embaraçoso até para o seu próprio deus."
  },
  Voice_95068_AwakerVoiceTitle = {
    Text = "Conversa: Sobre Murphy"
  },
  Voice_95068_UnlockDesc = {
    Text = "Desbloqueado após obter Despertador \"Murphy\""
  },
  Voice_95069_AwakerVoiceContent = {
    Text = "Aquele que consegue guiar as pessoas para fora da névoa é o verdadeiro portador da luz com corpo de puro prata. O paraíso sem pecado mencionado por Liet é, na verdade, construído sobre montanhas de cadáveres de fiéis. Como Santo Filho, espalharei a nova palavra de Deus a todos os crentes dignos de salvação."
  },
  Voice_95069_AwakerVoiceTitle = {
    Text = "Conversa·Sobre Missaga"
  },
  Voice_95070_AwakerVoiceContent = {
    Text = "Ó tu que me guias e me iluminas, aquele que outrora me manteve cego sob falsos significados, agora sob tua orientação, encontrei minha verdadeira missão — corrigir os hereges tolos e distorcidos, trazendo ao mundo uma luz eterna e inextinguível. Conheço tua natureza altruísta, tu não necessitas de minha devoção ou oferendas, então permite-me, por favor, acompanhar-te de perto, registrando cada uma das tuas palavras e ações sagradas, para que, nas trevas da noite, elas me sirvam como guia em meu caminho."
  },
  Voice_95070_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Cinco"
  },
  Voice_95070_UnlockDesc = {
    Text = "Nível de afinidade atingido 10 desbloqueado"
  },
  Voice_95071_AwakerVoiceContent = {
    Text = "Com algemas, banhado pela escuridão, caminhando em direção àquela luz, determinado... É isso que você quer me dizer?"
  },
  Voice_95071_AwakerVoiceTitle = {
    Text = "Iluminar: Insight"
  },
  Voice_95071_UnlockDesc = {
    Text = "Nível de iluminação atingiu 7 para desbloquear"
  },
  Voice_95072_AwakerVoiceContent = {
    Text = "Um servo da luz perdeu a chama em suas mãos, esta dor cega realmente me deixa angustiado. Sinceramente, peço que salve esta alma perdida. Por favor, segure minha mão, aproxime-se deste coração sagrado, e me conceda a orientação para alcançar a luz..."
  },
  Voice_95072_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Três"
  },
  Voice_95072_UnlockDesc = {
    Text = "Nível de afinidade atingido 6 desbloqueado"
  },
  Voice_95073_AwakerVoiceContent = {
    Text = "Infeliz criança, mas já que ela dedicou sua vida à sua causa, certamente alcançará a redenção final. Mas por que seu amigo, aquele macaco, também recebeu sua graça? Aquele menino malévolo até roubou o instrumento sagrado de minhas orações! Certamente há uma inundação de pecados escondida em sua alma. Que desrespeito! Que desrespeito!"
  },
  Voice_95073_AwakerVoiceTitle = {
    Text = "Conversa fiada: Sobre Aigis e Jenkins"
  },
  Voice_95073_UnlockDesc = {
    Text = "Desbloqueia após obter os Corpos Despertados \"Egis\" e \"Jenkin\""
  },
  Voice_95074_AwakerVoiceContent = {
    Text = "Saia rápido."
  },
  Voice_95074_AwakerVoiceTitle = {Text = "Defesa·II"},
  Voice_95075_AwakerVoiceContent = {
    Text = "A luz do Portador da Luz finalmente iluminará a longa noite!"
  },
  Voice_95075_AwakerVoiceTitle = {
    Text = "Superexaltação"
  },
  Voice_95076_AwakerVoiceContent = {
    Text = "Ah... Já vi, a imensa força, a verdade do mundo... Já compreendi meus erros do passado, você é verdadeiramente o Portador da Luz! Permita-me ser seu fiel apóstolo, este coração destinado ao Portador da Luz, doravante baterá e tremerá em reverência por você..."
  },
  Voice_95076_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Quatro"
  },
  Voice_95076_UnlockDesc = {
    Text = "Nível de afinidade atingido 8 desbloqueado"
  },
  Voice_95077_AwakerVoiceContent = {
    Text = "A redenção cega daquele padre é realmente uma atitude tola e inaceitável. O evangelho de Deus deve ser concedido naturalmente apenas aos justos e piedosos. Se até os próprios apóstolos de Deus não possuírem olhos perspicazes para discernir, concedendo recompensas aos ímpios e pecadores impenitentes e cheios de pecados, contaminando o puro reino de Deus, isso não seria uma traição tanto aos deuses quanto àqueles justos?"
  },
  Voice_95077_AwakerVoiceTitle = {
    Text = "Conversa fiada: Sobre o Salvador"
  },
  Voice_95077_UnlockDesc = {
    Text = "Desbloqueado após adquirir o Despertar \"Salvador\""
  },
  Voice_95078_AwakerVoiceContent = {
    Text = "Meu coração brilha com luz!"
  },
  Voice_95078_AwakerVoiceTitle = {
    Text = "Fúria Explosiva"
  },
  Voice_95079_AwakerVoiceContent = {Text = "Hah!"},
  Voice_95079_AwakerVoiceTitle = {Text = "Ataque·II"},
  Voice_95080_AwakerVoiceContent = {
    Text = "Quando criança, eu só queria voar para fora da gaiola, pois sempre acreditava que este lugar, que só traz sofrimento, não era digno de nostalgia. Mas agora, após duas vidas vividas, percebi que a liberdade não é a única coisa que almejo. Ver os fiéis ao saberem que receberão a redenção, com expressões cheias de fé, esperança e gratidão, é o verdadeiro significado de ser o Filho de Deus."
  },
  Voice_95080_AwakerVoiceTitle = {
    Text = "Conversa·Coisas favoritas"
  },
  Voice_95081_AwakerVoiceContent = {
    Text = "Durante o tempo em que segui Juliette, cometi muitos erros e não deveria mais receber uma confiança como esta. Mesmo assim, você ainda escolheu a mim... Não se preocupe, vou buscar novamente minha própria crença. O Filho Sagrado não decepcionará mais seu povo, nem a você."
  },
  Voice_95081_AwakerVoiceTitle = {
    Text = "Iluminar·Visão Remota"
  },
  Voice_95081_UnlockDesc = {
    Text = "Nível de iluminação atingiu 1 para desbloquear"
  },
  Voice_95082_AwakerVoiceContent = {
    Text = "Vou usar com gratidão o que me foi concedido."
  },
  Voice_95082_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · I"
  },
  Voice_95083_AwakerVoiceContent = {
    Text = "Desrespeito!"
  },
  Voice_95083_AwakerVoiceTitle = {
    Text = "Acertar · II"
  },
  Voice_95084_AwakerVoiceContent = {Text = "Droga."},
  Voice_95084_AwakerVoiceTitle = {Text = "Acertar·1"},
  Voice_95085_AwakerVoiceTitle = {
    Text = "Acertar·III"
  },
  Voice_95086_AwakerVoiceContent = {
    Text = "Em meu nome!"
  },
  Voice_95086_AwakerVoiceTitle = {Text = "Ataque·Um"},
  Voice_95087_AwakerVoiceContent = {
    Text = "Eu vi! Aquele raio de luz, aquele brilhando nas profundezas da consciência, está ficando cada vez mais brilhante! Ele está me chamando..."
  },
  Voice_95087_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexão"
  },
  Voice_95087_UnlockDesc = {
    Text = "Nível de iluminação atingiu 3 para desbloquear"
  },
  Voice_95088_AwakerVoiceContent = {
    Text = "Na infância, Castor e eu servimos juntos como Filhos Sagrados. Naquela época, eu sempre achei que ele fosse muito lento e desajeitado, precisando que eu próprio traçasse o caminho para o futuro. Hoje, conhecendo o caminho que você percorreu, compreendi que os alicerces do mundo são construídos e abertos por pessoas íntegras e dedicadas como você e ele."
  },
  Voice_95088_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Dois"
  },
  Voice_95088_UnlockDesc = {
    Text = "Nível de afinidade atingido 4 desbloqueado"
  },
  Voice_95089_AwakerVoiceContent = {
    Text = "Minha luz, desde que recebi sua orientação, acho que já estou trilhando o caminho totalmente correto. Até agora, ainda resta uma dúvida ao seu seguidor ignorante: aquele lendário reino puro e imaculado, também está sob seu domínio? Não existe tal coisa? Está me dizendo que... o reino puro e imaculado está aqui na terra, está dentro do coração puro dos justos?"
  },
  Voice_95089_AwakerVoiceTitle = {
    Text = "Conversa·Sobre Guardião do Segredo"
  },
  Voice_95090_AwakerVoiceContent = {
    Text = "Este coração que escuta a vontade divina está cada vez mais próximo de você."
  },
  Voice_95090_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · Três"
  },
  Voice_95091_AwakerVoiceContent = {
    Text = "Você... você tem alguma vontade a me transmitir? Seu apóstolo está sempre pronto para ouvir seus ensinamentos."
  },
  Voice_95091_AwakerVoiceTitle = {
    Text = "Conversa·Toque"
  },
  Voice_95092_AwakerVoiceContent = {
    Text = "Ilumina-me, ó guia perdido! Com a sua luz, já consegui ver tudo o que precisava ver... Usarei este corpo amaldiçoado para purificar tudo o que passou e fazer com que todo o futuro se banhe sob esta luz!"
  },
  Voice_95092_AwakerVoiceTitle = {
    Text = "Iluminar·Florescer"
  },
  Voice_95092_UnlockDesc = {
    Text = "Nível de iluminação atingiu 15 para desbloquear"
  },
  Voice_95093_AwakerVoiceContent = {
    Text = "Coração Sagrado como pavio, a luz brilhará eternamente!"
  },
  Voice_95093_AwakerVoiceTitle = {
    Text = "Habilidade·Um"
  },
  Voice_95391_AwakerVoiceContent = {
    Text = "Você busca salvar este mundo cruel? Vamos lá, pequena criatura cheia de esperança."
  },
  Voice_95391_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Um"
  },
  Voice_95391_UnlockDesc = {
    Text = "Nível de afinidade atingido 2 desbloqueado"
  },
  Voice_95392_AwakerVoiceContent = {
    Text = "Vá em frente, pegue essas coisas para brincar. Dizem que são coleções tabu escavadas de algum sítio arqueológico. Não tenho interesse nesses objetos que carregam o cheiro d'Ele. Tinha intenção de queimá-los diretamente, mas pensei que talvez fossem úteis para você, então os trouxe. \nVocê pergunta como eu os consegui? É claro que algumas pessoas \"voluntariamente\" me deram. Não se preocupe, a origem está garantidamente \"limpa\"."
  },
  Voice_95392_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Três"
  },
  Voice_95392_UnlockDesc = {
    Text = "Nível de afinidade atingido 6 desbloqueado"
  },
  Voice_95393_AwakerVoiceContent = {
    Text = "Caça concluída. Como recompensa, pague com o sorriso da criança."
  },
  Voice_95393_AwakerVoiceTitle = {
    Text = "Investigação Bem-sucedida"
  },
  Voice_95394_AwakerVoiceContent = {
    Text = "Sabe de uma coisa, pequeno, as balas que saem dessas duas armas não são balas comuns, são a concentração de desejo e maldade.\nEste caos desordenado forma chamas semelhantes à carne, e na sétima explosão do outro lado, tudo será arrastado para o inferno e queimado.\n\n."
  },
  Voice_95394_AwakerVoiceTitle = {
    Text = "Conversa: Sobre armas"
  },
  Voice_95395_AwakerVoiceContent = {
    Text = "Não precisa se pressionar tanto, meu Guardião do Segredo. Embora eu saiba que este é um caminho sinuoso que exige ação imediata, e que um pequeno passo em falso pode levar à destruição total. Mas se continuar assim, um dia você acabará desmaiando de exaustão. Se precisar de ajuda, pode vir conversar comigo, como membro da família."
  },
  Voice_95395_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Quatro"
  },
  Voice_95395_UnlockDesc = {
    Text = "Nível de afinidade atingido 8 desbloqueado"
  },
  Voice_95396_AwakerVoiceContent = {
    Text = "Queime, destrua, chore!"
  },
  Voice_95396_AwakerVoiceTitle = {
    Text = "Exaltar · Dois"
  },
  Voice_95397_AwakerVoiceContent = {
    Text = "Desaparecer."
  },
  Voice_95397_AwakerVoiceTitle = {Text = "Ataque·II"},
  Voice_95398_AwakerVoiceContent = {
    Text = "Meu campo de visão está mais claro. Vejo o que está escondido nas profundezas do abismo... Para vocês, preciso de um poder ainda maior..."
  },
  Voice_95398_AwakerVoiceTitle = {
    Text = "Iluminar·Construção"
  },
  Voice_95398_UnlockDesc = {
    Text = "Nível de iluminação atingiu 11 para desbloquear"
  },
  Voice_95399_AwakerVoiceContent = {
    Text = "Venha, Guardião, sente-se mais perto, agora está muito distante.\nSabe, quando te vi pela primeira vez, nunca imaginei que um dia poderia remover aqui, diante de você, essa casca que me chamam de cruel e fria. É um pouco engraçado, não é? O temido Senhor da Explosão que deseja encontrar uma família com quem possa compartilhar sinceramente seus sentimentos.\nPrometa-me que, se chegar o dia em que você não aguentar mais... chame meu nome em seu coração, e eu o levarei comigo para o meu reino. Embora isso apenas atrase o inevitável, ao menos no último momento, você poderá descansar em paz, em meus braços."
  },
  Voice_95399_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Cinco"
  },
  Voice_95399_UnlockDesc = {
    Text = "Nível de afinidade atingido 10 desbloqueado"
  },
  Voice_95400_AwakerVoiceContent = {
    Text = "Enfrente seu fim."
  },
  Voice_95400_AwakerVoiceTitle = {
    Text = "Carta de Habilidade·Quatro"
  },
  Voice_95401_AwakerVoiceContent = {Text = "Ugh!"},
  Voice_95401_AwakerVoiceTitle = {Text = "Acertar·1"},
  Voice_95402_AwakerVoiceContent = {
    Text = "Na bilhões de desejos e más intenções, queime!"
  },
  Voice_95402_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_95403_AwakerVoiceContent = {
    Text = "Depois de uma caçada bem-sucedida, sempre é necessário um banquete de celebração. Venha, prove a carne de camelo que assi e a tequila que acabei de conseguir. Espere, pequenino, você não pode beber álcool... Então beba o meu suco especial!"
  },
  Voice_95403_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Dois"
  },
  Voice_95403_UnlockDesc = {
    Text = "Nível de afinidade atingido 4 desbloqueado"
  },
  Voice_95404_AwakerVoiceContent = {
    Text = "O que foi, pequeno? Está querendo um abraço? Vem cá, meu peito quente está sempre aberto para você... Haha, não seja tímido, é muito natural que a irmã mais velha se importe com os mais novos, não é mesmo?"
  },
  Voice_95404_AwakerVoiceTitle = {
    Text = "Conversa·Toque"
  },
  Voice_95406_AwakerVoiceContent = {Text = "Maldito."},
  Voice_95406_AwakerVoiceTitle = {
    Text = "Acertar · II"
  },
  Voice_95407_AwakerVoiceContent = {
    Text = "Enfrente a Morte Âmbar."
  },
  Voice_95407_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_95408_AwakerVoiceContent = {
    Text = "Retirem-se primeiro, eu fico para trás... Fiquem tranquilos, eu voltarei com vida."
  },
  Voice_95408_AwakerVoiceTitle = {
    Text = "Investigação Interrompida"
  },
  Voice_95409_AwakerVoiceContent = {
    Text = "Vamos, vamos queimar tudo até virar cinzas!"
  },
  Voice_95409_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · Três"
  },
  Voice_95410_AwakerVoiceContent = {
    Text = "Fogo Explosivo, reacenda-se aqui!"
  },
  Voice_95410_AwakerVoiceTitle = {
    Text = "Despertar do Conhecimento Espiritual"
  },
  Voice_95411_AwakerVoiceContent = {
    Text = "O fogo está ficando cada vez mais forte. A pequena criatura quer ver um espetáculo de fogos de artifício?"
  },
  Voice_95411_AwakerVoiceTitle = {
    Text = "Atualizar·II"
  },
  Voice_95412_AwakerVoiceContent = {
    Text = "Aqueles que pisoteiam a humanidade, se escondem nas sombras e usam @1 como matéria-prima para seus sacrifícios e pesquisas sujas... um dia, eu vou matar todos eles."
  },
  Voice_95412_AwakerVoiceTitle = {
    Text = "Conversa·Coisas odiadas"
  },
  Voice_95413_AwakerVoiceContent = {Text = "Pim!"},
  Voice_95413_AwakerVoiceTitle = {Text = "Ataque·Um"},
  Voice_95414_AwakerVoiceContent = {
    Text = "Encontrá-lo-ei, não importa para qual canto do universo ele se esconda, eu o encontrarei no fim.\nVou fazer com que este rato sujo pague com tudo o que tem. No momento em que o encontrar, toda alegria e prazer deste mundo serão queimados no inferno.\nFique tranquilo, na cerimônia fúnebre dele, reservarei um lugar especial para você, para que possamos juntos saborear o seu último grito de agonia."
  },
  Voice_95414_AwakerVoiceTitle = {
    Text = "Conversa: Sobre N"
  },
  Voice_95415_AwakerVoiceContent = {
    Text = "Ouça o lamento da fusão estelar."
  },
  Voice_95415_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_95415_UnlockDesc = {
    Text = "Nível de iluminação atingiu 2 para desbloquear"
  },
  Voice_95416_AwakerVoiceContent = {
    Text = "Enfrente seu fim."
  },
  Voice_95416_AwakerVoiceTitle = {
    Text = "Habilidade·Um"
  },
  Voice_95417_AwakerVoiceContent = {
    Text = "Você é um membro da minha família de quem me orgulho muito, seja mais confiante, meu Guardião do Segredo! Não importa o que aconteça, eu serei sempre seu apoio mais forte."
  },
  Voice_95417_AwakerVoiceTitle = {
    Text = "Conversa·Sobre Guardião do Segredo"
  },
  Voice_95418_AwakerVoiceContent = {
    Text = "Essas existências indescritíveis estão corroendo este mundo, e você inevitavelmente se tornará seu inimigo. Mas isso não importa, pois eu estarei atrás de você."
  },
  Voice_95418_AwakerVoiceTitle = {
    Text = "Iluminar: Insight"
  },
  Voice_95418_UnlockDesc = {
    Text = "Nível de iluminação atingiu 7 para desbloquear"
  },
  Voice_95420_AwakerVoiceContent = {
    Text = "Queime, destrua, chore!"
  },
  Voice_95420_AwakerVoiceTitle = {
    Text = "Fúria Explosiva"
  },
  Voice_95421_AwakerVoiceContent = {
    Text = "Mantenha a calma."
  },
  Voice_95421_AwakerVoiceTitle = {
    Text = "Defesa · I"
  },
  Voice_95422_AwakerVoiceContent = {Text = "Recuar."},
  Voice_95422_AwakerVoiceTitle = {Text = "Defesa·II"},
  Voice_95423_AwakerVoiceContent = {
    Text = "Você pergunta o que penso sobre a corrosão? É como perguntar a um pequeno rato que ronda os esgotos o que ele acha dos nobres senhores lá no alto. Minha resposta é apenas uma: aversão instintiva do corpo. Se possível, eu apreciaria os seus gritos de morte sob minhas balas enquanto bebo uma deliciosa bebida de leite de camelo."
  },
  Voice_95423_AwakerVoiceTitle = {
    Text = "Conversa fiada·Sobre a crise"
  },
  Voice_95424_AwakerVoiceContent = {
    Text = "Quer que as chamas fiquem mais ardentes?"
  },
  Voice_95424_AwakerVoiceTitle = {
    Text = "Iluminar·Visão Remota"
  },
  Voice_95424_UnlockDesc = {
    Text = "Nível de iluminação atingiu 1 para desbloquear"
  },
  Voice_95425_AwakerVoiceContent = {
    Text = "Só venho aqui quando recebo uma encomenda. Se o pequeno quiser me procurar, use este feitiço. Vamos, repita comigo: ... Ia! KathiguRa!"
  },
  Voice_95425_AwakerVoiceTitle = {
    Text = "Conversa·Sobre Missaga"
  },
  Voice_95426_AwakerVoiceContent = {
    Text = "Há não muito tempo, ainda estávamos naquela cidade decadente, lutando para sobreviver com brutalidade e astúcia. Mesmo tendo nos tornado uma \"grande força\", tínhamos que manter total atenção diante dos lordes, das milícias e dos \"senhores cavaleiros\" que se recusavam a sair da história. Mas agora é diferente: todos se tornaram meu \"clã\" e não precisam mais se curvar à vontade dos outros. Bem, ainda há um pequenino que se perdeu por aí, mas acredito que ele ficará bem, afinal, todas as vezes que eu estava ocupado lá fora, era ele quem cuidava de todos os outros."
  },
  Voice_95426_AwakerVoiceTitle = {
    Text = "Conversa: Sobre família"
  },
  Voice_95427_AwakerVoiceContent = {
    Text = "Este é o inimigo do pequeno? Então - a caçada começa."
  },
  Voice_95427_AwakerVoiceTitle = {
    Text = "Início da Investigação"
  },
  Voice_95428_AwakerVoiceContent = {
    Text = "Eu sou o Mestre da Explosão que nunca será esquecido! Declaração! Todas as coisas perecerão!"
  },
  Voice_95428_AwakerVoiceTitle = {
    Text = "Sobre-Exaltação Aliemus Explosão·II"
  },
  Voice_95429_AwakerVoiceContent = {
    Text = "A combustão e a destruição são tudo para mim, eu adoro a morte que vem da caça... Você acha que eu diria isso?  \nhahaha, foi brincadeira, para mim, o mais importante são as pessoas ao meu redor. Nada é mais importante do que elas, nem mesmo... eu mesmo.\n\n."
  },
  Voice_95429_AwakerVoiceTitle = {
    Text = "Conversa·Coisas favoritas"
  },
  Voice_95430_AwakerVoiceContent = {
    Text = "O pequeno está com problemas? Então, respondendo ao chamado, Kittygura chegará com a destruição. Vamos fazer com que todos os problemas desapareçam em um estouro."
  },
  Voice_95430_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_95431_AwakerVoiceContent = {
    Text = "O sabor do poder... Quer experimentar com alguma criatura azarada?"
  },
  Voice_95431_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexão"
  },
  Voice_95431_UnlockDesc = {
    Text = "Nível de iluminação atingiu 3 para desbloquear"
  },
  Voice_95432_AwakerVoiceContent = {
    Text = "Eu sou o Mestre da Explosão que nunca será esquecido! Proclamo! Todas as coisas perecerão!"
  },
  Voice_95432_AwakerVoiceTitle = {
    Text = "Superexaltação"
  },
  Voice_95433_AwakerVoiceContent = {
    Text = "A lendária rainha de Aran, a grande corporeidade do desejo Tifreyah Soder, já a vi uma vez enquanto perseguia N. Embora eu não concorde com o que ela fez, sendo justo, se fosse a única maneira que eu encontrasse para que todos sobrevivessem àquele olhar d'Ele... Eu também faria a mesma escolha. Nesse aspecto, não há diferença entre ela e eu."
  },
  Voice_95433_AwakerVoiceTitle = {
    Text = "Conversa fiada: Sobre Táias"
  },
  Voice_95433_UnlockDesc = {
    Text = "Após obter o despertador \"Táias\", desbloqueado"
  },
  Voice_95434_AwakerVoiceContent = {
    Text = "Tem um ótimo toque, a arma está bem mantida."
  },
  Voice_95434_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · I"
  },
  Voice_95435_AwakerVoiceContent = {
    Text = "Eu sou o fogo, a chama, o Caos que arde eternamente... Eu levarei todos... para casa..."
  },
  Voice_95435_AwakerVoiceTitle = {
    Text = "Iluminar·Florescer"
  },
  Voice_95435_UnlockDesc = {
    Text = "Nível de iluminação atingiu 15 para desbloquear"
  },
  Voice_96361_AwakerVoiceContent = {
    Text = "Aqui, a torre gótica tem um ar clássico, e os despertados aqui também têm um cheiro que nunca senti antes — um aroma que mistura a fragrância dos mortos e um toque de vitalidade dos vivos. É realmente... tentador experimentar."
  },
  Voice_96361_AwakerVoiceTitle = {
    Text = "Conversa·Sobre Missaga"
  },
  Voice_96362_AwakerVoiceContent = {
    Text = "Quem busca a morte, realizarei seu desejo."
  },
  Voice_96362_AwakerVoiceTitle = {
    Text = "Exaltar · Dois"
  },
  Voice_96363_AwakerVoiceContent = {
    Text = "Já estou ansioso para começar."
  },
  Voice_96363_AwakerVoiceTitle = {
    Text = "Despertar do Conhecimento Espiritual"
  },
  Voice_96364_AwakerVoiceContent = {
    Text = "Seu coração está acelerado, não está? Venha, meu querido convidado, torne-se meu honrado convidado e aproveite este banquete conosco. Deixe-me guiá-lo a saborear juntos cada sutil resquício deixado pelos espíritos."
  },
  Voice_96364_AwakerVoiceTitle = {
    Text = "Iluminar·Florescer"
  },
  Voice_96364_UnlockDesc = {
    Text = "Nível de iluminação atingiu 15 para desbloquear"
  },
  Voice_96365_AwakerVoiceContent = {
    Text = "Shh, não fale, vamos ouvir em silêncio a voz dos mortos."
  },
  Voice_96365_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Um"
  },
  Voice_96365_UnlockDesc = {
    Text = "Nível de afinidade atingido 2 desbloqueado"
  },
  Voice_96366_AwakerVoiceContent = {
    Text = "A beleza eterna é nossa fé. Aplicar lentamente a dissolução sobre os vivos, apagando todas as marcas de existência... para a vida, isso é um tormento puro e cruel."
  },
  Voice_96366_AwakerVoiceTitle = {
    Text = "Conversa fiada·Sobre a crise"
  },
  Voice_96367_AwakerVoiceContent = {
    Text = "Tal como eu, Pikman também busca a arte eterna, e deveríamos ter nos tornado melhores amigos. No entanto, ele acredita que comer é um ato que destrói a eternidade, uma visão artística realmente muito estreita."
  },
  Voice_96367_AwakerVoiceTitle = {
    Text = "Conversa·Sobre Pikman"
  },
  Voice_96367_UnlockDesc = {
    Text = "Desbloqueado após obter o despertador \"Pikman\""
  },
  Voice_96368_AwakerVoiceContent = {Text = "Ha!"},
  Voice_96368_AwakerVoiceTitle = {Text = "Ataque·Um"},
  Voice_96369_AwakerVoiceContent = {
    Text = "Nenhum adjetivo seria capaz de descrever adequadamente esse aroma embriagante que vem de você — algo ao mesmo tempo semelhante ao retrogosto ácido e rico de um vinho de Bordeaux e à riqueza densa e suave de um creme de manteiga. Ah... A expectativa pelo dia da sua morte talvez venha a se tornar a coisa mais importante da minha vida."
  },
  Voice_96369_AwakerVoiceTitle = {
    Text = "Conversa·Sobre Guardião do Segredo"
  },
  Voice_96370_AwakerVoiceContent = {
    Text = "Já vi uma cena de crime: um homem cortando lentamente a pele, as unhas, as mãos e os pés de uma jovem, mas continuamente a curando. Ele não queria que ela morresse, tampouco desejava que ela vivesse. É claro que não poderia lhe conceder uma morte tranquila; apenas o fiz experimentar repetidamente a mesma experiência que aquela jovem passou. Acho que já faz alguns anos... Para quem profana a morte, isso é bastante justo, não acha?"
  },
  Voice_96370_AwakerVoiceTitle = {
    Text = "Conversa·Coisas odiadas"
  },
  Voice_96371_AwakerVoiceContent = {
    Text = "Sou o deus que governa a morte, mas por favor, não me entenda mal, nunca crio a morte. Apenas sigo os passos da morte e colho os frutos maduros e abundantes."
  },
  Voice_96371_AwakerVoiceTitle = {
    Text = "Iluminar·Visão Remota"
  },
  Voice_96371_UnlockDesc = {
    Text = "Nível de iluminação atingiu 1 para desbloquear"
  },
  Voice_96372_AwakerVoiceContent = {
    Text = "Você também deseja o meu sabor, Excelência Guardiã dos Segredos?"
  },
  Voice_96372_AwakerVoiceTitle = {
    Text = "Conversa·Toque"
  },
  Voice_96373_AwakerVoiceContent = {
    Text = "Hoje, quem será servido na mesa?"
  },
  Voice_96373_AwakerVoiceTitle = {
    Text = "Início da Investigação"
  },
  Voice_96374_AwakerVoiceContent = {
    Text = "Concederei a vocês a honra de serem o prato principal do jantar de hoje."
  },
  Voice_96374_AwakerVoiceTitle = {
    Text = "Investigação Bem-sucedida"
  },
  Voice_96375_AwakerVoiceContent = {
    Text = "Muito desagradável."
  },
  Voice_96375_AwakerVoiceTitle = {
    Text = "Acertar·III"
  },
  Voice_96376_AwakerVoiceContent = {
    Text = "Vou trazer um descanso puro."
  },
  Voice_96376_AwakerVoiceTitle = {
    Text = "Habilidade·Um"
  },
  Voice_96377_AwakerVoiceContent = {
    Text = "Antes de cada refeição, mantenho um diálogo com os espíritos dos mortos. Para eles, serem consumidos e saboreados com atenção significa a prolongação da vida e o último instante de glória. Assim como nós anelamos por eles, eles também anelam por nós."
  },
  Voice_96377_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Três"
  },
  Voice_96377_UnlockDesc = {
    Text = "Nível de afinidade atingido 6 desbloqueado"
  },
  Voice_96378_AwakerVoiceContent = {Text = "Silêncio."},
  Voice_96378_AwakerVoiceTitle = {
    Text = "Golpe·Quatro"
  },
  Voice_96379_AwakerVoiceContent = {
    Text = "Desapareça na sombra!"
  },
  Voice_96379_AwakerVoiceTitle = {
    Text = "Habilidade·II"
  },
  Voice_96380_AwakerVoiceContent = {
    Text = "É melhor mantermos distância."
  },
  Voice_96380_AwakerVoiceTitle = {
    Text = "Defesa · I"
  },
  Voice_96381_AwakerVoiceContent = {
    Text = "Desapareça na sombra!"
  },
  Voice_96381_AwakerVoiceTitle = {
    Text = "Carta de Habilidade·Quatro"
  },
  Voice_96382_AwakerVoiceContent = {
    Text = "Por que está tão cauteloso comigo? Você não deve e nem precisa ficar nervoso, morder seres vivos vai contra minha estética."
  },
  Voice_96382_AwakerVoiceTitle = {
    Text = "Conversa·Sobre comida"
  },
  Voice_96383_AwakerVoiceContent = {
    Text = "Quem busca a morte, realizarei seu desejo."
  },
  Voice_96383_AwakerVoiceTitle = {
    Text = "Fúria Explosiva"
  },
  Voice_96384_AwakerVoiceContent = {
    Text = "Muito desagradável."
  },
  Voice_96384_AwakerVoiceTitle = {Text = "Acertar·1"},
  Voice_96385_AwakerVoiceContent = {Text = "Cuidado."},
  Voice_96385_AwakerVoiceTitle = {Text = "Defesa·II"},
  Voice_96386_AwakerVoiceContent = {
    Text = "A paixão daquela senhorita é realmente comovente, mas o cheiro dela tem um aroma úmido que parece ter fermentado demais. Mesmo ela insistindo que eu provasse um pouco, isso realmente não combina com meu gosto. Que situação difícil."
  },
  Voice_96386_AwakerVoiceTitle = {
    Text = "Chat·Sobre Leigh"
  },
  Voice_96386_UnlockDesc = {
    Text = "Após obter o despertador \"Leigh\", desbloqueado"
  },
  Voice_96387_AwakerVoiceContent = {
    Text = "Você sabia? Toda vida que se vai deixa um eco longo. Cada um com timbres diferentes, esses ecos se estendem gradualmente a partir do momento em que a morte chega, até se dissiparem lentamente entre o céu e a terra, como um chamado semelhante a um suspiro."
  },
  Voice_96387_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Dois"
  },
  Voice_96387_UnlockDesc = {
    Text = "Nível de afinidade atingido 4 desbloqueado"
  },
  Voice_96388_AwakerVoiceContent = {
    Text = "Fique tranquilo, Excelentíssimo Guardião dos Segredos, estarei sempre ao seu lado até o dia em que sua vida chegar ao fim inevitável. Naquele momento, certamente devorarei seu corpo inteiro com a cerimônia mais solene. Guardarei sua alma para sempre dentro do meu corpo."
  },
  Voice_96388_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Cinco"
  },
  Voice_96388_UnlockDesc = {
    Text = "Nível de afinidade atingido 10 desbloqueado"
  },
  Voice_96389_AwakerVoiceContent = {
    Text = "Você não consegue sentir seu próprio cheiro? Que pena, você está perdendo o aroma mais doce e mais... Ai, ai, por que está se afastando?"
  },
  Voice_96389_AwakerVoiceTitle = {
    Text = "Taxa de afinidade · Quatro"
  },
  Voice_96389_UnlockDesc = {
    Text = "Nível de afinidade atingido 8 desbloqueado"
  },
  Voice_96390_AwakerVoiceContent = {
    Text = "Já consigo ver mais mortes; a paisagem do outro lado está cada vez mais clara..."
  },
  Voice_96390_AwakerVoiceTitle = {
    Text = "Ganhar Impulso · Três"
  },
  Voice_96391_AwakerVoiceContent = {
    Text = "Entregue seu corpo a mim, deixe-me saborear você cuidadosamente, cada gota de sangue, cada pedaço de carne, cada osso."
  },
  Voice_96391_AwakerVoiceTitle = {
    Text = "Superexaltação"
  },
  Voice_96392_AwakerVoiceContent = {
    Text = "Ingredientes diferentes precisam passar por tratamentos diferentes. As vísceras precisam ser curtidas, os tendões das pernas são melhores quando cozidos lentamente, as partes ricas em gordura são adequadas para fermentação e maturação, e as partes com texturas especiais podem ser fritas, grelhadas, ou até transformadas em gelatinas de carne com aparência elegante — todas essas etapas exigem escolhas cuidadosas. É claro que preservar e destacar o sabor natural dos ingredientes é uma forma essencial de respeito."
  },
  Voice_96392_AwakerVoiceTitle = {
    Text = "Iluminar: Insight"
  },
  Voice_96392_UnlockDesc = {
    Text = "Nível de iluminação atingiu 7 para desbloquear"
  },
  Voice_96393_AwakerVoiceContent = {
    Text = "Isso pode estar um pouco frio."
  },
  Voice_96393_AwakerVoiceTitle = {Text = "Ataque·II"},
  Voice_96394_AwakerVoiceContent = {
    Text = "O empratamento dos pratos também requer grande atenção. A combinação de sabores ácidos e doces, crocantes e tenros, refrescantes e pesados, suaves e ásperos, cria uma colisão entre sabores progressivos e texturas contrastantes. Cada mordida, mastigação e retrogosto oferecem sensações diferentes, proporcionando um prazer infinito e maravilhoso, que é exatamente o que uma boa comida deve trazer ao paladar."
  },
  Voice_96394_AwakerVoiceTitle = {
    Text = "Iluminar·Construção"
  },
  Voice_96394_UnlockDesc = {
    Text = "Nível de iluminação atingiu 11 para desbloquear"
  },
  Voice_96395_AwakerVoiceContent = {
    Text = "Muito obrigado pela sua hospitalidade, sinto-me verdadeiramente honrado."
  },
  Voice_96395_AwakerVoiceTitle = {
    Text = "Atualizar·II"
  },
  Voice_96396_AwakerVoiceContent = {
    Text = "Comida deliciosa sempre vale a pena esperar um pouco mais."
  },
  Voice_96396_AwakerVoiceTitle = {
